window.VERBCOMBO_ITEMS = [
 {"np":"zum Ausdruck","verb":"bringen","plain":"ausdrücken","en":"to express (formal)","lv":"B2","vdecoys":["setzen","stellen","führen"],"pdecoys":["verbergen","erwähnen","begründen"],"pAlt":["äußern"],"note":"Formal register. The intransitive counterpart is zum Ausdruck kommen (to be expressed): In ihrem Lächeln kommt Freude zum Ausdruck.","ex":[{"de":"Der Redner brachte seine Dankbarkeit für die Unterstützung zum Ausdruck.","en":"The speaker expressed his gratitude for the support."},{"de":"Mit diesem Brief möchte ich mein Bedauern zum Ausdruck bringen.","en":"With this letter I would like to express my regret."},{"de":"Die Schüler haben ihre Wünsche klar zum Ausdruck gebracht.","en":"The students expressed their wishes clearly."}],"exPlain":[{"de":"Der Redner drückte seine Dankbarkeit für die Unterstützung aus.","en":"The speaker expressed his gratitude for the support."}]},
 {"np":"zur Sprache","verb":"bringen","plain":"ansprechen","en":"to bring up (a topic)","lv":"B2","vdecoys":["setzen","stellen","legen"],"pdecoys":["verschweigen","beantworten","beschließen"],"vAlt":["kommen"],"pAlt":["thematisieren"],"note":"Passive counterpart: zur Sprache kommen (to come up, to be discussed): Bei der Sitzung kamen auch die Kosten zur Sprache.","ex":[{"de":"In der Sitzung brachte Frau Weber das Problem der Parkplätze zur Sprache.","en":"In the meeting, Ms Weber brought up the problem of parking spaces."},{"de":"Ich möchte noch ein anderes Thema zur Sprache bringen.","en":"I would like to raise another topic."},{"de":"Die Lehrerin hat das Mobbing in der Klasse zur Sprache gebracht.","en":"The teacher brought up the bullying in the class."}],"exPlain":[{"de":"Frau Weber sprach in der Sitzung das Problem der Parkplätze an.","en":"In the meeting, Ms Weber brought up the problem of parking spaces."}]},
 {"np":"in Gefahr","verb":"bringen","plain":"gefährden","en":"to endanger","lv":"B2","vdecoys":["machen","stellen","legen"],"pdecoys":["verhindern","schützen","warnen"],"vAlt":["geraten"],"note":"Often reflexive: sich in Gefahr bringen. Without an agent: in Gefahr geraten (to get into danger) or in Gefahr sein.","ex":[{"de":"Der Fahrer hat durch sein Verhalten alle Fahrgäste in Gefahr gebracht.","en":"By his behaviour the driver put all the passengers in danger."},{"de":"Wer bei Glatteis zu schnell fährt, bringt sich selbst in Gefahr.","en":"Anyone who drives too fast on black ice puts himself in danger."},{"de":"Die giftigen Dämpfe brachten alle Arbeiter in Gefahr.","en":"The toxic fumes put all the workers in danger."}],"exPlain":[{"de":"Der Fahrer hat durch sein Verhalten alle Fahrgäste gefährdet.","en":"By his behaviour the driver endangered all the passengers."}]},
 {"np":"in Ordnung","verb":"bringen","plain":"regeln","en":"to sort out, to put right","lv":"B1","vdecoys":["stellen","setzen","legen"],"pdecoys":["verschieben","verwalten","vergessen"],"pAlt":["klären"],"note":"With things such as a car or a room the phrase means 'to repair' or 'to tidy up' (das Auto wieder in Ordnung bringen); the plain verb here covers affairs and problems.","ex":[{"de":"Bevor wir verreisen, muss ich noch einige Dinge in Ordnung bringen.","en":"Before we go away I still have to sort a few things out."},{"de":"Er hat die Sache mit der Versicherung endlich in Ordnung gebracht.","en":"He has finally sorted out the matter with the insurance."},{"de":"Wir haben unsere finanziellen Angelegenheiten in Ordnung gebracht.","en":"We put our financial affairs in order."}],"exPlain":[{"de":"Er hat die Sache mit der Versicherung endlich geregelt.","en":"He has finally sorted out the matter with the insurance."}]},
 {"np":"zum Abschluss","verb":"bringen","plain":"abschließen","en":"to bring to a conclusion","lv":"B2","vdecoys":["setzen","stellen","geben"],"pdecoys":["beginnen","unterbrechen","vorbereiten"],"vAlt":["kommen"],"pAlt":["beenden"],"note":"Intransitive counterpart: zum Abschluss kommen (to come to an end).","ex":[{"de":"Die Firma will das Projekt noch vor Weihnachten zum Abschluss bringen.","en":"The company wants to complete the project before Christmas."},{"de":"Nach langen Verhandlungen brachten beide Seiten den Vertrag zum Abschluss.","en":"After long negotiations both sides concluded the contract."},{"de":"Ich muss die Arbeit heute noch zum Abschluss bringen.","en":"I have to finish the work today."}],"exPlain":[{"de":"Die Firma will das Projekt noch vor Weihnachten abschließen.","en":"The company wants to complete the project before Christmas."}]},
 {"np":"in Erfahrung","verb":"bringen","plain":"herausfinden","en":"to find out, to learn (formal)","lv":"C1","vdecoys":["setzen","nehmen","holen"],"pdecoys":["vermuten","verschweigen","vergessen"],"pAlt":["erfahren"],"note":"Formal. Typically with an object like den Namen, den Grund or a clause (wann, wer, ob).","ex":[{"de":"Die Polizei konnte die Identität des Mannes nicht in Erfahrung bringen.","en":"The police could not find out the man's identity."},{"de":"Ich werde versuchen, die genauen Zeiten in Erfahrung zu bringen.","en":"I will try to find out the exact times."},{"de":"Hast du schon in Erfahrung gebracht, wann der Zug fährt?","en":"Have you found out yet when the train leaves?"}],"exPlain":[{"de":"Die Polizei konnte nicht herausfinden, wer der Mann war.","en":"The police could not find out who the man was."}]},
 {"np":"zur Anwendung","verb":"bringen","plain":"anwenden","en":"to apply, to put into use (formal)","lv":"C1","vdecoys":["setzen","stellen","geben"],"pdecoys":["erfinden","verändern","vergessen"],"note":"Officialese. Passive-like counterpart: zur Anwendung kommen (to be applied).","ex":[{"de":"Die Behörde bringt das neue Verfahren ab dem Sommer zur Anwendung.","en":"The authority will apply the new procedure from the summer."},{"de":"Dieses Prinzip wurde in der Praxis nie zur Anwendung gebracht.","en":"This principle was never put into practice."},{"de":"Der Arzt brachte eine neue Therapie zur Anwendung.","en":"The doctor used a new therapy."}],"exPlain":[{"de":"Die Behörde wendet das neue Verfahren ab dem Sommer an.","en":"The authority applies the new procedure from the summer."}]},
 {"np":"in Verbindung","verb":"bringen","plain":"assoziieren","en":"to link, to associate (with)","lv":"B2","vdecoys":["stellen","legen","führen"],"pdecoys":["verwechseln","vergleichen","trennen"],"pAlt":["verknüpfen"],"note":"Pattern: jdn./etwas mit etwas in Verbindung bringen. Do not confuse with sich in Verbindung setzen / in Verbindung treten (= to contact).","ex":[{"de":"Ich bringe dieses Lied immer mit meinem ersten Urlaub am Meer in Verbindung.","en":"I always associate this song with my first holiday by the sea."},{"de":"Viele Menschen bringen den Namen dieser Stadt nur mit Fußball in Verbindung.","en":"Many people associate the name of this city only with football."},{"de":"Man hat ihn nie mit der Affäre in Verbindung gebracht.","en":"He was never linked to the affair."}],"exPlain":[{"de":"Viele Menschen assoziieren den Namen dieser Stadt nur mit Fußball.","en":"Many people associate the name of this city only with football."}]},
 {"np":"in Gang","verb":"setzen","plain":"auslösen","en":"to set in motion, to trigger","lv":"B2","vdecoys":["stellen","legen","führen"],"pdecoys":["beenden","verhindern","bremsen"],"vAlt":["bringen"],"pAlt":["anstoßen"],"note":"Intransitive counterpart: in Gang kommen (to get going): Die Verhandlungen kommen nur langsam in Gang.","ex":[{"de":"Die Entdeckung setzte eine ganze Reihe von Veränderungen in Gang.","en":"The discovery set off a whole series of changes."},{"de":"Der Streit hat eine heftige Debatte im ganzen Land in Gang gesetzt.","en":"The dispute set off a heated debate across the country."},{"de":"Die Nachricht könnte eine Welle von Protesten in Gang setzen.","en":"The news could set off a wave of protests."}],"exPlain":[{"de":"Die Entdeckung löste eine ganze Reihe von Veränderungen aus.","en":"The discovery triggered a whole series of changes."}]},
 {"np":"zum Stillstand","verb":"bringen","plain":"stoppen","en":"to bring to a standstill","lv":"B2","vdecoys":["setzen","stellen","geben"],"pdecoys":["beschleunigen","starten","steuern"],"pAlt":["anhalten"],"note":"Transitive. Intransitive counterpart: zum Stillstand kommen.","ex":[{"de":"Ein Defekt brachte die gesamte Produktion zum Stillstand.","en":"A defect brought the entire production to a standstill."},{"de":"Der Streik bringt den Verkehr in der Stadt zum Stillstand.","en":"The strike brings traffic in the city to a standstill."},{"de":"Die Polizei hat den Wagen nach wenigen Metern zum Stillstand gebracht.","en":"The police brought the car to a stop after a few metres."}],"exPlain":[{"de":"Ein Defekt stoppte die gesamte Produktion.","en":"A defect stopped the entire production."}]},
 {"np":"zum Stillstand","verb":"kommen","plain":"stehen bleiben","en":"to come to a standstill","lv":"B2","vdecoys":["gehen","fallen","laufen"],"pdecoys":["losfahren","beschleunigen","anfangen"],"vAlt":["bringen"],"pAlt":["anhalten","stoppen"],"note":"No agent: something stops by itself. With an agent: zum Stillstand bringen.","ex":[{"de":"Der Zug kam kurz vor dem Bahnhof zum Stillstand.","en":"The train came to a halt shortly before the station."},{"de":"Der Aufzug kam zwischen zwei Stockwerken zum Stillstand.","en":"The lift came to a standstill between two floors."},{"de":"Nach dem Stromausfall sind alle Maschinen zum Stillstand gekommen.","en":"After the power cut all the machines came to a standstill."}],"exPlain":[{"de":"Der Zug blieb kurz vor dem Bahnhof stehen.","en":"The train stopped shortly before the station."}]},
 {"np":"in Sicherheit","verb":"bringen","plain":"retten","en":"to take to safety","lv":"B2","vdecoys":["geben","stellen","machen"],"pdecoys":["verlieren","entdecken","verfolgen"],"note":"Often reflexive: sich in Sicherheit bringen. The state is in Sicherheit sein.","ex":[{"de":"Die Feuerwehr brachte die Bewohner rechtzeitig in Sicherheit.","en":"The fire brigade got the residents to safety in time."},{"de":"Er konnte sich mit einem Sprung in Sicherheit bringen.","en":"He managed to get to safety with a jump."},{"de":"Sie hat die Kinder in Sicherheit gebracht.","en":"She took the children to safety."}],"exPlain":[{"de":"Die Feuerwehr rettete die Bewohner rechtzeitig.","en":"The fire brigade rescued the residents in time."}]},
 {"np":"zur Welt","verb":"bringen","plain":"gebären","en":"to give birth to","lv":"B2","vdecoys":["geben","setzen","stellen"],"pdecoys":["erziehen","adoptieren","heiraten"],"note":"Standard register. 'Gebären' sounds formal or medical; in everyday speech people say ein Kind bekommen. Counterpart: zur Welt kommen (= to be born).","ex":[{"de":"Sie brachte im Mai gesunde Zwillinge zur Welt.","en":"She gave birth to healthy twins in May."},{"de":"Die Mutter hat ihr drittes Kind zu Hause zur Welt gebracht.","en":"The mother gave birth to her third child at home."},{"de":"Wie viele Kinder hat sie zur Welt gebracht?","en":"How many children has she given birth to?"}],"exPlain":[{"de":"Sie gebar im Mai gesunde Zwillinge.","en":"She gave birth to healthy twins in May."}]},
 {"np":"ums Leben","verb":"kommen","plain":"sterben","en":"to die (in an accident, a disaster)","lv":"B2","vdecoys":["gehen","fallen","geraten"],"pdecoys":["überleben","verschwinden","leiden"],"pAlt":["umkommen"],"note":"News register for violent or accidental deaths. Transitive: jdn. ums Leben bringen (= to kill).","ex":[{"de":"Bei dem Unfall sind zwei Menschen ums Leben gekommen.","en":"Two people died in the accident."},{"de":"Der Bergsteiger kam bei einem Sturz ums Leben.","en":"The climber died in a fall."},{"de":"Viele Soldaten kamen in diesem Krieg ums Leben.","en":"Many soldiers lost their lives in this war."}],"exPlain":[{"de":"Bei dem Unfall sind zwei Menschen gestorben.","en":"Two people died in the accident."}]},
 {"np":"zum Einsatz","verb":"kommen","plain":"eingesetzt werden","en":"to be used, to be deployed","lv":"B2","vdecoys":["treten","fallen","stehen"],"pdecoys":["erfunden werden","verkauft werden","entwickelt werden"],"vAlt":["bringen"],"pAlt":["verwendet werden"],"note":"Passive meaning without an agent. Active: etwas zum Einsatz bringen (formal).","ex":[{"de":"Bei dem Brand kamen mehr als hundert Feuerwehrleute zum Einsatz.","en":"More than a hundred firefighters were deployed at the fire."},{"de":"Im Winter kommen die neuen Streufahrzeuge zum Einsatz.","en":"The new gritting vehicles will be used in winter."},{"de":"In der Klinik kommt seit letztem Jahr ein neues Gerät zum Einsatz.","en":"A new device has been in use at the clinic since last year."}],"exPlain":[{"de":"Bei dem Brand wurden mehr als hundert Feuerwehrleute eingesetzt.","en":"More than a hundred firefighters were deployed at the fire."}]},
 {"np":"zur Anwendung","verb":"kommen","plain":"angewendet werden","en":"to be applied","lv":"C1","vdecoys":["gehen","fallen","treten"],"pdecoys":["erfunden werden","abgeschafft werden","vergessen werden"],"vAlt":["bringen"],"note":"Legal and administrative language; passive meaning. Active: zur Anwendung bringen.","ex":[{"de":"Diese Regel kommt nur bei Verträgen über 5000 Euro zur Anwendung.","en":"This rule applies only to contracts over 5,000 euros."},{"de":"Welches Recht kommt in diesem Fall zur Anwendung?","en":"Which law applies in this case?"},{"de":"Das neue Verfahren kam erstmals im Jahr 2019 zur Anwendung.","en":"The new procedure was first applied in 2019."}],"exPlain":[{"de":"Diese Regel wird nur bei Verträgen über 5000 Euro angewendet.","en":"This rule is applied only to contracts over 5,000 euros."}]},
 {"np":"in Betracht","verb":"kommen","plain":"eine Option sein","en":"to be an option, to come into consideration","lv":"B2","vdecoys":["gehen","liegen","treten"],"pdecoys":["verboten sein","bekannt sein","teuer sein"],"note":"Says that something is eligible or worth considering, not merely that it is possible. Close to in Frage kommen / infrage kommen. Transitive: etwas in Betracht ziehen (= to consider).","ex":[{"de":"Für diese Stelle kommen nur erfahrene Bewerber in Betracht.","en":"Only experienced applicants are under consideration for this position."},{"de":"Ein Umzug kommt für uns momentan nicht in Betracht.","en":"Moving is not an option for us at the moment."},{"de":"Welche Lösungen kamen sonst noch in Betracht?","en":"Which other solutions came into consideration?"}],"exPlain":[{"de":"Für uns ist ein Umzug momentan keine Option.","en":"Moving is not an option for us at the moment."}]},
 {"np":"zu dem Schluss","verb":"kommen","plain":"schlussfolgern","en":"to come to the conclusion","lv":"B2","vdecoys":["gehen","treten","fallen"],"pdecoys":["bezweifeln","behaupten","prüfen"],"pAlt":["folgern"],"note":"Also: zu dem Ergebnis kommen. Typically followed by a dass-clause.","ex":[{"de":"Die Forscher kamen zu dem Schluss, dass die Methode funktioniert.","en":"The researchers came to the conclusion that the method works."},{"de":"Nach langem Nachdenken bin ich zu dem Schluss gekommen, dass ich kündigen muss.","en":"After thinking for a long time I came to the conclusion that I have to quit."},{"de":"Zu welchem Schluss kommt der Bericht?","en":"What conclusion does the report reach?"}],"exPlain":[{"de":"Die Forscher schlussfolgerten, dass die Methode funktioniert.","en":"The researchers concluded that the method works."}]},
 {"np":"zu einer Einigung","verb":"kommen","plain":"sich einigen","en":"to reach an agreement","lv":"B2","vdecoys":["gehen","treten","stehen"],"pdecoys":["sich streiten","sich trennen","sich verabschieden"],"note":"The plain verb is reflexive: sich (auf + Akk.) einigen. Also: zu einer Einigung gelangen.","ex":[{"de":"Nach stundenlangen Gesprächen kamen beide Seiten zu einer Einigung.","en":"After hours of talks both sides reached an agreement."},{"de":"Hoffentlich kommen wir bald zu einer Einigung über den Preis.","en":"Hopefully we will soon reach an agreement on the price."},{"de":"Die Parteien sind nie zu einer Einigung gekommen.","en":"The parties never reached an agreement."}],"exPlain":[{"de":"Nach stundenlangen Gesprächen einigten sich beide Seiten.","en":"After hours of talks both sides agreed."}]},
 {"np":"zu Besuch","verb":"kommen","plain":"besuchen","en":"to come and visit","lv":"A2","vdecoys":["setzen","nehmen","laufen"],"pdecoys":["einladen","abholen","bleiben"],"vAlt":["fahren"],"note":"The person visited follows zu + Dat. (zu uns zu Besuch kommen), whereas besuchen takes the accusative (uns besuchen). The state is bei jdm. zu Besuch sein (= to be visiting someone).","ex":[{"de":"Meine Eltern kommen am Wochenende zu Besuch.","en":"My parents are coming to visit at the weekend."},{"de":"Kommst du bald mal wieder zu uns zu Besuch?","en":"Will you come and visit us again soon?"},{"de":"Letzte Woche kam eine alte Freundin zu Besuch.","en":"Last week an old friend came to visit."}],"exPlain":[{"de":"Meine Eltern besuchen uns am Wochenende.","en":"My parents are visiting us at the weekend."}]},
 {"np":"zur Ruhe","verb":"kommen","plain":"sich beruhigen","en":"to calm down, to find peace","lv":"B2","vdecoys":["fallen","treten","laufen"],"pdecoys":["sich ärgern","sich beeilen","sich streiten"],"pAlt":["sich entspannen"],"note":"Both 'calm down' and 'get some peace and quiet'; often used with nicht.","ex":[{"de":"Nach dem Umzug ist die Familie endlich zur Ruhe gekommen.","en":"After the move the family has finally settled down."},{"de":"In dieser lauten Stadt komme ich nie richtig zur Ruhe.","en":"In this noisy city I never really get to relax."},{"de":"Das Land kam nach den Unruhen nur langsam zur Ruhe.","en":"The country only slowly settled down after the unrest."}],"exPlain":[{"de":"Nach dem Umzug hat sich die Familie endlich beruhigt.","en":"After the move the family has finally calmed down."}]},
 {"np":"zum Vorschein","verb":"kommen","plain":"auftauchen","en":"to turn up, to come to light","lv":"B2","vdecoys":["gehen","fallen","laufen"],"pdecoys":["verschwinden","sich verstecken","ankommen"],"vAlt":["bringen"],"note":"Intransitive. Active: etwas zum Vorschein bringen (= to bring to light, reveal).","ex":[{"de":"Beim Aufräumen kam der verlorene Schlüssel wieder zum Vorschein.","en":"While tidying up, the lost key turned up again."},{"de":"Hinter dem Schrank kam eine alte Münze zum Vorschein.","en":"An old coin turned up behind the cupboard."},{"de":"Erst nach Jahren kamen die Fehler der Baufirma zum Vorschein.","en":"Only years later did the construction company's mistakes come to light."}],"exPlain":[{"de":"Beim Aufräumen tauchte der verlorene Schlüssel wieder auf.","en":"While tidying up, the lost key turned up again."}]},
 {"np":"ans Licht","verb":"kommen","plain":"bekannt werden","en":"to come to light, to become known","lv":"B2","vdecoys":["gehen","fallen","laufen"],"pdecoys":["geheim bleiben","vergessen werden","verboten werden"],"vAlt":["bringen"],"note":"Usually for something hidden or unpleasant. Active: etwas ans Licht bringen (= to reveal).","ex":[{"de":"Der Skandal kam erst nach Jahren ans Licht.","en":"The scandal only came to light after years."},{"de":"Wenn die Wahrheit ans Licht kommt, wird er seinen Job verlieren.","en":"If the truth comes out, he will lose his job."},{"de":"Die Fälschungen sind zufällig ans Licht gekommen.","en":"The forgeries came to light by chance."}],"exPlain":[{"de":"Der Skandal wurde erst nach Jahren bekannt.","en":"The scandal only became known after years."}]},
 {"np":"aus der Mode","verb":"kommen","plain":"unmodern werden","en":"to go out of fashion","lv":"B2","vdecoys":["laufen","treten","fahren"],"pdecoys":["beliebt werden","teurer werden","entstehen"],"vAlt":["geraten"],"pAlt":["veralten"],"note":"Opposite: in Mode kommen. The state is aus der Mode sein.","ex":[{"de":"Diese Art von Hosen ist nie ganz aus der Mode gekommen.","en":"This kind of trousers has never completely gone out of fashion."},{"de":"Telefonzellen kamen mit dem Handy schnell aus der Mode.","en":"Phone boxes quickly went out of fashion with the mobile phone."},{"de":"Breite Krawatten kommen langsam aus der Mode.","en":"Wide ties are slowly going out of fashion."}],"exPlain":[{"de":"Telefonzellen wurden mit dem Handy schnell unmodern.","en":"Phone boxes quickly became unfashionable with the mobile phone."}]},
 {"np":"zum Tragen","verb":"kommen","plain":"wirksam werden","en":"to take effect, to come into play","lv":"C1","vdecoys":["gehen","fallen","treten"],"pdecoys":["versagen","verschwinden","scheitern"],"vAlt":["bringen"],"note":"Written register; the subject is normally a thing or an effect (Vorteile, Erfahrung, eine Regel), not a person.","ex":[{"de":"Die Vorteile der neuen Methode kommen erst bei großen Datenmengen zum Tragen.","en":"The advantages of the new method only come into play with large amounts of data."},{"de":"Erst im Alter kam seine Erfahrung richtig zum Tragen.","en":"Only in old age did his experience really make itself felt."},{"de":"Wann kommen die Sparmaßnahmen zum Tragen?","en":"When will the austerity measures take effect?"}],"exPlain":[{"de":"Die Vorteile der neuen Methode werden erst bei großen Datenmengen wirksam.","en":"The advantages of the new method only take effect with large amounts of data."}]},
 {"np":"zu Schaden","verb":"kommen","plain":"verletzt werden","en":"to come to harm, to be hurt","lv":"B2","vdecoys":["gehen","fallen","laufen"],"pdecoys":["gerettet werden","geheilt werden","gewarnt werden"],"pAlt":["geschädigt werden"],"note":"Mostly in negative sentences or with niemand, keiner.","ex":[{"de":"Bei dem Unfall ist zum Glück niemand zu Schaden gekommen.","en":"Fortunately nobody was hurt in the accident."},{"de":"Die Kinder spielten wild, aber keines kam zu Schaden.","en":"The children played roughly, but none of them came to any harm."},{"de":"Auch der Fahrer kam nicht zu Schaden.","en":"The driver wasn't hurt either."}],"exPlain":[{"de":"Bei dem Unfall wurde zum Glück niemand verletzt.","en":"Fortunately nobody was hurt in the accident."}]},
 {"np":"zu Ende","verb":"gehen","plain":"enden","en":"to come to an end","lv":"A2","vdecoys":["stehen","fallen","treten"],"pdecoys":["beginnen","dauern","bleiben"],"note":"Also for supplies: Der Zucker geht zu Ende = we are running out of sugar. Transitive: etwas zu Ende bringen / führen.","ex":[{"de":"Der Film geht in zehn Minuten zu Ende.","en":"The film ends in ten minutes."},{"de":"Leider ging der schöne Urlaub viel zu schnell zu Ende.","en":"Unfortunately the lovely holiday ended far too quickly."},{"de":"Der Sommer geht langsam zu Ende.","en":"Summer is slowly coming to an end."}],"exPlain":[{"de":"Der Film endet in zehn Minuten.","en":"The film ends in ten minutes."}]},
 {"np":"in Erfüllung","verb":"gehen","plain":"sich erfüllen","en":"to come true","lv":"B2","vdecoys":["kommen","treten","fallen"],"pdecoys":["scheitern","sich verändern","verschwinden"],"note":"Subjects: Wunsch, Traum, Hoffnung, Prophezeiung. Not used for people as subject.","ex":[{"de":"Ihr größter Wunsch ging endlich in Erfüllung.","en":"Her greatest wish finally came true."},{"de":"Wenn alle Träume in Erfüllung gingen, wäre das Leben einfach.","en":"If all dreams came true, life would be easy."},{"de":"Seine Prophezeiung ist nie in Erfüllung gegangen.","en":"His prophecy never came true."}],"exPlain":[{"de":"Ihr größter Wunsch erfüllte sich endlich.","en":"Her greatest wish finally came true."}]},
 {"np":"in den Streik","verb":"treten","plain":"streiken","en":"to go on strike","lv":"B2","vdecoys":["kommen","fallen","laufen"],"pdecoys":["kündigen","verhandeln","arbeiten"],"vAlt":["gehen"],"note":"Press register. In speech also in den Streik gehen.","ex":[{"de":"Die Piloten sind gestern in den Streik getreten.","en":"The pilots went on strike yesterday."},{"de":"Wenn die Verhandlungen scheitern, treten die Beschäftigten in den Streik.","en":"If the negotiations fail, the employees will go on strike."},{"de":"Die Ärzte traten Anfang Mai in den Streik.","en":"The doctors went on strike at the beginning of May."}],"exPlain":[{"de":"Die Piloten haben gestern gestreikt.","en":"The pilots went on strike yesterday."}]},
 {"np":"in Kraft","verb":"treten","plain":"gültig werden","en":"to come into force","lv":"B2","vdecoys":["gehen","fallen","laufen"],"pdecoys":["ablaufen","ungültig werden","verjähren"],"note":"Start of validity (in Kraft treten) vs. state (in Kraft sein / bleiben) vs. end (außer Kraft treten). Transitive: etwas in Kraft setzen.","ex":[{"de":"Das neue Gesetz tritt am 1. Januar in Kraft.","en":"The new law comes into force on 1 January."},{"de":"Die Regelung ist bereits im Sommer in Kraft getreten.","en":"The regulation already came into force in the summer."},{"de":"Wann treten die neuen Bestimmungen in Kraft?","en":"When do the new provisions come into force?"}],"exPlain":[{"de":"Das neue Gesetz wird am 1. Januar gültig.","en":"The new law becomes valid on 1 January."}]},
 {"np":"außer Kraft","verb":"treten","plain":"ungültig werden","en":"to cease to apply, to expire","lv":"C1","vdecoys":["gehen","fallen","kommen"],"pdecoys":["gelten","beginnen","entstehen"],"note":"Opposite of in Kraft treten. Transitive: etwas außer Kraft setzen (= to repeal).","ex":[{"de":"Die alte Verordnung ist Ende des Jahres außer Kraft getreten.","en":"The old regulation ceased to apply at the end of the year."},{"de":"Mit dem Beschluss tritt das Gesetz sofort außer Kraft.","en":"With the resolution the law ceases to apply immediately."},{"de":"Wann tritt die Regelung außer Kraft?","en":"When does the regulation expire?"}],"exPlain":[{"de":"Die alte Verordnung ist Ende des Jahres ungültig geworden.","en":"The old regulation became invalid at the end of the year."}]},
 {"np":"außer Kraft","verb":"setzen","plain":"aufheben","en":"to repeal, to annul","lv":"C1","vdecoys":["bringen","stellen","legen"],"pdecoys":["erlassen","verabschieden","ändern"],"note":"Opposite: in Kraft setzen (= to put into effect). Intransitive: außer Kraft treten.","ex":[{"de":"Das Parlament setzte das umstrittene Gesetz außer Kraft.","en":"Parliament repealed the controversial law."},{"de":"Die Regierung hat die Regel nach den Protesten außer Kraft gesetzt.","en":"The government repealed the rule after the protests."},{"de":"Die Stadt hat die alte Satzung außer Kraft gesetzt.","en":"The city repealed the old by-law."}],"exPlain":[{"de":"Das Parlament hob das umstrittene Gesetz auf.","en":"Parliament repealed the controversial law."}]},
 {"np":"in Verbindung","verb":"treten","plain":"kontaktieren","en":"to get in touch (formal)","lv":"B2","vdecoys":["gehen","fallen","laufen"],"pdecoys":["einladen","begrüßen","vermeiden"],"note":"Formal; mit + Dat. Equivalent: sich in Verbindung setzen. State: in Verbindung stehen (= to be in contact).","ex":[{"de":"Bitte treten Sie bei Fragen mit unserem Büro in Verbindung.","en":"If you have any questions, please get in touch with our office."},{"de":"Die Firma trat mit mehreren Lieferanten in Verbindung.","en":"The company got in touch with several suppliers."},{"de":"Er versuchte, mit der Familie in Verbindung zu treten.","en":"He tried to get in touch with the family."}],"exPlain":[{"de":"Bitte kontaktieren Sie bei Fragen unser Büro.","en":"If you have any questions, please contact our office."}]},
 {"np":"in Erscheinung","verb":"treten","plain":"sich zeigen","en":"to appear, to become apparent","lv":"C1","vdecoys":["gehen","fallen","laufen"],"pdecoys":["verschwinden","sich verstecken","sich verändern"],"pAlt":["erscheinen","auftreten"],"note":"Often with kaum, nie or öffentlich (öffentlich in Erscheinung treten = to appear in public).","ex":[{"de":"Die ersten Symptome traten erst nach Wochen in Erscheinung.","en":"The first symptoms only appeared after weeks."},{"de":"Der Verein ist bisher kaum in Erscheinung getreten.","en":"The club has hardly made itself noticed so far."},{"de":"Wann tritt die Krankheit zum ersten Mal in Erscheinung?","en":"When does the illness first become apparent?"}],"exPlain":[{"de":"Die ersten Symptome zeigten sich erst nach Wochen.","en":"The first symptoms only showed after weeks."}]},
 {"np":"zutage","verb":"treten","plain":"sichtbar werden","en":"to come to light, to emerge","lv":"C1","vdecoys":["gehen","fallen","laufen"],"pdecoys":["verschwinden","verborgen bleiben","ausfallen"],"vAlt":["kommen"],"note":"Written register. Also: zutage kommen, etwas zutage fördern (= to bring to light).","ex":[{"de":"Bei der Prüfung traten schwere Mängel zutage.","en":"Serious defects came to light during the inspection."},{"de":"Nach dem Streit trat ihre Unzufriedenheit offen zutage.","en":"After the quarrel her dissatisfaction came out into the open."},{"de":"Der Fehler ist erst Jahre später zutage getreten.","en":"The error only came to light years later."}],"exPlain":[{"de":"Bei der Prüfung wurden schwere Mängel sichtbar.","en":"Serious defects became visible during the inspection."}]},
 {"np":"in Kenntnis","verb":"setzen","plain":"informieren","en":"to inform (formal)","lv":"B2","vdecoys":["bringen","geben","stellen"],"pdecoys":["beraten","beauftragen","überzeugen"],"pAlt":["benachrichtigen","unterrichten"],"note":"Formal. Pattern: jdn. von/über etwas in Kenntnis setzen. Do not confuse with etwas zur Kenntnis nehmen (= to take note of).","ex":[{"de":"Die Schulleitung setzte alle Eltern über den Vorfall in Kenntnis.","en":"The school management informed all parents about the incident."},{"de":"Bitte setzen Sie mich rechtzeitig in Kenntnis, wenn sich etwas ändert.","en":"Please let me know in good time if anything changes."},{"de":"Wurde der Betriebsrat in Kenntnis gesetzt?","en":"Was the works council informed?"}],"exPlain":[{"de":"Die Schulleitung informierte alle Eltern über den Vorfall.","en":"The school management informed all parents about the incident."}]},
 {"np":"unter Druck","verb":"setzen","plain":"bedrängen","en":"to put pressure on","lv":"B2","vdecoys":["stellen","legen","führen"],"pdecoys":["beruhigen","überzeugen","ermutigen"],"note":"The state is unter Druck stehen; the process is unter Druck geraten. Reflexive: sich unter Druck setzen (= to put pressure on oneself).","ex":[{"de":"Der Trainer setzt die jungen Spieler zu sehr unter Druck.","en":"The coach puts too much pressure on the young players."},{"de":"Lass dich von den anderen nicht unter Druck setzen!","en":"Don't let the others put pressure on you!"},{"de":"Die Gläubiger setzten das Unternehmen unter Druck.","en":"The creditors put the company under pressure."}],"exPlain":[{"de":"Die Gläubiger bedrängten das Unternehmen.","en":"The creditors pressed the company."}]},
 {"np":"in Brand","verb":"setzen","plain":"anzünden","en":"to set on fire","lv":"B2","vdecoys":["stellen","geben","machen"],"pdecoys":["löschen","ersticken","retten"],"vAlt":["stecken"],"note":"News and police register; also in Brand stecken. Intransitive: in Brand geraten (= to catch fire).","ex":[{"de":"Unbekannte setzten in der Nacht ein Auto in Brand.","en":"Unknown persons set a car on fire during the night."},{"de":"Der Blitz hat die Scheune in Brand gesetzt.","en":"Lightning set the barn on fire."},{"de":"Die Täter wollten das Haus in Brand setzen.","en":"The culprits wanted to set the house on fire."}],"exPlain":[{"de":"Unbekannte zündeten in der Nacht ein Auto an.","en":"Unknown persons set a car on fire during the night."}]},
 {"np":"Prioritäten","verb":"setzen","plain":"priorisieren","en":"to set priorities","lv":"B2","vdecoys":["machen","nehmen","halten"],"pdecoys":["ignorieren","verschieben","streichen"],"note":"Also: Schwerpunkte setzen, ein Zeichen setzen. 'Priorisieren' is a more technical word.","ex":[{"de":"Wer erfolgreich sein will, muss Prioritäten setzen.","en":"Anyone who wants to be successful has to set priorities."},{"de":"Wir haben beim Budget klare Prioritäten gesetzt.","en":"We set clear priorities for the budget."},{"de":"Du musst endlich Prioritäten setzen, sonst wirst du nie fertig.","en":"You finally have to set priorities, otherwise you will never get finished."}],"exPlain":[{"de":"Wer erfolgreich sein will, muss priorisieren.","en":"Anyone who wants to be successful has to prioritise."}]},
 {"np":"aufs Spiel","verb":"setzen","plain":"riskieren","en":"to risk, to put at stake","lv":"B2","vdecoys":["stellen","legen","bringen"],"pdecoys":["gewinnen","verlieren","bezahlen"],"note":"Counterpart with stehen: auf dem Spiel stehen (= to be at stake).","ex":[{"de":"Mit seinem Verhalten setzt er seinen guten Ruf aufs Spiel.","en":"With his behaviour he is putting his good reputation at risk."},{"de":"Sie wollte ihre Gesundheit nicht aufs Spiel setzen.","en":"She did not want to jeopardise her health."},{"de":"Die Firma hat mit dieser Entscheidung viel aufs Spiel gesetzt.","en":"The company put a lot at stake with this decision."}],"exPlain":[{"de":"Mit seinem Verhalten riskiert er seinen guten Ruf.","en":"With his behaviour he is risking his good reputation."}]},
 {"np":"zur Verfügung","verb":"stellen","plain":"bereitstellen","en":"to make available, to provide","lv":"B1","vdecoys":["legen","setzen","bringen"],"pdecoys":["benutzen","verkaufen","verlangen"],"pAlt":["überlassen"],"note":"Active: jdm. etwas zur Verfügung stellen; state: zur Verfügung stehen. Reflexive: sich zur Verfügung stellen (= to volunteer).","ex":[{"de":"Die Firma stellt den Mitarbeitern kostenlos Laptops zur Verfügung.","en":"The company provides its employees with laptops free of charge."},{"de":"Kannst du mir bitte dein Auto zur Verfügung stellen?","en":"Can you please let me use your car?"},{"de":"Der Verein hat uns einen Raum zur Verfügung gestellt.","en":"The club has made a room available to us."}],"exPlain":[{"de":"Die Firma stellt den Mitarbeitern kostenlos Laptops bereit.","en":"The company provides its employees with laptops free of charge."}]},
 {"np":"zur Verfügung","verb":"stehen","plain":"verfügbar sein","en":"to be available","lv":"B1","vdecoys":["liegen","gehen","kommen"],"pdecoys":["fehlen","ausverkauft sein","nötig sein"],"pAlt":["bereitstehen"],"note":"The person has the dative (uns, Ihnen). Counterpart: zur Verfügung stellen (= to provide).","ex":[{"de":"Für das Projekt stehen uns 50.000 Euro zur Verfügung.","en":"We have 50,000 euros available for the project."},{"de":"Wir stehen Ihnen jederzeit zur Verfügung.","en":"We are at your disposal at any time."},{"de":"Bis Mittwoch stand der Raum nicht zur Verfügung.","en":"The room was not available until Wednesday."}],"exPlain":[{"de":"Für das Projekt sind 50.000 Euro verfügbar.","en":"50,000 euros are available for the project."}]},
 {"np":"in Frage","verb":"stellen","plain":"anzweifeln","en":"to question, to call into question","lv":"B2","vdecoys":["setzen","legen","bringen"],"pdecoys":["bestätigen","beweisen","verstehen"],"pAlt":["bezweifeln"],"note":"Also written infrage stellen. Related: in Frage kommen (= to be an option), in Zweifel ziehen.","ex":[{"de":"Niemand will die Qualität seiner Arbeit in Frage stellen.","en":"Nobody wants to question the quality of his work."},{"de":"Die Opposition stellt den ganzen Plan in Frage.","en":"The opposition calls the whole plan into question."},{"de":"Man sollte Autoritäten manchmal in Frage stellen.","en":"One should sometimes question authorities."}],"exPlain":[{"de":"Niemand will die Qualität seiner Arbeit anzweifeln.","en":"Nobody wants to doubt the quality of his work."}]},
 {"np":"unter Beweis","verb":"stellen","plain":"beweisen","en":"to prove, to demonstrate","lv":"B2","vdecoys":["legen","setzen","bringen"],"pdecoys":["bezweifeln","verbessern","erklären"],"pAlt":["zeigen"],"note":"Typical objects: Können, Mut, Talent, Geduld, Fähigkeiten (a person shows what they are capable of). Not for proving a mathematical statement.","ex":[{"de":"Im Finale stellte die Mannschaft ihr Können unter Beweis.","en":"In the final the team proved its ability."},{"de":"Die junge Ärztin will in der Notaufnahme ihre Fähigkeiten unter Beweis stellen.","en":"The young doctor wants to demonstrate her skills in the emergency room."},{"de":"Er hat Mut unter Beweis gestellt.","en":"He proved his courage."}],"exPlain":[{"de":"Im Finale bewies die Mannschaft ihr Können.","en":"In the final the team proved its ability."}]},
 {"np":"eine Frage","verb":"stellen","plain":"fragen","en":"to ask a question","lv":"A2","vdecoys":["machen","geben","sagen"],"pdecoys":["antworten","bitten","sagen"],"note":"Not 'eine Frage machen'. The person asked is in the dative: jdm. eine Frage stellen, whereas fragen takes the accusative (jdn. fragen). Opposite: eine Frage beantworten.","ex":[{"de":"Darf ich Ihnen eine Frage stellen?","en":"May I ask you a question?"},{"de":"Der Lehrer stellte der Klasse eine schwere Frage.","en":"The teacher asked the class a difficult question."},{"de":"Die Kinder stellen den ganzen Tag Fragen.","en":"The children ask questions all day long."}],"exPlain":[{"de":"Darf ich Sie etwas fragen?","en":"May I ask you something?"}]},
 {"np":"einen Antrag","verb":"stellen","plain":"beantragen","en":"to apply for, to submit an application","lv":"B1","vdecoys":["geben","bringen","legen"],"pdecoys":["sich bewerben","bestellen","genehmigen"],"note":"einen Antrag auf + Akk. stellen (bei einer Behörde). 'Beantragen' takes the thing applied for directly as its object.","ex":[{"de":"Wer Wohngeld möchte, muss einen Antrag stellen.","en":"Anyone who wants housing benefit has to submit an application."},{"de":"Sie hat beim Amt einen Antrag auf Elterngeld gestellt.","en":"She submitted an application for parental allowance at the office."},{"de":"Bis wann kann ich den Antrag stellen?","en":"Until when can I submit the application?"}],"exPlain":[{"de":"Wer Wohngeld möchte, muss es beantragen.","en":"Anyone who wants housing benefit has to apply for it."}]},
 {"np":"Forderungen","verb":"stellen","plain":"fordern","en":"to make demands","lv":"B2","vdecoys":["machen","geben","bringen"],"pdecoys":["erfüllen","ablehnen","bezahlen"],"pAlt":["verlangen"],"note":"Pattern: Forderungen an jdn. stellen. Also Ansprüche / Bedingungen / Anforderungen stellen.","ex":[{"de":"Die Gewerkschaft stellt hohe Forderungen an die Arbeitgeber.","en":"The union makes high demands on the employers."},{"de":"Die Mieter stellten Forderungen, die niemand erfüllen konnte.","en":"The tenants made demands that nobody could meet."},{"de":"Wer so viele Forderungen stellt, sollte selbst etwas bieten.","en":"Anyone who makes so many demands should offer something themselves."}],"exPlain":[{"de":"Die Gewerkschaft fordert viel von den Arbeitgebern.","en":"The union demands a lot from the employers."}]},
 {"np":"in Rechnung","verb":"stellen","plain":"berechnen","en":"to charge, to bill","lv":"B2","vdecoys":["legen","machen","schicken"],"pdecoys":["bezahlen","quittieren","bestellen"],"note":"jdm. etwas in Rechnung stellen. Do not confuse with etwas in Rechnung ziehen (= to take into account).","ex":[{"de":"Der Handwerker hat uns die Anfahrt extra in Rechnung gestellt.","en":"The tradesman charged us extra for the call-out."},{"de":"Die Bank stellt für das Konto eine Gebühr in Rechnung.","en":"The bank charges a fee for the account."},{"de":"Darf ich Ihnen die Beratung in Rechnung stellen?","en":"May I bill you for the consultation?"}],"exPlain":[{"de":"Der Handwerker hat uns die Anfahrt extra berechnet.","en":"The tradesman charged us extra for the call-out."}]},
 {"np":"in Aussicht","verb":"stellen","plain":"versprechen","en":"to hold out the prospect of","lv":"C1","vdecoys":["legen","setzen","bringen"],"pdecoys":["verlangen","verbieten","fürchten"],"note":"Weaker than versprechen: it names a possibility, not a firm promise.","ex":[{"de":"Der Chef stellte den Mitarbeitern eine Gehaltserhöhung in Aussicht.","en":"The boss held out the prospect of a pay rise to the employees."},{"de":"Die Stadt hat den Anwohnern eine Lösung in Aussicht gestellt.","en":"The city has promised the residents a solution."},{"de":"Was wurde dir denn in Aussicht gestellt?","en":"What were you promised, then?"}],"exPlain":[{"de":"Der Chef versprach den Mitarbeitern eine Gehaltserhöhung.","en":"The boss promised the employees a pay rise."}]},
 {"np":"in den Schatten","verb":"stellen","plain":"übertreffen","en":"to outshine, to put in the shade","lv":"C1","vdecoys":["bringen","ziehen","führen"],"pdecoys":["beschatten","verdunkeln","bewundern"],"note":"Figurative. Beware: beschatten means 'to tail someone' (or to shade), not 'to outshine'.","ex":[{"de":"Die junge Sängerin stellte alle anderen Kandidaten in den Schatten.","en":"The young singer outshone all the other candidates."},{"de":"Seine neue Erfindung stellt alles bisher Dagewesene in den Schatten.","en":"His new invention puts everything seen so far in the shade."},{"de":"Der Neubau stellt das alte Gebäude völlig in den Schatten.","en":"The new building completely overshadows the old one."}],"exPlain":[{"de":"Die junge Sängerin übertraf alle anderen Kandidaten.","en":"The young singer surpassed all the other candidates."}]},
 {"np":"eine Diagnose","verb":"stellen","plain":"diagnostizieren","en":"to make a diagnosis","lv":"B2","vdecoys":["legen","geben","nehmen"],"pdecoys":["behandeln","heilen","untersuchen"],"note":"The standard verb is stellen ('eine Diagnose machen' is at best colloquial). Also: eine Prognose stellen.","ex":[{"de":"Die Ärztin konnte erst nach mehreren Tests eine Diagnose stellen.","en":"The doctor could only make a diagnosis after several tests."},{"de":"Wer stellt die Diagnose bei diesem Krankheitsbild?","en":"Who makes the diagnosis for this clinical picture?"},{"de":"Ohne Röntgenbild lässt sich keine sichere Diagnose stellen.","en":"Without an X-ray no reliable diagnosis can be made."}],"exPlain":[{"de":"Die Ärztin konnte erst nach mehreren Tests die Krankheit diagnostizieren.","en":"The doctor could only diagnose the illness after several tests."}]},
 {"np":"in Betracht","verb":"ziehen","plain":"erwägen","en":"to consider, to take into account","lv":"B2","vdecoys":["nehmen","setzen","stellen"],"pdecoys":["ablehnen","ausschließen","vergessen"],"note":"Intransitive counterpart: in Betracht kommen (= to be an option, to come into consideration).","ex":[{"de":"Die Firma zieht eine Verlegung des Standorts in Betracht.","en":"The company is considering relocating its site."},{"de":"Wir sollten auch andere Möglichkeiten in Betracht ziehen.","en":"We should also consider other options."},{"de":"Hast du schon in Betracht gezogen, den Job zu wechseln?","en":"Have you considered changing jobs?"}],"exPlain":[{"de":"Die Firma erwägt eine Verlegung des Standorts.","en":"The company is considering relocating its site."}]},
 {"np":"in Zweifel","verb":"ziehen","plain":"bezweifeln","en":"to doubt, to call into question","lv":"C1","vdecoys":["setzen","legen","führen"],"pdecoys":["bestätigen","vermuten","ignorieren"],"pAlt":["anzweifeln"],"note":"Formal. Close to in Frage stellen. Also: Zweifel haben / hegen (= to have doubts).","ex":[{"de":"Niemand zog seine Ehrlichkeit in Zweifel.","en":"Nobody doubted his honesty."},{"de":"Die Experten ziehen die Ergebnisse der Studie in Zweifel.","en":"The experts call the results of the study into question."},{"de":"Warum ziehst du meine Worte immer in Zweifel?","en":"Why do you always doubt my words?"}],"exPlain":[{"de":"Niemand bezweifelte seine Ehrlichkeit.","en":"Nobody doubted his honesty."}]},
 {"np":"Bilanz","verb":"ziehen","plain":"resümieren","en":"to take stock, to sum up","lv":"B2","vdecoys":["nehmen","geben","halten"],"pdecoys":["planen","prognostizieren","vermuten"],"pAlt":["bilanzieren"],"note":"Often with eine positive / negative Bilanz ziehen. 'Resümieren' is the more bookish verb.","ex":[{"de":"Am Jahresende zog der Verein Bilanz.","en":"At the end of the year the club took stock."},{"de":"Nach drei Jahren im Amt zieht die Bürgermeisterin eine positive Bilanz.","en":"After three years in office the mayor gives a positive overall assessment."},{"de":"Lass uns nach dem Projekt gemeinsam Bilanz ziehen.","en":"Let's take stock together after the project."}],"exPlain":[{"de":"Am Jahresende resümierte der Verein das vergangene Jahr.","en":"At the end of the year the club summed up the past year."}]},
 {"np":"Schlüsse","verb":"ziehen","plain":"folgern","en":"to draw conclusions","lv":"B2","vdecoys":["machen","nehmen","geben"],"pdecoys":["vermuten","bezweifeln","beobachten"],"pAlt":["schlussfolgern"],"note":"Plural Schlüsse; aus + Dat. Related: Konsequenzen ziehen, zu dem Schluss kommen.","ex":[{"de":"Aus den Daten lassen sich keine sicheren Schlüsse ziehen.","en":"No reliable conclusions can be drawn from the data."},{"de":"Welche Schlüsse ziehst du daraus?","en":"What conclusions do you draw from that?"},{"de":"Die Forscher zogen aus dem Experiment vorsichtige Schlüsse.","en":"The researchers drew cautious conclusions from the experiment."}],"exPlain":[{"de":"Aus den Daten lässt sich nichts sicher folgern.","en":"Nothing can be reliably inferred from the data."}]},
 {"np":"zur Rechenschaft","verb":"ziehen","plain":"belangen","en":"to hold accountable, to call to account","lv":"C1","vdecoys":["nehmen","bringen","holen"],"pdecoys":["freisprechen","belohnen","entschuldigen"],"note":"Also zur Verantwortung ziehen. 'Belangen' = to hold legally liable; both are formal.","ex":[{"de":"Die Verantwortlichen wurden nie zur Rechenschaft gezogen.","en":"Those responsible were never held to account."},{"de":"Wer den Unfall verursacht hat, wird zur Rechenschaft gezogen.","en":"Whoever caused the accident will be held accountable."},{"de":"Man kann ihn nicht für alles zur Rechenschaft ziehen.","en":"You cannot hold him accountable for everything."}],"exPlain":[{"de":"Die Verantwortlichen wurden nie belangt.","en":"Those responsible were never held to account."}]},
 {"np":"einen Vergleich","verb":"ziehen","plain":"vergleichen","en":"to draw a comparison","lv":"B2","vdecoys":["nehmen","geben","halten"],"pdecoys":["unterscheiden","bewerten","verwechseln"],"pAlt":[],"note":"Also einen Vergleich anstellen. Idiom: Der Vergleich hinkt = the comparison doesn't hold.","ex":[{"de":"Der Autor zieht einen Vergleich zwischen den beiden Epochen.","en":"The author draws a comparison between the two eras."},{"de":"Zieh doch bitte keinen Vergleich mit meiner Schwester!","en":"Please don't compare me with my sister!"},{"de":"Zwischen diesen beiden Fällen lässt sich kaum ein Vergleich ziehen.","en":"Hardly any comparison can be drawn between these two cases."}],"exPlain":[{"de":"Der Autor vergleicht die beiden Epochen.","en":"The author compares the two eras."}]},
 {"np":"in die Länge","verb":"ziehen","plain":"verlängern","en":"to drag out, to prolong (unnecessarily)","lv":"B2","vdecoys":["bringen","führen","setzen"],"pdecoys":["verkürzen","abbrechen","beschleunigen"],"pAlt":["hinauszögern"],"note":"Negative nuance: longer than necessary. Reflexive use is common: sich in die Länge ziehen.","ex":[{"de":"Der Redner zog seinen Vortrag unnötig in die Länge.","en":"The speaker unnecessarily dragged out his talk."},{"de":"Die Firma will das Verfahren nicht weiter in die Länge ziehen.","en":"The company does not want to drag the proceedings out any further."},{"de":"Die Besprechung zog sich bis zum Abend in die Länge.","en":"The meeting dragged on until the evening."}],"exPlain":[{"de":"Der Redner verlängerte seinen Vortrag unnötig.","en":"The speaker unnecessarily prolonged his talk."}]},
 {"np":"zu Rate","verb":"ziehen","plain":"konsultieren","en":"to consult","lv":"C1","vdecoys":["nehmen","holen","setzen"],"pdecoys":["behandeln","bezahlen","vermeiden"],"note":"Formal. Also: Rat holen, um Rat fragen (everyday).","ex":[{"de":"Bei Zweifeln sollte man einen Fachmann zu Rate ziehen.","en":"When in doubt you should consult an expert."},{"de":"Sie zog ihren Anwalt zu Rate.","en":"She consulted her lawyer."},{"de":"Die Regierung hat mehrere Experten zu Rate gezogen.","en":"The government has consulted several experts."}],"exPlain":[{"de":"Bei Zweifeln sollte man einen Fachmann konsultieren.","en":"When in doubt you should consult an expert."}]},
 {"np":"in Anspruch","verb":"nehmen","plain":"nutzen","en":"to make use of, to claim","lv":"B2","vdecoys":["bringen","stellen","setzen"],"pdecoys":["verweigern","anbieten","verschenken"],"pAlt":["beanspruchen"],"note":"Services and rights: Hilfe, Urlaub, ein Angebot in Anspruch nehmen. With a person as object it means 'to occupy fully': jdn. in Anspruch nehmen.","ex":[{"de":"Viele Eltern nehmen die Beratung der Stadt in Anspruch.","en":"Many parents make use of the city's counselling service."},{"de":"Er hat den Rechtsanwalt nur selten in Anspruch genommen.","en":"He rarely used the services of the lawyer."},{"de":"Die Arbeit nimmt mich völlig in Anspruch.","en":"The work takes up all my time and energy."}],"exPlain":[{"de":"Viele Eltern nutzen die Beratung der Stadt.","en":"Many parents use the city's counselling service."}]},
 {"np":"Abschied","verb":"nehmen","plain":"sich verabschieden","en":"to say goodbye, to take leave","lv":"B1","vdecoys":["machen","halten","sagen"],"pdecoys":["sich entschuldigen","sich bedanken","sich treffen"],"note":"Weightier than a casual farewell; von + Dat. Not 'Abschied machen'. Also: von etwas Abschied nehmen (= to give something up).","ex":[{"de":"Am Bahnhof nahmen wir unter Tränen Abschied voneinander.","en":"At the station we took leave of each other in tears."},{"de":"Er konnte von seinen Freunden nur kurz Abschied nehmen.","en":"He could only say a brief goodbye to his friends."},{"de":"Die Mannschaft nimmt heute von ihrem Trainer Abschied.","en":"The team says goodbye to its coach today."}],"exPlain":[{"de":"Am Bahnhof verabschiedeten wir uns unter Tränen voneinander.","en":"At the station we said goodbye to each other in tears."}]},
 {"np":"Rücksicht","verb":"nehmen","plain":"berücksichtigen","en":"to show consideration","lv":"B1","vdecoys":["machen","geben","bringen"],"pdecoys":["ignorieren","kritisieren","bewundern"],"note":"Pattern: auf jdn./etwas Rücksicht nehmen. berücksichtigen takes a direct object (Akk.) instead of auf and leans towards 'to take into account'. The adjective is rücksichtsvoll; the opposite is rücksichtslos.","ex":[{"de":"In der Bibliothek sollte man auf andere Rücksicht nehmen.","en":"In the library one should be considerate of others."},{"de":"Er nahm keine Rücksicht auf die schlafenden Nachbarn.","en":"He showed no consideration for the sleeping neighbours."},{"de":"Bitte nehmt Rücksicht auf die Kinder!","en":"Please be considerate of the children!"}],"exPlain":[{"de":"Er berücksichtigte die schlafenden Nachbarn nicht.","en":"He did not take the sleeping neighbours into account."}]},
 {"np":"Stellung","verb":"nehmen","plain":"sich äußern","en":"to comment, to state one's position","lv":"B2","vdecoys":["geben","machen","bringen"],"pdecoys":["sich bedanken","sich entschuldigen","sich ärgern"],"pAlt":["kommentieren"],"note":"Pattern: zu + Dat. Stellung nehmen. Stellung beziehen = to take a clear stand.","ex":[{"de":"Der Minister wollte zu den Vorwürfen nicht Stellung nehmen.","en":"The minister did not want to comment on the accusations."},{"de":"Wir bitten Sie, bis Freitag dazu Stellung zu nehmen.","en":"We ask you to comment on it by Friday."},{"de":"Der Vorstand hat zu der Kritik Stellung genommen.","en":"The board has responded to the criticism."}],"exPlain":[{"de":"Der Minister wollte sich zu den Vorwürfen nicht äußern.","en":"The minister did not want to comment on the accusations."}]},
 {"np":"Platz","verb":"nehmen","plain":"sich setzen","en":"to take a seat","lv":"A2","vdecoys":["setzen","stellen","legen"],"pdecoys":["aufstehen","sich legen","hereinkommen"],"note":"Polite and formal. Do not confuse with Platz machen (= to make room) or Platz haben (= to have room).","ex":[{"de":"Nehmen Sie bitte im Wartezimmer Platz.","en":"Please take a seat in the waiting room."},{"de":"Die Gäste nahmen am großen Tisch Platz.","en":"The guests took their seats at the big table."},{"de":"Er hat neben mir Platz genommen.","en":"He sat down next to me."}],"exPlain":[{"de":"Die Gäste setzten sich an den großen Tisch.","en":"The guests sat down at the big table."}]},
 {"np":"Einfluss","verb":"nehmen","plain":"beeinflussen","en":"to exert influence","lv":"B2","vdecoys":["machen","geben","bringen"],"pdecoys":["ignorieren","ablehnen","überprüfen"],"note":"Pattern: auf + Akk. Einfluss nehmen (an action); Einfluss haben (a state).","ex":[{"de":"Die Eltern wollten auf die Berufswahl ihres Sohnes Einfluss nehmen.","en":"The parents wanted to influence their son's choice of career."},{"de":"Medien nehmen stark Einfluss auf die Meinung der Menschen.","en":"The media strongly influence people's opinions."},{"de":"Er hat nie versucht, auf die Entscheidung Einfluss zu nehmen.","en":"He never tried to influence the decision."}],"exPlain":[{"de":"Die Eltern wollten die Berufswahl ihres Sohnes beeinflussen.","en":"The parents wanted to influence their son's choice of career."}]},
 {"np":"Anstoß","verb":"nehmen","plain":"sich stören","en":"to take offence","lv":"C1","vdecoys":["machen","stellen","tun"],"pdecoys":["sich freuen","sich wundern","sich entschuldigen"],"note":"Pattern: an + Dat. Anstoß nehmen. Different meaning: den Anstoß geben (= to initiate); Anstoß erregen (= to cause offence). In football, Anstoß haben = to kick off.","ex":[{"de":"Viele Leser nahmen Anstoß an der derben Sprache.","en":"Many readers took offence at the coarse language."},{"de":"Niemand hat daran Anstoß genommen.","en":"Nobody took offence at it."},{"de":"Sie nimmt an seinem lauten Auftreten Anstoß.","en":"She takes offence at his loud manner."}],"exPlain":[{"de":"Viele Leser störten sich an der derben Sprache.","en":"Many readers were bothered by the coarse language."}]},
 {"np":"zur Kenntnis","verb":"nehmen","plain":"registrieren","en":"to take note of","lv":"B2","vdecoys":["setzen","haben","machen"],"pdecoys":["ignorieren","widersprechen","ablehnen"],"pAlt":["wahrnehmen"],"note":"Can sound cool and detached: you acknowledge something without agreeing. Compare jdn. in Kenntnis setzen (= to inform).","ex":[{"de":"Bitte nehmen Sie zur Kenntnis, dass das Büro am Freitag geschlossen ist.","en":"Please note that the office is closed on Friday."},{"de":"Der Chef hat die Kritik zur Kenntnis genommen, aber nichts geändert.","en":"The boss took note of the criticism but changed nothing."},{"de":"Ich nehme zur Kenntnis, dass du anderer Meinung bist.","en":"I note that you are of a different opinion."}],"exPlain":[{"de":"Der Chef hat die Kritik registriert, aber nichts geändert.","en":"The boss registered the criticism but changed nothing."}]},
 {"np":"in Schutz","verb":"nehmen","plain":"verteidigen","en":"to defend, to stick up for","lv":"B2","vdecoys":["stellen","setzen","legen"],"pdecoys":["beschuldigen","bestrafen","belohnen"],"note":"Pattern: jdn. (vor/gegen etwas) in Schutz nehmen; usually about words, not physical defence.","ex":[{"de":"Die Lehrerin nahm den Schüler vor den Vorwürfen in Schutz.","en":"The teacher defended the pupil against the accusations."},{"de":"Er nahm seine Kollegin in Schutz, als der Chef sie kritisierte.","en":"He stuck up for his colleague when the boss criticised her."},{"de":"Warum nimmst du ihn immer in Schutz?","en":"Why do you always stand up for him?"}],"exPlain":[{"de":"Die Lehrerin verteidigte den Schüler gegen die Vorwürfe.","en":"The teacher defended the pupil against the accusations."}]},
 {"np":"ein Bad","verb":"nehmen","plain":"baden","en":"to take a bath","lv":"B1","vdecoys":["halten","bringen","stellen"],"pdecoys":["duschen","schwimmen","sich waschen"],"note":"Slightly formal; in everyday speech people say baden or in die Wanne gehen (sich ein Bad einlassen = to run a bath). Careful: das Bad is also the bathroom, so ein Bad haben = to have a bathroom.","ex":[{"de":"Nach dem Wandern nahm er ein heißes Bad.","en":"After the hike he took a hot bath."},{"de":"Möchtest du lieber duschen oder ein Bad nehmen?","en":"Would you rather have a shower or take a bath?"},{"de":"Sie nimmt jeden Abend ein Bad.","en":"She takes a bath every evening."}],"exPlain":[{"de":"Nach dem Wandern badete er in heißem Wasser.","en":"After the hike he bathed in hot water."}]},
 {"np":"in Angriff","verb":"nehmen","plain":"anpacken","en":"to tackle, to get started on","lv":"B2","vdecoys":["bringen","setzen","stellen"],"pdecoys":["aufschieben","abbrechen","vermeiden"],"pAlt":["angehen"],"note":"For larger tasks and projects, with the idea of starting energetically.","ex":[{"de":"Wir sollten das Problem möglichst bald in Angriff nehmen.","en":"We should tackle the problem as soon as possible."},{"de":"Im Frühjahr nimmt die Stadt den Bau der neuen Schule in Angriff.","en":"In spring the city will start building the new school."},{"de":"Hast du die Steuererklärung schon in Angriff genommen?","en":"Have you started on your tax return yet?"}],"exPlain":[{"de":"Wir sollten das Problem möglichst bald anpacken.","en":"We should tackle the problem as soon as possible."}]},
 {"np":"in Kauf","verb":"nehmen","plain":"akzeptieren","en":"to accept (a disadvantage), to put up with","lv":"B2","vdecoys":["geben","setzen","bringen"],"pdecoys":["vermeiden","verhindern","ablehnen"],"pAlt":["hinnehmen"],"note":"You knowingly accept a negative side effect in order to reach a goal.","ex":[{"de":"Für den Job nimmt sie einen langen Arbeitsweg in Kauf.","en":"For the job she puts up with a long commute."},{"de":"Die Firma nahm hohe Verluste in Kauf, um den Auftrag zu bekommen.","en":"The company accepted heavy losses to get the contract."},{"de":"Wer billig fliegt, muss manche Nachteile in Kauf nehmen.","en":"Anyone who flies cheaply has to put up with some disadvantages."}],"exPlain":[{"de":"Für den Job akzeptiert sie einen langen Arbeitsweg.","en":"For the job she accepts a long commute."}]},
 {"np":"zu Hilfe","verb":"nehmen","plain":"benutzen","en":"to use as an aid","lv":"B2","vdecoys":["bringen","setzen","stellen"],"pdecoys":["verlieren","ablehnen","verbieten"],"pAlt":["verwenden"],"note":"Do not confuse with jdm. zu Hilfe kommen / eilen (= to come to someone's aid).","ex":[{"de":"Zum Verstehen des Textes nahm er ein Wörterbuch zu Hilfe.","en":"To understand the text he used a dictionary."},{"de":"Nimm doch den Taschenrechner zu Hilfe!","en":"Why not use the calculator?"},{"de":"Die Polizei nahm einen Spürhund zu Hilfe.","en":"The police made use of a sniffer dog."}],"exPlain":[{"de":"Zum Verstehen des Textes benutzte er ein Wörterbuch.","en":"To understand the text he used a dictionary."}]},
 {"np":"Einsicht","verb":"nehmen","plain":"einsehen","en":"to inspect (documents)","lv":"C1","vdecoys":["machen","bringen","tun"],"pdecoys":["einreichen","ändern","verfassen"],"note":"Officialese: Einsicht in + Akk. nehmen. 'Einsehen' can also mean 'to realise, to admit' (Ich sehe meinen Fehler ein).","ex":[{"de":"Die Anwohner können beim Bauamt in die Pläne Einsicht nehmen.","en":"Residents can inspect the plans at the building office."},{"de":"Sie nahm Einsicht in die Akten.","en":"She inspected the files."},{"de":"Er verlangte, Einsicht in die Unterlagen zu nehmen.","en":"He demanded to inspect the documents."}],"exPlain":[{"de":"Die Anwohner können die Pläne beim Bauamt einsehen.","en":"Residents can look at the plans at the building office."}]},
 {"np":"Bezug","verb":"nehmen","plain":"sich beziehen","en":"to refer to","lv":"C1","vdecoys":["geben","machen","bringen"],"pdecoys":["sich erinnern","sich widersetzen","sich verabschieden"],"note":"Business and official letters; Bezug nehmen auf + Akk. Not the same as Bezug haben (= to be related to).","ex":[{"de":"Ich nehme Bezug auf Ihr Schreiben vom 12. März.","en":"I am referring to your letter of 12 March."},{"de":"In seiner Rede nahm der Präsident mehrfach Bezug auf die Geschichte des Landes.","en":"In his speech the president repeatedly referred to the country's history."},{"de":"Worauf nimmst du Bezug?","en":"What are you referring to?"}],"exPlain":[{"de":"Ich beziehe mich auf Ihr Schreiben vom 12. März.","en":"I am referring to your letter of 12 March."}]},
 {"np":"Kontakt","verb":"aufnehmen","plain":"kontaktieren","en":"to get in touch, to make contact","lv":"B1","vdecoys":["bringen","tun","treffen"],"pdecoys":["begrüßen","einladen","vermeiden"],"note":"Separable verb: nimmt ... Kontakt auf. Pattern: mit (or zu) + Dat. Kontakt aufnehmen; kontaktieren takes a direct object (Akk.). Avoid 'Kontakt machen' in this sense (colloquial/electrical only); Swiss German also says Kontakt nehmen.","ex":[{"de":"Bitte nehmen Sie mit unserem Kundenservice Kontakt auf.","en":"Please get in touch with our customer service."},{"de":"Ich habe gestern Kontakt mit der Vermieterin aufgenommen.","en":"I contacted the landlady yesterday."},{"de":"Er nahm zu seinen Verwandten in Kanada Kontakt auf.","en":"He got in touch with his relatives in Canada."}],"exPlain":[{"de":"Bitte kontaktieren Sie unseren Kundenservice.","en":"Please contact our customer service."}]},
 {"np":"um Entschuldigung","verb":"bitten","plain":"sich entschuldigen","en":"to apologise","lv":"B1","vdecoys":["fragen","sagen","rufen"],"pdecoys":["sich bedanken","sich beschweren","sich verabschieden"],"note":"Not 'um Entschuldigung fragen'. jdn. um Entschuldigung bitten (Akk. + um), but sich bei jdm. entschuldigen (bei + Dat.). Entschuldigung! alone can also mean 'excuse me'.","ex":[{"de":"Er bat sie um Entschuldigung für seine späte Antwort.","en":"He apologised to her for his late reply."},{"de":"Ich möchte alle um Entschuldigung bitten, die ich gestört habe.","en":"I would like to apologise to everyone I disturbed."},{"de":"Die Firma hat die Kunden um Entschuldigung gebeten.","en":"The company apologised to its customers."}],"exPlain":[{"de":"Er entschuldigte sich bei ihr für seine späte Antwort.","en":"He apologised to her for his late reply."}]},
 {"np":"in Urlaub","verb":"fahren","plain":"verreisen","en":"to go on holiday","lv":"A2","vdecoys":["machen","laufen","nehmen"],"pdecoys":["umziehen","arbeiten","pendeln"],"vAlt":["gehen","fliegen"],"note":"Not 'in Urlaub machen' or 'in Urlaub nehmen': say Urlaub machen / Urlaub nehmen (without in) or in Urlaub fahren / gehen / sein. verreisen is wider (any trip away, also on business).","ex":[{"de":"Im Sommer fahren wir für zwei Wochen in Urlaub.","en":"In summer we are going on holiday for two weeks."},{"de":"Fährst du dieses Jahr in Urlaub?","en":"Are you going on holiday this year?"},{"de":"Sie sind letztes Jahr nicht in Urlaub gefahren.","en":"They did not go on holiday last year."}],"exPlain":[{"de":"Im Sommer verreisen wir für zwei Wochen.","en":"In summer we are going away for two weeks."}]},
 {"np":"Bescheid","verb":"sagen","plain":"informieren","en":"to let (someone) know","lv":"A2","vdecoys":["machen","stellen","erzählen"],"pdecoys":["fragen","besuchen","einladen"],"vAlt":["geben"],"note":"jdm. Bescheid sagen / geben = to tell someone what you know or decided (dative; informieren takes the accusative). Compare: Bescheid wissen (= to be in the know).","ex":[{"de":"Sag mir bitte Bescheid, wenn du ankommst.","en":"Please let me know when you arrive."},{"de":"Ich habe den Kollegen schon Bescheid gesagt.","en":"I have already told my colleagues."},{"de":"Wir sagen Ihnen morgen Bescheid.","en":"We will let you know tomorrow."}],"exPlain":[{"de":"Informier mich bitte, wenn du ankommst.","en":"Please inform me when you arrive."}]},
 {"np":"Wirkung","verb":"zeigen","plain":"wirken","en":"to take effect, to work","lv":"B2","vdecoys":["stellen","geben","bringen"],"pdecoys":["versagen","scheitern","ausbleiben"],"note":"Also Wirkung erzielen, seine Wirkung tun. Wirkung haben describes the effect itself, Wirkung zeigen that it becomes visible.","ex":[{"de":"Das Medikament zeigt schon nach einer Stunde Wirkung.","en":"The medicine takes effect after just one hour."},{"de":"Die Sparmaßnahmen zeigten keine Wirkung.","en":"The savings measures had no effect."},{"de":"Wann zeigt der Tee Wirkung?","en":"When does the tea start to work?"}],"exPlain":[{"de":"Das Medikament wirkt schon nach einer Stunde.","en":"The medicine works after just one hour."}]},
 {"np":"Interesse","verb":"zeigen","plain":"sich interessieren","en":"to show interest","lv":"B1","vdecoys":["machen","geben","bringen"],"pdecoys":["sich ärgern","sich langweilen","sich beschweren"],"note":"zeigen = visible signs of interest; Interesse haben = inner state. Pattern: Interesse an + Dat. or für + Akk. zeigen; sich interessieren takes für + Akk.","ex":[{"de":"Die Kinder zeigten großes Interesse an dem Experiment.","en":"The children showed great interest in the experiment."},{"de":"Er zeigt Interesse an der Stelle.","en":"He is showing interest in the position."},{"de":"Mehrere Firmen haben Interesse an dem Grundstück gezeigt.","en":"Several companies have shown interest in the plot of land."}],"exPlain":[{"de":"Die Kinder interessierten sich sehr für das Experiment.","en":"The children were very interested in the experiment."}]},
 {"np":"Beachtung","verb":"schenken","plain":"beachten","en":"to pay attention to","lv":"B2","vdecoys":["machen","nehmen","bringen"],"pdecoys":["ignorieren","vergessen","kritisieren"],"note":"Dative object: jdm./einer Sache Beachtung schenken; beachten takes the accusative. Often negated. Beachtung finden = to get attention.","ex":[{"de":"Die Medien schenkten dem Vorfall kaum Beachtung.","en":"The media paid hardly any attention to the incident."},{"de":"Er schenkte ihrem Rat keine Beachtung.","en":"He paid no attention to her advice."},{"de":"Dieser Frage sollte man mehr Beachtung schenken.","en":"More attention should be paid to this question."}],"exPlain":[{"de":"Die Medien beachteten den Vorfall kaum.","en":"The media paid hardly any attention to the incident."}]},
 {"np":"Vertrauen","verb":"schenken","plain":"vertrauen","en":"to place trust in","lv":"B2","vdecoys":["machen","legen","stellen"],"pdecoys":["misstrauen","kontrollieren","verraten"],"note":"Dative of the person: jdm. Vertrauen schenken. It sounds warmer and more deliberate than vertrauen.","ex":[{"de":"Ich schenke ihm mein ganzes Vertrauen.","en":"I place my complete trust in him."},{"de":"Wem schenkst du eigentlich dein Vertrauen?","en":"Whom do you actually trust?"},{"de":"Die Kunden schenkten dem neuen Anbieter nur langsam Vertrauen.","en":"The customers only slowly came to trust the new provider."}],"exPlain":[{"de":"Ich vertraue ihm vollkommen.","en":"I trust him completely."}]},
 {"np":"Glauben","verb":"schenken","plain":"glauben","en":"to believe (someone), to give credence to","lv":"C1","vdecoys":["geben","stellen","legen"],"pdecoys":["bezweifeln","widersprechen","vergessen"],"note":"Formal and mostly negated; dative of the person or statement.","ex":[{"de":"Niemand wollte seiner Erklärung Glauben schenken.","en":"Nobody wanted to believe his explanation."},{"de":"Dem Zeugen schenkte das Gericht keinen Glauben.","en":"The court did not believe the witness."},{"de":"Wer schenkt solchen Gerüchten schon Glauben?","en":"Who gives credence to such rumours anyway?"}],"exPlain":[{"de":"Niemand wollte seiner Erklärung glauben.","en":"Nobody wanted to believe his explanation."}]},
 {"np":"auf die Nerven","verb":"gehen","plain":"nerven","en":"to get on someone's nerves","lv":"B1","vdecoys":["treten","laufen","kommen"],"pdecoys":["beruhigen","helfen","gefallen"],"pAlt":["stören"],"note":"Colloquial; the person affected is in the dative (mir, uns), while nerven takes the accusative (mich, uns).","ex":[{"de":"Der ständige Lärm geht mir auf die Nerven.","en":"The constant noise gets on my nerves."},{"de":"Dein Gejammer ging uns allen auf die Nerven.","en":"Your moaning got on all our nerves."},{"de":"Geht dir die Hitze auch so auf die Nerven?","en":"Is the heat getting on your nerves too?"}],"exPlain":[{"de":"Der ständige Lärm nervt mich.","en":"The constant noise annoys me."}]},
 {"np":"aus dem Weg","verb":"gehen","plain":"meiden","en":"to avoid, to steer clear of","lv":"B2","vdecoys":["fallen","liegen","sitzen"],"pdecoys":["suchen","begegnen","erwarten"],"pAlt":["vermeiden"],"note":"Dative object: jdm./einer Sache aus dem Weg gehen; meiden takes the accusative. Related: jdm. aus dem Weg bleiben (= to stay out of someone's way).","ex":[{"de":"Er geht jedem Streit aus dem Weg.","en":"He avoids every quarrel."},{"de":"Sie ging ihrem Ex-Mann nach der Trennung lange aus dem Weg.","en":"After the separation she kept out of her ex-husband's way for a long time."},{"de":"Konflikten gehe ich lieber aus dem Weg.","en":"I prefer to avoid conflicts."}],"exPlain":[{"de":"Er meidet jeden Streit.","en":"He avoids every quarrel."}]},
 {"np":"im Trend","verb":"liegen","plain":"modern sein","en":"to be trendy","lv":"B2","vdecoys":["gehen","laufen","fallen"],"pdecoys":["veraltet sein","teuer sein","selten sein"],"vAlt":["sein"],"pAlt":["angesagt sein"],"note":"Often voll im Trend liegen.","ex":[{"de":"Nachhaltige Mode liegt voll im Trend.","en":"Sustainable fashion is very much in vogue."},{"de":"Kleine Smartphones lagen lange nicht im Trend.","en":"Small smartphones were not trendy for a long time."},{"de":"Liegen Retro-Möbel immer noch im Trend?","en":"Are retro furnishings still trendy?"}],"exPlain":[{"de":"Nachhaltige Mode ist sehr modern.","en":"Sustainable fashion is very fashionable."}]},
 {"np":"auf der Hand","verb":"liegen","plain":"offensichtlich sein","en":"to be obvious","lv":"C1","vdecoys":["gehen","kommen","fallen"],"pdecoys":["verborgen sein","unklar sein","falsch sein"],"pAlt":["klar sein"],"note":"Idiom; the subject is a thing (Lösung, Grund, Vorteil), not a person.","ex":[{"de":"Die Lösung des Problems liegt doch auf der Hand.","en":"The solution to the problem is surely obvious."},{"de":"Es liegt auf der Hand, dass die Preise weiter steigen.","en":"It is obvious that prices will keep rising."},{"de":"Die Gründe für den Misserfolg lagen auf der Hand.","en":"The reasons for the failure were obvious."}],"exPlain":[{"de":"Die Lösung des Problems ist doch offensichtlich.","en":"The solution to the problem is surely obvious."}]},
 {"np":"einen Vortrag","verb":"halten","plain":"referieren","en":"to give a talk","lv":"B1","vdecoys":["sagen","stellen","führen"],"pdecoys":["zuhören","schreiben","diskutieren"],"note":"Standard combination with halten; colloquially also einen Vortrag machen. 'Referieren' is more formal.","ex":[{"de":"Der Professor hält morgen einen Vortrag über Klimaschutz.","en":"The professor is giving a talk on climate protection tomorrow."},{"de":"Sie hat auf der Konferenz einen Vortrag gehalten.","en":"She gave a talk at the conference."},{"de":"Wer hält den Vortrag?","en":"Who is giving the talk?"}],"exPlain":[{"de":"Der Professor referiert morgen über Klimaschutz.","en":"The professor is giving a talk on climate protection tomorrow."}]},
 {"np":"eine Rede","verb":"halten","plain":"reden","en":"to give a speech","lv":"B1","vdecoys":["geben","sprechen","sagen"],"pdecoys":["schweigen","flüstern","singen"],"note":"Not 'eine Rede geben' (English 'give'). Related: einen Toast ausbringen (a toast), eine Ansprache halten.","ex":[{"de":"Der Bürgermeister hielt vor den Gästen eine kurze Rede.","en":"The mayor gave a short speech to the guests."},{"de":"Zum Abschied hielt die Chefin eine Rede.","en":"The boss gave a speech as a farewell."},{"de":"Wer hält bei der Hochzeit eine Rede?","en":"Who is giving a speech at the wedding?"}],"exPlain":[{"de":"Der Bürgermeister redete kurz zu den Gästen.","en":"The mayor spoke briefly to the guests."}],"pAlt":["sprechen"]},
 {"np":"ein Versprechen","verb":"halten","plain":"einhalten","en":"to keep a promise","lv":"B1","vdecoys":["tragen","führen","stellen"],"pdecoys":["brechen","vergeben","versprechen"],"pAlt":["erfüllen"],"note":"Also: Wort halten (= to keep one's word). Opposite: ein Versprechen brechen.","ex":[{"de":"Er hat sein Versprechen gehalten und kam pünktlich.","en":"He kept his promise and arrived on time."},{"de":"Politiker sollten ihre Versprechen halten.","en":"Politicians should keep their promises."},{"de":"Warum hältst du dein Versprechen nicht?","en":"Why don't you keep your promise?"}],"exPlain":[{"de":"Er hat sein Versprechen eingehalten und kam pünktlich.","en":"He kept his promise and arrived on time."}]},
 {"np":"Schritt","verb":"halten","plain":"mithalten","en":"to keep pace","lv":"B2","vdecoys":["machen","bleiben","stehen"],"pdecoys":["zurückbleiben","aufgeben","überholen"],"note":"Pattern: mit jdm./etwas Schritt halten. Figurative for developments, speed, performance.","ex":[{"de":"Kleine Firmen können mit den Konzernen kaum Schritt halten.","en":"Small firms can hardly keep pace with the big corporations."},{"de":"Der Hund konnte mit dem Fahrrad nicht mehr Schritt halten.","en":"The dog could no longer keep up with the bicycle."},{"de":"Die Löhne halten mit den Preisen nicht Schritt.","en":"Wages are not keeping pace with prices."}],"exPlain":[{"de":"Kleine Firmen können mit den Konzernen kaum mithalten.","en":"Small firms can hardly keep up with the big corporations."}]},
 {"np":"Rücksprache","verb":"halten","plain":"sich beraten","en":"to consult, to check back","lv":"C1","vdecoys":["stellen","geben","bringen"],"pdecoys":["sich beschweren","sich verabschieden","sich entschuldigen"],"vAlt":["nehmen"],"pAlt":["sich besprechen","sich absprechen"],"note":"Business German; mit + Dat. Rücksprache nehmen is also used.","ex":[{"de":"Ich muss erst mit meinem Chef Rücksprache halten.","en":"I first have to check with my boss."},{"de":"Die Ärztin hielt mit dem Kollegen Rücksprache.","en":"The doctor consulted her colleague."},{"de":"Bitte halten Sie vor der Bestellung Rücksprache mit der Einkaufsabteilung.","en":"Please check with the purchasing department before ordering."}],"exPlain":[{"de":"Ich muss mich erst mit meinem Chef beraten.","en":"I first have to consult my boss."}]},
 {"np":"für wahr","verb":"halten","plain":"glauben","en":"to believe, to take to be true","lv":"C1","vdecoys":["machen","ziehen","sehen"],"pdecoys":["bezweifeln","erfinden","behaupten"],"note":"Pattern: etwas für + Adjektiv halten (für richtig, für möglich, für unmöglich).","ex":[{"de":"Viele Menschen halten die Gerüchte für wahr.","en":"Many people take the rumours to be true."},{"de":"Er hielt ihre Geschichte für wahr.","en":"He believed her story."},{"de":"Warum haltet ihr das für wahr?","en":"Why do you take that to be true?"}],"exPlain":[{"de":"Viele Menschen glauben die Gerüchte.","en":"Many people believe the rumours."}]},
 {"np":"im Auge","verb":"behalten","plain":"beobachten","en":"to keep an eye on","lv":"B2","vdecoys":["bewahren","tragen","lassen"],"pdecoys":["übersehen","vergessen","ignorieren"],"note":"Also im Auge haben (= to have in mind). With a goal it means 'to keep in mind': Das Ziel im Auge behalten.","ex":[{"de":"Wir sollten die Entwicklung der Preise im Auge behalten.","en":"We should keep an eye on the development of prices."},{"de":"Behalte die Kinder bitte im Auge!","en":"Please keep an eye on the children!"},{"de":"Die Polizei behielt den Verdächtigen im Auge.","en":"The police kept the suspect under observation."}],"exPlain":[{"de":"Wir sollten die Entwicklung der Preise beobachten.","en":"We should observe the development of prices."}]},
 {"np":"auf dem Laufenden","verb":"halten","plain":"informieren","en":"to keep informed","lv":"B2","vdecoys":["setzen","geben","stellen"],"pdecoys":["beraten","besuchen","verwarnen"],"pAlt":["unterrichten"],"note":"The state is auf dem Laufenden sein or bleiben (to be or stay up to date).","ex":[{"de":"Bitte halten Sie mich über die Entwicklung auf dem Laufenden.","en":"Please keep me posted on developments."},{"de":"Die Redaktion hält ihre Leser ständig auf dem Laufenden.","en":"The editorial team keeps its readers constantly up to date."},{"de":"Ich halte dich auf dem Laufenden, sobald ich Neuigkeiten habe.","en":"I'll keep you posted as soon as I have news."}],"exPlain":[{"de":"Bitte informieren Sie mich über die Entwicklung.","en":"Please inform me about developments."}]},
 {"np":"ins Gewicht","verb":"fallen","plain":"wichtig sein","en":"to matter, to carry weight","lv":"C1","vdecoys":["gehen","kommen","liegen"],"pdecoys":["teuer sein","billig sein","wachsen"],"note":"Mostly with kaum, nicht, schwer: schwer ins Gewicht fallen = to weigh heavily. Don't translate 'fallen' or 'Gewicht' literally.","ex":[{"de":"Der Preisunterschied fällt bei dieser Menge kaum ins Gewicht.","en":"The price difference hardly matters with this quantity."},{"de":"Beim Verkauf fällt vor allem die Lage ins Gewicht.","en":"When selling, the location is above all what counts."},{"de":"Ein paar Minuten Verspätung fallen nicht ins Gewicht.","en":"A few minutes' delay doesn't matter."}],"exPlain":[{"de":"Der Preisunterschied ist bei dieser Menge kaum wichtig.","en":"The price difference is hardly important with this quantity."}]},
 {"np":"in Ohnmacht","verb":"fallen","plain":"ohnmächtig werden","en":"to faint","lv":"B2","vdecoys":["gehen","laufen","treten"],"pdecoys":["einschlafen","erschrecken","sterben"],"note":"Colloquially also umkippen. Aus der Ohnmacht erwachen = to come round.","ex":[{"de":"Bei der Hitze fiel der Schüler plötzlich in Ohnmacht.","en":"In the heat the pupil suddenly fainted."},{"de":"Sie ist vor Schreck fast in Ohnmacht gefallen.","en":"She almost fainted with fright."},{"de":"Wenn ich Blut sehe, falle ich in Ohnmacht.","en":"When I see blood I faint."}],"exPlain":[{"de":"Bei der Hitze wurde der Schüler plötzlich ohnmächtig.","en":"In the heat the pupil suddenly fainted."}]},
 {"np":"ins Wort","verb":"fallen","plain":"unterbrechen","en":"to interrupt (someone)","lv":"B2","vdecoys":["gehen","laufen","treten"],"pdecoys":["antworten","zuhören","widersprechen"],"note":"jdm. ins Wort fallen: the interrupted person is in the dative; unterbrechen takes the accusative.","ex":[{"de":"Er fiel dem Redner mehrmals ins Wort.","en":"He interrupted the speaker several times."},{"de":"Entschuldigung, wenn ich dir ins Wort falle, aber der Bus kommt.","en":"Sorry to interrupt you, but the bus is coming."},{"de":"Sie hasst es, wenn man ihr ins Wort fällt.","en":"She hates it when people interrupt her."}],"exPlain":[{"de":"Er unterbrach den Redner mehrmals.","en":"He interrupted the speaker several times."}]},
 {"np":"im Stich","verb":"lassen","plain":"verlassen","en":"to abandon, to let down","lv":"B2","vdecoys":["halten","geben","bringen"],"pdecoys":["unterstützen","begleiten","besuchen"],"note":"Also for things that fail: Mein Gedächtnis lässt mich im Stich (= my memory fails me).","ex":[{"de":"Er hat seine Freunde in der schwersten Zeit im Stich gelassen.","en":"He abandoned his friends in their hardest time."},{"de":"Die Partei hat ihre Wähler im Stich gelassen.","en":"The party has let its voters down."},{"de":"Ich lasse dich nie im Stich.","en":"I will never let you down."}],"exPlain":[{"de":"Er hat seine Freunde in der schwersten Zeit verlassen.","en":"He left his friends in their hardest time."}]},
 {"np":"außer Acht","verb":"lassen","plain":"ignorieren","en":"to disregard, to leave out of account","lv":"B2","vdecoys":["bringen","setzen","stellen"],"pdecoys":["beachten","bedenken","prüfen"],"pAlt":["vernachlässigen"],"note":"Formal; often with nicht ... außer Acht lassen = to bear in mind.","ex":[{"de":"Bei der Planung wurde ein wichtiger Punkt außer Acht gelassen.","en":"An important point was disregarded in the planning."},{"de":"Man darf die Risiken nicht außer Acht lassen.","en":"One must not ignore the risks."},{"de":"Ich habe die Warnung leider außer Acht gelassen.","en":"Unfortunately I disregarded the warning."}],"exPlain":[{"de":"Bei der Planung wurde ein wichtiger Punkt ignoriert.","en":"An important point was ignored in the planning."}]},
 {"np":"im Gange","verb":"sein","plain":"laufen","en":"to be under way","lv":"B2","vdecoys":["stehen","liegen","kommen"],"pdecoys":["enden","ausfallen","warten"],"note":"Used with sein; often in vollem Gange sein (= to be in full swing).","ex":[{"de":"Die Renovierung ist bereits im Gange.","en":"The renovation is already under way."},{"de":"Seit Monaten sind Gespräche zwischen den Parteien im Gange.","en":"Talks between the parties have been going on for months."},{"de":"Ist das Spiel schon im Gange?","en":"Is the match already under way?"}],"exPlain":[{"de":"Die Renovierung läuft bereits.","en":"The renovation is already under way."}]},
 {"np":"am Leben","verb":"bleiben","plain":"überleben","en":"to stay alive, to survive","lv":"B1","vdecoys":["stehen","liegen","gehen"],"pdecoys":["sterben","verschwinden","aufgeben"],"note":"Related: am Leben sein (= to be alive), am Leben halten (= to keep alive).","ex":[{"de":"Trotz der schweren Verletzung blieb der Patient am Leben.","en":"Despite the serious injury the patient stayed alive."},{"de":"Die Pflanze bleibt auch ohne Wasser lange am Leben.","en":"The plant stays alive for a long time even without water."},{"de":"Wer in der Wüste am Leben bleiben will, braucht Wasser.","en":"Anyone who wants to stay alive in the desert needs water."}],"exPlain":[{"de":"Trotz der schweren Verletzung überlebte der Patient.","en":"Despite the serious injury the patient survived."}]},
 {"np":"auf Ablehnung","verb":"stoßen","plain":"abgelehnt werden","en":"to meet with rejection","lv":"B2","vdecoys":["gehen","fallen","laufen"],"pdecoys":["gelobt werden","gewählt werden","übersehen werden"],"vAlt":["treffen"],"pAlt":["zurückgewiesen werden"],"note":"stoßen auf + Akk. (ist gestoßen). The subject is an idea, plan or proposal. Also bei jdm. auf Ablehnung stoßen.","ex":[{"de":"Der Vorschlag stieß bei den Anwohnern auf Ablehnung.","en":"The proposal met with rejection from the residents."},{"de":"Die neuen Regeln sind bei vielen Schülern auf Ablehnung gestoßen.","en":"The new rules have met with rejection among many pupils."},{"de":"Mit dieser Idee wirst du auf Ablehnung stoßen.","en":"You will meet with rejection with this idea."}],"exPlain":[{"de":"Der Vorschlag wurde von den Anwohnern abgelehnt.","en":"The proposal was rejected by the residents."}]},
 {"np":"auf Kritik","verb":"stoßen","plain":"kritisiert werden","en":"to meet with criticism","lv":"B2","vdecoys":["gehen","fallen","laufen"],"pdecoys":["gelobt werden","ignoriert werden","vergessen werden"],"vAlt":["treffen"],"note":"Passive meaning without agent. Also: auf Zustimmung / Interesse / Widerstand stoßen.","ex":[{"de":"Der Plan stieß in der Presse auf scharfe Kritik.","en":"The plan met with sharp criticism in the press."},{"de":"Die Entscheidung ist bei den Eltern auf Kritik gestoßen.","en":"The decision has met with criticism from the parents."},{"de":"Das neue Gesetz stößt auf immer mehr Kritik.","en":"The new law is meeting with more and more criticism."}],"exPlain":[{"de":"Der Plan wurde in der Presse scharf kritisiert.","en":"The plan was sharply criticised in the press."}]},
 {"np":"in der Lage","verb":"sein","plain":"können","en":"to be able to, to be in a position to","lv":"B2","vdecoys":["stehen","kommen","gehen"],"pdecoys":["wollen","müssen","dürfen"],"pAlt":["imstande sein"],"note":"Followed by zu + Infinitiv. Synonym: imstande sein. More formal than können.","ex":[{"de":"Er ist nicht in der Lage, die Miete zu zahlen.","en":"He is not in a position to pay the rent."},{"de":"Sind Sie in der Lage, Auto zu fahren?","en":"Are you in a fit state to drive?"},{"de":"Nach dem Unfall war sie lange nicht in der Lage zu arbeiten.","en":"After the accident she was unable to work for a long time."}],"exPlain":[{"de":"Er kann die Miete nicht zahlen.","en":"He cannot pay the rent."}]},
 {"np":"im Besitz","verb":"sein","plain":"besitzen","en":"to be in possession of","lv":"B2","vdecoys":["fallen","kommen","gehen"],"pdecoys":["verlieren","verkaufen","brauchen"],"pAlt":["haben"],"note":"Followed by a genitive or by von + Dat.: im Besitz einer Sache / von etwas sein. Formal, mostly legal contexts. Also: etwas steht im Besitz von jdm. (= is owned by).","ex":[{"de":"Er ist im Besitz eines gültigen Führerscheins.","en":"He is in possession of a valid driving licence."},{"de":"Die Familie war lange im Besitz des Schlosses.","en":"The family owned the castle for a long time."},{"de":"Wer im Besitz einer Waffe ist, braucht eine Erlaubnis.","en":"Anyone who possesses a weapon needs a permit."}],"exPlain":[{"de":"Er besitzt einen gültigen Führerschein.","en":"He holds a valid driving licence."}]},
 {"np":"von Bedeutung","verb":"sein","plain":"wichtig sein","en":"to be important, to matter","lv":"B2","vdecoys":["stehen","liegen","fallen"],"pdecoys":["bekannt sein","teuer sein","neu sein"],"vAlt":["bleiben","werden"],"note":"Often von großer / geringer Bedeutung sein; für + Akk.","ex":[{"de":"Für unser Projekt ist diese Information von großer Bedeutung.","en":"This information is of great importance for our project."},{"de":"Seine Meinung war für die Entscheidung nicht von Bedeutung.","en":"His opinion was of no importance for the decision."},{"de":"Was ist für dich im Leben von Bedeutung?","en":"What matters to you in life?"}],"exPlain":[{"de":"Diese Information ist für unser Projekt sehr wichtig.","en":"This information is very important for our project."}]},
 {"np":"ins Gespräch","verb":"kommen","plain":"sich unterhalten","en":"to get talking, to strike up a conversation","lv":"B1","vdecoys":["fallen","laufen","stehen"],"pdecoys":["sich streiten","sich verabschieden","sich vorstellen"],"note":"Pattern: mit jdm. ins Gespräch kommen. kommen marks the start; sich unterhalten names the activity itself. Transitive: etwas ins Gespräch bringen is different (= to bring up a topic).","ex":[{"de":"Auf der Party kam ich mit einem Architekten ins Gespräch.","en":"At the party I got talking to an architect."},{"de":"Im Zug kommt man leicht mit anderen Reisenden ins Gespräch.","en":"On the train you easily get into conversation with other travellers."},{"de":"Wir sind schnell ins Gespräch gekommen.","en":"We quickly got talking."}],"exPlain":[{"de":"Auf der Party unterhielt ich mich bald mit einem Architekten.","en":"At the party I was soon chatting with an architect."}]},
 {"np":"zur Anzeige","verb":"bringen","plain":"anzeigen","en":"to report (to the police)","lv":"B2","vdecoys":["geben","setzen","stellen"],"pdecoys":["verhaften","verurteilen","verteidigen"],"note":"Police and legal register. Everyday: eine Anzeige erstatten, jdn. anzeigen. Intransitive: zur Anzeige kommen.","ex":[{"de":"Der Vermieter brachte den Mieter wegen Sachbeschädigung zur Anzeige.","en":"The landlord reported the tenant for damage to property."},{"de":"Die Nachbarin hat den Vorfall nicht zur Anzeige gebracht.","en":"The neighbour did not report the incident."},{"de":"Wer das Vergehen sieht, sollte es zur Anzeige bringen.","en":"Anyone who sees the offence should report it."}],"exPlain":[{"de":"Der Vermieter zeigte den Mieter wegen Sachbeschädigung an.","en":"The landlord reported the tenant for damage to property."}]},
 {"np":"zur Abstimmung","verb":"bringen","plain":"abstimmen lassen","en":"to put to a vote","lv":"C1","vdecoys":["nehmen","setzen","legen"],"pdecoys":["diskutieren lassen","verschieben","ablehnen"],"vAlt":["stellen"],"note":"Parliamentary and committee language. Intransitive: zur Abstimmung kommen. The plain version needs über + Akk.: über etwas abstimmen lassen.","ex":[{"de":"Der Vorsitzende brachte den Antrag zur Abstimmung.","en":"The chairman put the motion to a vote."},{"de":"Das Gesetz soll noch vor der Sommerpause zur Abstimmung gebracht werden.","en":"The law is to be put to a vote before the summer recess."},{"de":"Wann wird der Vorschlag zur Abstimmung gebracht?","en":"When will the proposal be put to a vote?"}],"exPlain":[{"de":"Der Vorsitzende ließ über den Antrag abstimmen.","en":"The chairman had the motion voted on."}]},
 {"np":"in die Wege","verb":"leiten","plain":"einleiten","en":"to initiate, to set in motion","lv":"C1","vdecoys":["bringen","setzen","stellen"],"pdecoys":["verhindern","beenden","abschaffen"],"pAlt":["veranlassen"],"note":"Formal; the first, preparatory steps are taken. Note the plural: in die Wege leiten.","ex":[{"de":"Die Stadt hat den Bau der neuen Brücke bereits in die Wege geleitet.","en":"The city has already set the construction of the new bridge in motion."},{"de":"Der Ministerin gelang es, die Reform in die Wege zu leiten.","en":"The minister managed to get the reform under way."},{"de":"Wer leitet die nötigen Schritte in die Wege?","en":"Who is initiating the necessary steps?"}],"exPlain":[{"de":"Die Stadt hat den Bau der neuen Brücke bereits eingeleitet.","en":"The city has already initiated the construction of the new bridge."}]},
 {"np":"unter die Lupe","verb":"nehmen","plain":"untersuchen","en":"to scrutinise, to take a close look at","lv":"B2","vdecoys":["stellen","setzen","bringen"],"pdecoys":["ignorieren","vergrößern","verlieren"],"pAlt":["prüfen"],"note":"Figurative: Lupe = magnifying glass.","ex":[{"de":"Die Behörde nimmt die Finanzen des Vereins genau unter die Lupe.","en":"The authority is taking a close look at the club's finances."},{"de":"Experten haben den Fall unter die Lupe genommen.","en":"Experts have scrutinised the case."},{"de":"Wir sollten die Zahlen noch einmal unter die Lupe nehmen.","en":"We should take another close look at the figures."}],"exPlain":[{"de":"Die Behörde untersucht die Finanzen des Vereins genau.","en":"The authority examines the club's finances closely."}]},
 {"np":"zur Debatte","verb":"stehen","plain":"diskutiert werden","en":"to be under discussion, to be at issue","lv":"B2","vdecoys":["liegen","sein","gehen"],"pdecoys":["beschlossen werden","vergessen werden","verboten werden"],"pAlt":["besprochen werden"],"note":"Often negated: steht nicht zur Debatte = is out of the question. Active: etwas zur Debatte stellen (= to put up for discussion).","ex":[{"de":"Auf der Sitzung steht auch das neue Budget zur Debatte.","en":"The new budget is also on the agenda at the meeting."},{"de":"Seine Entlassung stand nie zur Debatte.","en":"His dismissal was never up for discussion."},{"de":"Was genau steht hier zur Debatte?","en":"What exactly is at issue here?"}],"exPlain":[{"de":"Auf der Sitzung wird auch das neue Budget diskutiert.","en":"The new budget is also being discussed at the meeting."}]},
 {"np":"unter Druck","verb":"stehen","plain":"gestresst sein","en":"to be under pressure","lv":"B1","vdecoys":["liegen","sitzen","laufen"],"pdecoys":["entspannt sein","gelangweilt sein","müde sein"],"pAlt":["Stress haben"],"note":"State; the process is unter Druck geraten, the action unter Druck setzen. Also unter Zeitdruck stehen.","ex":[{"de":"Vor den Prüfungen stehen viele Studenten stark unter Druck.","en":"Before the exams many students are under heavy pressure."},{"de":"Das Team steht seit Wochen unter großem Druck.","en":"The team has been under great pressure for weeks."},{"de":"Stehst du gerade unter Druck?","en":"Are you under pressure at the moment?"}],"exPlain":[{"de":"Vor den Prüfungen sind viele Studenten stark gestresst.","en":"Before the exams many students are very stressed."}]},
 {"np":"im Widerspruch","verb":"stehen","plain":"widersprechen","en":"to contradict, to be at odds with","lv":"C1","vdecoys":["sitzen","hängen","gehen"],"pdecoys":["zustimmen","bestätigen","übereinstimmen"],"note":"Pattern: im Widerspruch zu + Dat. stehen; widersprechen takes a direct dative. Beginning of the state: in Widerspruch geraten.","ex":[{"de":"Seine Aussage steht im Widerspruch zu den Beweisen.","en":"His statement contradicts the evidence."},{"de":"Die Zahlen stehen im Widerspruch zu dem, was der Minister behauptet.","en":"The figures contradict what the minister claims."},{"de":"Dein Verhalten steht im Widerspruch zu deinen Worten.","en":"Your behaviour is at odds with your words."}],"exPlain":[{"de":"Seine Aussage widerspricht den Beweisen.","en":"His statement contradicts the evidence."}]},
 {"np":"in Konkurrenz","verb":"stehen","plain":"konkurrieren","en":"to compete, to be in competition","lv":"B2","vdecoys":["sitzen","fallen","machen"],"pdecoys":["zusammenarbeiten","kooperieren","helfen"],"vAlt":["treten"],"note":"State: in Konkurrenz stehen; beginning: in Konkurrenz treten (zu jdm.). Without in: jdm. Konkurrenz machen (= to compete with someone).","ex":[{"de":"Online-Shops stehen in Konkurrenz zu den kleinen Läden.","en":"Online shops are in competition with the small stores."},{"de":"Die Schwestern standen schon als Kinder miteinander in Konkurrenz.","en":"The sisters were already rivals as children."},{"de":"Mit wem stehst du in Konkurrenz?","en":"Who are you competing with?"}],"exPlain":[{"de":"Online-Shops konkurrieren mit den kleinen Läden.","en":"Online shops compete with the small stores."}]},
 {"np":"unter Beobachtung","verb":"stehen","plain":"beobachtet werden","en":"to be under observation","lv":"B2","vdecoys":["fallen","sitzen","gehen"],"pdecoys":["bestraft werden","ignoriert werden","vergessen werden"],"note":"Passive meaning without agent. Active: jdn. unter Beobachtung stellen.","ex":[{"de":"Der Patient steht noch bis morgen unter Beobachtung.","en":"The patient is still under observation until tomorrow."},{"de":"Die Firma steht seit Jahren unter Beobachtung der Behörden.","en":"The company has been under the observation of the authorities for years."},{"de":"Wer unter Beobachtung steht, verhält sich oft anders.","en":"People who are being watched often behave differently."}],"exPlain":[{"de":"Der Patient wird noch bis morgen beobachtet.","en":"The patient is still being observed until tomorrow."}]},
 {"np":"zur Seite","verb":"stehen","plain":"unterstützen","en":"to support, to stand by","lv":"B2","vdecoys":["bleiben","sein","machen"],"pdecoys":["verlassen","kritisieren","stören"],"pAlt":["helfen"],"note":"Dative of the person: jdm. zur Seite stehen; unterstützen takes the accusative.","ex":[{"de":"Die ganze Familie stand ihm in dieser Zeit zur Seite.","en":"His whole family stood by him during this time."},{"de":"Ein erfahrener Kollege steht den Neuen zur Seite.","en":"An experienced colleague supports the newcomers."},{"de":"Wer steht dir bei der Prüfung zur Seite?","en":"Who is supporting you during the exam?"}],"exPlain":[{"de":"Die ganze Familie unterstützte ihn in dieser Zeit.","en":"His whole family supported him during this time."}]},
 {"np":"auf dem Standpunkt","verb":"stehen","plain":"meinen","en":"to take the view, to maintain","lv":"C1","vdecoys":["sitzen","liegen","gehen"],"pdecoys":["bezweifeln","fragen","verbieten"],"note":"Formal; usually followed by a dass-clause. Stronger than meinen: a firm position.","ex":[{"de":"Die Verwaltung steht auf dem Standpunkt, dass der Antrag zu spät kam.","en":"The administration takes the view that the application came too late."},{"de":"Ich stand schon immer auf dem Standpunkt, dass man ehrlich sein sollte.","en":"I have always held the view that one should be honest."},{"de":"Wir stehen auf dem Standpunkt, dass jeder eine zweite Chance verdient.","en":"We take the view that everyone deserves a second chance."}],"exPlain":[{"de":"Die Verwaltung meint, dass der Antrag zu spät kam.","en":"The administration thinks that the application came too late."}]},
 {"np":"im Weg","verb":"stehen","plain":"behindern","en":"to be in the way, to obstruct","lv":"B2","vdecoys":["gehen","fallen","bringen"],"pdecoys":["helfen","begleiten","führen"],"vAlt":["sein","liegen"],"note":"Dative of the person: jdm. im Weg stehen; behindern takes the accusative. Literal and figurative.","ex":[{"de":"Der alte Schrank steht mir im Weg.","en":"The old cupboard is in my way."},{"de":"Niemand wollte ihm bei der Karriere im Weg stehen.","en":"Nobody wanted to stand in the way of his career."},{"de":"Stell das Rad nicht dorthin, da steht es allen im Weg.","en":"Don't put the bike there, it's in everyone's way."}],"exPlain":[{"de":"Niemand wollte ihn bei seiner Karriere behindern.","en":"Nobody wanted to obstruct him in his career."}]},
 {"np":"Schlange","verb":"stehen","plain":"anstehen","en":"to queue, to stand in line","lv":"B1","vdecoys":["sitzen","laufen","gehen"],"pdecoys":["drängeln","überholen","vorlaufen"],"pAlt":["sich anstellen"],"note":"No article: Schlange stehen. Anstehen is common in Austria, Switzerland and parts of Germany; sich anstellen means to join the queue.","ex":[{"de":"Vor dem Museum mussten wir über eine Stunde Schlange stehen.","en":"In front of the museum we had to queue for over an hour."},{"de":"Am Black Friday stehen die Kunden vor dem Laden Schlange.","en":"On Black Friday customers queue in front of the shop."},{"de":"Ich möchte nicht schon wieder an der Kasse Schlange stehen.","en":"I don't want to queue at the checkout again."}],"exPlain":[{"de":"Vor dem Museum mussten wir über eine Stunde anstehen.","en":"In front of the museum we had to queue for over an hour."}]},
 {"np":"eine Entscheidung","verb":"treffen","plain":"entscheiden","en":"to make a decision","lv":"B1","vdecoys":["machen","geben","nehmen"],"pdecoys":["überlegen","planen","verschieben"],"vAlt":["fällen"],"note":"Nicht: eine Entscheidung machen. Eine Entscheidung fällen klingt formeller (Gericht, Gremien).","ex":[{"de":"Wir müssen heute noch eine Entscheidung treffen.","en":"We have to make a decision today."},{"de":"Hast du schon eine Entscheidung getroffen?","en":"Have you made a decision yet?"},{"de":"Der Vorstand traf die Entscheidung ohne lange Diskussion.","en":"The board made the decision without a long discussion."}],"exPlain":[{"de":"Wir müssen heute noch entscheiden.","en":"We have to decide today."},{"de":"Der Vorstand entschied ohne lange Diskussion.","en":"The board decided without a long discussion."}]},
 {"np":"Vorkehrungen","verb":"treffen","plain":"vorsorgen","en":"to take precautions","lv":"B2","vdecoys":["geben","nehmen","halten"],"pdecoys":["vergessen","verzichten","aufschieben"],"note":"Fast immer Plural. Auch: Vorsorge treffen. Formell (Behörden, Versicherungen).","ex":[{"de":"Die Stadt hat Vorkehrungen gegen Hochwasser getroffen.","en":"The city has taken precautions against flooding."},{"de":"Für den Notfall sollte man rechtzeitig Vorkehrungen treffen.","en":"You should take precautions in good time for an emergency."},{"de":"Wir trafen alle nötigen Vorkehrungen, bevor der Sturm kam.","en":"We took all the necessary precautions before the storm arrived."}],"exPlain":[{"de":"Die Stadt hat gegen Hochwasser vorgesorgt.","en":"The city has made provisions against flooding."},{"de":"Für den Notfall sollte man rechtzeitig vorsorgen.","en":"You should make provisions in good time for an emergency."}]},
 {"np":"eine Auswahl","verb":"treffen","plain":"auswählen","en":"to make a selection","lv":"B2","vdecoys":["nehmen","legen","halten"],"pdecoys":["bestellen","vergleichen","sortieren"],"pAlt":["wählen"],"note":"Oft mit aus + Dat.: aus vielen Angeboten eine Auswahl treffen.","ex":[{"de":"Bei so vielen Bewerbungen ist es schwer, eine Auswahl zu treffen.","en":"With so many applications it is hard to make a selection."},{"de":"Der Trainer trifft morgen die endgültige Auswahl für das Team.","en":"The coach will make the final selection for the team tomorrow."},{"de":"Wir haben aus über zweihundert Fotos eine Auswahl getroffen.","en":"We made a selection from over two hundred photos."}],"exPlain":[{"de":"Bei so vielen Bewerbungen ist es schwer auszuwählen.","en":"With so many applications it is hard to choose."},{"de":"Wir haben aus über zweihundert Fotos zwölf ausgewählt.","en":"We selected twelve from over two hundred photos."}]},
 {"np":"eine Vereinbarung","verb":"treffen","plain":"vereinbaren","en":"to make an agreement","lv":"B2","vdecoys":["geben","nehmen","bringen"],"pdecoys":["verlangen","bestellen","bestätigen"],"note":"Passiv ist häufig: Es wurde eine Vereinbarung getroffen. Formell (Verträge, Verwaltung).","ex":[{"de":"Die Nachbarn haben eine Vereinbarung über die Gartenpflege getroffen.","en":"The neighbours have made an agreement about looking after the garden."},{"de":"Bitte treffen Sie vorab eine schriftliche Vereinbarung mit dem Vermieter.","en":"Please make a written agreement with the landlord beforehand."},{"de":"Nach langem Streit trafen die Parteien schließlich eine Vereinbarung.","en":"After a long dispute the parties finally reached an agreement."}],"exPlain":[{"de":"Die Nachbarn haben vereinbart, wer sich um den Garten kümmert.","en":"The neighbours have agreed who will look after the garden."},{"de":"Wir vereinbaren morgen die Lieferzeiten.","en":"We will agree on the delivery times tomorrow."}],"vAlt":["schließen"]},
 {"np":"Vorbereitungen","verb":"treffen","plain":"vorbereiten","en":"to make preparations","lv":"B1","vdecoys":["geben","nehmen","halten"],"pdecoys":["vorstellen","vorschlagen","vorlesen"],"note":"Meist Plural, oft mit für + Akk.: Vorbereitungen für die Reise treffen.","ex":[{"de":"Die Familie trifft schon jetzt Vorbereitungen für die Hochzeit.","en":"The family is already making preparations for the wedding."},{"de":"Wir haben alle nötigen Vorbereitungen für die Reise getroffen.","en":"We have made all the necessary preparations for the trip."},{"de":"Bevor der Gast kam, traf sie noch rasch letzte Vorbereitungen.","en":"Before the guest arrived, she quickly made some last preparations."}],"exPlain":[{"de":"Die Familie bereitet schon jetzt die Hochzeit vor.","en":"The family is already preparing the wedding."},{"de":"Wir haben alles für die Reise vorbereitet.","en":"We have prepared everything for the trip."}]},
 {"np":"Hilfe","verb":"leisten","plain":"helfen","en":"to give help, to assist","lv":"B1","vdecoys":["machen","tun","halten"],"pdecoys":["retten","bitten","brauchen"],"note":"Etwas formeller als helfen. Feste Wendung: Erste Hilfe leisten.","ex":[{"de":"Nach dem Unfall leistete ein Passant sofort Hilfe.","en":"After the accident a passer-by immediately gave assistance."},{"de":"Die Helfer haben den Betroffenen schnell Hilfe geleistet.","en":"The helpers quickly gave assistance to those affected."},{"de":"Wer Hilfe leisten kann, soll sich bitte melden.","en":"Anyone who can help should please come forward."}],"exPlain":[{"de":"Nach dem Unfall half ein Passant sofort.","en":"After the accident a passer-by helped immediately."},{"de":"Die Helfer haben den Betroffenen schnell geholfen.","en":"The helpers quickly helped those affected."}]},
 {"np":"Widerstand","verb":"leisten","plain":"sich wehren","en":"to put up resistance","lv":"B2","vdecoys":["nehmen","geben","halten"],"pdecoys":["nachgeben","gehorchen","aufgeben"],"pAlt":["sich widersetzen"],"note":"Widerstand leisten gegen + Akk. Häufig in Berichten über Polizei und Politik.","ex":[{"de":"Die Demonstranten leisteten gegen die Räumung Widerstand.","en":"The demonstrators put up resistance against the eviction."},{"de":"Er hat bei der Festnahme keinen Widerstand geleistet.","en":"He offered no resistance during the arrest."},{"de":"Die Bevölkerung wollte keinen Widerstand leisten.","en":"The population did not want to put up any resistance."}],"exPlain":[{"de":"Die Demonstranten wehrten sich gegen die Räumung.","en":"The demonstrators resisted the eviction."},{"de":"Er hat sich bei der Festnahme nicht gewehrt.","en":"He did not resist during the arrest."}],"vAlt":["bieten"]},
 {"np":"einen Beitrag","verb":"leisten","plain":"beitragen","en":"to make a contribution","lv":"B2","vdecoys":["treffen","setzen","legen"],"pdecoys":["verhindern","schreiben","fordern"],"note":"Meist mit zu + Dat.: einen Beitrag zum Umweltschutz leisten. Der Beitrag kann auch Geld sein.","ex":[{"de":"Jeder kann einen Beitrag zum Umweltschutz leisten.","en":"Everyone can make a contribution to protecting the environment."},{"de":"Mit ihrer Forschung leistete sie einen wichtigen Beitrag zur Medizin.","en":"With her research she made an important contribution to medicine."},{"de":"Ich möchte gern meinen Beitrag leisten.","en":"I would like to do my bit."}],"exPlain":[{"de":"Jeder kann zum Umweltschutz beitragen.","en":"Everyone can contribute to protecting the environment."},{"de":"Mit ihrer Forschung trug sie wesentlich zur Medizin bei.","en":"With her research she contributed significantly to medicine."}]},
 {"np":"Ersatz","verb":"leisten","plain":"ersetzen","en":"to compensate, to make good a loss","lv":"C1","vdecoys":["machen","halten","tragen"],"pdecoys":["reparieren","versichern","bestellen"],"note":"Rechtssprache, meist Schadenersatz leisten. Nicht verwechseln mit Ersatz sein (stellvertretend).","ex":[{"de":"Die Versicherung muss für den Schaden Ersatz leisten.","en":"The insurance company has to compensate for the damage."},{"de":"Der Verursacher leistete Ersatz für das zerstörte Fenster.","en":"The person responsible paid compensation for the broken window."}],"exPlain":[{"de":"Die Versicherung muss den Schaden ersetzen.","en":"The insurance company has to cover the damage."},{"de":"Der Verursacher ersetzte den Schaden am Fenster.","en":"The person responsible paid for the damage to the window."}]},
 {"np":"einen Eid","verb":"leisten","plain":"schwören","en":"to take an oath","lv":"C1","vdecoys":["machen","geben","bringen"],"pdecoys":["beichten","verzeihen","verraten"],"vAlt":["ablegen"],"note":"Amtlich und feierlich: einen Eid leisten oder ablegen; auch Amtseid, Treueeid.","ex":[{"de":"Der Zeuge leistete vor Gericht einen Eid.","en":"The witness took an oath in court."},{"de":"Die neuen Minister leisten morgen ihren Amtseid.","en":"The new ministers will take their oath of office tomorrow."},{"de":"Soldaten mussten früher einen Eid auf den König leisten.","en":"In the past soldiers had to swear an oath to the king."}],"exPlain":[{"de":"Der Zeuge schwor vor Gericht, die Wahrheit zu sagen.","en":"The witness swore in court to tell the truth."},{"de":"Soldaten mussten früher dem König Treue schwören.","en":"In the past soldiers had to swear loyalty to the king."}]},
 {"np":"Unterstützung","verb":"leisten","plain":"unterstützen","en":"to give support","lv":"B2","vdecoys":["machen","bringen","nehmen"],"pdecoys":["anfordern","danken","ablehnen"],"note":"Formell: Unterstützung leisten bei + Dat. Gegenstück aus Sicht des Empfängers: Unterstützung erfahren.","ex":[{"de":"Das Rote Kreuz leistet den Flutopfern schnelle Unterstützung.","en":"The Red Cross is giving the flood victims fast support."},{"de":"Die Kollegen haben mir bei dem Projekt große Unterstützung geleistet.","en":"My colleagues gave me great support with the project."},{"de":"Wir leisten gern Unterstützung, wenn Sie Fragen haben.","en":"We are happy to provide support if you have any questions."}],"exPlain":[{"de":"Das Rote Kreuz unterstützt die Flutopfer schnell.","en":"The Red Cross is quickly supporting the flood victims."},{"de":"Die Kollegen haben mich bei dem Projekt sehr unterstützt.","en":"My colleagues supported me a great deal with the project."}],"vAlt":["geben","bieten"]},
 {"np":"einer Aufforderung Folge","verb":"leisten","plain":"befolgen","en":"to comply with a request or order","lv":"C1","vdecoys":["machen","halten","tragen"],"pdecoys":["ablehnen","ignorieren","verlangen"],"note":"Dativ der Sache: einem Befehl, einer Vorladung, einem Aufruf Folge leisten. Amtsdeutsch (Polizei, Behörden).","ex":[{"de":"Der Fahrer leistete der Aufforderung der Polizei sofort Folge.","en":"The driver immediately complied with the police's request."},{"de":"Wer der Vorladung nicht Folge leistet, muss mit einer Strafe rechnen.","en":"Anyone who does not comply with the summons must expect a penalty."},{"de":"Wir haben dem Aufruf gern Folge geleistet.","en":"We gladly followed the appeal."}],"exPlain":[{"de":"Der Fahrer befolgte die Aufforderung der Polizei sofort.","en":"The driver immediately followed the police's request."},{"de":"Wer die Vorladung nicht befolgt, muss mit einer Strafe rechnen.","en":"Anyone who does not follow the summons must expect a penalty."}]},
 {"np":"Kritik","verb":"üben","plain":"kritisieren","en":"to criticise","lv":"B2","vdecoys":["machen","halten","stellen"],"pdecoys":["loben","bewundern","überprüfen"],"vAlt":["äußern"],"note":"Kritik üben an + Dat. Gehoben, häufig in Nachrichten und Kommentaren.","ex":[{"de":"Die Opposition übte scharfe Kritik an dem Gesetz.","en":"The opposition sharply criticised the law."},{"de":"An der Arbeit anderer Kritik zu üben ist leicht.","en":"It is easy to criticise other people's work."},{"de":"Viele Leser haben Kritik an dem Artikel geübt.","en":"Many readers have criticised the article."}],"exPlain":[{"de":"Die Opposition kritisierte das Gesetz scharf.","en":"The opposition sharply criticised the law."},{"de":"Viele Leser haben den Artikel kritisiert.","en":"Many readers have criticised the article."}]},
 {"np":"Druck","verb":"ausüben","plain":"drängen","en":"to put pressure (on someone)","lv":"B2","vdecoys":["geben","legen","stellen"],"pdecoys":["bitten","empfehlen","überzeugen"],"note":"Das Verb ist ausüben (trennbar), nicht üben. Druck ausüben auf + Akk. Umgangssprachlich auch: Druck machen.","ex":[{"de":"Der Chef übt starken Druck auf die Mitarbeiter aus.","en":"The boss puts heavy pressure on the staff."},{"de":"Die Eltern haben keinen Druck auf ihn ausgeübt.","en":"His parents did not put any pressure on him."},{"de":"Die Gewerkschaft will Druck ausüben, damit die Löhne steigen.","en":"The union wants to apply pressure so that wages rise."}],"exPlain":[{"de":"Der Chef drängt die Mitarbeiter zu mehr Leistung.","en":"The boss pushes the staff to perform more."},{"de":"Die Eltern haben ihn nicht gedrängt.","en":"His parents did not push him."}]},
 {"np":"Einfluss","verb":"ausüben","plain":"beeinflussen","en":"to exert influence","lv":"B2","vdecoys":["machen","geben","setzen"],"pdecoys":["überzeugen","beraten","kontrollieren"],"vAlt":["nehmen"],"note":"Das Verb ist ausüben (trennbar). Einfluss ausüben/nehmen auf + Akk. Einfluss haben beschreibt nur den Zustand.","ex":[{"de":"Soziale Medien üben großen Einfluss auf Jugendliche aus.","en":"Social media exert great influence on young people."},{"de":"Er hat versucht, Einfluss auf die Entscheidung auszuüben.","en":"He tried to exert influence on the decision."},{"de":"Die Lobby übte jahrelang Einfluss auf die Gesetzgebung aus.","en":"For years the lobby exerted influence on legislation."}],"exPlain":[{"de":"Soziale Medien beeinflussen Jugendliche stark.","en":"Social media strongly influence young people."},{"de":"Er hat versucht, die Entscheidung zu beeinflussen.","en":"He tried to influence the decision."}]},
 {"np":"Zurückhaltung","verb":"üben","plain":"sich zurückhalten","en":"to exercise restraint","lv":"C1","vdecoys":["machen","geben","halten"],"pdecoys":["zögern","ausweichen","verbergen"],"note":"Gehoben, oft in Politik und Medien: bei etwas Zurückhaltung üben.","ex":[{"de":"Die Regierung bat die Medien, bei der Berichterstattung Zurückhaltung zu üben.","en":"The government asked the media to show restraint in their reporting."},{"de":"Wir sollten in dieser Frage Zurückhaltung üben.","en":"We should exercise restraint on this question."},{"de":"Die Polizei übte bei der Demonstration bewusst Zurückhaltung.","en":"The police deliberately showed restraint at the demonstration."}],"exPlain":[{"de":"Die Regierung bat die Medien, sich bei der Berichterstattung zurückzuhalten.","en":"The government asked the media to hold back in their reporting."},{"de":"Die Polizei hielt sich bei der Demonstration bewusst zurück.","en":"The police deliberately held back at the demonstration."}]},
 {"np":"Verzicht","verb":"üben","plain":"verzichten","en":"to forgo, to practise self-denial","lv":"B2","vdecoys":["machen","geben","nehmen"],"pdecoys":["verlangen","hoffen","bedauern"],"note":"Verzicht üben auf + Akk.; gehoben, oft bei Fasten, Konsum, Umweltschutz.","ex":[{"de":"In der Fastenzeit üben viele Menschen Verzicht auf Süßigkeiten.","en":"During Lent many people give up sweets."},{"de":"Wir müssen alle Verzicht üben, wenn wir das Klima schützen wollen.","en":"We all have to practise self-denial if we want to protect the climate."},{"de":"Er übte jahrelang Verzicht, um das Studium seiner Kinder zu bezahlen.","en":"For years he did without things in order to pay for his children's studies."}],"exPlain":[{"de":"In der Fastenzeit verzichten viele Menschen auf Süßigkeiten.","en":"During Lent many people do without sweets."},{"de":"Wir müssen alle verzichten, wenn wir das Klima schützen wollen.","en":"We all have to do without if we want to protect the climate."}]},
 {"np":"Geduld","verb":"üben","plain":"sich gedulden","en":"to be patient, to exercise patience","lv":"B2","vdecoys":["machen","stellen","halten"],"pdecoys":["schweigen","zögern","sich ausruhen"],"vAlt":["haben"],"note":"Geduld üben betont das bewusste Aushalten; Geduld haben beschreibt eine Eigenschaft.","ex":[{"de":"Beim Warten auf das Visum musste ich viel Geduld üben.","en":"While waiting for the visa I had to be very patient."},{"de":"Bitte üben Sie noch ein wenig Geduld, der Arzt kommt gleich.","en":"Please be patient a little longer, the doctor will be right with you."},{"de":"Eltern üben täglich Geduld mit ihren Kindern.","en":"Parents practise patience with their children every day."}],"exPlain":[{"de":"Beim Warten auf das Visum musste ich mich lange gedulden.","en":"While waiting for the visa I had to wait patiently for a long time."},{"de":"Bitte gedulden Sie sich noch ein wenig, der Arzt kommt gleich.","en":"Please wait a little longer, the doctor will be right with you."}]},
 {"np":"ein Gespräch","verb":"führen","plain":"sich unterhalten","en":"to have a conversation","lv":"B1","vdecoys":["treffen","halten","geben"],"pdecoys":["schweigen","zuhören","verstehen"],"pAlt":["sprechen"],"note":"Oft mit Adjektiv: ein ernstes, vertrauliches Gespräch führen. Im Plural oft offiziell: Gespräche führen (Politik, Wirtschaft).","ex":[{"de":"Der Chef möchte morgen ein Gespräch mit dir führen.","en":"The boss wants to have a talk with you tomorrow."},{"de":"Wir haben lange ein vertrauliches Gespräch geführt.","en":"We had a long confidential conversation."},{"de":"Die Minister führten Gespräche über den Handel.","en":"The ministers held talks about trade."}],"exPlain":[{"de":"Der Chef möchte sich morgen kurz mit dir unterhalten.","en":"The boss wants to have a quick chat with you tomorrow."},{"de":"Wir haben uns lange vertraulich unterhalten.","en":"We talked confidentially for a long time."}],"vAlt":["haben"]},
 {"np":"Verhandlungen","verb":"führen","plain":"verhandeln","en":"to negotiate, to hold negotiations","lv":"B2","vdecoys":["machen","halten","geben"],"pdecoys":["verkaufen","bezahlen","streiten"],"note":"Meist Plural; Verhandlungen führen mit + Dat. über + Akk.","ex":[{"de":"Die Tarifpartner führen seit Wochen Verhandlungen.","en":"The two sides in the pay dispute have been negotiating for weeks."},{"de":"Er führte die Verhandlungen geschickt und erreichte einen niedrigeren Preis.","en":"He negotiated skilfully and got a lower price."},{"de":"Mit dem Vermieter wollen wir keine langen Verhandlungen führen.","en":"We don't want to hold long negotiations with the landlord."}],"exPlain":[{"de":"Die Tarifpartner verhandeln seit Wochen.","en":"The two sides in the pay dispute have been negotiating for weeks."},{"de":"Er verhandelte geschickt und erreichte einen niedrigeren Preis.","en":"He negotiated skilfully and got a lower price."}]},
 {"np":"einen Prozess","verb":"führen","plain":"prozessieren","en":"to conduct a lawsuit, to litigate","lv":"B2","vdecoys":["halten","geben","treffen"],"pdecoys":["verurteilen","verhaften","verteidigen"],"note":"Prozess führen gegen + Akk. (vor Gericht). Hier ist Prozess das Gerichtsverfahren, nicht ein Ablauf.","ex":[{"de":"Die Firma führt seit Jahren einen Prozess gegen ihren früheren Partner.","en":"The company has been litigating against its former partner for years."},{"de":"Er wollte keinen Prozess führen, weil es zu teuer war.","en":"He did not want to go to court because it was too expensive."},{"de":"Der Anwalt hat mehrere Prozesse gegen die Stadt geführt.","en":"The lawyer has conducted several lawsuits against the city."}],"exPlain":[{"de":"Die Firma prozessiert seit Jahren gegen ihren früheren Partner.","en":"The company has been in litigation with its former partner for years."},{"de":"Er wollte nicht prozessieren, weil es zu teuer war.","en":"He did not want to go to court because it was too expensive."}]},
 {"np":"den Beweis","verb":"führen","plain":"beweisen","en":"to furnish proof, to prove","lv":"C1","vdecoys":["machen","setzen","halten"],"pdecoys":["vermuten","behaupten","widerlegen"],"note":"Wissenschafts- und Rechtssprache: den Beweis für etwas führen. Im Alltag: etwas beweisen.","ex":[{"de":"Die Verteidigung konnte den Beweis für seine Unschuld nicht führen.","en":"The defence could not furnish proof of his innocence."},{"de":"In der Mathematik führt man den Beweis oft durch Widerspruch.","en":"In mathematics one often conducts the proof by contradiction."},{"de":"Es gelang ihr, den Beweis zu führen, dass die Daten falsch waren.","en":"She succeeded in proving that the data were wrong."}],"exPlain":[{"de":"Die Verteidigung konnte seine Unschuld nicht beweisen.","en":"The defence could not prove his innocence."},{"de":"Es gelang ihr zu beweisen, dass die Daten falsch waren.","en":"She succeeded in proving that the data were wrong."}]},
 {"np":"Protokoll","verb":"führen","plain":"protokollieren","en":"to keep the minutes","lv":"B2","vdecoys":["halten","treffen","legen"],"pdecoys":["vorlesen","unterschreiben","auswerten"],"vAlt":["schreiben"],"note":"Wer das Protokoll führt, schreibt Sitzung oder Verhandlung mit.","ex":[{"de":"Wer führt heute das Protokoll?","en":"Who is taking the minutes today?"},{"de":"Die Schriftführerin führte bei der Sitzung das Protokoll.","en":"The secretary kept the minutes at the meeting."},{"de":"Er hat jahrelang das Protokoll geführt.","en":"He kept the minutes for years."}],"exPlain":[{"de":"Wer protokolliert heute?","en":"Who is taking the minutes today?"},{"de":"Die Schriftführerin protokollierte die Sitzung.","en":"The secretary recorded the meeting in the minutes."}]},
 {"np":"eine Ehe","verb":"führen","plain":"verheiratet sein","en":"to be married, to have a marriage","lv":"B2","vdecoys":["machen","geben","nehmen"],"pdecoys":["heiraten","sich verloben","sich scheiden lassen"],"note":"Meist mit Adjektiv: eine glückliche, harmonische Ehe führen. Nicht: heiraten (Ereignis).","ex":[{"de":"Meine Großeltern führten fast sechzig Jahre lang eine glückliche Ehe.","en":"My grandparents had a happy marriage for almost sixty years."},{"de":"Sie führen seit Jahren eine harmonische Ehe.","en":"They have had a harmonious marriage for years."},{"de":"Er hat eine unglückliche Ehe geführt und sich dann scheiden lassen.","en":"He was in an unhappy marriage and then got divorced."}],"exPlain":[{"de":"Meine Großeltern waren fast sechzig Jahre lang glücklich verheiratet.","en":"My grandparents were happily married for almost sixty years."}],"vAlt":["haben"]},
 {"np":"ein Leben","verb":"führen","plain":"leben","en":"to lead a life","lv":"B2","vdecoys":["machen","halten","stellen"],"pdecoys":["wohnen","genießen","planen"],"note":"Fast immer mit Adjektiv: ein ruhiges, einfaches, selbstbestimmtes Leben führen.","ex":[{"de":"Seit seiner Pensionierung führt er ein ruhiges Leben auf dem Land.","en":"Since retiring he has led a quiet life in the country."},{"de":"Sie wollte ein selbstbestimmtes Leben führen.","en":"She wanted to lead a self-determined life."},{"de":"Die Familie führte jahrelang ein bescheidenes Leben.","en":"The family led a modest life for years."}],"exPlain":[{"de":"Seit seiner Pensionierung lebt er ruhig auf dem Land.","en":"Since retiring he has lived quietly in the country."},{"de":"Sie wollte selbstbestimmt leben.","en":"She wanted to live in a self-determined way."}]},
 {"np":"Aufsicht","verb":"führen","plain":"beaufsichtigen","en":"to supervise, to be in charge of supervision","lv":"B2","vdecoys":["geben","nehmen","bringen"],"pdecoys":["untersuchen","bestrafen","unterrichten"],"vAlt":["haben"],"note":"Amtlich und in Schulen: bei einer Prüfung, in der Pause Aufsicht führen.","ex":[{"de":"In der Pause führt ein Lehrer Aufsicht auf dem Schulhof.","en":"During the break a teacher is on supervision duty in the schoolyard."},{"de":"Während der Klausur führte eine Kollegin die Aufsicht.","en":"A colleague supervised during the exam."},{"de":"Wer führt am Samstag Aufsicht im Schwimmbad?","en":"Who is supervising at the swimming pool on Saturday?"}],"exPlain":[{"de":"In der Pause beaufsichtigt ein Lehrer die Kinder auf dem Schulhof.","en":"During the break a teacher supervises the children in the schoolyard."},{"de":"Während der Klausur beaufsichtigte eine Kollegin die Schüler.","en":"A colleague supervised the students during the exam."}]},
 {"np":"Regie","verb":"führen","plain":"inszenieren","en":"to direct (a film, play)","lv":"B2","vdecoys":["halten","stellen","legen"],"pdecoys":["schreiben","spielen","produzieren"],"note":"Regie führen bei + Dat.: bei Film, Theater, Oper und Fernsehen.","ex":[{"de":"Bei dem Theaterstück führt ein bekannter Schauspieler Regie.","en":"A well-known actor is directing the play."},{"de":"Sie hat schon bei mehreren Opern Regie geführt.","en":"She has already directed several operas."},{"de":"Wer wird bei der neuen Serie Regie führen?","en":"Who is going to direct the new series?"}],"exPlain":[{"de":"Ein bekannter Schauspieler inszeniert das Theaterstück.","en":"A well-known actor is directing the play."},{"de":"Sie hat schon mehrere Opern inszeniert.","en":"She has already directed several operas."}]},
 {"np":"Anklang","verb":"finden","plain":"gefallen","en":"to meet with approval, to go down well","lv":"C1","vdecoys":["machen","nehmen","geben"],"pdecoys":["klingen","ablehnen","singen"],"note":"Das Subjekt ist die Sache (Idee, Vorschlag), die gut ankommt; wer sie gut findet, steht in bei + Dat.: Anklang finden bei + Dat.","ex":[{"de":"Der Vorschlag fand bei den Kollegen großen Anklang.","en":"The proposal went down very well with the colleagues."},{"de":"Die neue Musik hat bei jungen Leuten viel Anklang gefunden.","en":"The new music has been very popular with young people."},{"de":"Ihre Idee wird sicher Anklang finden.","en":"Her idea will certainly be well received."}],"exPlain":[{"de":"Der Vorschlag gefiel den Kollegen sehr.","en":"The colleagues liked the proposal a lot."},{"de":"Die neue Musik hat jungen Leuten sehr gefallen.","en":"Young people have liked the new music a lot."}]},
 {"np":"Beachtung","verb":"finden","plain":"beachtet werden","en":"to receive attention, to be noticed","lv":"B2","vdecoys":["haben","nehmen","machen"],"pdecoys":["übersehen werden","vergessen werden","verboten werden"],"note":"Passivbedeutung: Beachtung finden = beachtet werden. Aktiv dazu: Beachtung schenken.","ex":[{"de":"Ihre Studie fand in der Fachwelt kaum Beachtung.","en":"Her study received hardly any attention among experts."},{"de":"Die Warnung der Experten hat leider keine Beachtung gefunden.","en":"Unfortunately the experts' warning was not heeded."},{"de":"Solche Details finden oft zu wenig Beachtung.","en":"Such details often get too little attention."}],"exPlain":[{"de":"Ihre Studie wurde in der Fachwelt kaum beachtet.","en":"Her study was hardly noticed among experts."},{"de":"Die Warnung der Experten wurde leider nicht beachtet.","en":"Unfortunately the experts' warning was not heeded."}]},
 {"np":"Verwendung","verb":"finden","plain":"verwendet werden","en":"to be used, to find a use","lv":"B2","vdecoys":["nehmen","machen","geben"],"pdecoys":["verbraucht werden","weggeworfen werden","verkauft werden"],"note":"Passivbedeutung: Verwendung finden = verwendet werden. Formell.","ex":[{"de":"Alte Reifen finden hier als Spielgeräte neue Verwendung.","en":"Old tyres find a new use here as play equipment."},{"de":"Das Material findet im Bauwesen vielfältige Verwendung.","en":"The material is used in many ways in construction."},{"de":"Der Begriff fand in der Gesetzessprache bald Verwendung.","en":"The term soon came into use in legal language."}],"exPlain":[{"de":"Alte Reifen werden hier als Spielgeräte weiterverwendet.","en":"Old tyres are reused here as play equipment."},{"de":"Das Material wird im Bauwesen vielfältig verwendet.","en":"The material is used in many ways in construction."}]},
 {"np":"Zustimmung","verb":"finden","plain":"akzeptiert werden","en":"to meet with approval","lv":"B2","vdecoys":["nehmen","machen","treffen"],"pdecoys":["abgelehnt werden","verhindert werden","vergessen werden"],"pAlt":["gebilligt werden"],"note":"Passivbedeutung: Das Subjekt ist die Sache, die Zustimmung bekommt. Zustimmung finden bei + Dat.","ex":[{"de":"Der Plan fand im Gemeinderat breite Zustimmung.","en":"The plan met with broad approval on the local council."},{"de":"Seine Vorschläge haben bei den Mitarbeitern keine Zustimmung gefunden.","en":"His proposals did not find approval among the staff."},{"de":"Das neue Gesetz dürfte kaum Zustimmung finden.","en":"The new law is unlikely to find much approval."}],"exPlain":[{"de":"Der Plan wurde im Gemeinderat von fast allen akzeptiert.","en":"The plan was accepted by almost everyone on the local council."},{"de":"Seine Vorschläge wurden von den Mitarbeitern nicht akzeptiert.","en":"His proposals were not accepted by the staff."}]},
 {"np":"Berücksichtigung","verb":"finden","plain":"berücksichtigt werden","en":"to be taken into account","lv":"C1","vdecoys":["haben","nehmen","machen"],"pdecoys":["ignoriert werden","vergessen werden","abgelehnt werden"],"note":"Passivbedeutung; Amtsdeutsch. Aktiv dazu: etwas berücksichtigen; ähnlich: einer Sache Rechnung tragen.","ex":[{"de":"Die Einwände der Anwohner fanden bei der Planung Berücksichtigung.","en":"The residents' objections were taken into account in the planning."},{"de":"Die Wünsche der Kunden sollen künftig mehr Berücksichtigung finden.","en":"Customers' wishes are to be given more consideration in future."},{"de":"Ihr Antrag hat leider keine Berücksichtigung gefunden.","en":"Unfortunately her application was not taken into account."}],"exPlain":[{"de":"Die Einwände der Anwohner wurden bei der Planung berücksichtigt.","en":"The residents' objections were taken into account in the planning."},{"de":"Ihr Antrag wurde leider nicht berücksichtigt.","en":"Unfortunately her application was not taken into account."}]},
 {"np":"Auskunft","verb":"erteilen","plain":"informieren","en":"to give information","lv":"B2","vdecoys":["machen","bringen","stellen"],"pdecoys":["fragen","verbergen","anrufen"],"vAlt":["geben"],"note":"Formell (Amt, Firma). Im Alltag: Auskunft geben.","ex":[{"de":"Die Pressestelle erteilt keine Auskunft zu laufenden Verfahren.","en":"The press office gives no information on ongoing proceedings."},{"de":"Gern erteile ich Ihnen telefonisch Auskunft.","en":"I am happy to give you information by phone."},{"de":"Der Mitarbeiter hat mir freundlich Auskunft erteilt.","en":"The employee kindly gave me the information."}],"exPlain":[{"de":"Die Pressestelle informiert nicht über laufende Verfahren.","en":"The press office does not give information about ongoing proceedings."},{"de":"Der Mitarbeiter hat mich freundlich informiert.","en":"The employee kindly informed me."}]},
 {"np":"die Erlaubnis","verb":"erteilen","plain":"erlauben","en":"to give permission","lv":"B2","vdecoys":["machen","treffen","stellen"],"pdecoys":["verbieten","bitten","brauchen"],"vAlt":["geben"],"note":"Formell; Dativ der Person: jdm. die Erlaubnis erteilen. Im Alltag: Erlaubnis geben.","ex":[{"de":"Der Vermieter hat uns die Erlaubnis erteilt, einen Hund zu halten.","en":"The landlord gave us permission to keep a dog."},{"de":"Die Schulleiterin erteilte den Schülern die Erlaubnis, früher zu gehen.","en":"The headteacher gave the pupils permission to leave early."},{"de":"Wer erteilt die Erlaubnis zum Betreten des Geländes?","en":"Who gives permission to enter the grounds?"}],"exPlain":[{"de":"Der Vermieter hat uns erlaubt, einen Hund zu halten.","en":"The landlord allowed us to keep a dog."},{"de":"Die Schulleiterin erlaubte den Schülern, früher zu gehen.","en":"The headteacher allowed the pupils to leave early."}]},
 {"np":"einen Auftrag","verb":"erteilen","plain":"beauftragen","en":"to give an order, to commission","lv":"B2","vdecoys":["treffen","stellen","setzen"],"pdecoys":["ausführen","erledigen","anbieten"],"vAlt":["geben"],"note":"Formell, Geschäftssprache: jdm. einen Auftrag erteilen. Plain mit anderer Valenz: jdn. mit etwas beauftragen. Der Empfänger führt den Auftrag aus.","ex":[{"de":"Die Stadt erteilte einer Baufirma den Auftrag für die neue Brücke.","en":"The city commissioned a construction firm to build the new bridge."},{"de":"Wir haben dem Handwerker gestern den Auftrag erteilt.","en":"We gave the tradesman the job yesterday."},{"de":"Sie erteilt ihrer Assistentin täglich neue Aufträge.","en":"She gives her assistant new tasks every day."}],"exPlain":[{"de":"Die Stadt beauftragte eine Baufirma mit dem Bau der neuen Brücke.","en":"The city commissioned a construction firm to build the new bridge."},{"de":"Wir haben den Handwerker gestern beauftragt.","en":"We commissioned the tradesman yesterday."}]},
 {"np":"eine Absage","verb":"erteilen","plain":"ablehnen","en":"to reject, to turn down","lv":"B2","vdecoys":["treffen","stellen","bringen"],"pdecoys":["zusagen","einladen","verschieben"],"pAlt":["absagen"],"note":"Oft übertragen: einem Plan eine klare Absage erteilen = ihn entschieden ablehnen. Dativ der Person oder Sache.","ex":[{"de":"Der Minister erteilte höheren Steuern eine klare Absage.","en":"The minister clearly rejected higher taxes."},{"de":"Die Firma hat mir nach dem Gespräch leider eine Absage erteilt.","en":"Unfortunately the company turned me down after the interview."},{"de":"Der Verein erteilte allen Fusionsplänen eine Absage.","en":"The club rejected all merger plans."}],"exPlain":[{"de":"Der Minister lehnte höhere Steuern klar ab.","en":"The minister clearly rejected higher taxes."},{"de":"Der Verein lehnte alle Fusionspläne ab.","en":"The club rejected all merger plans."}]},
 {"np":"Unterricht","verb":"erteilen","plain":"unterrichten","en":"to teach, to give lessons","lv":"B2","vdecoys":["stellen","bringen","führen"],"pdecoys":["lernen","studieren","prüfen"],"vAlt":["geben","halten"],"note":"Formell/schulisch: Unterricht erteilen. Unterricht machen ist nur umgangssprachlich. Unterricht nehmen bedeutet das Gegenteil (Schüler sein).","ex":[{"de":"Sie erteilt seit zehn Jahren Unterricht an einer Volkshochschule.","en":"She has been teaching at an adult education centre for ten years."},{"de":"Wegen der Krankheitswelle konnte kein Unterricht erteilt werden.","en":"Because of the wave of illness no lessons could be given."},{"de":"Der Pianist hat jahrelang jungen Talenten Unterricht erteilt.","en":"The pianist gave lessons to young talents for years."}],"exPlain":[{"de":"Sie unterrichtet seit zehn Jahren an einer Volkshochschule.","en":"She has been teaching at an adult education centre for ten years."},{"de":"Der Pianist hat jahrelang junge Talente unterrichtet.","en":"The pianist taught young talents for years."}]},
 {"np":"eine Genehmigung","verb":"erteilen","plain":"genehmigen","en":"to grant a permit","lv":"C1","vdecoys":["machen","nehmen","stellen"],"pdecoys":["beantragen","verweigern","beschaffen"],"note":"Amtsdeutsch: Die Behörde erteilt die Genehmigung. Passiv ist üblich: Die Genehmigung wurde erteilt.","ex":[{"de":"Die Stadt hat dem Bau des Hotels die Genehmigung erteilt.","en":"The city has granted the permit for building the hotel."},{"de":"Das Amt erteilt die Genehmigung frühestens nach vier Wochen.","en":"The office grants the permit after four weeks at the earliest."},{"de":"Wurde Ihnen die Genehmigung bereits erteilt?","en":"Have you already been granted the permit?"}],"exPlain":[{"de":"Die Stadt hat den Bau des Hotels genehmigt.","en":"The city has approved the building of the hotel."},{"de":"Das Amt genehmigt den Antrag frühestens nach vier Wochen.","en":"The office approves the application after four weeks at the earliest."}]},
 {"np":"einen Rat","verb":"geben","plain":"raten","en":"to give advice","lv":"B1","vdecoys":["machen","stellen","sagen"],"pdecoys":["fragen","folgen","bitten"],"vAlt":["erteilen"],"note":"Der Rat ist maskulin. Rat erteilen klingt formeller; sehr häufig auch: Ratschläge geben.","ex":[{"de":"Kannst du mir einen Rat geben, welches Handy ich kaufen soll?","en":"Can you give me some advice on which phone to buy?"},{"de":"Sie hat mir einen wertvollen Rat gegeben.","en":"She gave me some valuable advice."},{"de":"Er gab ihm den Rat, nichts zu unterschreiben.","en":"He advised him not to sign anything."}],"exPlain":[{"de":"Kannst du mir raten, welches Handy ich kaufen soll?","en":"Can you advise me which phone to buy?"},{"de":"Er riet ihm, nichts zu unterschreiben.","en":"He advised him not to sign anything."}]},
 {"np":"Bescheid","verb":"geben","plain":"informieren","en":"to let someone know","lv":"B1","vdecoys":["machen","stellen","nehmen"],"pdecoys":["wissen","fragen","einladen"],"vAlt":["sagen"],"pAlt":["benachrichtigen"],"note":"Bescheid geben = Bescheid sagen: kurz mitteilen. Nicht verwechseln mit Bescheid wissen (= informiert sein).","ex":[{"de":"Gib mir bitte Bescheid, wenn du angekommen bist.","en":"Please let me know when you have arrived."},{"de":"Die Praxis hat mir noch nicht Bescheid gegeben.","en":"The surgery has not let me know yet."},{"de":"Ich gebe Ihnen morgen Bescheid, ob wir den Termin halten können.","en":"I will let you know tomorrow whether we can keep the appointment."}],"exPlain":[{"de":"Informiere mich bitte, wenn du angekommen bist.","en":"Please inform me when you have arrived."},{"de":"Ich informiere Sie morgen, ob wir den Termin halten können.","en":"I will inform you tomorrow whether we can keep the appointment."}]},
 {"np":"eine Antwort","verb":"geben","plain":"antworten","en":"to give an answer","lv":"A2","vdecoys":["machen","stellen","nehmen"],"pdecoys":["fragen","erklären","wiederholen"],"note":"Meist: auf eine Frage eine Antwort geben. Im Alltag sagt man oft einfach antworten.","ex":[{"de":"Der Minister gab auf alle Fragen eine klare Antwort.","en":"The minister gave a clear answer to all questions."},{"de":"Ich kann dir leider noch keine Antwort geben.","en":"Unfortunately I can't give you an answer yet."},{"de":"Gestern gab sie mir endlich eine Antwort.","en":"Yesterday she finally gave me an answer."}],"exPlain":[{"de":"Der Minister antwortete klar auf alle Fragen.","en":"The minister answered all questions clearly."},{"de":"Gestern antwortete sie mir endlich.","en":"Yesterday she finally answered me."}]},
 {"np":"Anlass","verb":"geben","plain":"auslösen","en":"to give cause for, to occasion","lv":"C1","vdecoys":["machen","bringen","stellen"],"pdecoys":["verhindern","beenden","beruhigen"],"note":"Anlass geben zu + Dat.: meist für Kritik, Sorge, Zweifel. Anlass haben = einen Grund haben.","ex":[{"de":"Sein Verhalten gab Anlass zu Kritik.","en":"His behaviour gave cause for criticism."},{"de":"Der Vorfall hat Anlass zur Sorge gegeben.","en":"The incident gave cause for concern."},{"de":"Die Ergebnisse gaben Anlass zu neuen Fragen.","en":"The results raised new questions."}],"exPlain":[{"de":"Sein Verhalten löste Kritik aus.","en":"His behaviour triggered criticism."},{"de":"Der Vorfall hat Sorge ausgelöst.","en":"The incident triggered concern."}],"vAlt":["bieten"]},
 {"np":"einen Hinweis","verb":"geben","plain":"hinweisen","en":"to give a tip, to point something out","lv":"B1","vdecoys":["legen","stellen","nehmen"],"pdecoys":["verbergen","übersetzen","vorschreiben"],"note":"Hinweis geben auf + Akk.; trennbares Verb: jdn. auf etwas hinweisen. Hinweise geben kann auch Tipps oder Spuren nennen (der Polizei Hinweise geben).","ex":[{"de":"Die Lehrerin hat uns einen Hinweis auf den Abgabetermin gegeben.","en":"The teacher pointed out the deadline to us."},{"de":"Der Arzt gab mir einen Hinweis auf mögliche Nebenwirkungen.","en":"The doctor pointed out possible side effects to me."},{"de":"Darf ich Ihnen einen kurzen Hinweis auf die neuen Öffnungszeiten geben?","en":"May I briefly draw your attention to the new opening hours?"}],"exPlain":[{"de":"Die Lehrerin hat uns auf den Abgabetermin hingewiesen.","en":"The teacher pointed out the deadline to us."},{"de":"Der Arzt wies mich auf mögliche Nebenwirkungen hin.","en":"The doctor pointed out possible side effects to me."}]},
 {"np":"Gelegenheit","verb":"geben","plain":"ermöglichen","en":"to give the opportunity","lv":"B2","vdecoys":["machen","stellen","tragen"],"pdecoys":["verhindern","zwingen","verbieten"],"vAlt":["bieten"],"note":"Mit zu-Infinitiv: jdm. (die) Gelegenheit geben, etwas zu tun. Wer Gelegenheit hat, kann etwas tun.","ex":[{"de":"Das Praktikum gab ihr die Gelegenheit, den Beruf kennenzulernen.","en":"The internship gave her the opportunity to get to know the profession."},{"de":"Wir wollen den Kindern Gelegenheit geben, Musik auszuprobieren.","en":"We want to give the children the opportunity to try out music."},{"de":"Gib ihm doch Gelegenheit, sich zu erklären!","en":"Give him a chance to explain himself!"}],"exPlain":[{"de":"Das Praktikum ermöglichte ihr, den Beruf kennenzulernen.","en":"The internship made it possible for her to get to know the profession."},{"de":"Wir wollen den Kindern ermöglichen, Musik auszuprobieren.","en":"We want to make it possible for the children to try out music."}]},
 {"np":"Recht","verb":"geben","plain":"zustimmen","en":"to admit that someone is right","lv":"B2","vdecoys":["legen","sagen","bringen"],"pdecoys":["widersprechen","bestreiten","zweifeln"],"note":"Dativ der Person: jdm. Recht (auch: recht) geben. Verwandt: Recht haben = selbst richtigliegen.","ex":[{"de":"Ich muss dir Recht geben: Die Idee war nicht gut.","en":"I have to admit you are right: the idea was not good."},{"de":"Nach kurzem Zögern gab er ihr Recht.","en":"After a brief hesitation he conceded that she was right."},{"de":"Am Ende hat die Geschichte ihm Recht gegeben.","en":"In the end history proved him right."}],"exPlain":[{"de":"Ich muss dir zustimmen: Die Idee war nicht gut.","en":"I have to agree with you: the idea was not good."},{"de":"Nach kurzem Zögern stimmte er ihr zu.","en":"After a brief hesitation he agreed with her."}]},
 {"np":"Fortschritte","verb":"machen","plain":"vorankommen","en":"to make progress","lv":"B1","vdecoys":["bekommen","nehmen","geben"],"pdecoys":["zurückgehen","wiederholen","aufhören"],"vAlt":["erzielen"],"pAlt":["sich verbessern"],"note":"Meist Plural: gute, große Fortschritte machen (Singular selten: einen großen Fortschritt machen). Nicht: Fortschritte bekommen.","ex":[{"de":"Mein Sohn macht in der Schule große Fortschritte.","en":"My son is making great progress at school."},{"de":"Ihr habt im letzten Jahr enorme Fortschritte gemacht.","en":"You made enormous progress last year."},{"de":"Sie machte beim Deutschlernen schnelle Fortschritte.","en":"She made rapid progress in learning German."}],"exPlain":[{"de":"Mein Sohn kommt in der Schule gut voran.","en":"My son is getting on well at school."},{"de":"Ihr seid im letzten Jahr enorm vorangekommen.","en":"You made enormous headway last year."}]},
 {"np":"Gebrauch","verb":"machen","plain":"nutzen","en":"to make use of","lv":"B2","vdecoys":["geben","haben","tun"],"pdecoys":["verzichten","verbrauchen","kaufen"],"note":"Meist mit von + Dat.: von seinem Recht, einer Möglichkeit Gebrauch machen. Formell.","ex":[{"de":"Viele Bürger machen von ihrem Wahlrecht keinen Gebrauch.","en":"Many citizens do not make use of their right to vote."},{"de":"Er machte großzügig von der Möglichkeit Gebrauch, Urlaub zu nehmen.","en":"He generously made use of the option of taking leave."},{"de":"Von diesem Angebot sollten Sie unbedingt Gebrauch machen.","en":"You should definitely take advantage of this offer."}],"exPlain":[{"de":"Viele Bürger nutzen ihr Wahlrecht nicht.","en":"Many citizens do not use their right to vote."},{"de":"Dieses Angebot sollten Sie unbedingt nutzen.","en":"You should definitely take advantage of this offer."}]},
 {"np":"sich Gedanken","verb":"machen","plain":"nachdenken","en":"to think about, to give thought to","lv":"B1","vdecoys":["haben","tun","stellen"],"pdecoys":["sich erinnern","träumen","vergessen"],"pAlt":["überlegen"],"note":"Reflexiv, mit dem Dativ. sich Gedanken machen über + Akk. = nachdenken; sich Gedanken machen um + Akk. = sich Sorgen machen.","ex":[{"de":"Ich mache mir Gedanken über meine berufliche Zukunft.","en":"I am thinking about my professional future."},{"de":"Hast du dir schon Gedanken über das Geschenk gemacht?","en":"Have you thought about the present yet?"},{"de":"Wir sollten uns rechtzeitig Gedanken über die Rente machen.","en":"We should give some thought to our pension in good time."}],"exPlain":[{"de":"Ich denke über meine berufliche Zukunft nach.","en":"I am thinking about my professional future."},{"de":"Hast du schon über das Geschenk nachgedacht?","en":"Have you thought about the present yet?"}]},
 {"np":"sich Sorgen","verb":"machen","plain":"sich sorgen","en":"to worry","lv":"B1","vdecoys":["tun","nehmen","stellen"],"pdecoys":["sich freuen","sich ärgern","sich langweilen"],"note":"Reflexiv, mit dem Dativ: sich Sorgen machen um + Akk. Sich keine Sorgen machen = unbesorgt sein.","ex":[{"de":"Wir machen uns große Sorgen um Opas Gesundheit.","en":"We are very worried about Grandpa's health."},{"de":"Mach dir keine Sorgen, ich komme pünktlich!","en":"Don't worry, I'll be on time!"},{"de":"Sie hat sich um ihren Sohn viel zu viele Sorgen gemacht.","en":"She worried far too much about her son."}],"exPlain":[{"de":"Wir sorgen uns sehr um Opas Gesundheit.","en":"We are very worried about Grandpa's health."},{"de":"Du brauchst dich nicht zu sorgen, ich komme pünktlich!","en":"You needn't worry, I'll be on time!"}]},
 {"np":"eine Pause","verb":"machen","plain":"pausieren","en":"to take a break","lv":"A2","vdecoys":["tun","bringen","treiben"],"pdecoys":["weitermachen","aufholen","rennen"],"vAlt":["einlegen"],"note":"Üblich sind machen oder einlegen. Ich nehme mir eine Pause ist ebenfalls verbreitet, gilt aber teils als englisch beeinflusst.","ex":[{"de":"Lass uns eine kurze Pause machen und etwas trinken.","en":"Let's take a short break and have something to drink."},{"de":"Auf der Wanderung machten wir eine Stunde Pause.","en":"On the hike we took an hour's break."},{"de":"Die Band hat nach der Tour eine längere Pause gemacht.","en":"The band took a longer break after the tour."}],"exPlain":[{"de":"Lass uns kurz pausieren und etwas trinken.","en":"Let's pause briefly and have something to drink."},{"de":"Die Band hat nach der Tour lange pausiert.","en":"The band took a long break after the tour."}]},
 {"np":"ein Angebot","verb":"machen","plain":"anbieten","en":"to make an offer","lv":"B1","vdecoys":["treiben","bringen","setzen"],"pdecoys":["annehmen","bestellen","ablehnen"],"note":"Auch: ein Angebot unterbreiten (formell). Das Gegenstück ist ein Angebot annehmen oder ablehnen.","ex":[{"de":"Die Firma hat mir ein gutes Angebot gemacht.","en":"The company made me a good offer."},{"de":"Können Sie mir ein günstiges Angebot machen?","en":"Can you make me a favourable offer?"},{"de":"Er machte ihr ein Angebot, das sie kaum ablehnen konnte.","en":"He made her an offer that she could hardly refuse."}],"exPlain":[{"de":"Die Firma hat mir eine Stelle angeboten.","en":"The company offered me a job."},{"de":"Können Sie mir etwas Günstiges anbieten?","en":"Can you offer me something inexpensive?"}]},
 {"np":"einen Vorschlag","verb":"machen","plain":"vorschlagen","en":"to make a suggestion","lv":"A2","vdecoys":["geben","stellen","sagen"],"pdecoys":["vorlesen","vorziehen","vorstellen"],"note":"Einen Vorschlag geben ist unüblich. Formell: einen Vorschlag unterbreiten.","ex":[{"de":"Ich möchte einen Vorschlag machen: Wir gehen heute essen.","en":"I'd like to make a suggestion: let's go out to eat today."},{"de":"Hat jemand einen besseren Vorschlag gemacht?","en":"Has anyone made a better suggestion?"},{"de":"Sie machte den Vorschlag, die Sitzung zu verschieben.","en":"She suggested postponing the meeting."}],"exPlain":[{"de":"Ich schlage vor: Wir gehen heute essen.","en":"I suggest we go out to eat today."},{"de":"Sie schlug vor, die Sitzung zu verschieben.","en":"She suggested postponing the meeting."}]},
 {"np":"Eindruck","verb":"machen","plain":"beeindrucken","en":"to make an impression","lv":"B1","vdecoys":["geben","nehmen","bringen"],"pdecoys":["vorstellen","bemerken","beschreiben"],"vAlt":["hinterlassen"],"note":"Eindruck machen auf + Akk. = beeindrucken. Mit Adjektiv auch: einen guten oder schlechten Eindruck machen (= so wirken). Nicht: Eindruck geben.","ex":[{"de":"Die Rede machte auf die Zuhörer großen Eindruck.","en":"The speech made a great impression on the audience."},{"de":"Ihr Mut hat auf uns tiefen Eindruck gemacht.","en":"Her courage made a deep impression on us."},{"de":"Das Konzert macht auf mich jedes Mal großen Eindruck.","en":"The concert impresses me greatly every time."}],"exPlain":[{"de":"Die Rede beeindruckte die Zuhörer sehr.","en":"The speech impressed the audience greatly."},{"de":"Ihr Mut hat uns tief beeindruckt.","en":"Her courage impressed us deeply."}]},
 {"np":"sich Hoffnungen","verb":"machen","plain":"hoffen","en":"to have hopes, to get one's hopes up","lv":"B2","vdecoys":["tun","bringen","stellen"],"pdecoys":["bezweifeln","befürchten","verzweifeln"],"note":"Reflexiv, meist Plural: sich Hoffnungen machen auf + Akk. Hoffen ist etwas allgemeiner; sich Hoffnungen machen betont die (oft unsichere) Erwartung. Jdm. Hoffnung machen = jdm. Hoffnung geben.","ex":[{"de":"Wir machen uns noch Hoffnungen auf einen Platz im Finale.","en":"We still have hopes of a place in the final."},{"de":"Mach dir keine falschen Hoffnungen: Er kommt nicht zurück.","en":"Don't get your hopes up: he is not coming back."},{"de":"Sie hatte sich lange Hoffnungen auf die Stelle gemacht.","en":"She had long had her hopes set on the job."}],"exPlain":[{"de":"Wir hoffen noch auf einen Platz im Finale.","en":"We are still hoping for a place in the final."},{"de":"Sie hatte lange auf die Stelle gehofft.","en":"She had hoped for the job for a long time."}]},
 {"np":"Schluss","verb":"machen","plain":"aufhören","en":"to call it a day, to stop","lv":"B1","vdecoys":["geben","nehmen","setzen"],"pdecoys":["anfangen","weitermachen","beginnen"],"note":"Neutral bis umgangssprachlich. Schluss machen mit + Dat. = mit etwas aufhören; unter Paaren: mit jdm. Schluss machen = die Beziehung beenden.","ex":[{"de":"Ich mache jetzt Schluss, es ist schon spät.","en":"I'm calling it a day, it is already late."},{"de":"Er hat nach drei Jahren mit seiner Freundin Schluss gemacht.","en":"After three years he broke up with his girlfriend."},{"de":"Mach endlich Schluss mit dem Streit!","en":"Put an end to the quarrel at last!"}],"exPlain":[{"de":"Ich höre jetzt auf, es ist schon spät.","en":"I'm stopping now, it is already late."},{"de":"Hör endlich mit dem Streit auf!","en":"Stop the quarrel at last!"}]},
 {"np":"Erfahrungen","verb":"machen","plain":"erleben","en":"to have experiences","lv":"B1","vdecoys":["nehmen","geben","finden"],"pdecoys":["vergessen","erfinden","erzählen"],"vAlt":["sammeln"],"note":"Erfahrungen machen (mit + Dat.) = etwas (Gutes oder Schlechtes) erleben und daraus lernen; erleben ist etwas allgemeiner. Erfahrung haben (Singular) = Erfahrung besitzen: Sie hat viel Erfahrung.","ex":[{"de":"Mit dem neuen Chef haben wir bisher gute Erfahrungen gemacht.","en":"So far we have had good experiences with the new boss."},{"de":"Sie machte im Ausland viele neue Erfahrungen.","en":"She had many new experiences abroad."},{"de":"Hast du mit dieser Firma schon Erfahrungen gemacht?","en":"Have you had any experience with this company yet?"}],"exPlain":[{"de":"Mit dem neuen Chef haben wir bisher viel Gutes erlebt.","en":"So far we have experienced a lot of good things with the new boss."},{"de":"Sie erlebte im Ausland viel Neues.","en":"She experienced many new things abroad."}]},
 {"np":"Karriere","verb":"machen","plain":"aufsteigen","en":"to have a career, to climb the career ladder","lv":"B1","vdecoys":["treiben","nehmen","gehen"],"pdecoys":["kündigen","scheitern","absteigen"],"note":"Karriere machen = beruflich vorankommen, oft schnell. Ohne Artikel.","ex":[{"de":"Sie hat in der Bank schnell Karriere gemacht.","en":"She quickly climbed the career ladder at the bank."},{"de":"Er wollte nur Karriere machen und vernachlässigte die Familie.","en":"He only wanted to get ahead in his career and neglected his family."},{"de":"Wer Karriere machen will, muss oft umziehen.","en":"Anyone who wants to make a career often has to move."}],"exPlain":[{"de":"Sie ist in der Bank schnell aufgestiegen.","en":"She rose quickly at the bank."},{"de":"Er wollte nur beruflich aufsteigen und vernachlässigte die Familie.","en":"He only wanted to move up professionally and neglected his family."}]},
 {"np":"eine Reise","verb":"machen","plain":"reisen","en":"to take a trip, to go on a journey","lv":"A2","vdecoys":["gehen","nehmen","treiben"],"pdecoys":["fliegen","besuchen","wandern"],"vAlt":["unternehmen"],"note":"Nicht: eine Reise gehen oder nehmen. Auch: eine Reise antreten (= beginnen).","ex":[{"de":"Im Sommer machen wir eine Reise nach Italien.","en":"In the summer we are going on a trip to Italy."},{"de":"Sie haben letztes Jahr eine lange Reise durch Südamerika gemacht.","en":"Last year they took a long trip through South America."},{"de":"Nach dem Studium machte er eine Reise um die Welt.","en":"After university he went on a trip around the world."}],"exPlain":[{"de":"Im Sommer reisen wir nach Italien.","en":"In the summer we are travelling to Italy."},{"de":"Sie sind letztes Jahr lange durch Südamerika gereist.","en":"Last year they travelled through South America for a long time."}]},
 {"np":"einen Spaziergang","verb":"machen","plain":"spazieren gehen","en":"to go for a walk","lv":"A2","vdecoys":["gehen","nehmen","treiben"],"pdecoys":["einkaufen","besuchen","aufräumen"],"vAlt":["unternehmen"],"note":"Nicht: einen Spaziergang gehen. Das Verb ist machen (oder unternehmen).","ex":[{"de":"Nach dem Essen machen wir meistens einen Spaziergang.","en":"After dinner we usually go for a walk."},{"de":"Er hat mit dem Hund einen langen Spaziergang gemacht.","en":"He went for a long walk with the dog."},{"de":"Mach doch einen Spaziergang, das tut dir gut!","en":"Why don't you go for a walk, it will do you good!"}],"exPlain":[{"de":"Nach dem Essen gehen wir meistens spazieren.","en":"After dinner we usually go for a walk."},{"de":"Er ist mit dem Hund lange spazieren gegangen.","en":"He went for a long walk with the dog."}]},
 {"np":"ein Foto","verb":"machen","plain":"fotografieren","en":"to take a photo","lv":"A2","vdecoys":["nehmen","geben","tun"],"pdecoys":["zeichnen","filmen","malen"],"vAlt":["schießen"],"note":"Nicht: ein Foto nehmen (englisch take a photo). Fotos schießen ist umgangssprachlich.","ex":[{"de":"Darf ich ein Foto von euch machen?","en":"May I take a photo of you?"},{"de":"Wir haben im Urlaub Hunderte von Fotos gemacht.","en":"We took hundreds of photos on holiday."},{"de":"Mach bitte ein Foto, bevor der Kuchen weg ist!","en":"Please take a photo before the cake is gone!"}],"exPlain":[{"de":"Darf ich euch fotografieren?","en":"May I photograph you?"},{"de":"Im Urlaub haben wir viel fotografiert.","en":"On holiday we took a lot of photos."}]},
 {"np":"Einkäufe","verb":"machen","plain":"einkaufen","en":"to do the shopping","lv":"A2","vdecoys":["nehmen","gehen","tun"],"pdecoys":["verkaufen","bezahlen","bestellen"],"vAlt":["erledigen"],"note":"Einkäufe machen = einkaufen, meist größere oder geplante Einkäufe. Auch: Einkäufe erledigen.","ex":[{"de":"Am Samstag mache ich immer die großen Einkäufe.","en":"On Saturdays I always do the big shopping."},{"de":"Hast du schon alle Einkäufe für die Party gemacht?","en":"Have you already done all the shopping for the party?"},{"de":"Sie machte schnell noch ein paar Einkäufe vor dem Feiertag.","en":"She quickly did some shopping before the holiday."}],"exPlain":[{"de":"Am Samstag kaufe ich immer groß ein.","en":"On Saturdays I always do a big shop."},{"de":"Hast du schon alles für die Party eingekauft?","en":"Have you already bought everything for the party?"}]},
 {"np":"Angst","verb":"haben","plain":"sich fürchten","en":"to be afraid","lv":"A2","vdecoys":["tun","setzen","tragen"],"pdecoys":["hassen","vermeiden","bedauern"],"pAlt":["fürchten"],"note":"Angst haben vor + Dat. (Person oder Sache); Angst haben um + Akk. = sich um jdn. sorgen. Angst machen = jdm. Angst einjagen.","ex":[{"de":"Ich habe Angst vor Spinnen.","en":"I am afraid of spiders."},{"de":"Hast du Angst vor der Prüfung?","en":"Are you afraid of the exam?"},{"de":"Als Kind hatte sie große Angst im Dunkeln.","en":"As a child she was very afraid of the dark."}],"exPlain":[{"de":"Ich fürchte mich vor Spinnen.","en":"I am afraid of spiders."},{"de":"Fürchtest du dich vor der Prüfung?","en":"Are you afraid of the exam?"}]},
 {"np":"Hunger","verb":"haben","plain":"hungrig sein","en":"to be hungry","lv":"A2","vdecoys":["sein","tun","nehmen"],"pdecoys":["satt sein","durstig sein","müde sein"],"note":"Im Deutschen nicht mit sein: Ich habe Hunger (nicht: Ich bin Hunger). Ebenso: Durst haben.","ex":[{"de":"Nach dem Sport hatte ich riesigen Hunger.","en":"After sports I was ravenous."},{"de":"Habt ihr Hunger? Es gibt gleich Suppe.","en":"Are you hungry? There will be soup shortly."},{"de":"Die Kinder haben immer Hunger, wenn sie aus der Schule kommen.","en":"The children are always hungry when they come home from school."}],"exPlain":[{"de":"Nach dem Sport war ich sehr hungrig.","en":"After sports I was very hungry."},{"de":"Seid ihr hungrig? Es gibt gleich Suppe.","en":"Are you hungry? There will be soup shortly."}]},
 {"np":"Lust","verb":"haben","plain":"wollen","en":"to feel like (doing something)","lv":"A2","vdecoys":["sein","tun","nehmen"],"pdecoys":["müssen","sollen","dürfen"],"pAlt":["möchten"],"note":"Lust haben, etwas zu tun / Lust haben auf + Akk. Gegenteil: keine Lust haben. Als einfaches Verb passen wollen oder möchten nur bei Lust + zu-Infinitiv; Lust haben ist etwas weicher (to feel like).","ex":[{"de":"Hast du Lust, heute Abend ins Kino zu gehen?","en":"Do you feel like going to the cinema tonight?"},{"de":"Wir hatten keine Lust, bei dem Wetter spazieren zu gehen.","en":"We didn't feel like going for a walk in that weather."},{"de":"Er hat nie Lust, mir im Haushalt zu helfen.","en":"He never feels like helping me around the house."}],"exPlain":[{"de":"Willst du heute Abend ins Kino gehen?","en":"Do you want to go to the cinema tonight?"},{"de":"Wir wollten bei dem Wetter nicht spazieren gehen.","en":"We didn't want to go for a walk in that weather."}]},
 {"np":"Interesse","verb":"haben","plain":"sich interessieren","en":"to be interested","lv":"A2","vdecoys":["machen","tun","geben"],"pdecoys":["sich langweilen","sich erinnern","sich verabschieden"],"note":"Interesse haben an + Dat., aber sich interessieren für + Akk. Auch: Interesse zeigen.","ex":[{"de":"Hast du Interesse an einem Sprachkurs?","en":"Are you interested in a language course?"},{"de":"Er hatte schon als Kind großes Interesse an Technik.","en":"Even as a child he was very interested in technology."},{"de":"Wir haben leider kein Interesse an diesem Angebot.","en":"Unfortunately we are not interested in this offer."}],"exPlain":[{"de":"Interessierst du dich für einen Sprachkurs?","en":"Are you interested in a language course?"},{"de":"Er interessierte sich schon als Kind sehr für Technik.","en":"Even as a child he was very interested in technology."}]},
 {"np":"Mut","verb":"haben","plain":"mutig sein","en":"to be brave","lv":"B1","vdecoys":["tun","tragen","halten"],"pdecoys":["ängstlich sein","müde sein","vorsichtig sein"],"note":"Mut haben, etwas zu tun. Das Gegenteil ist Angst haben. Mut fassen = Mut finden und beginnen.","ex":[{"de":"Sie hatte den Mut, dem Chef zu widersprechen.","en":"She had the courage to contradict the boss."},{"de":"Du musst Mut haben, wenn du allein reisen willst.","en":"You need courage if you want to travel alone."},{"de":"Hättest du den Mut, vom Zehnmeterbrett zu springen?","en":"Would you have the courage to jump from the ten-metre board?"}],"exPlain":[{"de":"Sie war mutig genug, dem Chef zu widersprechen.","en":"She was brave enough to contradict the boss."},{"de":"Wer allein reisen will, muss mutig sein.","en":"Anyone who wants to travel alone must be brave."}]},
 {"np":"Zweifel","verb":"haben","plain":"zweifeln","en":"to have doubts","lv":"B2","vdecoys":["machen","geben","tun"],"pdecoys":["glauben","vertrauen","wissen"],"vAlt":["hegen"],"note":"Zweifel haben an + Dat. oder mit ob-Satz. Zweifel hegen ist gehobener.","ex":[{"de":"Ich habe Zweifel, ob das Wetter hält.","en":"I have my doubts about whether the weather will hold."},{"de":"Hast du Zweifel an seiner Ehrlichkeit?","en":"Do you have doubts about his honesty?"},{"de":"Sie hatte nie Zweifel daran, dass er kommt.","en":"She never had any doubt that he would come."}],"exPlain":[{"de":"Ich zweifle, ob das Wetter hält.","en":"I doubt whether the weather will hold."},{"de":"Zweifelst du an seiner Ehrlichkeit?","en":"Do you doubt his honesty?"}]},
 {"np":"Erfolg","verb":"haben","plain":"erfolgreich sein","en":"to be successful","lv":"B1","vdecoys":["machen","nehmen","bekommen"],"pdecoys":["scheitern","verlieren","sich irren"],"vAlt":["erzielen","feiern"],"note":"Erfolg haben mit/bei + Dat. Gegenteil: scheitern. Ein Erfolg kann auch gefeiert oder erzielt werden.","ex":[{"de":"Mit ihrem ersten Roman hatte die Autorin sofort Erfolg.","en":"With her first novel the author was an immediate success."},{"de":"Die Band hat im Ausland großen Erfolg gehabt.","en":"The band was very successful abroad."},{"de":"Wer hartnäckig bleibt, wird am Ende Erfolg haben.","en":"Whoever keeps at it will succeed in the end."}],"exPlain":[{"de":"Mit ihrem ersten Roman war die Autorin sofort erfolgreich.","en":"With her first novel the author was immediately successful."},{"de":"Wer hartnäckig bleibt, wird am Ende erfolgreich sein.","en":"Whoever keeps at it will be successful in the end."}]},
 {"np":"Verständnis","verb":"haben","plain":"verstehen","en":"to be understanding, to sympathise","lv":"B1","vdecoys":["machen","geben","tun"],"pdecoys":["wissen","erklären","kennen"],"note":"Verständnis haben für + Akk. = jdn. oder etwas nachvollziehen können. Oft verneint: kein Verständnis haben. Auch: Verständnis zeigen.","ex":[{"de":"Ich habe vollstes Verständnis für deinen Ärger.","en":"I fully understand your anger."},{"de":"Die Lehrerin hatte kein Verständnis für ständige Verspätungen.","en":"The teacher had no sympathy for constant lateness."},{"de":"Hätten Sie Verständnis dafür, dass wir den Termin verschieben müssen?","en":"Would you be understanding about our having to postpone the appointment?"}],"exPlain":[{"de":"Ich verstehe deinen Ärger vollkommen.","en":"I completely understand your anger."},{"de":"Können Sie verstehen, dass wir den Termin verschieben müssen?","en":"Can you understand that we have to postpone the appointment?"}]},
 {"np":"Bedarf","verb":"haben","plain":"brauchen","en":"to have a need for","lv":"B2","vdecoys":["machen","geben","tun"],"pdecoys":["verbrauchen","kaufen","anbieten"],"pAlt":["benötigen"],"note":"Formell. Bedarf haben an + Dat., oft in Wirtschaft und Verwaltung. Häufiger als Konstruktion: Es besteht Bedarf an + Dat.","ex":[{"de":"Die Schule hat dringenden Bedarf an Lehrkräften.","en":"The school urgently needs teachers."},{"de":"Haben Sie Bedarf an weiteren Informationen?","en":"Do you need any further information?"},{"de":"Die Klinik hatte im Winter hohen Bedarf an Schutzkleidung.","en":"In winter the clinic had a high demand for protective clothing."}],"exPlain":[{"de":"Die Schule braucht dringend Lehrkräfte.","en":"The school urgently needs teachers."},{"de":"Brauchen Sie weitere Informationen?","en":"Do you need any further information?"}]},
 {"np":"Streit","verb":"haben","plain":"sich streiten","en":"to be quarrelling","lv":"B1","vdecoys":["stellen","tun","nehmen"],"pdecoys":["sich versöhnen","sich verabschieden","sich entschuldigen"],"note":"Streit haben mit + Dat. Gegenteil: sich vertragen. Beginn des Streits: Streit anfangen.","ex":[{"de":"Die Nachbarn haben schon wieder Streit wegen des Zauns.","en":"The neighbours are quarrelling over the fence again."},{"de":"Ich möchte mit dir keinen Streit haben.","en":"I don't want to have a quarrel with you."},{"de":"Die Geschwister hatten den ganzen Tag Streit.","en":"The siblings were quarrelling all day."}],"exPlain":[{"de":"Die Nachbarn streiten sich schon wieder wegen des Zauns.","en":"The neighbours are quarrelling over the fence again."},{"de":"Die Geschwister stritten sich den ganzen Tag.","en":"The siblings quarrelled all day."}]},
 {"np":"Verdacht","verb":"haben","plain":"vermuten","en":"to suspect","lv":"B2","vdecoys":["machen","geben","tun"],"pdecoys":["beweisen","wissen","behaupten"],"vAlt":["hegen"],"note":"Verdacht haben, dass ...; auch: jdn. im Verdacht haben. Verdacht schöpfen = anfangen zu vermuten.","ex":[{"de":"Die Polizei hat den Verdacht, dass der Brand gelegt wurde.","en":"The police suspect that the fire was set deliberately."},{"de":"Ich hatte sofort den Verdacht, dass etwas nicht stimmt.","en":"I immediately suspected that something was wrong."},{"de":"Hast du einen Verdacht, wer das war?","en":"Do you have a suspicion who that was?"}],"exPlain":[{"de":"Die Polizei vermutet, dass der Brand gelegt wurde.","en":"The police suspect that the fire was set deliberately."},{"de":"Ich vermutete sofort, dass etwas nicht stimmt.","en":"I immediately suspected that something was wrong."}]},
 {"np":"Spaß","verb":"haben","plain":"sich amüsieren","en":"to have fun","lv":"A2","vdecoys":["tun","nehmen","halten"],"pdecoys":["sich langweilen","sich ärgern","sich beeilen"],"note":"Spaß haben (Person als Subjekt) und Spaß machen (Sache als Subjekt): Wir haben Spaß. Das Spiel macht mir Spaß.","ex":[{"de":"Auf der Party hatten wir viel Spaß.","en":"We had a lot of fun at the party."},{"de":"Habt ihr im Urlaub Spaß gehabt?","en":"Did you have fun on holiday?"},{"de":"Ich hoffe, die Kinder haben Spaß beim Spielen.","en":"I hope the children are having fun playing."}],"exPlain":[{"de":"Auf der Party haben wir uns gut amüsiert.","en":"We enjoyed ourselves at the party."},{"de":"Habt ihr euch im Urlaub amüsiert?","en":"Did you enjoy yourselves on holiday?"}]},
 {"np":"Einspruch","verb":"erheben","plain":"widersprechen","en":"to lodge an objection","lv":"B2","vdecoys":["machen","stellen","geben"],"pdecoys":["zustimmen","bewilligen","abstimmen"],"vAlt":["einlegen"],"note":"Recht und Verwaltung: Einspruch erheben gegen + Akk. Auch: Widerspruch einlegen.","ex":[{"de":"Gegen den Bescheid kann man innerhalb eines Monats Einspruch erheben.","en":"You can lodge an objection to the notice within one month."},{"de":"Die Anwohner erhoben Einspruch gegen den Bau der Straße.","en":"The residents lodged an objection to the construction of the road."},{"de":"Hat jemand Einspruch erhoben?","en":"Has anyone raised an objection?"}],"exPlain":[{"de":"Dem Bescheid kann man innerhalb eines Monats widersprechen.","en":"You can object to the notice within one month."},{"de":"Die Anwohner widersprachen dem Bau der Straße.","en":"The residents objected to the construction of the road."}]},
 {"np":"Anspruch","verb":"erheben","plain":"beanspruchen","en":"to lay claim to","lv":"C1","vdecoys":["machen","geben","tun"],"pdecoys":["verzichten","anbieten","verleihen"],"note":"Anspruch erheben auf + Akk., in Recht und Politik. Anspruch haben auf + Akk. = ein Recht darauf haben.","ex":[{"de":"Beide Länder erheben Anspruch auf die Inseln.","en":"Both countries lay claim to the islands."},{"de":"Der Erbe erhob Anspruch auf das Haus.","en":"The heir laid claim to the house."},{"de":"Ich erhebe keinen Anspruch darauf, immer recht zu haben.","en":"I don't claim to be right all the time."}],"exPlain":[{"de":"Beide Länder beanspruchen die Inseln.","en":"Both countries claim the islands."},{"de":"Der Erbe beanspruchte das Haus.","en":"The heir claimed the house."}]},
 {"np":"Klage","verb":"erheben","plain":"klagen","en":"to file a lawsuit","lv":"B2","vdecoys":["machen","stellen","geben"],"pdecoys":["verurteilen","freisprechen","verteidigen"],"vAlt":["einreichen"],"pAlt":["verklagen"],"note":"Klage erheben gegen + Akk. (vor Gericht). Auch: Klage einreichen. Das Nomen Klage kann außerdem Beschwerde bedeuten.","ex":[{"de":"Der Mieter will gegen die Kündigung Klage erheben.","en":"The tenant wants to take legal action against the notice."},{"de":"Sie hat gegen ihren früheren Arbeitgeber Klage erhoben.","en":"She filed a lawsuit against her former employer."},{"de":"Wegen des Verkehrslärms erhoben mehrere Bürger Klage.","en":"Several citizens brought an action over the traffic noise."}],"exPlain":[{"de":"Der Mieter will gegen die Kündigung klagen.","en":"The tenant wants to sue over the notice."},{"de":"Sie hat gegen ihren früheren Arbeitgeber geklagt.","en":"She sued her former employer."}]},
 {"np":"Forderungen","verb":"erheben","plain":"fordern","en":"to make demands","lv":"B2","vdecoys":["legen","geben","nehmen"],"pdecoys":["bezahlen","anbieten","versprechen"],"vAlt":["stellen"],"note":"Meist Plural: Forderungen erheben/stellen. Gegenstück: auf Forderungen eingehen.","ex":[{"de":"Die Gewerkschaft erhebt Forderungen nach höheren Löhnen.","en":"The union is making demands for higher wages."},{"de":"Der Verband erhob neue Forderungen an die Politik.","en":"The association made new demands of the politicians."},{"de":"Die Demonstranten haben klare Forderungen erhoben.","en":"The demonstrators made clear demands."}],"exPlain":[{"de":"Die Gewerkschaft fordert höhere Löhne.","en":"The union demands higher wages."},{"de":"Die Demonstranten haben klare Änderungen gefordert.","en":"The demonstrators demanded clear changes."}]},
 {"np":"Vorwürfe","verb":"erheben","plain":"beschuldigen","en":"to make accusations","lv":"B2","vdecoys":["geben","stellen","nehmen"],"pdecoys":["entschuldigen","loben","verzeihen"],"vAlt":["machen"],"note":"Vorwürfe erheben gegen + Akk.: öffentlich beschuldigen (formell). Jdm. Vorwürfe machen: jdn. persönlich tadeln.","ex":[{"de":"Die Opposition erhebt schwere Vorwürfe gegen den Minister.","en":"The opposition is making serious accusations against the minister."},{"de":"Mehrere Mitarbeiter haben Vorwürfe gegen den Chef erhoben.","en":"Several employees have made accusations against the boss."},{"de":"Er erhob keine Vorwürfe, obwohl er verletzt war.","en":"He made no accusations, although he was hurt."}],"exPlain":[{"de":"Die Opposition beschuldigt den Minister schwer.","en":"The opposition is gravely accusing the minister."},{"de":"Mehrere Mitarbeiter haben den Chef beschuldigt.","en":"Several employees have accused the boss."}]},
 {"np":"Protest","verb":"erheben","plain":"protestieren","en":"to protest","lv":"B2","vdecoys":["machen","geben","stellen"],"pdecoys":["zustimmen","applaudieren","schweigen"],"vAlt":["einlegen"],"note":"Protest erheben gegen + Akk.: formell (Briefe, Politik, Diplomatie). Alltag: protestieren.","ex":[{"de":"Die Botschaft erhob scharfen Protest gegen die Entscheidung.","en":"The embassy lodged a strong protest against the decision."},{"de":"Viele Bürger erheben Protest gegen die neue Steuer.","en":"Many citizens are protesting against the new tax."},{"de":"Der Verein hat lautstark Protest erhoben.","en":"The club protested loudly."}],"exPlain":[{"de":"Die Botschaft protestierte scharf gegen die Entscheidung.","en":"The embassy sharply protested against the decision."},{"de":"Viele Bürger protestieren gegen die neue Steuer.","en":"Many citizens are protesting against the new tax."}]},
 {"np":"einer Kontrolle","verb":"unterziehen","plain":"kontrollieren","en":"to subject to an inspection","lv":"C1","vdecoys":["geben","legen","führen"],"pdecoys":["umgehen","verstecken","aufheben"],"note":"etw./jdn. einer Kontrolle unterziehen. Das Verb ist untrennbar: unterzog, unterzogen. Amtsdeutsch.","ex":[{"de":"Der Zoll unterzog das Gepäck einer gründlichen Kontrolle.","en":"Customs subjected the luggage to a thorough inspection."},{"de":"Jedes Fahrzeug wird vor der Auslieferung einer Kontrolle unterzogen.","en":"Every vehicle is inspected before delivery."},{"de":"Die Behörde hat den Betrieb einer Kontrolle unterzogen.","en":"The authority has inspected the company."}],"exPlain":[{"de":"Der Zoll kontrollierte das Gepäck gründlich.","en":"Customs checked the luggage thoroughly."},{"de":"Jedes Fahrzeug wird vor der Auslieferung kontrolliert.","en":"Every vehicle is checked before delivery."}]},
 {"np":"sich einer Behandlung","verb":"unterziehen","plain":"sich behandeln lassen","en":"to undergo treatment","lv":"C1","vdecoys":["geben","legen","nehmen"],"pdecoys":["heilen","pflegen","verschreiben"],"note":"Reflexiv: sich einer Behandlung, Therapie, Untersuchung unterziehen. Das Verb ist untrennbar.","ex":[{"de":"Nach dem Unfall musste er sich einer langen Behandlung unterziehen.","en":"After the accident he had to undergo a long course of treatment."},{"de":"Sie unterzog sich einer Therapie, um mit dem Rauchen aufzuhören.","en":"She underwent therapy in order to stop smoking."},{"de":"Wer sich dieser Behandlung unterzieht, braucht viel Geduld.","en":"Anyone who undergoes this treatment needs a lot of patience."}],"exPlain":[{"de":"Nach dem Unfall musste er sich lange behandeln lassen.","en":"After the accident he had to be treated for a long time."},{"de":"Sie ließ sich behandeln, um mit dem Rauchen aufzuhören.","en":"She had treatment in order to stop smoking."}]},
 {"np":"sich einer Operation","verb":"unterziehen","plain":"sich operieren lassen","en":"to undergo an operation","lv":"B2","vdecoys":["geben","legen","nehmen"],"pdecoys":["operieren","untersuchen","heilen"],"note":"Reflexiv: sich einer Operation unterziehen. Das Verb ist untrennbar; Perfekt: hat sich unterzogen.","ex":[{"de":"Der Patient muss sich einer Operation am Knie unterziehen.","en":"The patient has to undergo an operation on his knee."},{"de":"Sie unterzog sich einer schwierigen Operation und erholte sich schnell.","en":"She underwent a difficult operation and recovered quickly."},{"de":"Nach dem Unfall hat er sich mehreren Operationen unterzogen.","en":"After the accident he underwent several operations."}],"exPlain":[{"de":"Der Patient muss sich am Knie operieren lassen.","en":"The patient has to have an operation on his knee."},{"de":"Sie ließ sich operieren und erholte sich schnell.","en":"She had an operation and recovered quickly."}]},
 {"np":"Abhilfe","verb":"schaffen","plain":"abhelfen","en":"to remedy, to put right","lv":"C1","vdecoys":["machen","geben","setzen"],"pdecoys":["verschlimmern","bemerken","melden"],"pAlt":["beheben"],"note":"Abhilfe schaffen (bei + Dat. oder gegen + Akk.). Plain: dem Missstand abhelfen (Dativ) oder den Fehler beheben (Akkusativ).","ex":[{"de":"Die Stadt will mit mehr Bussen Abhilfe schaffen.","en":"The city wants to remedy the situation with more buses."},{"de":"Hier muss dringend Abhilfe geschaffen werden.","en":"Something urgently has to be done about this."},{"de":"Der Techniker schuf schnell Abhilfe, indem er das Kabel ersetzte.","en":"The technician quickly fixed the problem by replacing the cable."}],"exPlain":[{"de":"Die Stadt will dem Problem mit mehr Bussen abhelfen.","en":"The city wants to remedy the problem with more buses."},{"de":"Dem Mangel muss dringend abgeholfen werden.","en":"The shortage has to be remedied urgently."}]},
 {"np":"Klarheit","verb":"schaffen","plain":"klären","en":"to clarify, to bring clarity","lv":"B2","vdecoys":["machen","halten","stellen"],"pdecoys":["verwirren","vergessen","verstecken"],"note":"Klarheit schaffen über + Akk. Auch: für Klarheit sorgen.","ex":[{"de":"Ein Gespräch mit dem Chef soll endlich Klarheit schaffen.","en":"A talk with the boss is meant to bring clarity at last."},{"de":"Das Gericht hat Klarheit über die Rechtslage geschaffen.","en":"The court has clarified the legal situation."},{"de":"Wir müssen vor dem Start Klarheit darüber schaffen, wer welche Aufgabe übernimmt.","en":"Before the start we need to clarify who takes on which task."}],"exPlain":[{"de":"Ein Gespräch mit dem Chef soll die Lage endlich klären.","en":"A talk with the boss is meant to clarify the situation at last."},{"de":"Wir müssen vor dem Start klären, wer welche Aufgabe übernimmt.","en":"Before the start we need to clarify who takes on which task."}],"vAlt":["bringen"]},
 {"np":"Ordnung","verb":"schaffen","plain":"ordnen","en":"to put in order, to tidy up","lv":"B1","vdecoys":["nehmen","treffen","stellen"],"pdecoys":["durcheinanderbringen","sammeln","verlegen"],"pAlt":["aufräumen"],"note":"Ordnung schaffen in + Dat.: Zimmer, Akten oder Abläufe in Ordnung bringen. Umgangssprachlich auch: Ordnung machen.","ex":[{"de":"Am Wochenende will ich endlich Ordnung im Keller schaffen.","en":"At the weekend I finally want to get the basement in order."},{"de":"Die neue Leiterin hat in der Abteilung Ordnung geschaffen.","en":"The new head has brought order to the department."},{"de":"Der Hausmeister schafft jeden Morgen Ordnung im Hof.","en":"The caretaker tidies the yard every morning."}],"exPlain":[{"de":"Am Wochenende will ich endlich meine Unterlagen ordnen.","en":"At the weekend I finally want to sort out my papers."},{"de":"Die neue Leiterin hat die Abläufe in der Abteilung geordnet.","en":"The new head has put the department's procedures in order."}],"vAlt":["machen"]},
 {"np":"Voraussetzungen","verb":"schaffen","plain":"ermöglichen","en":"to create the conditions","lv":"B2","vdecoys":["machen","geben","bringen"],"pdecoys":["verhindern","verlangen","ausschließen"],"note":"Voraussetzungen schaffen für + Akk.: Bedingungen herstellen, damit etwas möglich wird. Meist Plural.","ex":[{"de":"Die Stadt will die Voraussetzungen für neue Arbeitsplätze schaffen.","en":"The city wants to create the conditions for new jobs."},{"de":"Wir haben die Voraussetzungen für eine Zusammenarbeit geschaffen.","en":"We have created the conditions for cooperation."},{"de":"Mit dem neuen Gesetz wurden die Voraussetzungen für den Ausbau geschaffen.","en":"The new law created the conditions for the expansion."}],"exPlain":[{"de":"Die Stadt will neue Arbeitsplätze ermöglichen.","en":"The city wants to make new jobs possible."},{"de":"Mit dem neuen Gesetz wurde der Ausbau ermöglicht.","en":"The new law made the expansion possible."}]},
 {"np":"Ausgleich","verb":"schaffen","plain":"ausgleichen","en":"to create a balance","lv":"B2","vdecoys":["setzen","legen","nehmen"],"pdecoys":["vergleichen","verteilen","ausnutzen"],"note":"Ausgleich schaffen für + Akk. / zu + Dat. / zwischen + Dat.","ex":[{"de":"Der Sport schafft einen guten Ausgleich zur Büroarbeit.","en":"Sport provides a good balance to office work."},{"de":"Die Regierung will einen Ausgleich zwischen Stadt und Land schaffen.","en":"The government wants to create a balance between town and country."},{"de":"Für Familien mit Kindern soll ein finanzieller Ausgleich geschaffen werden.","en":"Financial compensation is to be provided for families with children."}],"exPlain":[{"de":"Der Sport gleicht die Büroarbeit gut aus.","en":"Sport compensates well for office work."},{"de":"Die Regierung will die Unterschiede zwischen Stadt und Land ausgleichen.","en":"The government wants to even out the differences between town and country."}]},
 {"np":"Freundschaft","verb":"schließen","plain":"sich anfreunden","en":"to become friends","lv":"B2","vdecoys":["machen","treffen","nehmen"],"pdecoys":["sich verlieben","sich verloben","sich streiten"],"vAlt":["knüpfen"],"note":"Freundschaft schließen mit + Dat. Nicht: Freunde machen (englisch make friends); besser: Freunde finden.","ex":[{"de":"Im Sprachkurs schloss sie schnell Freundschaft mit einer Italienerin.","en":"In the language course she quickly made friends with an Italian woman."},{"de":"Die beiden Jungen haben im Urlaub Freundschaft geschlossen.","en":"The two boys became friends on holiday."},{"de":"Wir wollen mit unseren Nachbarn Freundschaft schließen.","en":"We want to become friends with our neighbours."}],"exPlain":[{"de":"Im Sprachkurs freundete sie sich schnell mit einer Italienerin an.","en":"In the language course she quickly became friends with an Italian woman."},{"de":"Die beiden Jungen haben sich im Urlaub angefreundet.","en":"The two boys became friends on holiday."}]},
 {"np":"Frieden","verb":"schließen","plain":"sich versöhnen","en":"to make peace","lv":"B2","vdecoys":["treffen","legen","setzen"],"pdecoys":["kämpfen","sich trennen","sich streiten"],"note":"Frieden schließen mit + Dat.: zwischen Personen oder Staaten. Sich versöhnen passt nur bei Personen; Staaten schließen Frieden (einen Friedensvertrag).","ex":[{"de":"Nach dem langen Streit schlossen die Brüder endlich Frieden.","en":"After the long quarrel the brothers finally made peace."},{"de":"Die beiden Staaten schlossen nach drei Jahren Krieg Frieden.","en":"The two states made peace after three years of war."},{"de":"Ich möchte mit dir Frieden schließen.","en":"I would like to make peace with you."}],"exPlain":[{"de":"Nach dem langen Streit versöhnten sich die Brüder endlich.","en":"After the long quarrel the brothers finally made up."},{"de":"Ich möchte mich mit dir versöhnen.","en":"I would like to make up with you."}]},
 {"np":"eine Ehe","verb":"schließen","plain":"heiraten","en":"to marry, to enter into a marriage","lv":"C1","vdecoys":["machen","nehmen","treffen"],"pdecoys":["sich verloben","sich trennen","sich verlieben"],"vAlt":["eingehen"],"note":"Amtlich und juristisch: eine Ehe schließen. Im Alltag: heiraten.","ex":[{"de":"Das Paar schloss die Ehe im kleinen Kreis.","en":"The couple got married with only a few guests."},{"de":"In Deutschland kann man in der Regel erst mit achtzehn Jahren eine Ehe schließen.","en":"In Germany one can generally only marry at the age of eighteen."},{"de":"Sie haben vor zehn Jahren die Ehe geschlossen.","en":"They got married ten years ago."}],"exPlain":[{"de":"Das Paar heiratete im kleinen Kreis.","en":"The couple got married with only a few guests."},{"de":"Sie haben vor zehn Jahren geheiratet.","en":"They got married ten years ago."}]},
 {"np":"ein Bündnis","verb":"schließen","plain":"sich verbünden","en":"to form an alliance","lv":"B2","vdecoys":["machen","treffen","nehmen"],"pdecoys":["sich zerstreiten","kapitulieren","sich trennen"],"vAlt":["eingehen"],"note":"Politik, Geschichte und Wirtschaft: ein Bündnis mit + Dat. schließen.","ex":[{"de":"Die beiden Parteien schlossen vor der Wahl ein Bündnis.","en":"The two parties formed an alliance before the election."},{"de":"Mehrere Staaten haben ein Bündnis gegen den Angreifer geschlossen.","en":"Several states have formed an alliance against the aggressor."},{"de":"Wir sollten ein Bündnis mit den anderen Vereinen schließen.","en":"We should form an alliance with the other clubs."}],"exPlain":[{"de":"Die beiden Parteien verbündeten sich vor der Wahl.","en":"The two parties allied themselves before the election."},{"de":"Mehrere Staaten haben sich gegen den Angreifer verbündet.","en":"Several states have allied themselves against the aggressor."}]},
 {"np":"einen Kompromiss","verb":"schließen","plain":"sich einigen","en":"to compromise, to strike a compromise","lv":"B2","vdecoys":["geben","nehmen","halten"],"pdecoys":["streiten","ablehnen","verweigern"],"vAlt":["eingehen"],"note":"Auch: einen Kompromiss finden. Kompromiss schließen mit + Dat. über + Akk.","ex":[{"de":"Nach stundenlanger Diskussion schlossen die Parteien einen Kompromiss.","en":"After hours of discussion the parties struck a compromise."},{"de":"Wir haben bei der Wahl des Urlaubsorts einen Kompromiss geschlossen.","en":"We compromised on the choice of holiday destination."},{"de":"Beide Seiten sind bereit, einen Kompromiss zu schließen.","en":"Both sides are prepared to compromise."}],"exPlain":[{"de":"Nach stundenlanger Diskussion einigten sich die Parteien.","en":"After hours of discussion the parties came to an agreement."},{"de":"Wir haben uns auf einen Urlaubsort geeinigt.","en":"We agreed on a holiday destination."}]},
 {"np":"ein Geständnis","verb":"ablegen","plain":"gestehen","en":"to make a confession","lv":"C1","vdecoys":["geben","halten","bringen"],"pdecoys":["leugnen","verschweigen","anklagen"],"note":"Vor Gericht und Polizei: ein Geständnis ablegen. Das Verb ist trennbar (legt ab).","ex":[{"de":"Der Angeklagte legte vor Gericht ein umfassendes Geständnis ab.","en":"The defendant made a full confession in court."},{"de":"Nach stundenlangem Verhör hat er endlich ein Geständnis abgelegt.","en":"After hours of interrogation he finally confessed."},{"de":"Sie wollte kein Geständnis ablegen.","en":"She did not want to make a confession."}],"exPlain":[{"de":"Der Angeklagte gestand vor Gericht alles.","en":"The defendant confessed everything in court."},{"de":"Nach stundenlangem Verhör hat er endlich gestanden.","en":"After hours of interrogation he finally confessed."}],"vAlt":["machen"]},
 {"np":"Zeugnis","verb":"ablegen","plain":"bezeugen","en":"to bear witness","lv":"C1","vdecoys":["machen","halten","tragen"],"pdecoys":["verleugnen","verkünden","schreiben"],"note":"Zeugnis ablegen von + Dat. oder für + Akk.; auch übertragen: Etwas legt Zeugnis von etwas ab (= belegt es). Gehoben.","ex":[{"de":"Die Ruinen legen Zeugnis von der Größe des Reiches ab.","en":"The ruins bear witness to the greatness of the empire."},{"de":"Mehrere Überlebende legten vor dem Gericht Zeugnis ab.","en":"Several survivors gave testimony before the court."},{"de":"Das Tagebuch legt Zeugnis vom Alltag der Kriegszeit ab.","en":"The diary bears witness to everyday life in wartime."}],"exPlain":[{"de":"Die Ruinen bezeugen die Größe des Reiches.","en":"The ruins testify to the greatness of the empire."},{"de":"Das Tagebuch bezeugt den Alltag der Kriegszeit.","en":"The diary testifies to everyday life in wartime."}]},
 {"np":"Rechenschaft","verb":"ablegen","plain":"sich verantworten","en":"to account for one's actions","lv":"C1","vdecoys":["machen","halten","führen"],"pdecoys":["bezahlen","kontrollieren","bestrafen"],"vAlt":["geben"],"note":"Rechenschaft ablegen über + Akk. / vor + Dat. Das Verb ist trennbar (legt ab).","ex":[{"de":"Der Minister musste vor dem Parlament Rechenschaft über die Ausgaben ablegen.","en":"The minister had to account for the spending before parliament."},{"de":"Wir müssen niemandem Rechenschaft ablegen.","en":"We don't have to answer to anyone."},{"de":"Die Firma legt jedes Jahr Rechenschaft über ihre Spenden ab.","en":"The company accounts for its donations every year."}],"exPlain":[{"de":"Der Minister musste sich vor dem Parlament für die Ausgaben verantworten.","en":"The minister had to answer to parliament for the spending."},{"de":"Wir müssen uns vor niemandem verantworten.","en":"We don't have to answer to anyone."}]},
 {"np":"Unterstützung","verb":"erfahren","plain":"unterstützt werden","en":"to receive support","lv":"B2","vdecoys":["machen","halten","nehmen"],"pdecoys":["abgelehnt werden","vergessen werden","bestraft werden"],"vAlt":["erhalten","bekommen"],"note":"Passivbedeutung: Das Subjekt bekommt etwas. Das Projekt erfährt Unterstützung = Es wird unterstützt. Formell.","ex":[{"de":"Das Projekt erfährt breite Unterstützung in der Bevölkerung.","en":"The project enjoys broad support among the population."},{"de":"Die Familie hat viel Unterstützung von den Nachbarn erfahren.","en":"The family received a lot of support from the neighbours."},{"de":"Junge Gründer erfahren hier tatkräftige Unterstützung.","en":"Young founders receive active support here."}],"exPlain":[{"de":"Das Projekt wird von der Bevölkerung breit unterstützt.","en":"The project is widely supported by the population."},{"de":"Die Familie wurde von den Nachbarn stark unterstützt.","en":"The family was strongly supported by the neighbours."}]},
 {"np":"Förderung","verb":"erfahren","plain":"gefördert werden","en":"to receive support, to be promoted","lv":"C1","vdecoys":["machen","halten","nehmen"],"pdecoys":["vernachlässigt werden","gekürzt werden","benachteiligt werden"],"vAlt":["erhalten","bekommen"],"note":"Passivbedeutung; Förderung bezeichnet Unterstützung durch Geld oder Training. Formell.","ex":[{"de":"Begabte Kinder erfahren an dieser Schule gezielte Förderung.","en":"Gifted children receive targeted support at this school."},{"de":"Das Orchester hat jahrelang staatliche Förderung erfahren.","en":"The orchestra received state funding for years."},{"de":"Der Nachwuchs erfährt in dem Verein besondere Förderung.","en":"Young talent receives special support in the club."}],"exPlain":[{"de":"Begabte Kinder werden an dieser Schule gezielt gefördert.","en":"Gifted children are specifically supported at this school."},{"de":"Das Orchester wurde jahrelang vom Staat gefördert.","en":"The orchestra was funded by the state for years."}]},
 {"np":"Ablehnung","verb":"erfahren","plain":"abgelehnt werden","en":"to meet with rejection","lv":"B2","vdecoys":["machen","geben","nehmen"],"pdecoys":["akzeptiert werden","gelobt werden","gewählt werden"],"vAlt":["erleben"],"note":"Passivbedeutung: Subjekt ist die Person oder Sache, die abgelehnt wird.","ex":[{"de":"Der Vorschlag erfuhr bei den Mitgliedern entschiedene Ablehnung.","en":"The proposal met with firm rejection from the members."},{"de":"Er hat als Kind viel Ablehnung erfahren.","en":"As a child he experienced a lot of rejection."},{"de":"Die neue Regel erfuhr von allen Seiten Ablehnung.","en":"The new rule was rejected from all sides."}],"exPlain":[{"de":"Der Vorschlag wurde von den Mitgliedern entschieden abgelehnt.","en":"The proposal was firmly rejected by the members."},{"de":"Er wurde als Kind oft abgelehnt.","en":"As a child he was often rejected."}]},
 {"np":"Veränderung","verb":"erfahren","plain":"sich verändern","en":"to undergo change","lv":"B2","vdecoys":["halten","geben","nehmen"],"pdecoys":["sich erinnern","stagnieren","sich wiederholen"],"vAlt":["erleben"],"note":"Passivnahe Bedeutung: etwas durchläuft eine Veränderung. Formell, oft in Berichten.","ex":[{"de":"Das Viertel hat in den letzten Jahren große Veränderungen erfahren.","en":"The district has undergone major changes in recent years."},{"de":"Die Sprache erfährt ständig kleine Veränderungen.","en":"Language is constantly undergoing small changes."},{"de":"Auch der Hafen erfuhr eine grundlegende Veränderung.","en":"The harbour also underwent a fundamental change."}],"exPlain":[{"de":"Das Viertel hat sich in den letzten Jahren stark verändert.","en":"The district has changed a lot in recent years."},{"de":"Die Sprache verändert sich ständig.","en":"Language is constantly changing."}]},
 {"np":"Anzeige","verb":"erstatten","plain":"anzeigen","en":"to report (a crime) to the police","lv":"B2","vdecoys":["geben","nehmen","halten"],"pdecoys":["verhaften","verurteilen","festnehmen"],"note":"Anzeige erstatten gegen + Akk. (bei der Polizei); amtlich. Das Verb ist untrennbar (erstattet, erstattete, erstattet).","ex":[{"de":"Nach dem Einbruch erstattete sie Anzeige bei der Polizei.","en":"After the burglary she reported it to the police."},{"de":"Er hat gegen den Nachbarn Anzeige erstattet.","en":"He filed a complaint against his neighbour."},{"de":"Wo kann ich Anzeige erstatten?","en":"Where can I report this?"}],"exPlain":[{"de":"Nach dem Einbruch zeigte sie den Vorfall bei der Polizei an.","en":"After the burglary she reported the incident to the police."},{"de":"Er hat den Nachbarn angezeigt.","en":"He reported his neighbour to the police."}]},
 {"np":"Bericht","verb":"erstatten","plain":"berichten","en":"to report, to give a report","lv":"B2","vdecoys":["halten","führen","treffen"],"pdecoys":["verheimlichen","veröffentlichen","fragen"],"note":"jdm. (oder an + Akk.) Bericht erstatten über + Akk.: formell, Amt, Gremium. Vergleiche: Anzeige erstatten.","ex":[{"de":"Die Kommission erstattete dem Ministerium Bericht über die Lage.","en":"The commission reported to the ministry on the situation."},{"de":"Der Leiter muss dem Vorstand regelmäßig Bericht erstatten.","en":"The manager has to report to the board regularly."},{"de":"Wer erstattet nächste Woche Bericht über das Projekt?","en":"Who will report on the project next week?"}],"exPlain":[{"de":"Die Kommission berichtete dem Ministerium über die Lage.","en":"The commission reported to the ministry on the situation."},{"de":"Der Leiter muss dem Vorstand regelmäßig berichten.","en":"The manager has to report to the board regularly."}]},
 {"np":"Bedenken","verb":"äußern","plain":"einwenden","en":"to express reservations","lv":"B2","vdecoys":["machen","geben","stellen"],"pdecoys":["zustimmen","bestätigen","beruhigen"],"note":"Bedenken äußern gegen/wegen + Akk./Gen.; auch anmelden. Einwenden ist nur ungefähr gleich: man nennt dabei den Einwand selbst.","ex":[{"de":"Der Architekt äußerte Bedenken gegen den Plan.","en":"The architect expressed reservations about the plan."},{"de":"Mehrere Eltern haben Bedenken wegen der Sicherheit geäußert.","en":"Several parents have expressed concerns about safety."},{"de":"Hast du Bedenken geäußert, als du den Vertrag gesehen hast?","en":"Did you express any reservations when you saw the contract?"}],"exPlain":[{"de":"Der Architekt wandte ein, der Plan sei zu riskant.","en":"The architect objected that the plan was too risky."},{"de":"Mehrere Eltern wandten ein, die Sicherheit sei nicht gewährleistet.","en":"Several parents objected that safety was not guaranteed."}]},
 {"np":"einen Wunsch","verb":"äußern","plain":"wünschen","en":"to express a wish","lv":"B1","vdecoys":["machen","geben","stellen"],"pdecoys":["erfüllen","brauchen","versprechen"],"note":"Nicht: einen Wunsch machen (englisch make a wish). Man wünscht sich etwas, oder man äußert einen Wunsch (sagt ihn).","ex":[{"de":"Die Kundin äußerte den Wunsch, mit dem Chef zu sprechen.","en":"The customer expressed the wish to speak to the boss."},{"de":"Hast du schon einen Wunsch zum Geburtstag geäußert?","en":"Have you already named a wish for your birthday?"},{"de":"Er äußert selten eigene Wünsche.","en":"He rarely expresses wishes of his own."}],"exPlain":[{"de":"Die Kundin wünschte, mit dem Chef zu sprechen.","en":"The customer wished to speak to the boss."},{"de":"Hast du schon gesagt, was du dir zum Geburtstag wünschst?","en":"Have you already said what you want for your birthday?"}]},
 {"np":"eine Vermutung","verb":"äußern","plain":"vermuten","en":"to voice a suspicion or conjecture","lv":"B2","vdecoys":["machen","geben","treffen"],"pdecoys":["wissen","beweisen","bezweifeln"],"note":"Auch: Vermutungen anstellen (= überlegen, was der Fall sein könnte). Eine Vermutung haben beschreibt nur den Zustand.","ex":[{"de":"Der Arzt äußerte die Vermutung, dass es sich um eine Allergie handelt.","en":"The doctor voiced the suspicion that it was an allergy."},{"de":"Die Reporterin hat eine Vermutung zur Ursache geäußert.","en":"The reporter has voiced a conjecture about the cause."},{"de":"Ich möchte hier keine Vermutungen äußern.","en":"I don't want to speculate here."}],"exPlain":[{"de":"Der Arzt vermutete, dass es sich um eine Allergie handelt.","en":"The doctor suspected that it was an allergy."},{"de":"Die Reporterin hat vermutet, dass ein Defekt die Ursache war.","en":"The reporter has surmised that a defect was the cause."}]},
 {"np":"eine Frage","verb":"richten","plain":"fragen","en":"to put a question (to someone)","lv":"B2","vdecoys":["machen","geben","bringen"],"pdecoys":["antworten","erklären","zweifeln"],"vAlt":["stellen"],"note":"Eine Frage an jdn. richten: formelle Variante von eine Frage stellen. Nicht: eine Frage machen.","ex":[{"de":"Die Journalistin richtete eine Frage zu den Kosten an den Minister.","en":"The journalist put a question about the costs to the minister."},{"de":"Bitte richten Sie Ihre Fragen an die Geschäftsstelle.","en":"Please address your questions to the office."},{"de":"Er hat eine kritische Frage an die Firma gerichtet.","en":"He put a critical question to the company."}],"exPlain":[{"de":"Die Journalistin fragte den Minister nach den Kosten.","en":"The journalist asked the minister about the costs."},{"de":"Bitte fragen Sie die Geschäftsstelle.","en":"Please ask the office."}]},
 {"np":"eine Bitte","verb":"richten","plain":"bitten","en":"to address a request (to someone)","lv":"B2","vdecoys":["machen","geben","legen"],"pdecoys":["danken","anbieten","versprechen"],"vAlt":["äußern"],"note":"Eine Bitte an jdn. richten: formell. Im Alltag: jdn. um etwas bitten.","ex":[{"de":"Darf ich eine Bitte an Sie richten?","en":"May I address a request to you?"},{"de":"Die Bewohner richteten die Bitte an den Bürgermeister, die Straße zu sperren.","en":"The residents asked the mayor to close the street."},{"de":"Sie hat die Bitte an uns gerichtet, leiser zu sein.","en":"She asked us to be quieter."}],"exPlain":[{"de":"Darf ich Sie um etwas bitten?","en":"May I ask you for something?"},{"de":"Sie hat uns gebeten, leiser zu sein.","en":"She asked us to be quieter."}]},
 {"np":"einen Blick","verb":"werfen","plain":"anschauen","en":"to take a (quick) look","lv":"B1","vdecoys":["machen","geben","nehmen"],"pdecoys":["übersehen","beobachten","vergleichen"],"vAlt":["riskieren"],"pAlt":["ansehen"],"note":"Einen Blick auf/in + Akk. werfen = kurz hinsehen. Nicht: einen Blick nehmen.","ex":[{"de":"Darf ich kurz einen Blick auf deine Notizen werfen?","en":"May I take a quick look at your notes?"},{"de":"Sie warf einen Blick auf die Uhr und stand auf.","en":"She glanced at the clock and got up."},{"de":"Hast du schon einen Blick in den Brief geworfen?","en":"Have you had a look at the letter yet?"}],"exPlain":[{"de":"Darf ich kurz deine Notizen anschauen?","en":"May I take a quick look at your notes?"},{"de":"Hast du den Brief schon angeschaut?","en":"Have you looked at the letter yet?"}]},
 {"np":"einen Entschluss","verb":"fassen","plain":"sich entschließen","en":"to make up one's mind","lv":"B2","vdecoys":["bringen","machen","nehmen"],"pdecoys":["verhindern","zögern","überlegen"],"pAlt":["beschließen"],"note":"Üblich ist fassen. Treffen gehört zu Entscheidung (eine Entscheidung treffen).","ex":[{"de":"Nach langem Überlegen fasste er den Entschluss, auszuwandern.","en":"After much thought he resolved to emigrate."},{"de":"Ich habe den Entschluss gefasst, mit dem Rauchen aufzuhören.","en":"I have made up my mind to stop smoking."},{"de":"Sie fasste den festen Entschluss, nie wieder zu spät zu kommen.","en":"She made a firm resolution never to be late again."}],"exPlain":[{"de":"Nach langem Überlegen entschloss er sich auszuwandern.","en":"After much thought he decided to emigrate."},{"de":"Ich habe mich entschlossen, mit dem Rauchen aufzuhören.","en":"I have decided to stop smoking."}]},
 {"np":"einen Vorsatz","verb":"fassen","plain":"sich vornehmen","en":"to make a resolution","lv":"B2","vdecoys":["treffen","nehmen","geben"],"pdecoys":["versprechen","vergessen","bereuen"],"note":"Einen Vorsatz fassen, oft Plural: gute Vorsätze fassen (z. B. zu Silvester).","ex":[{"de":"Zu Silvester fasse ich immer gute Vorsätze.","en":"On New Year's Eve I always make good resolutions."},{"de":"Er hatte den Vorsatz gefasst, mehr Sport zu treiben.","en":"He had made a resolution to do more sport."},{"de":"Sie fasste den Vorsatz, jeden Tag Deutsch zu lernen.","en":"She resolved to study German every day."}],"exPlain":[{"de":"Zu Silvester nehme ich mir immer viel vor.","en":"On New Year's Eve I always resolve to do a lot."},{"de":"Er hatte sich vorgenommen, mehr Sport zu treiben.","en":"He had resolved to do more sport."}]},
 {"np":"Mut","verb":"fassen","plain":"sich trauen","en":"to pluck up courage","lv":"B2","vdecoys":["tun","tragen","setzen"],"pdecoys":["zögern","aufgeben","verzichten"],"vAlt":["schöpfen"],"note":"Mut fassen = anfangen, mutig zu sein; Mut haben ist ein Zustand. Gegenteil: den Mut verlieren.","ex":[{"de":"Endlich fasste sie Mut und sprach den Chef an.","en":"At last she plucked up her courage and spoke to the boss."},{"de":"Er fasste Mut und sprang vom Dreimeterbrett.","en":"He summoned up his courage and jumped from the three-metre board."},{"de":"Nach dem Erfolg hat das Team neuen Mut gefasst.","en":"After the success the team took fresh heart."}],"exPlain":[{"de":"Endlich traute sie sich, den Chef anzusprechen.","en":"At last she dared to speak to the boss."},{"de":"Er traute sich und sprang vom Dreimeterbrett.","en":"He dared and jumped from the three-metre board."}]},
 {"np":"einen Beschluss","verb":"fassen","plain":"beschließen","en":"to pass a resolution","lv":"B2","vdecoys":["halten","machen","geben"],"pdecoys":["ablehnen","vorschlagen","aufheben"],"note":"Gremien fassen einen Beschluss (Gemeinderat, Vorstand, Versammlung). Passiv: Ein Beschluss wurde gefasst.","ex":[{"de":"Der Gemeinderat hat einstimmig den Beschluss gefasst, die Schule zu sanieren.","en":"The local council unanimously resolved to renovate the school."},{"de":"Die Versammlung fasst morgen ihren Beschluss.","en":"The assembly will pass its resolution tomorrow."},{"de":"Wann wurde dieser Beschluss gefasst?","en":"When was this resolution passed?"}],"exPlain":[{"de":"Der Gemeinderat hat einstimmig beschlossen, die Schule zu sanieren.","en":"The local council unanimously decided to renovate the school."},{"de":"Die Versammlung beschließt morgen.","en":"The assembly will decide tomorrow."}]},
 {"np":"Verantwortung","verb":"tragen","plain":"verantwortlich sein","en":"to bear responsibility","lv":"B2","vdecoys":["machen","halten","treiben"],"pdecoys":["antworten","entschuldigen","bestrafen"],"vAlt":["haben"],"note":"Verantwortung tragen für + Akk. Verantwortung übernehmen = anfangen, sie zu tragen.","ex":[{"de":"Eltern tragen die Verantwortung für ihre Kinder.","en":"Parents bear responsibility for their children."},{"de":"Der Kapitän trug die Verantwortung für das Schiff.","en":"The captain bore responsibility for the ship."},{"de":"Wer trägt die Verantwortung für den Fehler?","en":"Who is responsible for the mistake?"}],"exPlain":[{"de":"Eltern sind für ihre Kinder verantwortlich.","en":"Parents are responsible for their children."},{"de":"Der Kapitän war für das Schiff verantwortlich.","en":"The captain was responsible for the ship."}]},
 {"np":"Sorge","verb":"tragen","plain":"sorgen","en":"to see to it, to ensure","lv":"C1","vdecoys":["geben","halten","bringen"],"pdecoys":["versorgen","besorgen","umsorgen"],"note":"Feste Wendung: für etwas / dafür Sorge tragen, dass ... Amtsdeutsch. Nicht verwechseln mit Sorgen haben oder sich Sorgen machen.","ex":[{"de":"Der Vermieter muss dafür Sorge tragen, dass das Treppenhaus sauber ist.","en":"The landlord must see to it that the stairwell is clean."},{"de":"Wir tragen Sorge für die Sicherheit der Gäste.","en":"We take care of the safety of the guests."},{"de":"Die Stadt trägt Sorge dafür, dass alle Kinder einen Schulplatz haben.","en":"The city ensures that all children have a school place."}],"exPlain":[{"de":"Der Vermieter muss dafür sorgen, dass das Treppenhaus sauber ist.","en":"The landlord must make sure that the stairwell is clean."},{"de":"Die Stadt sorgt dafür, dass alle Kinder einen Schulplatz haben.","en":"The city makes sure that all children have a school place."}]},
 {"np":"einer Sache Rechnung","verb":"tragen","plain":"berücksichtigen","en":"to take into account","lv":"C1","vdecoys":["geben","nehmen","halten"],"pdecoys":["bezahlen","kassieren","ignorieren"],"note":"Dativ der Sache: einem Umstand Rechnung tragen. Hat nichts mit einer Rechnung zum Bezahlen zu tun. Gehoben.","ex":[{"de":"Das neue Gesetz trägt den Bedürfnissen von Familien Rechnung.","en":"The new law takes families' needs into account."},{"de":"Wir haben dem Wunsch der Kunden Rechnung getragen.","en":"We took the customers' wish into account."},{"de":"Der Lehrplan muss den technischen Entwicklungen Rechnung tragen.","en":"The curriculum must take technical developments into account."}],"exPlain":[{"de":"Das neue Gesetz berücksichtigt die Bedürfnisse von Familien.","en":"The new law takes families' needs into account."},{"de":"Wir haben den Wunsch der Kunden berücksichtigt.","en":"We took the customers' wish into account."}]},
 {"np":"die Kosten","verb":"tragen","plain":"bezahlen","en":"to bear the costs","lv":"B2","vdecoys":["geben","legen","setzen"],"pdecoys":["kosten","verdienen","sparen"],"vAlt":["übernehmen"],"pAlt":["zahlen"],"note":"Die Kosten tragen = sie bezahlen müssen oder wollen. Auch: die Kosten übernehmen.","ex":[{"de":"Wer trägt die Kosten für den Umzug?","en":"Who bears the costs of the move?"},{"de":"Die Krankenkasse trägt die Kosten der Behandlung.","en":"The health insurance covers the costs of the treatment."},{"de":"Die Kosten für die Reparatur trägt der Vermieter.","en":"The landlord bears the cost of the repair."}],"exPlain":[{"de":"Wer bezahlt den Umzug?","en":"Who pays for the move?"},{"de":"Die Krankenkasse bezahlt die Behandlung.","en":"The health insurance pays for the treatment."}]},
 {"np":"Aufmerksamkeit","verb":"schenken","plain":"achten","en":"to pay attention to","lv":"B2","vdecoys":["machen","legen","setzen"],"pdecoys":["vergessen","aufgeben","ablenken"],"vAlt":["widmen"],"note":"Dativ: einer Sache Aufmerksamkeit schenken = auf sie achten. Üblich sind schenken oder widmen; Aufmerksamkeit geben klingt nach dem Englischen (give attention).","ex":[{"de":"Man sollte den Warnzeichen des Körpers mehr Aufmerksamkeit schenken.","en":"One should pay more attention to the body's warning signs."},{"de":"Die Lehrerin schenkte jedem Kind die gleiche Aufmerksamkeit.","en":"The teacher gave every child the same attention."},{"de":"Während des Vortrags schenkte sie ihrem Handy mehr Aufmerksamkeit als dem Redner.","en":"During the talk she paid more attention to her phone than to the speaker."}],"exPlain":[{"de":"Man sollte mehr auf die Warnzeichen des Körpers achten.","en":"One should pay more attention to the body's warning signs."},{"de":"Die Lehrerin achtete auf alle Kinder gleichermaßen.","en":"The teacher paid equal attention to every child."}]},
 {"np":"Gehör","verb":"schenken","plain":"zuhören","en":"to lend an ear, to listen to","lv":"C1","vdecoys":["machen","nehmen","halten"],"pdecoys":["überhören","verstehen","sprechen"],"pAlt":["anhören"],"note":"Dativ: jdm./einer Bitte Gehör schenken = jdn. anhören und ernst nehmen. Gehoben.","ex":[{"de":"Der Bürgermeister schenkte den Sorgen der Anwohner kein Gehör.","en":"The mayor did not lend an ear to the residents' concerns."},{"de":"Ich bat sie, mir kurz Gehör zu schenken.","en":"I asked her to hear me out briefly."},{"de":"Warum schenkt niemand diesen Warnungen Gehör?","en":"Why does nobody listen to these warnings?"}],"exPlain":[{"de":"Der Bürgermeister hörte den Anwohnern nicht zu, als sie ihre Sorgen schilderten.","en":"The mayor did not listen to the residents when they described their concerns."},{"de":"Ich bat sie, mir kurz zuzuhören.","en":"I asked her to listen to me briefly."}]},
 {"np":"Sport","verb":"treiben","plain":"sich sportlich betätigen","en":"to do sport","lv":"A2","vdecoys":["spielen","tun","üben"],"pdecoys":["gewinnen","zuschauen","verlieren"],"vAlt":["machen","betreiben"],"note":"Sport treiben ist Standard; Sport machen ist umgangssprachlich sehr häufig. Nicht: Sport spielen. Einzelne Sportarten: Fußball spielen, schwimmen.","ex":[{"de":"Ich treibe dreimal pro Woche Sport.","en":"I do sport three times a week."},{"de":"Früher haben wir viel Sport getrieben.","en":"In the past we did a lot of sport."},{"de":"Wer regelmäßig Sport treibt, bleibt länger gesund.","en":"Anyone who does sport regularly stays healthy longer."}],"exPlain":[{"de":"Ich betätige mich dreimal pro Woche sportlich.","en":"I engage in sport three times a week."},{"de":"Wer sich regelmäßig sportlich betätigt, bleibt länger gesund.","en":"Anyone who is regularly active in sport stays healthy longer."}]},
 {"np":"Handel","verb":"treiben","plain":"handeln","en":"to trade","lv":"B2","vdecoys":["stellen","führen","halten"],"pdecoys":["produzieren","verbieten","schenken"],"vAlt":["betreiben"],"note":"Handel treiben mit + Dat.: Waren kaufen und verkaufen. Auch: Handel betreiben. Das Verb handeln kann auch tun oder verhandeln bedeuten.","ex":[{"de":"Schon im Mittelalter trieb die Stadt Handel mit fernen Ländern.","en":"Even in the Middle Ages the city traded with distant lands."},{"de":"Die Kaufleute treiben seit Jahrhunderten Handel mit Gewürzen.","en":"The merchants have traded in spices for centuries."},{"de":"Mit gefälschten Waren Handel zu treiben ist verboten.","en":"Trading in counterfeit goods is forbidden."}],"exPlain":[{"de":"Schon im Mittelalter handelte die Stadt mit fernen Ländern.","en":"Even in the Middle Ages the city traded with distant lands."},{"de":"Die Kaufleute handeln seit Jahrhunderten mit Gewürzen.","en":"The merchants have traded in spices for centuries."}]},
 {"np":"Unfug","verb":"treiben","plain":"herumalbern","en":"to get up to mischief","lv":"B1","vdecoys":["spielen","halten","führen"],"pdecoys":["stillsitzen","aufräumen","gehorchen"],"vAlt":["anstellen","machen"],"note":"Unfug treiben = Unsinn oder Dummheiten machen, oft von Kindern. Etwas umgangssprachlich. Herumalbern trifft nur ungefähr: es betont das alberne Verhalten.","ex":[{"de":"Die Kinder haben im Garten wieder Unfug getrieben.","en":"The children have been getting up to mischief in the garden again."},{"de":"Hör auf, Unfug zu treiben, und mach deine Hausaufgaben!","en":"Stop messing about and do your homework!"},{"de":"Sie trieben auf der Klassenfahrt allerlei Unfug.","en":"On the class trip they got up to all sorts of mischief."}],"exPlain":[{"de":"Die Kinder haben im Garten wieder herumgealbert.","en":"The children have been messing about in the garden again."},{"de":"Hör auf herumzualbern und mach deine Hausaufgaben!","en":"Stop messing about and do your homework!"}]},
 {"np":"Missbrauch","verb":"treiben","plain":"missbrauchen","en":"to abuse, to misuse","lv":"C1","vdecoys":["machen","führen","geben"],"pdecoys":["gebrauchen","verbrauchen","brauchen"],"note":"Missbrauch treiben mit + Dat.: etwas falsch oder schädlich benutzen. Häufiger ist das einfache Verb missbrauchen.","ex":[{"de":"Er treibt Missbrauch mit dem Vertrauen seiner Kunden.","en":"He abuses his customers' trust."},{"de":"Die Firma hat jahrelang Missbrauch mit Fördergeldern getrieben.","en":"For years the company misused subsidies."},{"de":"Wer mit Medikamenten Missbrauch treibt, gefährdet seine Gesundheit.","en":"Anyone who abuses medication endangers their health."}],"exPlain":[{"de":"Er missbraucht das Vertrauen seiner Kunden.","en":"He abuses his customers' trust."},{"de":"Die Firma hat jahrelang Fördergelder missbraucht.","en":"For years the company misused subsidies."}]},
 {"np":"Spott","verb":"treiben","plain":"spotten","en":"to mock, to make fun of","lv":"C1","vdecoys":["machen","führen","geben"],"pdecoys":["loben","bewundern","danken"],"note":"Spott treiben mit + Dat. = sich über jdn./etwas lustig machen. Gehoben.","ex":[{"de":"Die Mitschüler trieben Spott mit seinem Akzent.","en":"His classmates mocked his accent."},{"de":"Er trieb gern Spott mit den Schwächen anderer.","en":"He liked to make fun of other people's weaknesses."},{"de":"Die Presse trieb jahrelang Spott mit dem Politiker.","en":"For years the press ridiculed the politician."}],"exPlain":[{"de":"Die Mitschüler spotteten über seinen Akzent.","en":"His classmates mocked his accent."},{"de":"Er spottete gern über die Schwächen anderer.","en":"He liked to mock other people's weaknesses."}]},
 {"np":"Forschung","verb":"betreiben","plain":"forschen","en":"to carry out research","lv":"B2","vdecoys":["stellen","führen","halten"],"pdecoys":["studieren","lehren","lernen"],"note":"Forschung betreiben (auf einem Gebiet). Das Passiv ist häufig: Hier wird Forschung betrieben.","ex":[{"de":"An der Universität wird intensiv Forschung zu erneuerbaren Energien betrieben.","en":"Intensive research into renewable energy is carried out at the university."},{"de":"Das Institut betreibt seit 1990 Forschung im Bereich der Krebsmedizin.","en":"The institute has been doing research in cancer medicine since 1990."},{"de":"Wer Forschung betreiben will, braucht Geduld.","en":"Anyone who wants to do research needs patience."}],"exPlain":[{"de":"An der Universität wird intensiv zu erneuerbaren Energien geforscht.","en":"Intensive research into renewable energy is carried out at the university."},{"de":"Das Institut forscht seit 1990 im Bereich der Krebsmedizin.","en":"The institute has been doing research in cancer medicine since 1990."}],"vAlt":["treiben"]},
 {"np":"Durst","verb":"haben","plain":"durstig sein","en":"to be thirsty","lv":"A2","vdecoys":["sein","werden","tun"],"pdecoys":["hungrig sein","müde sein","trinken"],"note":"Nicht: Ich bin Durst. Mit dem Nomen immer haben (Hunger haben, Durst haben).","ex":[{"de":"Nach dem Sport habe ich großen Durst.","en":"After sports I am very thirsty."},{"de":"Hast du Durst? Hier ist Wasser.","en":"Are you thirsty? Here is some water."},{"de":"Die Kinder hatten Durst, weil es so heiß war.","en":"The children were thirsty because it was so hot."}],"exPlain":[{"de":"Nach dem Sport bin ich sehr durstig.","en":"After sports I am very thirsty."},{"de":"Die Kinder waren durstig, weil es so heiß war.","en":"The children were thirsty because it was so hot."}]},
 {"np":"Schmerzen","verb":"haben","plain":"wehtun","en":"to be in pain / to hurt","lv":"A2","vdecoys":["sein","tun","werden"],"pdecoys":["bluten","heilen","schwitzen"],"note":"Der Satzbau wechselt: Ich habe Schmerzen im Rücken = Mein Rücken tut (mir) weh. Wehtun ist trennbar (er tut weh).","ex":[{"de":"Seit gestern habe ich starke Schmerzen im Rücken.","en":"I have had severe back pain since yesterday."},{"de":"Hast du Schmerzen? Soll ich einen Arzt rufen?","en":"Are you in pain? Should I call a doctor?"},{"de":"Mein Opa hatte nach der Operation lange Schmerzen.","en":"After the operation my grandfather was in pain for a long time."}],"exPlain":[{"de":"Mein Rücken tut seit gestern sehr weh.","en":"My back has hurt a lot since yesterday."},{"de":"Tut dir etwas weh?","en":"Does something hurt?"}]},
 {"np":"Langeweile","verb":"haben","plain":"sich langweilen","en":"to be bored","lv":"A2","vdecoys":["sein","tun","werden"],"pdecoys":["sich freuen","sich ärgern","sich ausruhen"],"note":"Das einfache Verb ist reflexiv: sich langweilen. Dritte Möglichkeit: Mir ist langweilig.","ex":[{"de":"Bei Regen haben die Kinder schnell Langeweile.","en":"When it rains, the children quickly get bored."},{"de":"Ich habe Langeweile. Hast du eine Idee?","en":"I'm bored. Do you have an idea?"},{"de":"Am Sonntag hatte er zu Hause große Langeweile.","en":"On Sunday he was very bored at home."}],"exPlain":[{"de":"Bei Regen langweilen sich die Kinder schnell.","en":"When it rains, the children quickly get bored."},{"de":"Ich langweile mich. Hast du eine Idee?","en":"I'm bored. Do you have an idea?"}]},
 {"np":"eine Erkältung","verb":"haben","plain":"erkältet sein","en":"to have a cold","lv":"A2","vdecoys":["sein","machen","tun"],"pdecoys":["verletzt sein","müde sein","gesund sein"],"note":"Der Beginn heißt sich erkälten: Ich habe mich erkältet.","ex":[{"de":"Ich habe eine Erkältung und bleibe heute im Bett.","en":"I have a cold and am staying in bed today."},{"de":"Meine Tochter hatte letzte Woche eine Erkältung.","en":"My daughter had a cold last week."},{"de":"Hast du etwa eine Erkältung? Du hustest ja so.","en":"Do you have a cold? You are coughing so much."}],"exPlain":[{"de":"Ich bin erkältet und bleibe heute im Bett.","en":"I have a cold and am staying in bed today."},{"de":"Meine Tochter war letzte Woche erkältet.","en":"My daughter had a cold last week."}]},
 {"np":"Husten","verb":"haben","plain":"husten","en":"to have a cough / to cough","lv":"A2","vdecoys":["machen","sein","tun"],"pdecoys":["niesen","schnarchen","atmen"],"note":"Husten haben nennt den Zustand (oft über längere Zeit); husten kann auch eine einzelne Handlung sein.","ex":[{"de":"Seit drei Tagen habe ich Husten.","en":"I have had a cough for three days."},{"de":"Der Junge hatte nachts starken Husten.","en":"The boy had a bad cough at night."},{"de":"Wenn du Husten hast, solltest du viel Tee trinken.","en":"If you have a cough, you should drink a lot of tea."}],"exPlain":[{"de":"Ich huste seit drei Tagen.","en":"I have been coughing for three days."},{"de":"Der Junge hustete nachts viel.","en":"The boy coughed a lot at night."}]},
 {"np":"Verspätung","verb":"haben","plain":"verspätet sein","en":"to be delayed / late (train, flight)","lv":"A2","vdecoys":["sein","machen","tun"],"pdecoys":["pünktlich sein","ausfallen","abfahren"],"note":"Vor allem bei Zug, Bus und Flug. Bei Personen sagt man eher: Ich komme zu spät.","ex":[{"de":"Der Zug nach Hamburg hat zwanzig Minuten Verspätung.","en":"The train to Hamburg is twenty minutes late."},{"de":"Hat das Flugzeug wieder Verspätung?","en":"Is the plane delayed again?"},{"de":"Entschuldigung, ich habe leider zehn Minuten Verspätung.","en":"Sorry, I'm afraid I'm ten minutes late."}],"exPlain":[{"de":"Der Zug nach Hamburg ist zwanzig Minuten verspätet.","en":"The train to Hamburg is twenty minutes late."},{"de":"Ist das Flugzeug wieder verspätet?","en":"Is the plane delayed again?"}]},
 {"np":"zu spät","verb":"kommen","plain":"sich verspäten","en":"to be late, to arrive late","lv":"A2","vdecoys":["machen","nehmen","haben"],"pdecoys":["sich beeilen","warten","verpassen"],"pAlt":["verspätet sein"],"note":"Das einfache Verb ist reflexiv: sich verspäten (Ich habe mich verspätet).","ex":[{"de":"Wenn du zu spät kommst, hat der Film schon angefangen.","en":"If you arrive late, the film will already have started."},{"de":"Der Bus kam heute leider zu spät.","en":"The bus was late today, unfortunately."},{"de":"Sie kommt fast nie zu spät.","en":"She is almost never late."}],"exPlain":[{"de":"Ich verspäte mich heute etwas.","en":"I will be a bit late today."},{"de":"Der Bus hat sich heute leider verspätet.","en":"The bus was delayed today, unfortunately."}]},
 {"np":"eine Party","verb":"machen","plain":"feiern","en":"to have / throw a party","lv":"A2","vdecoys":["nehmen","tun","spielen"],"pdecoys":["tanzen","einladen","besuchen"],"vAlt":["geben","veranstalten","schmeißen"],"note":"Eine Party geben klingt etwas gehobener; umgangssprachlich auch: eine Party schmeißen.","ex":[{"de":"Zu meinem Geburtstag mache ich eine kleine Party.","en":"For my birthday I'm having a small party."},{"de":"Die Nachbarn haben gestern eine Party gemacht, und es war sehr laut.","en":"The neighbours had a party yesterday and it was very loud."},{"de":"Wollen wir im Garten eine Party machen?","en":"Shall we have a party in the garden?"}],"exPlain":[{"de":"Zu meinem Geburtstag feiere ich mit Freunden.","en":"For my birthday I celebrate with friends."},{"de":"Am Samstag feiern wir bei uns zu Hause.","en":"On Saturday we're celebrating at our place."}]},
 {"np":"eine Wanderung","verb":"machen","plain":"wandern","en":"to go on a hike","lv":"A2","vdecoys":["nehmen","tun","treiben"],"pdecoys":["spazieren","klettern","reisen"],"vAlt":["unternehmen"],"note":"Mit dem Nomen steht machen; mit dem Verb: wandern oder wandern gehen.","ex":[{"de":"Am Sonntag machen wir eine Wanderung in den Bergen.","en":"On Sunday we're going on a hike in the mountains."},{"de":"Im Urlaub haben wir jeden Tag eine kleine Wanderung gemacht.","en":"On holiday we went on a short hike every day."},{"de":"Wollen wir morgen eine Wanderung machen, wenn das Wetter gut ist?","en":"Shall we go on a hike tomorrow if the weather is good?"}],"exPlain":[{"de":"Am Sonntag wandern wir in den Bergen.","en":"On Sunday we're hiking in the mountains."},{"de":"Im Urlaub sind wir jeden Tag ein Stück gewandert.","en":"On holiday we hiked a little every day."}]},
 {"np":"Rad","verb":"fahren","plain":"radeln","en":"to ride a bike, to cycle","lv":"A2","vdecoys":["gehen","laufen","treiben"],"pdecoys":["wandern","joggen","reiten"],"note":"Radeln ist umgangssprachlich, aber sehr üblich. Auch: Fahrrad fahren.","ex":[{"de":"Mein Sohn kann schon gut Rad fahren.","en":"My son can already ride a bike well."},{"de":"Am Sonntag fahren wir gern Rad.","en":"On Sundays we like to go cycling."},{"de":"Fährst du auch so gern Rad wie ich?","en":"Do you like cycling as much as I do?"}],"exPlain":[{"de":"Mein Sohn kann schon gut radeln.","en":"My son can already ride a bike well."},{"de":"Am Sonntag radeln wir gern.","en":"On Sundays we like to go cycling."}]},
 {"np":"ein Geschenk","verb":"machen","plain":"schenken","en":"to give someone a present","lv":"A2","vdecoys":["sagen","stellen","tun"],"pdecoys":["kaufen","einpacken","bekommen"],"note":"Mit Dativ: jemandem ein Geschenk machen. Das einfache Verb schenken braucht Dativ und Akkusativ.","ex":[{"de":"Zu Weihnachten machen wir uns immer kleine Geschenke.","en":"At Christmas we always give each other small presents."},{"de":"Meine Oma hat mir zum Geburtstag ein schönes Geschenk gemacht.","en":"My grandma gave me a lovely present for my birthday."},{"de":"Er hat seiner Frau ein besonderes Geschenk gemacht.","en":"He gave his wife a special present."}],"exPlain":[{"de":"Zu Weihnachten schenken wir uns immer etwas Kleines.","en":"At Christmas we always give each other something small."},{"de":"Meine Oma hat mir zum Geburtstag ein Buch geschenkt.","en":"My grandma gave me a book for my birthday."}]},
 {"np":"Pläne","verb":"machen","plain":"planen","en":"to make plans","lv":"A2","vdecoys":["tun","nehmen","bauen"],"pdecoys":["träumen","hoffen","vergessen"],"vAlt":["schmieden"],"note":"Pläne haben bedeutet etwas anderes: Hast du Pläne für heute? = Hast du etwas vor?","ex":[{"de":"Wir machen schon Pläne für unseren Urlaub im Sommer.","en":"We are already making plans for our summer holiday."},{"de":"Für das Wochenende habe ich noch keine Pläne gemacht.","en":"I haven't made any plans for the weekend yet."},{"de":"Lass uns zusammen Pläne für den Abend machen!","en":"Let's make plans for the evening together!"}],"exPlain":[{"de":"Wir planen schon unseren Urlaub im Sommer.","en":"We are already planning our summer holiday."},{"de":"Lass uns zusammen den Abend planen!","en":"Let's plan the evening together!"}]},
 {"np":"Danke","verb":"sagen","plain":"sich bedanken","en":"to say thank you","lv":"A2","vdecoys":["geben","machen","tun"],"pdecoys":["grüßen","sich entschuldigen","antworten"],"pAlt":["danken"],"note":"Sich bedanken: bei jemandem für etwas. Danken steht mit Dativ: Ich danke dir.","ex":[{"de":"Sag deiner Oma bitte Danke für das Geschenk!","en":"Please say thank you to your grandma for the present!"},{"de":"Die Kinder sagen der Lehrerin Danke.","en":"The children say thank you to the teacher."},{"de":"Ich wollte euch nur Danke sagen.","en":"I just wanted to say thank you to you."}],"exPlain":[{"de":"Hast du dich schon bei deiner Oma bedankt?","en":"Have you thanked your grandma yet?"},{"de":"Ich möchte mich bei euch für die Hilfe bedanken.","en":"I would like to thank you for your help."}]},
 {"np":"Hallo","verb":"sagen","plain":"grüßen","en":"to say hello, to send regards","lv":"A2","vdecoys":["geben","machen","tun"],"pdecoys":["sich verabschieden","antworten","einladen"],"note":"Grüßen hat Akkusativ (jemanden grüßen); bei Hallo sagen steht der Empfänger im Dativ.","ex":[{"de":"Die Kinder sagen jedem Nachbarn Hallo.","en":"The children say hello to every neighbour."},{"de":"Sag deiner Schwester bitte Hallo von mir!","en":"Please say hello to your sister from me!"},{"de":"Ich wollte nur kurz Hallo sagen.","en":"I just wanted to say a quick hello."}],"exPlain":[{"de":"Die Kinder grüßen jeden Nachbarn.","en":"The children greet every neighbour."},{"de":"Grüß deine Schwester bitte von mir!","en":"Please give my regards to your sister!"}]},
 {"np":"Auf Wiedersehen","verb":"sagen","plain":"sich verabschieden","en":"to say goodbye","lv":"A2","vdecoys":["geben","machen","tun"],"pdecoys":["begrüßen","sich entschuldigen","sich bedanken"],"note":"Das einfache Verb ist reflexiv: sich von jemandem verabschieden.","ex":[{"de":"Die Kinder sagen der Lehrerin Auf Wiedersehen.","en":"The children say goodbye to the teacher."},{"de":"Nach dem Essen sagten wir allen Auf Wiedersehen.","en":"After dinner we said goodbye to everyone."},{"de":"Ich muss jetzt gehen und möchte noch kurz Auf Wiedersehen sagen.","en":"I have to go now and would like to say goodbye quickly."}],"exPlain":[{"de":"Die Kinder verabschieden sich von der Lehrerin.","en":"The children say goodbye to the teacher."},{"de":"Nach dem Essen verabschiedeten wir uns von allen.","en":"After dinner we said goodbye to everyone."}]},
 {"np":"ein Picknick","verb":"machen","plain":"picknicken","en":"to have a picnic","lv":"A2","vdecoys":["tun","nehmen","spielen"],"pdecoys":["grillen","wandern","kochen"],"ex":[{"de":"Bei schönem Wetter machen wir ein Picknick im Park.","en":"In nice weather we have a picnic in the park."},{"de":"Gestern haben wir am See ein Picknick gemacht.","en":"Yesterday we had a picnic by the lake."},{"de":"Sollen wir morgen ein Picknick machen?","en":"Shall we have a picnic tomorrow?"}],"exPlain":[{"de":"Bei schönem Wetter picknicken wir im Park.","en":"In nice weather we have a picnic in the park."},{"de":"Gestern haben wir am See gepicknickt.","en":"Yesterday we had a picnic by the lake."}]},
 {"np":"einen Kuss","verb":"geben","plain":"küssen","en":"to give someone a kiss","lv":"A2","vdecoys":["stellen","tun","sagen"],"pdecoys":["umarmen","streicheln","begrüßen"],"note":"Mit Dativ: jemandem einen Kuss geben; küssen steht mit Akkusativ.","ex":[{"de":"Das kleine Mädchen gibt seiner Mutter einen Kuss.","en":"The little girl gives her mother a kiss."},{"de":"Gib mir noch einen Kuss, bevor du gehst!","en":"Give me another kiss before you go!"},{"de":"Er hat seiner Frau zum Abschied einen Kuss gegeben.","en":"He gave his wife a kiss goodbye."}],"exPlain":[{"de":"Das kleine Mädchen küsst seine Mutter.","en":"The little girl kisses her mother."},{"de":"Er hat seine Frau zum Abschied geküsst.","en":"He kissed his wife goodbye."}]},
 {"np":"in den Arm","verb":"nehmen","plain":"umarmen","en":"to give someone a hug","lv":"A2","vdecoys":["stellen","bringen","machen"],"pdecoys":["küssen","streicheln","begrüßen"],"note":"Auch möglich: jemanden in die Arme nehmen.","ex":[{"de":"Als meine Freundin traurig war, nahm ich sie in den Arm.","en":"When my friend was sad, I gave her a hug."},{"de":"Komm her, ich nehme dich kurz in den Arm.","en":"Come here, let me give you a quick hug."},{"de":"Zur Begrüßung nimmt mein Opa mich immer fest in den Arm.","en":"To greet me, my grandpa always gives me a big hug."}],"exPlain":[{"de":"Als meine Freundin traurig war, umarmte ich sie.","en":"When my friend was sad, I hugged her."},{"de":"Zur Begrüßung umarmt mein Opa mich immer fest.","en":"To greet me, my grandpa always hugs me tightly."}]},
 {"np":"Übungen","verb":"machen","plain":"üben","en":"to do exercises, to practise","lv":"A2","vdecoys":["tun","nehmen","treiben"],"pdecoys":["lernen","wiederholen","lösen"],"note":"Nicht: Übungen tun. Üben kann auch ohne Objekt stehen.","ex":[{"de":"Du musst jeden Tag Übungen machen, dann wirst du besser.","en":"You have to do exercises every day, then you will get better."},{"de":"Vor der Prüfung haben wir viele Übungen gemacht.","en":"Before the exam we did a lot of exercises."},{"de":"Die Schüler machen im Unterricht viele Übungen zur Grammatik.","en":"In class the pupils do a lot of grammar exercises."}],"exPlain":[{"de":"Du musst jeden Tag üben, dann wirst du besser.","en":"You have to practise every day, then you will get better."},{"de":"Vor der Prüfung haben wir viel geübt.","en":"Before the exam we practised a lot."}]},
 {"np":"zu Fuß","verb":"gehen","plain":"laufen","en":"to walk, to go on foot","lv":"A2","vdecoys":["fahren","reisen","fliegen"],"pdecoys":["radeln","springen","schwimmen"],"note":"Laufen heißt im Alltag oft einfach „zu Fuß gehen“; es kann aber auch „rennen“ bedeuten. Gegenteil: fahren.","ex":[{"de":"Bei schönem Wetter gehen wir zu Fuß zur Schule.","en":"In nice weather we walk to school."},{"de":"Der Bahnhof ist ganz nah, wir können zu Fuß gehen.","en":"The station is very close, we can go on foot."},{"de":"Mein Onkel geht jeden Tag zu Fuß zur Arbeit.","en":"My uncle walks to work every day."}],"exPlain":[{"de":"Der Bahnhof ist ganz nah, wir können laufen.","en":"The station is very close, we can walk."},{"de":"Zur Arbeit laufe ich meistens.","en":"I usually walk to work."}]},
 {"np":"einen Traum","verb":"haben","plain":"träumen","en":"to have a dream (while asleep)","lv":"A2","vdecoys":["sehen","machen","nehmen"],"pdecoys":["schlafen","aufwachen","schnarchen"],"note":"Nicht: einen Traum sehen (wie im Russischen). Ein Traum kann auch ein Lebenswunsch sein (Ich habe einen Traum); dann ist träumen hier nicht gemeint.","ex":[{"de":"Letzte Nacht hatte ich einen schönen Traum.","en":"Last night I had a lovely dream."},{"de":"Hast du manchmal einen Traum, an den du dich am Morgen noch genau erinnerst?","en":"Do you sometimes have a dream that you still remember exactly the next morning?"},{"de":"Er hatte einen Traum und lachte laut im Schlaf.","en":"He was dreaming and laughed loudly in his sleep."}],"exPlain":[{"de":"Letzte Nacht habe ich etwas Schönes geträumt.","en":"Last night I dreamed something lovely."},{"de":"Er träumte und lachte laut im Schlaf.","en":"He was dreaming and laughed loudly in his sleep."}]},
 {"np":"gute Laune","verb":"haben","plain":"gut gelaunt sein","en":"to be in a good mood","lv":"A2","vdecoys":["sein","werden","tun"],"pdecoys":["traurig sein","müde sein","wütend sein"],"note":"Gegenteil: schlechte Laune haben. Auch: guter Laune sein (gehoben).","ex":[{"de":"Heute habe ich gute Laune, weil die Sonne scheint.","en":"Today I'm in a good mood because the sun is shining."},{"de":"Meine Schwester hat morgens nie gute Laune.","en":"My sister is never in a good mood in the morning."},{"de":"Warum hast du denn so gute Laune?","en":"Why are you in such a good mood?"}],"exPlain":[{"de":"Heute bin ich gut gelaunt, weil die Sonne scheint.","en":"Today I'm in a good mood because the sun is shining."},{"de":"Meine Schwester ist morgens nie gut gelaunt.","en":"My sister is never in a good mood in the morning."}]},
 {"np":"Ja","verb":"sagen","plain":"zustimmen","en":"to say yes, to agree","lv":"B1","vdecoys":["geben","machen","tun"],"pdecoys":["ablehnen","fragen","hoffen"],"note":"Ja sagen zu + Dativ; zustimmen steht direkt mit Dativ (jemandem/einer Sache zustimmen).","ex":[{"de":"Zu meinem Vorschlag hat sie sofort Ja gesagt.","en":"She said yes to my suggestion straight away."},{"de":"Wenn du mitkommen möchtest, sag einfach Ja.","en":"If you'd like to come along, just say yes."},{"de":"Meine Eltern haben zu dem Plan Ja gesagt.","en":"My parents said yes to the plan."}],"exPlain":[{"de":"Sie hat meinem Vorschlag sofort zugestimmt.","en":"She agreed to my suggestion straight away."},{"de":"Meine Eltern haben dem Plan zugestimmt.","en":"My parents agreed to the plan."}]},
 {"np":"Nein","verb":"sagen","plain":"ablehnen","en":"to say no, to decline","lv":"B1","vdecoys":["geben","machen","tun"],"pdecoys":["zustimmen","annehmen","vorschlagen"],"note":"Nein sagen zu + Dativ; ablehnen hat ein Akkusativobjekt (etwas ablehnen).","ex":[{"de":"Zu dem Job hat sie leider Nein gesagt.","en":"She said no to the job, unfortunately."},{"de":"Aus Höflichkeit sagt er nur selten Nein.","en":"Out of politeness he rarely says no."},{"de":"Die Kinder haben zum Spinat energisch Nein gesagt.","en":"The children said a firm no to the spinach."}],"exPlain":[{"de":"Den Job hat sie leider abgelehnt.","en":"She turned down the job, unfortunately."},{"de":"Den Spinat haben die Kinder energisch abgelehnt.","en":"The children firmly refused the spinach."}]},
 {"np":"Mühe","verb":"geben","plain":"sich anstrengen","en":"to make an effort","lv":"B1","vdecoys":["nehmen","tun","stellen"],"pdecoys":["sich beeilen","sich ärgern","sich ausruhen"],"pAlt":["sich bemühen"],"note":"Immer reflexiv: sich (Dat.) Mühe geben. Nicht verwechseln: Mühe machen = Arbeit verursachen; Mühe haben = Schwierigkeiten haben.","ex":[{"de":"Die Kinder geben sich beim Malen viel Mühe.","en":"The children take great pains with their painting."},{"de":"Ich habe mir bei dem Kuchen große Mühe gegeben.","en":"I put a lot of effort into the cake."},{"de":"Gib dir bitte etwas mehr Mühe mit deiner Schrift!","en":"Please make a bit more effort with your handwriting!"}],"exPlain":[{"de":"Die Kinder strengen sich beim Malen sehr an.","en":"The children try very hard with their painting."},{"de":"Streng dich bitte mit deiner Schrift etwas mehr an!","en":"Please try a bit harder with your handwriting!"}]},
 {"np":"Grüße","verb":"bestellen","plain":"grüßen","en":"to pass on greetings","lv":"B1","vdecoys":["machen","tun","stellen"],"pdecoys":["verabschieden","einladen","begrüßen"],"vAlt":["ausrichten","übermitteln"],"note":"Mit Dativ: jemandem Grüße bestellen; grüßen steht mit Akkusativ. Übermitteln klingt förmlicher.","ex":[{"de":"Bestell deiner Mutter bitte schöne Grüße von mir!","en":"Please give your mother my best regards!"},{"de":"Ich soll dir von Tom schöne Grüße bestellen.","en":"I'm supposed to pass on Tom's best wishes to you."},{"de":"Sie hat uns herzliche Grüße von unserer Tante bestellt.","en":"She passed on warm greetings from our aunt."}],"exPlain":[{"de":"Grüß deine Mutter bitte von mir!","en":"Please give my regards to your mother!"},{"de":"Tom lässt dich grüßen.","en":"Tom sends his regards."}]},
 {"np":"ein Telefonat","verb":"führen","plain":"telefonieren","en":"to make / have a phone call","lv":"B1","vdecoys":["geben","halten","stellen"],"pdecoys":["schreiben","klingeln","zuhören"],"ex":[{"de":"Ich muss noch schnell ein Telefonat führen.","en":"I just have to make a quick phone call."},{"de":"Während des Essens führte er ein langes Telefonat.","en":"During the meal he had a long phone call."},{"de":"Sie hat im Zug ein Telefonat mit ihrer Schwester geführt.","en":"She had a phone call with her sister on the train."}],"exPlain":[{"de":"Ich muss noch schnell telefonieren.","en":"I just have to make a quick phone call."},{"de":"Während des Essens telefonierte er lange.","en":"During the meal he was on the phone for a long time."}]},
 {"np":"einen Bummel","verb":"machen","plain":"bummeln","en":"to go for a stroll (through town)","lv":"B1","vdecoys":["nehmen","tun","treiben"],"pdecoys":["einkaufen","joggen","sich ausruhen"],"note":"Meist ein Stadtbummel: ohne Ziel durch Straßen und Geschäfte gehen.","ex":[{"de":"Nach dem Essen machen wir noch einen Bummel durch die Altstadt.","en":"After the meal we'll go for a stroll through the old town."},{"de":"Am Samstag haben wir einen langen Bummel durch die Stadt gemacht.","en":"On Saturday we went for a long stroll through town."},{"de":"Hast du Lust, einen kleinen Bummel zu machen?","en":"Do you feel like a little stroll?"}],"exPlain":[{"de":"Nach dem Essen bummeln wir noch durch die Altstadt.","en":"After the meal we'll stroll through the old town."},{"de":"Am Samstag sind wir lange durch die Stadt gebummelt.","en":"On Saturday we strolled through town for a long time."}]},
 {"np":"ein Sonnenbad","verb":"nehmen","plain":"sich sonnen","en":"to sunbathe","lv":"B1","vdecoys":["geben","haben","tun"],"pdecoys":["baden","schwimmen","sich abkühlen"],"note":"Das einfache Verb ist reflexiv: sich sonnen.","ex":[{"de":"Auf dem Balkon nimmt sie gern ein Sonnenbad.","en":"She likes to sunbathe on the balcony."},{"de":"Nach dem Schwimmen haben wir ein Sonnenbad genommen.","en":"After swimming we sunbathed."},{"de":"Du solltest nicht zu lange ein Sonnenbad nehmen.","en":"You shouldn't sunbathe for too long."}],"exPlain":[{"de":"Auf dem Balkon sonnt sie sich gern.","en":"She likes to sunbathe on the balcony."},{"de":"Nach dem Schwimmen haben wir uns gesonnt.","en":"After swimming we sunbathed."}]},
 {"np":"eine Dusche","verb":"nehmen","plain":"duschen","en":"to take a shower","lv":"B1","vdecoys":["tun","stellen","bringen"],"pdecoys":["baden","waschen","putzen"],"note":"Duschen ist im Alltag deutlich häufiger.","ex":[{"de":"Nach dem Sport nehme ich immer eine kalte Dusche.","en":"After sport I always take a cold shower."},{"de":"Ich will schnell eine Dusche nehmen, dann gehen wir.","en":"I just want to take a quick shower, then we'll go."},{"de":"Hast du schon eine Dusche genommen?","en":"Have you already had a shower?"}],"exPlain":[{"de":"Nach dem Sport dusche ich immer kalt.","en":"After sport I always shower cold."},{"de":"Ich will schnell duschen, dann gehen wir.","en":"I just want to take a quick shower, then we'll go."}]},
 {"np":"Bekanntschaft","verb":"machen","plain":"kennenlernen","en":"to make someone's acquaintance","lv":"B2","vdecoys":["nehmen","geben","treffen"],"pdecoys":["besuchen","einladen","vorstellen"],"note":"Meist: jemandes Bekanntschaft machen (gehoben). Mit etwas Bekanntschaft machen heißt oft ironisch: etwas Unangenehmes kennenlernen (mit der Polizei). Kennenlernen steht mit Akkusativ.","ex":[{"de":"Im Urlaub habe ich die Bekanntschaft eines netten Ehepaars gemacht.","en":"On holiday I made the acquaintance of a nice couple."},{"de":"Auf der Party haben wir die Bekanntschaft ihres Bruders gemacht.","en":"At the party we made the acquaintance of her brother."},{"de":"Er machte auf der Reise die Bekanntschaft einer jungen Frau.","en":"On the journey he made the acquaintance of a young woman."}],"exPlain":[{"de":"Im Urlaub habe ich ein nettes Ehepaar kennengelernt.","en":"On holiday I got to know a nice couple."},{"de":"Auf der Party haben wir ihren Bruder kennengelernt.","en":"At the party we got to know her brother."}]},
 {"np":"Unrecht","verb":"haben","plain":"sich irren","en":"to be wrong","lv":"B1","vdecoys":["machen","nehmen","stellen"],"pdecoys":["zweifeln","vermuten","vergessen"],"note":"Gegenteil: Recht haben. Nicht verwechseln: jemandem Unrecht tun = jemanden ungerecht behandeln.","ex":[{"de":"Da hast du leider Unrecht, der Laden schließt erst um acht.","en":"You're wrong there, I'm afraid; the shop only closes at eight."},{"de":"Ich glaube, ich hatte Unrecht.","en":"I think I was wrong."},{"de":"Mein Bruder gibt nie zu, dass er Unrecht hat.","en":"My brother never admits that he is wrong."}],"exPlain":[{"de":"Da irrst du dich leider, der Laden schließt erst um acht.","en":"You're mistaken there, I'm afraid; the shop only closes at eight."},{"de":"Ich glaube, ich habe mich geirrt.","en":"I think I was mistaken."}]},
 {"np":"Stress","verb":"haben","plain":"gestresst sein","en":"to be stressed, to be under stress","lv":"B1","vdecoys":["sein","tun","werden"],"pdecoys":["müde sein","krank sein","faul sein"],"note":"Stress haben mit jemandem heißt umgangssprachlich auch: Ärger haben (dann passt gestresst sein nicht).","ex":[{"de":"Vor Weihnachten habe ich immer viel Stress.","en":"Before Christmas I'm always really stressed."},{"de":"Er hat im Moment viel Stress bei der Arbeit.","en":"He is under a lot of stress at work at the moment."},{"de":"Wegen der Prüfungen haben die Studenten gerade viel Stress.","en":"Because of the exams the students are under a lot of stress right now."}],"exPlain":[{"de":"Vor Weihnachten bin ich immer gestresst.","en":"Before Christmas I am always stressed."},{"de":"Er ist im Moment bei der Arbeit sehr gestresst.","en":"He is very stressed at work at the moment."}]},
 {"np":"Musik","verb":"machen","plain":"musizieren","en":"to make music","lv":"B1","vdecoys":["nehmen","halten","tun"],"pdecoys":["singen","tanzen","komponieren"],"note":"Musik machen = selbst singen oder spielen (nicht nur hören). Musizieren ist etwas gehobener.","ex":[{"de":"Am Wochenende machen wir zusammen Musik.","en":"At the weekend we make music together."},{"de":"In unserer Familie hat man immer viel Musik gemacht.","en":"In our family people have always played a lot of music."},{"de":"Mit Freunden Musik zu machen, macht mir großen Spaß.","en":"Making music with friends is great fun for me."}],"exPlain":[{"de":"Am Wochenende musizieren wir zusammen.","en":"At the weekend we make music together."},{"de":"In unserer Familie hat man immer viel musiziert.","en":"In our family people have always made a lot of music."}]},
 {"np":"einen Versuch","verb":"machen","plain":"versuchen","en":"to make an attempt, to try","lv":"B1","vdecoys":["geben","nehmen","treffen"],"pdecoys":["planen","hoffen","scheitern"],"vAlt":["unternehmen","wagen"],"note":"Einen Versuch machen/unternehmen/wagen sind möglich, versuchen ist im Alltag viel häufiger.","ex":[{"de":"Machen wir noch einen Versuch, vielleicht klappt es diesmal.","en":"Let's make one more attempt, maybe it will work this time."},{"de":"Er hat schon mehrmals den Versuch gemacht, mit dem Rauchen aufzuhören.","en":"He has tried several times to stop smoking."},{"de":"Ich mache einen letzten Versuch und rufe ihn noch einmal an.","en":"I'll make one last attempt and call him again."}],"exPlain":[{"de":"Versuchen wir es noch einmal, vielleicht klappt es diesmal.","en":"Let's try again, maybe it will work this time."},{"de":"Er hat mehrmals versucht, mit dem Rauchen aufzuhören.","en":"He has tried several times to stop smoking."}]},
 {"np":"an die Reihe","verb":"kommen","plain":"drankommen","en":"to have one's turn","lv":"B1","vdecoys":["gehen","treten","stehen"],"pdecoys":["warten","anstehen","aufpassen"],"note":"Drankommen ist umgangssprachlich. Der Zustand heißt an der Reihe sein oder dran sein (Wer ist dran?).","ex":[{"de":"Warten Sie bitte, Sie kommen gleich an die Reihe.","en":"Please wait, it will be your turn in a moment."},{"de":"Ich warte schon dreißig Minuten und komme immer noch nicht an die Reihe.","en":"I've been waiting for thirty minutes and it's still not my turn."},{"de":"Wann kommen wir endlich an die Reihe?","en":"When will it finally be our turn?"}],"exPlain":[{"de":"Warten Sie bitte, Sie kommen gleich dran.","en":"Please wait, it will be your turn in a moment."},{"de":"Wann kommen wir endlich dran?","en":"When will it finally be our turn?"}]},
 {"np":"Rast","verb":"machen","plain":"rasten","en":"to take a break (on a journey/hike)","lv":"B1","vdecoys":["nehmen","haben","legen"],"pdecoys":["wandern","übernachten","frühstücken"],"vAlt":["halten"],"note":"Bei Wanderung, Radtour oder Autofahrt. Rast machen/halten = unterwegs kurz anhalten und ausruhen.","ex":[{"de":"Nach zwei Stunden machten wir an einer Hütte Rast.","en":"After two hours we took a rest at a hut."},{"de":"Am Mittag machen wir kurz Rast und essen etwas.","en":"At noon we'll stop briefly and eat something."},{"de":"Die Wanderer haben am See Rast gemacht.","en":"The hikers stopped for a rest by the lake."}],"exPlain":[{"de":"Nach zwei Stunden rasteten wir an einer Hütte.","en":"After two hours we rested at a hut."},{"de":"Die Wanderer haben am See gerastet.","en":"The hikers rested by the lake."}]},
 {"np":"Halt","verb":"machen","plain":"anhalten","en":"to stop (on a journey)","lv":"A2","vdecoys":["tun","stellen","nehmen"],"pdecoys":["umsteigen","aussteigen","weiterfahren"],"pAlt":["halten"],"note":"Ähnlich: Rast machen (= anhalten und sich ausruhen). Für Züge und Busse sagt man meist einfach „halten“ (Der Zug hält in Köln).","ex":[{"de":"Wir machen in Köln Halt und essen etwas.","en":"We'll stop in Cologne and eat something."},{"de":"Der Zug macht nur in großen Städten Halt.","en":"The train only stops in big cities."},{"de":"Mach bitte an der nächsten Raststätte Halt.","en":"Please stop at the next service station."}],"exPlain":[{"de":"Wir halten in Köln an und essen etwas.","en":"We'll stop in Cologne and eat something."},{"de":"Halte bitte an der nächsten Raststätte an.","en":"Please stop at the next service station."}]},
 {"np":"den Bus","verb":"nehmen","plain":"mit dem Bus fahren","en":"to take the bus","lv":"A2","vdecoys":["gehen","steigen","kommen"],"pdecoys":["den Bus verpassen","auf den Bus warten","aus dem Bus steigen"],"vAlt":["benutzen"],"note":"Nicht: den Bus fahren – das macht der Busfahrer. Dasselbe gilt für den Zug, die U-Bahn, ein Taxi.","ex":[{"de":"Ich nehme morgens den Bus zur Arbeit.","en":"In the morning I take the bus to work."},{"de":"Wir haben den Bus genommen, weil es geregnet hat.","en":"We took the bus because it was raining."},{"de":"Nimm doch den Bus, das ist einfacher!","en":"Why don't you take the bus, it's easier!"}],"exPlain":[{"de":"Ich fahre morgens mit dem Bus zur Arbeit.","en":"In the morning I go to work by bus."},{"de":"Wir sind mit dem Bus gefahren, weil es geregnet hat.","en":"We went by bus because it was raining."}]},
 {"np":"eine Allergie","verb":"haben","plain":"allergisch sein","en":"to have an allergy, to be allergic","lv":"A2","vdecoys":["sein","machen","tragen"],"pdecoys":["gesund sein","müde sein","niesen"],"note":"Üblich mit gegen + Akk.: eine Allergie gegen Pollen = allergisch gegen Pollen.","ex":[{"de":"Ich habe eine Allergie gegen Nüsse.","en":"I have an allergy to nuts."},{"de":"Mein Sohn hat eine Allergie gegen Katzen.","en":"My son has an allergy to cats."},{"de":"Hast du eine Allergie?","en":"Do you have an allergy?"}],"exPlain":[{"de":"Ich bin allergisch gegen Nüsse.","en":"I am allergic to nuts."},{"de":"Mein Sohn ist allergisch gegen Katzen.","en":"My son is allergic to cats."}]},
 {"np":"Gewicht","verb":"verlieren","plain":"abnehmen","en":"to lose weight","lv":"A2","vdecoys":["verlassen","fallen","wegwerfen"],"pdecoys":["zunehmen","wiegen","essen"],"note":"Auch: an Gewicht verlieren. Das Gegenteil: zunehmen.","ex":[{"de":"Mein Onkel hat im letzten Jahr viel Gewicht verloren.","en":"My uncle lost a lot of weight last year."},{"de":"Sie möchte vor dem Sommer etwas Gewicht verlieren.","en":"She wants to lose a little weight before summer."},{"de":"Ohne Sport verliert man nur langsam Gewicht.","en":"Without exercise you only lose weight slowly."}],"exPlain":[{"de":"Mein Onkel hat im letzten Jahr viel abgenommen.","en":"My uncle lost a lot of weight last year."},{"de":"Sie möchte vor dem Sommer etwas abnehmen.","en":"She wants to lose a little weight before summer."}]},
 {"np":"Luft","verb":"holen","plain":"einatmen","en":"to take a breath, to breathe in","lv":"A2","vdecoys":["stellen","bringen","tun"],"pdecoys":["ausatmen","pusten","schlucken"],"note":"Übertragen: „Luft holen“ = kurz Pause machen, sich erholen.","ex":[{"de":"Der Schwimmer holt tief Luft und taucht unter.","en":"The swimmer takes a deep breath and dives."},{"de":"Warte kurz, ich muss erst Luft holen.","en":"Wait a moment, I have to catch my breath first."},{"de":"Nach dem Lauf musste sie erst einmal tief Luft holen.","en":"After the run she first had to take a deep breath."}],"exPlain":[{"de":"Der Schwimmer atmet tief ein und taucht unter.","en":"The swimmer breathes in deeply and dives."},{"de":"Atmen Sie bitte tief ein.","en":"Please breathe in deeply."}]},
 {"np":"Geduld","verb":"haben","plain":"geduldig sein","en":"to be patient, to have patience","lv":"A2","vdecoys":["sein","halten","machen"],"pdecoys":["ungeduldig sein","wütend sein","müde sein"],"note":"Auch: mit jemandem Geduld haben (Ich habe mit ihm viel Geduld).","ex":[{"de":"Haben Sie bitte noch etwas Geduld, der Arzt kommt gleich.","en":"Please be patient a little longer, the doctor will be here shortly."},{"de":"Mit kleinen Kindern muss man viel Geduld haben.","en":"With small children you need a lot of patience."},{"de":"Ich hatte heute keine Geduld mehr.","en":"I had no patience left today."}],"exPlain":[{"de":"Seien Sie bitte noch etwas geduldig, der Arzt kommt gleich.","en":"Please be patient a little longer, the doctor will be here shortly."},{"de":"Mit kleinen Kindern muss man sehr geduldig sein.","en":"With small children you have to be very patient."}]},
 {"np":"Hoffnung","verb":"haben","plain":"hoffen","en":"to have hope, to hope","lv":"B1","vdecoys":["sein","tun","stellen"],"pdecoys":["zweifeln","warten","fürchten"],"note":"Hoffnung auf + Akk. = hoffen auf + Akk. Mit dass-Satz: Ich habe die Hoffnung, dass … / Ich hoffe, dass …","ex":[{"de":"Ich habe noch Hoffnung, dass sie kommt.","en":"I still have hope that she will come."},{"de":"Wir haben Hoffnung auf besseres Wetter.","en":"We are hoping for better weather."}],"exPlain":[{"de":"Ich hoffe noch, dass sie kommt.","en":"I still hope that she will come."},{"de":"Wir hoffen auf besseres Wetter.","en":"We are hoping for better weather."}]},
 {"np":"Pläne","verb":"haben","plain":"vorhaben","en":"to have plans","lv":"A2","vdecoys":["sein","schaffen","stellen"],"pdecoys":["vergessen","absagen","vorbereiten"],"note":"„Vorhaben“ ist trennbar: Ich habe heute nichts vor. Nicht verwechseln mit „Pläne machen“ (= planen).","ex":[{"de":"Habt ihr am Wochenende schon Pläne?","en":"Do you already have plans for the weekend?"},{"de":"Ich habe für den Urlaub noch keine Pläne.","en":"I don't have any plans for the holiday yet."},{"de":"Sie hat für nächstes Jahr schon viele Pläne.","en":"She already has many plans for next year."}],"exPlain":[{"de":"Habt ihr am Wochenende schon etwas vor?","en":"Do you already have something planned for the weekend?"},{"de":"Sie hat für nächstes Jahr schon viel vor.","en":"She already has a lot planned for next year."}]},
 {"np":"eine Verabredung","verb":"haben","plain":"verabredet sein","en":"to have a date / to have arranged to meet someone","lv":"A2","vdecoys":["sein","tun","geben"],"pdecoys":["verspätet sein","krank sein","allein sein"],"note":"Eine Verabredung ist privat (Freunde, Date). Beim Arzt oder beim Amt sagt man „einen Termin haben“.","ex":[{"de":"Ich habe heute Abend eine Verabredung.","en":"I have a date this evening."},{"de":"Hast du morgen schon eine Verabredung?","en":"Do you already have plans to meet someone tomorrow?"},{"de":"Sie hatte gestern eine Verabredung mit einer Freundin.","en":"Yesterday she had arranged to meet a friend."}],"exPlain":[{"de":"Ich bin heute Abend verabredet.","en":"I have plans to meet someone this evening."},{"de":"Bist du morgen schon verabredet?","en":"Are you already meeting someone tomorrow?"}]},
 {"np":"Unterricht","verb":"geben","plain":"unterrichten","en":"to teach, to give lessons","lv":"A2","vdecoys":["tun","bringen","stellen"],"pdecoys":["lernen","studieren","erklären"],"vAlt":["halten","erteilen"],"pAlt":["lehren"],"note":"Wer Unterricht nimmt oder hat, ist Schüler. „Unterricht erteilen“ ist die formelle Variante.","ex":[{"de":"Er gibt seit zehn Jahren Unterricht.","en":"He has been teaching for ten years."},{"de":"Frau Berger hat früher an einer Grundschule Unterricht gegeben.","en":"Ms Berger used to teach at a primary school."},{"de":"Ich gebe nur am Vormittag Unterricht.","en":"I only teach in the morning."}],"exPlain":[{"de":"Er unterrichtet seit zehn Jahren.","en":"He has been teaching for ten years."},{"de":"Frau Berger hat früher an einer Grundschule unterrichtet.","en":"Ms Berger used to teach at a primary school."}]},
 {"np":"Auskunft","verb":"geben","plain":"informieren","en":"to give information","lv":"A2","vdecoys":["sagen","machen","halten"],"pdecoys":["fragen","bitten","suchen"],"vAlt":["erteilen"],"note":"Auskunft über + Akk. geben; „informieren“ hat die Person im Akkusativ (jemanden über etwas informieren). „Auskunft erteilen“ klingt formeller.","ex":[{"de":"Am Schalter gibt man Ihnen gern Auskunft.","en":"At the counter they will gladly give you information."},{"de":"Können Sie mir bitte Auskunft über die Zugverbindung nach Hamburg geben?","en":"Could you please give me information about the train connection to Hamburg?"},{"de":"Die Mitarbeiterin gab uns freundlich Auskunft.","en":"The employee gave us information in a friendly way."}],"exPlain":[{"de":"Am Schalter informiert man Sie gern.","en":"At the counter they will gladly inform you."},{"de":"Können Sie mich bitte über die Zugverbindung nach Hamburg informieren?","en":"Could you please inform me about the train connection to Hamburg?"}]},
 {"np":"die Erlaubnis","verb":"geben","plain":"erlauben","en":"to give permission","lv":"B1","vdecoys":["machen","tun","stellen"],"pdecoys":["verbieten","bitten","verlangen"],"vAlt":["erteilen"],"note":"Mit Dativ der Person: jemandem die Erlaubnis geben = jemandem etwas erlauben. „Die Erlaubnis erteilen“ ist amtlicher.","ex":[{"de":"Der Lehrer hat uns die Erlaubnis gegeben, früher zu gehen.","en":"The teacher gave us permission to leave early."},{"de":"Meine Eltern geben mir keine Erlaubnis für die Reise.","en":"My parents won't give me permission for the trip."},{"de":"Der Arzt gab ihm die Erlaubnis, wieder zu arbeiten.","en":"The doctor gave him permission to work again."}],"exPlain":[{"de":"Der Lehrer hat uns erlaubt, früher zu gehen.","en":"The teacher allowed us to leave early."},{"de":"Meine Eltern erlauben mir die Reise nicht.","en":"My parents don't allow me to go on the trip."}]},
 {"np":"einen Anruf","verb":"machen","plain":"anrufen","en":"to make a phone call","lv":"A2","vdecoys":["tun","geben","stellen"],"pdecoys":["anklopfen","anmelden","auflegen"],"vAlt":["tätigen"],"note":"„Anrufen“ steht mit Akkusativ: jemanden anrufen. „Einen Anruf tätigen“ ist formell (Amtsdeutsch).","ex":[{"de":"Kann ich kurz einen Anruf machen?","en":"Can I make a quick phone call?"},{"de":"Er hat gestern einen wichtigen Anruf gemacht.","en":"Yesterday he made an important phone call."},{"de":"Ich mache gleich noch einen Anruf, dann komme ich.","en":"I'll make one more call, then I'll come."}],"exPlain":[{"de":"Ich muss noch schnell jemanden anrufen.","en":"I just have to call someone quickly."},{"de":"Er hat gestern wegen der Wohnung angerufen.","en":"Yesterday he called about the flat."}]},
 {"np":"einen Anruf","verb":"bekommen","plain":"angerufen werden","en":"to get a phone call","lv":"A2","vdecoys":["holen","sagen","stellen"],"pdecoys":["anrufen","telefonieren","antworten"],"vAlt":["erhalten","kriegen"],"note":"Passivische Bedeutung: Du bekommst den Anruf, jemand anderes ruft an. Nicht verwechseln: einen Anruf annehmen = ans Telefon gehen.","ex":[{"de":"Ich habe gestern einen Anruf von meiner Bank bekommen.","en":"Yesterday I got a call from my bank."},{"de":"Sie bekam mitten in der Nacht einen Anruf.","en":"She got a call in the middle of the night."},{"de":"Hast du schon einen Anruf von der Firma bekommen?","en":"Have you had a call from the company yet?"}],"exPlain":[{"de":"Ich bin gestern von meiner Bank angerufen worden.","en":"Yesterday my bank called me."},{"de":"Sie wurde mitten in der Nacht angerufen.","en":"She got a call in the middle of the night."}]},
 {"np":"ans Telefon","verb":"gehen","plain":"abheben","en":"to answer the phone","lv":"A2","vdecoys":["antworten","sprechen","fahren"],"pdecoys":["auflegen","anrufen","klingeln"],"pAlt":["rangehen"],"note":"Nicht: ans Telefon antworten. Umgangssprachlich auch: rangehen (Geh doch mal ran!).","ex":[{"de":"Das Telefon klingelt. Gehst du bitte ans Telefon?","en":"The phone is ringing. Could you answer it?"},{"de":"Mein Bruder geht nie ans Telefon.","en":"My brother never answers the phone."},{"de":"Als es klingelte, ging sie sofort ans Telefon.","en":"When it rang, she answered the phone straight away."}],"exPlain":[{"de":"Das Telefon klingelt. Hebst du bitte ab?","en":"The phone is ringing. Could you pick up?"},{"de":"Mein Bruder hebt nie ab.","en":"My brother never picks up."}]},
 {"np":"Notizen","verb":"machen","plain":"notieren","en":"to take notes","lv":"A2","vdecoys":["nehmen","tun","legen"],"pdecoys":["vergessen","lesen","kopieren"],"pAlt":["mitschreiben"],"note":"Meist mit Dativ-Reflexivpronomen: sich (Dat.) Notizen machen. Nicht: Notizen nehmen (englisch „take notes“).","ex":[{"de":"Ich mache mir im Unterricht immer Notizen.","en":"I always take notes in class."},{"de":"Mach dir doch Notizen, dann vergisst du nichts.","en":"Take some notes, then you won't forget anything."},{"de":"Sie hat sich während des Vortrags viele Notizen gemacht.","en":"She took a lot of notes during the talk."}],"exPlain":[{"de":"Ich notiere im Unterricht immer das Wichtigste.","en":"In class I always write down the most important things."},{"de":"Notier dir das lieber, dann vergisst du nichts.","en":"You'd better write that down, then you won't forget it."}]},
 {"np":"einen Fehler","verb":"machen","plain":"etwas falsch machen","en":"to make a mistake","lv":"A2","vdecoys":["tun","nehmen","geben"],"pdecoys":["sich verlaufen","sich ärgern","sich entschuldigen"],"vAlt":["begehen"],"note":"Einen Fehler machen = etwas falsch machen. „Einen Fehler begehen“ klingt gehoben. Nicht dasselbe: sich irren = etwas falsch beurteilen oder meinen.","ex":[{"de":"Ich habe in der Rechnung einen Fehler gemacht.","en":"I made a mistake in the calculation."},{"de":"Jeder macht mal einen Fehler.","en":"Everyone makes a mistake sometimes."},{"de":"Entschuldigung, da habe ich einen Fehler gemacht.","en":"Sorry, I made a mistake there."}],"exPlain":[{"de":"Entschuldigung, da habe ich etwas falsch gemacht.","en":"Sorry, I did something wrong there."},{"de":"Jeder macht mal etwas falsch.","en":"Everyone does something wrong sometimes."}]},
 {"np":"eine Reservierung","verb":"machen","plain":"reservieren","en":"to make a reservation","lv":"A2","vdecoys":["geben","stellen","tun"],"pdecoys":["bestätigen","absagen","bezahlen"],"vAlt":["vornehmen"],"note":"Im Alltag sagt man meist direkt: einen Tisch / ein Zimmer / einen Platz reservieren. „Eine Reservierung vornehmen“ ist formell.","ex":[{"de":"Wir möchten für Samstag eine Reservierung machen.","en":"We would like to make a reservation for Saturday."},{"de":"Hast du schon eine Reservierung gemacht?","en":"Have you already made a reservation?"},{"de":"Ich habe eine Reservierung für vier Personen gemacht.","en":"I made a reservation for four people."}],"exPlain":[{"de":"Wir möchten für Samstag einen Tisch reservieren.","en":"We would like to reserve a table for Saturday."},{"de":"Hast du schon reserviert?","en":"Have you already reserved?"}]},
 {"np":"ein Paket","verb":"aufgeben","plain":"verschicken","en":"to send a parcel (at the post office)","lv":"A2","vdecoys":["angeben","eingeben","nachgeben"],"pdecoys":["abholen","auspacken","öffnen"],"pAlt":["abschicken","schicken"],"note":"Trennbar: Ich gebe das Paket heute auf. Auch: einen Brief aufgeben, Gepäck aufgeben (am Flughafen).","ex":[{"de":"Ich möchte dieses Paket nach Spanien aufgeben.","en":"I would like to send this parcel to Spain."},{"de":"Sie hat gestern ein Paket für ihre Oma aufgegeben.","en":"Yesterday she posted a parcel to her grandma."},{"de":"Wo kann man hier ein Paket aufgeben?","en":"Where can you send a parcel around here?"}],"exPlain":[{"de":"Ich möchte dieses Paket nach Spanien verschicken.","en":"I would like to send this parcel to Spain."},{"de":"Sie hat ihrer Oma gestern ein Paket geschickt.","en":"Yesterday she sent her grandma a parcel."}]},
 {"np":"eine Kopie","verb":"machen","plain":"kopieren","en":"to make a copy","lv":"A2","vdecoys":["tun","nehmen","schreiben"],"pdecoys":["scannen","drucken","speichern"],"vAlt":["anfertigen"],"pAlt":["fotokopieren"],"note":"„Eine Kopie anfertigen“ klingt formeller.","ex":[{"de":"Kannst du mir bitte eine Kopie von dem Brief machen?","en":"Can you please make me a copy of the letter?"},{"de":"Ich habe vom Pass zwei Kopien gemacht.","en":"I made two copies of the passport."},{"de":"Im Büro machen wir schnell eine Kopie.","en":"At the office we'll quickly make a copy."}],"exPlain":[{"de":"Kannst du den Brief bitte kopieren?","en":"Can you please copy the letter?"},{"de":"Ich habe den Pass zweimal kopiert.","en":"I copied the passport twice."}]},
 {"np":"Lärm","verb":"machen","plain":"laut sein","en":"to make noise","lv":"A2","vdecoys":["tun","geben","nehmen"],"pdecoys":["leise sein","ruhig sein","schlafen"],"note":"Auch: Krach machen (umgangssprachlich).","ex":[{"de":"Bitte macht nicht so viel Lärm, das Baby schläft.","en":"Please don't make so much noise, the baby is asleep."},{"de":"Die Nachbarn haben gestern Abend viel Lärm gemacht.","en":"The neighbours made a lot of noise yesterday evening."},{"de":"Kinder machen oft Lärm.","en":"Children often make noise."}],"exPlain":[{"de":"Bitte seid nicht so laut, das Baby schläft.","en":"Please don't be so loud, the baby is asleep."},{"de":"Die Nachbarn waren gestern Abend sehr laut.","en":"The neighbours were very loud yesterday evening."}]},
 {"np":"an der Reihe","verb":"sein","plain":"dran sein","en":"to be someone's turn","lv":"A2","vdecoys":["stehen","gehen","bleiben"],"pdecoys":["warten","anstehen","weggehen"],"note":"„Dran sein“ ist umgangssprachlich. Auch: Wer kommt als Nächster dran?","ex":[{"de":"Sie sind als Nächste an der Reihe.","en":"You are next."},{"de":"Wer ist jetzt an der Reihe?","en":"Whose turn is it now?"},{"de":"Nach dir bin ich an der Reihe.","en":"After you it's my turn."}],"exPlain":[{"de":"Sie sind als Nächste dran.","en":"You are next."},{"de":"Wer ist jetzt dran?","en":"Whose turn is it now?"}]},
 {"np":"Bescheid","verb":"wissen","plain":"informiert sein","en":"to know about something, to be informed","lv":"B1","vdecoys":["kennen","können","verstehen"],"pdecoys":["sich irren","unsicher sein","fragen"],"note":"Meist: über etwas Bescheid wissen; auch: in/mit etwas Bescheid wissen (= sich auskennen). Nicht verwechseln mit „Bescheid sagen“ (= jemanden informieren).","ex":[{"de":"Wissen Sie schon Bescheid? Der Zug fällt aus.","en":"Do you know already? The train is cancelled."},{"de":"Ich weiß über den neuen Termin leider nicht Bescheid.","en":"Unfortunately I don't know about the new appointment."},{"de":"Frag Anna, sie weiß über alles Bescheid.","en":"Ask Anna, she knows about everything."}],"exPlain":[{"de":"Sind Sie schon informiert? Der Zug fällt aus.","en":"Have you been told yet? The train is cancelled."},{"de":"Frag Anna, sie ist über alles informiert.","en":"Ask Anna, she is informed about everything."}]},
 {"np":"Feierabend","verb":"machen","plain":"aufhören zu arbeiten","en":"to finish work for the day, to knock off","lv":"B1","vdecoys":["stellen","legen","führen"],"pdecoys":["anfangen zu arbeiten","länger arbeiten","Pause machen"],"note":"Alltagssprachlich. Feierabend haben beschreibt den Zustand danach (Ich habe Feierabend); Feierabend machen den Moment des Aufhörens.","ex":[{"de":"Um fünf Uhr machen wir normalerweise Feierabend.","en":"We normally knock off at five o'clock."},{"de":"Heute habe ich schon früh Feierabend gemacht, weil nichts mehr zu tun war.","en":"I finished early today because there was nothing left to do."},{"de":"Mach doch endlich Feierabend, du arbeitest schon seit zehn Stunden!","en":"Just call it a day already, you've been working for ten hours!"}],"exPlain":[{"de":"Um fünf Uhr hören wir normalerweise auf zu arbeiten.","en":"We normally stop working at five o'clock."},{"de":"Heute habe ich schon früh aufgehört zu arbeiten, weil nichts mehr zu tun war.","en":"I stopped working early today because there was nothing left to do."}]},
 {"np":"Überstunden","verb":"machen","plain":"länger arbeiten","en":"to work overtime","lv":"B1","vdecoys":["stellen","halten","legen"],"pdecoys":["weniger arbeiten","kündigen","pausieren"],"vAlt":["leisten"],"note":"Überstunden leisten klingt formeller. Gegenteil: Überstunden abbauen (Freizeitausgleich nehmen).","ex":[{"de":"Im Dezember muss ich fast jeden Tag Überstunden machen.","en":"In December I have to work overtime almost every day."},{"de":"Die Verkäuferinnen haben vor Weihnachten viele Überstunden gemacht.","en":"The shop assistants worked a lot of overtime before Christmas."},{"de":"Wenn wir Überstunden machen, bekommen wir dafür freie Tage.","en":"If we work overtime, we get days off in return."}],"exPlain":[{"de":"Im Dezember muss ich fast jeden Tag länger arbeiten.","en":"In December I have to work longer almost every day."},{"de":"Die Verkäuferinnen haben vor Weihnachten oft länger gearbeitet.","en":"The shop assistants often worked longer hours before Christmas."}]},
 {"np":"Werbung","verb":"machen","plain":"werben","en":"to advertise, to promote","lv":"B1","vdecoys":["geben","halten","führen"],"pdecoys":["verkaufen","bestellen","vergleichen"],"vAlt":["treiben","schalten"],"note":"Werbung machen für + Akk. = werben für + Akk. Werbung treiben klingt formeller.","ex":[{"de":"Die Firma macht im Fernsehen viel Werbung für ihre neuen Produkte.","en":"The company does a lot of advertising on television for its new products."},{"de":"Wir haben in der Zeitung Werbung für das Konzert gemacht.","en":"We advertised the concert in the newspaper."},{"de":"Für sein Café macht er vor allem im Internet Werbung.","en":"He mostly advertises his café on the internet."}],"exPlain":[{"de":"Die Firma wirbt im Fernsehen stark für ihre neuen Produkte.","en":"The company advertises its new products heavily on television."},{"de":"Wir haben in der Zeitung für das Konzert geworben.","en":"We advertised the concert in the newspaper."}]},
 {"np":"eine Anzeige","verb":"aufgeben","plain":"inserieren","en":"to place an ad","lv":"B2","vdecoys":["halten","nehmen","legen"],"pdecoys":["abonnieren","lesen","kündigen"],"vAlt":["schalten"],"note":"Gemeint ist die Zeitungs- oder Online-Anzeige (Kleinanzeige), nicht die Strafanzeige. Trennbar: Ich gebe eine Anzeige auf.","ex":[{"de":"Wir haben in der Zeitung eine Anzeige aufgegeben, um das Sofa zu verkaufen.","en":"We placed an ad in the newspaper to sell the sofa."},{"de":"Sie gab eine Anzeige auf, weil sie eine neue Mitarbeiterin suchte.","en":"She placed an ad because she was looking for a new employee."},{"de":"Ich möchte für mein altes Fahrrad im Internet eine Anzeige aufgeben.","en":"I'd like to place an ad online for my old bike."}],"exPlain":[{"de":"Wir haben in der Zeitung inseriert, um das Sofa zu verkaufen.","en":"We advertised in the newspaper to sell the sofa."},{"de":"Sie inserierte, weil sie eine neue Mitarbeiterin suchte.","en":"She advertised because she was looking for a new employee."}]},
 {"np":"eine Bestellung","verb":"aufgeben","plain":"bestellen","en":"to place an order","lv":"B1","vdecoys":["halten","legen","stellen"],"pdecoys":["liefern","bezahlen","verkaufen"],"note":"Trennbar: Ich gebe die Bestellung auf. Im Restaurant nimmt der Kellner die Bestellung auf.","ex":[{"de":"Ich habe gestern im Internet eine Bestellung aufgegeben.","en":"I placed an order online yesterday."},{"de":"Wenn Sie bis 14 Uhr eine Bestellung aufgeben, liefern wir schon morgen.","en":"If you place an order by 2 p.m., we will deliver tomorrow."},{"de":"Hast du die Bestellung für das Büro schon aufgegeben?","en":"Have you already placed the order for the office?"}],"exPlain":[{"de":"Ich habe gestern im Internet bestellt.","en":"I ordered online yesterday."},{"de":"Wenn Sie bis 14 Uhr bestellen, liefern wir schon morgen.","en":"If you order by 2 p.m., we will deliver tomorrow."}]},
 {"np":"die Kündigung","verb":"einreichen","plain":"kündigen","en":"to hand in one's notice, to resign","lv":"B1","vdecoys":["halten","stellen","legen"],"pdecoys":["einstellen","befördern","sich bewerben"],"vAlt":["abgeben"],"note":"Meist vom Arbeitnehmer gesagt. Kündigen kann auch der Arbeitgeber; „einreichen“ passt dann nicht.","ex":[{"de":"Nach zehn Jahren in der Firma hat sie die Kündigung eingereicht.","en":"After ten years at the company she handed in her notice."},{"de":"Wenn du den Job wechseln willst, musst du bis Ende des Monats die Kündigung einreichen.","en":"If you want to change jobs, you have to hand in your notice by the end of the month."},{"de":"Er reichte die Kündigung schriftlich ein.","en":"He submitted his notice in writing."}],"exPlain":[{"de":"Nach zehn Jahren in der Firma hat sie gekündigt.","en":"After ten years at the company she quit."},{"de":"Wenn du den Job wechseln willst, musst du bis Ende des Monats kündigen.","en":"If you want to change jobs, you have to give notice by the end of the month."}]},
 {"np":"eine Anfrage","verb":"stellen","plain":"anfragen","en":"to make an enquiry","lv":"B1","vdecoys":["geben","bringen","legen"],"pdecoys":["antworten","anbieten","bestellen"],"vAlt":["richten"],"note":"Mit an + Akk. oder bei + Dat.: eine Anfrage an die Firma richten/stellen, bei der Firma eine Anfrage stellen. Plain: bei jemandem anfragen (trennbar).","ex":[{"de":"Ich möchte bei der Firma eine Anfrage zu den Preisen stellen.","en":"I'd like to make an enquiry to the company about the prices."},{"de":"Die Kunden haben schon mehrere Anfragen zum neuen Produkt gestellt.","en":"Customers have already made several enquiries about the new product."},{"de":"Wir stellten eine Anfrage an die Stadtverwaltung, bekamen aber keine Antwort.","en":"We sent an enquiry to the city administration but got no reply."}],"exPlain":[{"de":"Ich möchte bei der Firma wegen der Preise anfragen.","en":"I'd like to enquire at the company about the prices."},{"de":"Wir fragten bei der Stadtverwaltung an, bekamen aber keine Antwort.","en":"We enquired at the city administration but got no reply."}]},
 {"np":"eine Ausbildung","verb":"machen","plain":"ausgebildet werden","en":"to do an apprenticeship/vocational training","lv":"B1","vdecoys":["stellen","halten","führen"],"pdecoys":["ausbilden","unterrichten","studieren"],"vAlt":["absolvieren"],"note":"Plain ist Passiv: Er macht eine Ausbildung = Er wird ausgebildet. Absolvieren klingt formeller. Nicht verwechseln: eine Ausbildung haben = bereits abgeschlossen.","ex":[{"de":"Nach der Schule macht er eine Ausbildung als Elektriker.","en":"After school he is training as an electrician."},{"de":"Meine Schwester hat eine Ausbildung zur Krankenschwester gemacht.","en":"My sister did training as a nurse."},{"de":"Ich möchte lieber eine Ausbildung machen als studieren.","en":"I would rather do vocational training than go to university."}],"exPlain":[{"de":"Nach der Schule wird er als Elektriker ausgebildet.","en":"After school he is trained as an electrician."},{"de":"Meine Schwester wurde zur Krankenschwester ausgebildet.","en":"My sister was trained as a nurse."}]},
 {"np":"einen Unterschied","verb":"machen","plain":"unterscheiden","en":"to make a distinction, to treat differently","lv":"B1","vdecoys":["haben","stellen","halten"],"pdecoys":["vergleichen","verwechseln","bemerken"],"note":"Meist verneint und mit zwischen: keinen Unterschied zwischen A und B machen. Nicht verwechseln mit Das macht keinen Unterschied (= Das ist egal).","ex":[{"de":"Die Lehrerin macht keinen Unterschied zwischen den Schülern.","en":"The teacher doesn't treat the pupils differently."},{"de":"Man sollte keinen Unterschied zwischen Jungen und Mädchen machen.","en":"One shouldn't make a distinction between boys and girls."},{"de":"Im Alltag macht er keinen Unterschied zwischen Arbeit und Freizeit.","en":"In everyday life he makes no distinction between work and leisure."}],"exPlain":[{"de":"Die Lehrerin unterscheidet nicht zwischen den Schülern.","en":"The teacher doesn't distinguish between the pupils."},{"de":"Man sollte nicht zwischen Jungen und Mädchen unterscheiden.","en":"One shouldn't distinguish between boys and girls."}]},
 {"np":"eine Diskussion","verb":"führen","plain":"diskutieren","en":"to hold a discussion","lv":"B1","vdecoys":["legen","tragen","treiben"],"pdecoys":["verhandeln","beschließen","widersprechen"],"note":"Mit über + Akk.: eine Diskussion über ein Thema führen = über ein Thema diskutieren.","ex":[{"de":"Im Seminar haben wir eine lebhafte Diskussion über das Thema geführt.","en":"In the seminar we had a lively discussion about the topic."},{"de":"Die Kollegen führten eine lange Diskussion über den neuen Plan.","en":"The colleagues had a long discussion about the new plan."},{"de":"Wir sollten diese Diskussion nicht hier im Flur führen.","en":"We shouldn't have this discussion here in the corridor."}],"exPlain":[{"de":"Im Seminar haben wir lebhaft über das Thema diskutiert.","en":"In the seminar we discussed the topic in a lively way."},{"de":"Die Kollegen diskutierten lange über den neuen Plan.","en":"The colleagues discussed the new plan for a long time."}]},
 {"np":"ein Interview","verb":"führen","plain":"interviewen","en":"to conduct an interview","lv":"B1","vdecoys":["halten","stellen","treiben"],"pdecoys":["fotografieren","übersetzen","vorlesen"],"vAlt":["machen"],"note":"Der Fragende führt das Interview (mit jemandem); der Befragte gibt ein Interview. Machen ist umgangssprachlicher.","ex":[{"de":"Die Journalistin führt morgen ein Interview mit dem Bürgermeister.","en":"Tomorrow the journalist is conducting an interview with the mayor."},{"de":"Für die Schülerzeitung haben wir ein Interview mit der Direktorin geführt.","en":"For the school newspaper we conducted an interview with the headteacher."},{"de":"Sie führte das Interview ruhig und professionell.","en":"She conducted the interview calmly and professionally."}],"exPlain":[{"de":"Die Journalistin interviewt morgen den Bürgermeister.","en":"Tomorrow the journalist is interviewing the mayor."},{"de":"Für die Schülerzeitung haben wir die Direktorin interviewt.","en":"For the school newspaper we interviewed the headteacher."}]},
 {"np":"ein Interview","verb":"geben","plain":"sich interviewen lassen","en":"to give an interview","lv":"B1","vdecoys":["halten","stellen","treiben"],"pdecoys":["interviewen","befragen","fragen"],"note":"Der Befragte gibt ein Interview (einer Zeitung, einem Sender); der Fragende führt es. Plain: sich interviewen lassen.","ex":[{"de":"Der Politiker hat der Zeitung ein langes Interview gegeben.","en":"The politician gave the newspaper a long interview."},{"de":"Nach dem Spiel gibt sie kein Interview.","en":"After the match she doesn't give an interview."},{"de":"Der Autor gab dem Fernsehsender ein Interview über sein neues Buch.","en":"The author gave the television channel an interview about his new book."}],"exPlain":[{"de":"Der Politiker hat sich von der Zeitung lange interviewen lassen.","en":"The politician let the newspaper interview him at length."},{"de":"Nach dem Spiel lässt sie sich nicht interviewen.","en":"After the match she doesn't let herself be interviewed."}]},
 {"np":"eine Präsentation","verb":"halten","plain":"präsentieren","en":"to give a presentation","lv":"B1","vdecoys":["legen","führen","tragen"],"pdecoys":["lesen","drucken","kopieren"],"vAlt":["machen"],"pAlt":["vorstellen"],"note":"Machen ist umgangssprachlicher. Wie bei Vortrag/Rede ist halten üblich; „eine Präsentation geben“ hört man zwar (Anglizismus), es gilt aber nicht als gutes Deutsch.","ex":[{"de":"Morgen muss ich vor dem ganzen Team eine Präsentation halten.","en":"Tomorrow I have to give a presentation in front of the whole team."},{"de":"Sie hat ihre Präsentation auf Englisch gehalten.","en":"She gave her presentation in English."},{"de":"Wer hält die Präsentation für den Kunden?","en":"Who is giving the presentation for the client?"}],"exPlain":[{"de":"Morgen muss ich vor dem ganzen Team meine Ergebnisse präsentieren.","en":"Tomorrow I have to present my results in front of the whole team."},{"de":"Sie hat ihr Projekt auf Englisch präsentiert.","en":"She presented her project in English."}]},
 {"np":"Gewinn","verb":"machen","plain":"Geld verdienen","en":"to make a profit","lv":"B1","vdecoys":["nehmen","geben","führen"],"pdecoys":["ausgeben","sparen","bezahlen"],"vAlt":["erzielen"],"note":"Von Firmen und Geschäften gesagt; Gewinn = Einnahmen minus Kosten (Geld verdienen ist weiter gefasst). Erzielen klingt formeller. Gegenteil: Verlust machen.","ex":[{"de":"Im letzten Jahr hat die Firma zum ersten Mal Gewinn gemacht.","en":"Last year the company made a profit for the first time."},{"de":"Mit dem kleinen Laden macht sie kaum Gewinn.","en":"She hardly makes any profit with the little shop."},{"de":"Kleine Betriebe machen oft nur wenig Gewinn.","en":"Small businesses often make only a small profit."}],"exPlain":[{"de":"Im letzten Jahr hat die Firma zum ersten Mal Geld verdient.","en":"Last year the company made money for the first time."},{"de":"Mit dem kleinen Laden verdient sie kaum etwas.","en":"She hardly earns anything with the little shop."}]},
 {"np":"außer Betrieb","verb":"sein","plain":"nicht funktionieren","en":"to be out of order","lv":"B1","vdecoys":["liegen","laufen","fallen"],"pdecoys":["funktionieren","reparieren","bedienen"],"note":"Auf Schildern: „Außer Betrieb“. Gegenteil: in Betrieb sein. Mit nehmen/setzen: außer Betrieb nehmen/setzen = stilllegen, abschalten.","ex":[{"de":"Der Aufzug ist seit Montag außer Betrieb.","en":"The lift has been out of order since Monday."},{"de":"Leider ist die Kaffeemaschine im Büro wieder außer Betrieb.","en":"Unfortunately the coffee machine in the office is out of order again."},{"de":"Wegen der Bauarbeiten war die U-Bahn-Linie das ganze Wochenende außer Betrieb.","en":"Because of the construction work the underground line was out of service all weekend."}],"exPlain":[{"de":"Der Aufzug funktioniert seit Montag nicht.","en":"The lift hasn't worked since Monday."},{"de":"Leider funktioniert die Kaffeemaschine im Büro wieder nicht.","en":"Unfortunately the coffee machine in the office isn't working again."}]},
 {"np":"auf der Suche","verb":"sein","plain":"suchen","en":"to be looking for","lv":"B1","vdecoys":["liegen","stehen","laufen"],"pdecoys":["finden","fragen","verlieren"],"note":"Meist mit nach + Dat.: auf der Suche nach etwas sein (auch ohne Ergänzung möglich: Ich bin auf der Suche). Das Plain-Verb hat ein direktes Objekt (Akk.).","ex":[{"de":"Ich bin gerade auf der Suche nach einer neuen Wohnung.","en":"I'm currently looking for a new flat."},{"de":"Die Firma ist auf der Suche nach erfahrenen Mitarbeitern.","en":"The company is looking for experienced employees."},{"de":"Er war lange auf der Suche nach einem passenden Job.","en":"He was looking for a suitable job for a long time."}],"exPlain":[{"de":"Ich suche gerade eine neue Wohnung.","en":"I'm currently looking for a new flat."},{"de":"Die Firma sucht erfahrene Mitarbeiter.","en":"The company is looking for experienced employees."}]},
 {"np":"ein Versprechen","verb":"geben","plain":"versprechen","en":"to give a promise, to promise","lv":"B1","vdecoys":["nehmen","legen","stellen"],"pdecoys":["einhalten","verbieten","gestehen"],"note":"Üblich ist geben. Nicht verwechseln mit ein Versprechen halten/brechen (das bezeichnet etwas anderes).","ex":[{"de":"Ich gebe dir mein Versprechen, dass ich pünktlich komme.","en":"I give you my promise that I'll be on time."},{"de":"Der Chef gab uns das Versprechen, dass niemand entlassen wird.","en":"The boss promised us that nobody would be dismissed."},{"de":"Sie hat ihrer Mutter ein Versprechen gegeben.","en":"She made a promise to her mother."}],"exPlain":[{"de":"Ich verspreche dir, dass ich pünktlich komme.","en":"I promise you that I'll be on time."},{"de":"Der Chef versprach uns, dass niemand entlassen wird.","en":"The boss promised us that nobody would be dismissed."}]},
 {"np":"in Frage","verb":"kommen","plain":"möglich sein","en":"to be possible, to be an option","lv":"B1","vdecoys":["gehen","liegen","fallen"],"pdecoys":["fragen","antworten","verbieten"],"note":"Auch infrage kommen. Verneint ist die Wendung stärker: Das kommt nicht in Frage = Das ist ausgeschlossen. Positiv: als Möglichkeit/Kandidat geeignet sein. Ähnlich: in Betracht kommen.","ex":[{"de":"Für die Stelle kommen nur Bewerber mit Erfahrung in Frage.","en":"Only applicants with experience are considered for the position."},{"de":"Ein Umzug nach Berlin kommt für mich nicht in Frage.","en":"Moving to Berlin is out of the question for me."},{"de":"Kommt der Samstag als Termin für das Treffen in Frage?","en":"Is Saturday a possible date for the meeting?"}],"exPlain":[{"de":"Ist der Samstag als Termin für das Treffen möglich?","en":"Is Saturday possible as a date for the meeting?"},{"de":"Wäre ein früherer Termin für Sie möglich?","en":"Would an earlier appointment be possible for you?"}]},
 {"np":"Schulden","verb":"haben","plain":"schulden","en":"to owe, to be in debt","lv":"B1","vdecoys":["sein","geben","führen"],"pdecoys":["leihen","kosten","zahlen"],"note":"Schulden haben bei jemandem = jemandem etwas schulden. Nicht verwechseln mit Schulden machen (neue Schulden aufnehmen).","ex":[{"de":"Ich habe noch zweihundert Euro Schulden bei dir.","en":"I still owe you two hundred euros."},{"de":"Die Firma hat hohe Schulden bei mehreren Lieferanten.","en":"The company owes a lot of money to several suppliers."},{"de":"Er hatte lange Schulden bei der Bank, aber jetzt hat er alles zurückgezahlt.","en":"He was in debt to the bank for a long time, but now he has paid everything back."}],"exPlain":[{"de":"Ich schulde dir noch zweihundert Euro.","en":"I still owe you two hundred euros."},{"de":"Die Firma schuldet mehreren Lieferanten viel Geld.","en":"The company owes several suppliers a lot of money."}]},
 {"np":"einen Abschluss","verb":"machen","plain":"abschließen","en":"to graduate, to complete a degree","lv":"B1","vdecoys":["nehmen","geben","halten"],"pdecoys":["abbrechen","beginnen","wiederholen"],"note":"Gemeint ist ein Schul-, Ausbildungs- oder Studienabschluss. Plain: sein Studium / seine Ausbildung abschließen (trennbar).","ex":[{"de":"Nach fünf Jahren hat sie ihren Abschluss in Biologie gemacht.","en":"After five years she graduated in biology."},{"de":"Mein Bruder macht nächstes Jahr seinen Abschluss an der Hochschule.","en":"My brother will complete his degree at the university next year."},{"de":"Er hat in der Schweiz seinen Abschluss als Ingenieur gemacht.","en":"He earned his engineering qualification in Switzerland."}],"exPlain":[{"de":"Nach fünf Jahren hat sie ihr Biologiestudium abgeschlossen.","en":"After five years she completed her biology degree."},{"de":"Mein Bruder schließt nächstes Jahr sein Studium an der Hochschule ab.","en":"My brother will complete his studies at the university next year."}]},
 {"np":"eine Weiterbildung","verb":"machen","plain":"sich weiterbilden","en":"to do further training","lv":"B1","vdecoys":["nehmen","stellen","führen"],"pdecoys":["unterrichten","kündigen","sich bewerben"],"vAlt":["absolvieren"],"note":"Berufliche Weiterbildung. Plain ist reflexiv: sich (zum/zur …) weiterbilden. Absolvieren klingt formeller.","ex":[{"de":"Nächstes Jahr möchte ich eine Weiterbildung zum Projektmanager machen.","en":"Next year I'd like to do further training to become a project manager."},{"de":"Sie hat neben dem Beruf eine Weiterbildung gemacht.","en":"She did further training alongside her job."},{"de":"Du solltest eine Weiterbildung in Buchhaltung machen.","en":"You should do further training in accounting."}],"exPlain":[{"de":"Nächstes Jahr möchte ich mich zum Projektmanager weiterbilden.","en":"Next year I'd like to train further to become a project manager."},{"de":"Sie hat sich neben dem Beruf weitergebildet.","en":"She trained further alongside her job."}]},
 {"np":"einen Blog","verb":"führen","plain":"bloggen","en":"to run a blog, to blog","lv":"B1","vdecoys":["halten","tragen","bringen"],"pdecoys":["chatten","surfen","streamen"],"vAlt":["betreiben","schreiben"],"note":"Betreiben klingt etwas formeller; schreiben meint nur den Schreibakt, nicht das Führen des ganzen Blogs.","ex":[{"de":"Seit zwei Jahren führt sie einen Blog über Reisen.","en":"For two years she has been running a travel blog."},{"de":"Er führt einen Blog, in dem er über seine Arbeit schreibt.","en":"He runs a blog in which he writes about his work."},{"de":"Viele Schüler führen einen Blog über ihre Hobbys.","en":"Many pupils keep a blog about their hobbies."}],"exPlain":[{"de":"Seit zwei Jahren bloggt sie über Reisen.","en":"For two years she has been blogging about travel."},{"de":"Viele Schüler bloggen über ihre Hobbys.","en":"Many pupils blog about their hobbies."}]},
 {"np":"auf die Idee","verb":"kommen","plain":"einfallen","en":"to come up with the idea, to think of","lv":"B1","vdecoys":["gehen","laufen","stehen"],"pdecoys":["vergessen","ablehnen","verstehen"],"note":"Oft mit Infinitivgruppe: auf die Idee kommen, etwas zu tun. Plain: etwas fällt jemandem ein (Dativ der Person!): Mir fiel ein, … ≈ Ich kam auf die Idee, … (einfallen ist spontaner, kommt eher „in den Kopf“).","ex":[{"de":"Wie bist du nur auf die Idee gekommen, ohne Termin beim Chef vorbeizugehen?","en":"How did you come up with the idea of dropping in on the boss without an appointment?"},{"de":"Plötzlich kam sie auf die Idee, sich selbstständig zu machen.","en":"Suddenly she hit on the idea of going self-employed."},{"de":"Auf so eine Idee muss man erst einmal kommen!","en":"You have to think of an idea like that first!"}],"exPlain":[{"de":"Wie konnte es dir nur einfallen, ohne Termin beim Chef vorbeizugehen?","en":"How could it even occur to you to drop in on the boss without an appointment?"},{"de":"Plötzlich fiel ihr ein, sich selbstständig zu machen.","en":"Suddenly it occurred to her to go self-employed."}]},
 {"np":"Homeoffice","verb":"machen","plain":"von zu Hause arbeiten","en":"to work from home","lv":"B1","vdecoys":["führen","tragen","halten"],"pdecoys":["pendeln","kündigen","umziehen"],"vAlt":["haben"],"note":"Umgangssprachlich. Neutral: im Homeoffice arbeiten. Ich habe heute Homeoffice ist ebenfalls üblich.","ex":[{"de":"Dienstags und donnerstags mache ich Homeoffice.","en":"On Tuesdays and Thursdays I work from home."},{"de":"Viele Kollegen machen zwei Tage pro Woche Homeoffice.","en":"Many colleagues work from home two days a week."},{"de":"Wegen des Schnees haben wir gestern alle Homeoffice gemacht.","en":"Because of the snow we all worked from home yesterday."}],"exPlain":[{"de":"Dienstags und donnerstags arbeite ich von zu Hause.","en":"On Tuesdays and Thursdays I work from home."},{"de":"Viele Kollegen arbeiten zwei Tage pro Woche von zu Hause.","en":"Many colleagues work from home two days a week."}]},
 {"np":"das Recht","verb":"haben","plain":"dürfen","en":"to have the right (to)","lv":"B1","vdecoys":["machen","tragen","halten"],"pdecoys":["müssen","sollen","mögen"],"note":"Mit Infinitiv + zu: das Recht haben, etwas zu tun. Betont einen rechtlichen oder moralischen Anspruch; klingt formeller als dürfen. Nicht verwechseln mit Recht haben (= richtig liegen).","ex":[{"de":"Als Kunde hast du das Recht, die Ware zurückzugeben.","en":"As a customer you have the right to return the goods."},{"de":"Jeder Mitarbeiter hatte das Recht, an der Versammlung teilzunehmen.","en":"Every employee had the right to take part in the meeting."},{"de":"Wir haben das Recht, den Vertrag zu kündigen.","en":"We have the right to terminate the contract."}],"exPlain":[{"de":"Als Kunde darfst du die Ware zurückgeben.","en":"As a customer you may return the goods."},{"de":"Jeder Mitarbeiter durfte an der Versammlung teilnehmen.","en":"Every employee was allowed to take part in the meeting."}]},
 {"np":"die Pflicht","verb":"haben","plain":"müssen","en":"to have a duty (to), to be obliged (to)","lv":"B1","vdecoys":["machen","geben","nehmen"],"pdecoys":["dürfen","können","wollen"],"note":"Mit Infinitiv + zu: die Pflicht haben, etwas zu tun. Klingt formeller als müssen. Gegenteil im Sinn: das Recht haben (dürfen).","ex":[{"de":"Der Vermieter hat die Pflicht, die Heizung zu reparieren.","en":"The landlord has a duty to repair the heating."},{"de":"Wir haben die Pflicht, alle Kunden rechtzeitig zu informieren.","en":"We have a duty to inform all customers in good time."},{"de":"Als Beamter hatte er die Pflicht, neutral zu bleiben.","en":"As a civil servant he had a duty to remain neutral."}],"exPlain":[{"de":"Der Vermieter muss die Heizung reparieren.","en":"The landlord must repair the heating."},{"de":"Wir müssen alle Kunden rechtzeitig informieren.","en":"We must inform all customers in good time."}]},
 {"np":"die Möglichkeit","verb":"haben","plain":"können","en":"to have the opportunity (to), to be able (to)","lv":"B1","vdecoys":["machen","bringen","halten"],"pdecoys":["müssen","mögen","sollen"],"note":"Mit Infinitiv + zu: die Möglichkeit haben, etwas zu tun. Betont die Gelegenheit, nicht die Erlaubnis.","ex":[{"de":"Bei uns haben Sie die Möglichkeit, im Homeoffice zu arbeiten.","en":"With us you have the option of working from home."},{"de":"Hast du morgen die Möglichkeit, früher zu kommen?","en":"Will you be able to come earlier tomorrow?"},{"de":"Die Studenten hatten die Möglichkeit, ein Semester im Ausland zu verbringen.","en":"The students had the opportunity to spend a semester abroad."}],"exPlain":[{"de":"Bei uns können Sie im Homeoffice arbeiten.","en":"With us you can work from home."},{"de":"Die Studenten konnten ein Semester im Ausland verbringen.","en":"The students were able to spend a semester abroad."}]},
 {"np":"eine Zusammenfassung","verb":"machen","plain":"zusammenfassen","en":"to make a summary","lv":"B1","vdecoys":["nehmen","halten","führen"],"pdecoys":["erklären","übersetzen","wiederholen"],"vAlt":["schreiben","geben"],"note":"Meist mit Genitiv oder von + Dat.: eine Zusammenfassung des Textes / vom Text machen = den Text zusammenfassen. Plain ist trennbar.","ex":[{"de":"Der Lehrer bat uns, eine Zusammenfassung des Textes zu machen.","en":"The teacher asked us to make a summary of the text."},{"de":"Kannst du kurz eine Zusammenfassung der Besprechung machen?","en":"Can you briefly make a summary of the meeting?"},{"de":"Ich habe von dem Buch eine Zusammenfassung gemacht.","en":"I made a summary of the book."}],"exPlain":[{"de":"Der Lehrer bat uns, den Text zusammenzufassen.","en":"The teacher asked us to summarise the text."},{"de":"Kannst du die Besprechung kurz zusammenfassen?","en":"Can you briefly summarise the meeting?"}]},
 {"np":"eine Übersetzung","verb":"machen","plain":"übersetzen","en":"to do a translation","lv":"B1","vdecoys":["nehmen","halten","führen"],"pdecoys":["erklären","vorlesen","korrigieren"],"vAlt":["anfertigen"],"note":"Anfertigen klingt formeller. Oft mit Genitiv oder von + Dat.: eine Übersetzung des Textes / vom Text ins Deutsche machen.","ex":[{"de":"Für die Konferenz muss ich eine Übersetzung des Textes machen.","en":"For the conference I have to do a translation of the text."},{"de":"Hast du die Übersetzung schon gemacht?","en":"Have you already done the translation?"},{"de":"Er macht Übersetzungen für eine Agentur.","en":"He does translations for an agency."}],"exPlain":[{"de":"Für die Konferenz muss ich den Text übersetzen.","en":"For the conference I have to translate the text."},{"de":"Er übersetzt für eine Agentur.","en":"He translates for an agency."}]},
 {"np":"vor einer Entscheidung","verb":"stehen","plain":"sich entscheiden müssen","en":"to face a decision","lv":"B1","vdecoys":["liegen","sitzen","gehen"],"pdecoys":["sich entschuldigen","sich erinnern","sich verabschieden"],"note":"Auch: vor einer Wahl / einem Problem stehen. Mit Dativ nach vor. Nicht: eine Entscheidung treffen (die Entscheidung wirklich fällen).","ex":[{"de":"Nach dem Abitur steht sie vor einer wichtigen Entscheidung.","en":"After her school-leaving exams she faces an important decision."},{"de":"Wir stehen vor der Entscheidung, ob wir umziehen oder bleiben.","en":"We face the decision whether to move or to stay."},{"de":"Als junge Unternehmer standen sie plötzlich vor einer schweren Entscheidung.","en":"As young entrepreneurs they suddenly faced a difficult decision."}],"exPlain":[{"de":"Nach dem Abitur muss sie sich bald entscheiden.","en":"After her school-leaving exams she will soon have to decide."},{"de":"Wir müssen uns entscheiden, ob wir umziehen oder bleiben.","en":"We have to decide whether to move or to stay."}]},
 {"np":"ein Schnäppchen","verb":"machen","plain":"günstig kaufen","en":"to snap up a bargain","lv":"B1","vdecoys":["halten","geben","tragen"],"pdecoys":["teuer verkaufen","verlieren","umtauschen"],"note":"Umgangssprachlich. Man kann auch sagen: ein Schnäppchen finden.","ex":[{"de":"Auf dem Flohmarkt habe ich ein echtes Schnäppchen gemacht.","en":"I snapped up a real bargain at the flea market."},{"de":"Beim Schlussverkauf kann man oft Schnäppchen machen.","en":"At the end-of-season sale you can often find bargains."},{"de":"Mit diesem Angebot hast du wirklich ein Schnäppchen gemacht!","en":"You really got yourself a bargain with that offer!"}],"exPlain":[{"de":"Auf dem Flohmarkt habe ich etwas sehr günstig gekauft.","en":"I bought something very cheaply at the flea market."},{"de":"Beim Schlussverkauf kann man oft günstig kaufen.","en":"At the end-of-season sale you can often buy things cheaply."}],"vAlt":["finden"]},
 {"np":"im Kino","verb":"laufen","plain":"gezeigt werden","en":"to be showing (at the cinema)","lv":"B1","vdecoys":["gehen","stehen","liegen"],"pdecoys":["drehen","besuchen","bezahlen"],"note":"Ebenso: im Fernsehen/Radio laufen. Ein neuer Film kommt ins Kino (= startet). Was läuft im Kino? ist die übliche Frage.","ex":[{"de":"Welcher Film läuft heute Abend im Kino?","en":"Which film is showing at the cinema this evening?"},{"de":"Der neue Film läuft seit Donnerstag im Kino.","en":"The new film has been showing at the cinema since Thursday."},{"de":"Dieser Film lief damals monatelang im Kino.","en":"Back then this film ran at the cinema for months."}],"exPlain":[{"de":"Welcher Film wird heute Abend im Kino gezeigt?","en":"Which film is being shown at the cinema this evening?"},{"de":"Der neue Film wird seit Donnerstag im Kino gezeigt.","en":"The new film has been shown at the cinema since Thursday."}]},
 {"np":"in der Zeitung","verb":"stehen","plain":"berichtet werden","en":"to be reported in the newspaper","lv":"B1","vdecoys":["sitzen","hängen","laufen"],"pdecoys":["verkauft werden","bezahlt werden","gelöscht werden"],"note":"Plain ist Passiv und braucht oft über + Akk.: Über den Unfall wird berichtet. Auch: im Internet / in den Nachrichten stehen.","ex":[{"de":"Der Unfall steht heute in der Zeitung.","en":"The accident is in the newspaper today."},{"de":"Über die Wahl stand gestern nichts in der Zeitung.","en":"Yesterday there was nothing in the newspaper about the election."},{"de":"Hast du gelesen, was über unsere Firma in der Zeitung steht?","en":"Have you read what it says about our company in the newspaper?"}],"exPlain":[{"de":"Über den Unfall wird heute in der Zeitung berichtet.","en":"The accident is reported on in the newspaper today."},{"de":"Über die Wahl wurde gestern nichts in der Zeitung berichtet.","en":"Nothing was reported about the election in the newspaper yesterday."}]},
 {"np":"Rat","verb":"suchen","plain":"sich beraten lassen","en":"to seek advice","lv":"B1","vdecoys":["machen","stellen","bringen"],"pdecoys":["raten","beraten","empfehlen"],"vAlt":["holen","einholen"],"note":"Meist mit bei + Dat.: bei jemandem Rat suchen. Nicht verwechseln mit einen Rat geben (= raten). Rat holen sagt man meist reflexiv: sich (Dat.) Rat holen; formeller: Rat einholen.","ex":[{"de":"Wenn du Probleme mit dem Vertrag hast, solltest du bei einem Anwalt Rat suchen.","en":"If you have problems with the contract, you should seek advice from a lawyer."},{"de":"Viele junge Leute suchen bei ihren Eltern Rat.","en":"Many young people seek advice from their parents."},{"de":"In dieser schwierigen Lage suchte sie bei einer Freundin Rat.","en":"In this difficult situation she sought advice from a friend."}],"exPlain":[{"de":"Wenn du Probleme mit dem Vertrag hast, solltest du dich von einem Anwalt beraten lassen.","en":"If you have problems with the contract, you should get advice from a lawyer."},{"de":"Viele junge Leute lassen sich von ihren Eltern beraten.","en":"Many young people take advice from their parents."}]},
 {"np":"die Aufgabe","verb":"haben","plain":"sollen","en":"to have the task (of)","lv":"B1","vdecoys":["halten","tragen","führen"],"pdecoys":["dürfen","können","wollen"],"note":"Mit Infinitiv + zu: die Aufgabe haben, etwas zu tun. Betont die Zuständigkeit; klingt formeller als sollen.","ex":[{"de":"Der Ausschuss hat die Aufgabe, die Anträge zu prüfen.","en":"The committee has the task of examining the applications."},{"de":"Ich hatte die Aufgabe, die Gäste am Eingang zu begrüßen.","en":"My task was to welcome the guests at the entrance."},{"de":"Wer hat heute die Aufgabe, das Protokoll zu schreiben?","en":"Whose task is it today to write the minutes?"}],"exPlain":[{"de":"Der Ausschuss soll die Anträge prüfen.","en":"The committee is to examine the applications."},{"de":"Ich sollte die Gäste am Eingang begrüßen.","en":"I was supposed to welcome the guests at the entrance."}]},
 {"np":"eine Besprechung","verb":"abhalten","plain":"sich besprechen","en":"to hold a meeting","lv":"B1","vdecoys":["geben","stellen","treiben"],"pdecoys":["sich verabreden","absagen","verschieben"],"note":"Formeller (Büro). Plain ist reflexiv: sich besprechen (mit jemandem). Abhalten ist trennbar: Wir halten eine Besprechung ab.","ex":[{"de":"Das Team hält jeden Montag eine Besprechung ab.","en":"The team holds a meeting every Monday."},{"de":"Wir müssen noch heute eine Besprechung abhalten.","en":"We have to hold a meeting today."},{"de":"Die Abteilung hielt gestern eine kurze Besprechung ab.","en":"The department held a short meeting yesterday."}],"exPlain":[{"de":"Das Team bespricht sich jeden Montag.","en":"The team has a meeting every Monday."},{"de":"Wir müssen uns noch heute besprechen.","en":"We have to meet and discuss things today."}],"vAlt":["halten"]},
 {"np":"in Eile","verb":"sein","plain":"es eilig haben","en":"to be in a hurry","lv":"B1","vdecoys":["liegen","stehen","gehen"],"pdecoys":["sich ausruhen","sich Zeit lassen","sich verspäten"],"note":"Auch: in Eile geraten. Plain: es eilig haben (mit etwas / zu …).","ex":[{"de":"Ich bin leider in Eile, wir können später sprechen.","en":"Unfortunately I'm in a hurry, we can talk later."},{"de":"Er war in Eile und hatte keine Zeit zum Frühstücken.","en":"He was in a hurry and had no time for breakfast."},{"de":"Wenn man in Eile ist, passieren leicht Fehler.","en":"Mistakes happen easily when you are in a hurry."}],"exPlain":[{"de":"Ich habe es leider eilig, wir können später sprechen.","en":"Unfortunately I'm in a hurry, we can talk later."},{"de":"Wenn man es eilig hat, passieren leicht Fehler.","en":"Mistakes happen easily when you are in a hurry."}]},
 {"np":"ein Experiment","verb":"machen","plain":"experimentieren","en":"to do an experiment","lv":"B1","vdecoys":["nehmen","halten","geben"],"pdecoys":["beobachten","messen","erfinden"],"vAlt":["durchführen"],"note":"Durchführen klingt formeller. Plain: mit etwas experimentieren.","ex":[{"de":"Im Chemieunterricht haben wir ein Experiment mit Salz und Wasser gemacht.","en":"In chemistry class we did an experiment with salt and water."},{"de":"Die Forscher machen jeden Tag neue Experimente.","en":"The researchers do new experiments every day."},{"de":"Mit diesem Set kann man zu Hause einfache Experimente machen.","en":"With this kit you can do simple experiments at home."}],"exPlain":[{"de":"Im Chemieunterricht haben wir mit Salz und Wasser experimentiert.","en":"In chemistry class we experimented with salt and water."},{"de":"Die Forscher experimentieren jeden Tag.","en":"The researchers experiment every day."}]},
 {"np":"Schutz","verb":"bieten","plain":"schützen","en":"to offer protection","lv":"B1","vdecoys":["machen","legen","tun"],"pdecoys":["verbieten","verstecken","öffnen"],"vAlt":["gewähren"],"note":"Schutz bieten vor + Dat.: Das Dach bietet Schutz vor dem Regen = Das Dach schützt vor dem Regen. Gewähren klingt formeller.","ex":[{"de":"Der Regenschirm bietet nur wenig Schutz vor dem Sturm.","en":"The umbrella offers little protection from the storm."},{"de":"Die Hütte bot uns Schutz vor dem Gewitter.","en":"The hut sheltered us from the thunderstorm."},{"de":"Dieses Gesetz bietet Verbrauchern Schutz vor unfairen Verträgen.","en":"This law protects consumers from unfair contracts."}],"exPlain":[{"de":"Der Regenschirm schützt nur wenig vor dem Sturm.","en":"The umbrella protects little against the storm."},{"de":"Die Hütte schützte uns vor dem Gewitter.","en":"The hut protected us from the thunderstorm."}]},
 {"np":"Vertrauen","verb":"haben","plain":"vertrauen","en":"to trust; to have confidence in","lv":"B1","vdecoys":["machen","stellen","tragen"],"pdecoys":["zweifeln","hoffen","erwarten"],"pAlt":["trauen"],"note":"Vertrauen zu + Dat. oder in + Akk. haben = jemandem vertrauen (Dativ!). Vertrauen schenken ist die gehobenere Variante; haben beschreibt den Zustand.","ex":[{"de":"Ich habe vollstes Vertrauen zu meinem Arzt.","en":"I have complete trust in my doctor."},{"de":"Hast du kein Vertrauen in deine eigenen Fähigkeiten?","en":"Don't you have any faith in your own abilities?"},{"de":"Die Kinder hatten sofort Vertrauen zur neuen Nachbarin.","en":"The children trusted the new neighbour straight away."}],"exPlain":[{"de":"Ich vertraue meinem Arzt vollkommen.","en":"I trust my doctor completely."},{"de":"Vertraust du deinen eigenen Fähigkeiten nicht?","en":"Don't you trust your own abilities?"}]},
 {"np":"Mitleid","verb":"haben","plain":"bemitleiden","en":"to feel pity; to pity","lv":"B2","vdecoys":["machen","tun","geben"],"pdecoys":["trösten","verzeihen","bewundern"],"note":"Mit jemandem Mitleid haben ≈ jemanden bemitleiden (Akkusativ!). Nicht ganz gleich: bemitleiden klingt oft herablassend, Mitleid haben/empfinden ist neutral.","ex":[{"de":"Ich habe wirklich Mitleid mit den Menschen, die ihr Zuhause verloren haben.","en":"I really feel sorry for the people who have lost their homes."},{"de":"Hast du denn gar kein Mitleid mit dem armen Kerl?","en":"Don't you feel any pity for the poor guy?"},{"de":"Wir hatten Mitleid mit dem frierenden Hund und gaben ihm etwas zu fressen.","en":"We felt sorry for the freezing dog and gave it something to eat."}],"exPlain":[{"de":"Ich bemitleide die Menschen, die ihr Zuhause verloren haben.","en":"I pity the people who have lost their homes."},{"de":"Wir bemitleideten den frierenden Hund und gaben ihm etwas zu fressen.","en":"We pitied the freezing dog and gave it something to eat."}]},
 {"np":"jemandem eine Freude","verb":"machen","plain":"erfreuen","en":"to make someone happy; to please someone","lv":"B2","vdecoys":["stellen","legen","halten"],"pdecoys":["danken","trösten","grüßen"],"vAlt":["bereiten"],"note":"Dativ der Person: jemandem eine Freude machen = jemanden (Akk.) erfreuen. Alltagssprachlich ist die Wendung mit machen häufiger als das gehobene erfreuen.","ex":[{"de":"Mit den Blumen hast du ihr wirklich eine Freude gemacht.","en":"You really made her happy with those flowers."},{"de":"Ich wollte meinen Eltern zum Geburtstag eine Freude machen.","en":"I wanted to make my parents happy for their birthday."},{"de":"Der Brief hat dem alten Mann eine große Freude gemacht.","en":"The letter made the old man very happy."}],"exPlain":[{"de":"Mit den Blumen hast du sie wirklich erfreut.","en":"You really pleased her with those flowers."},{"de":"Der Brief hat den alten Mann sehr erfreut.","en":"The letter pleased the old man very much."}]},
 {"np":"jemandem Sorgen","verb":"machen","plain":"beunruhigen","en":"to worry someone; to cause concern","lv":"B1","vdecoys":["geben","tun","stellen"],"pdecoys":["beruhigen","trösten","ärgern"],"vAlt":["bereiten"],"note":"Die Person steht im Dativ: Das macht mir Sorgen = Das beunruhigt mich (Akk.). Nicht verwechseln mit sich Sorgen machen (um jemanden), wo die besorgte Person das Subjekt ist.","ex":[{"de":"Der Husten meiner Tochter macht mir Sorgen.","en":"My daughter's cough worries me."},{"de":"Die steigenden Preise machen vielen Familien große Sorgen.","en":"The rising prices cause many families great concern."},{"de":"Dein langes Schweigen hat uns Sorgen gemacht.","en":"Your long silence worried us."}],"exPlain":[{"de":"Der Husten meiner Tochter beunruhigt mich.","en":"My daughter's cough worries me."},{"de":"Die steigenden Preise beunruhigen viele Familien sehr.","en":"The rising prices greatly worry many families."}]},
 {"np":"jemandem Mut","verb":"machen","plain":"ermutigen","en":"to encourage someone","lv":"B2","vdecoys":["bringen","setzen","stellen"],"pdecoys":["trösten","loben","warnen"],"note":"Dativ der Person: jemandem Mut machen = jemanden (Akk.) ermutigen. Nicht mit Mut haben (= mutig sein) verwechseln.","ex":[{"de":"Meine Freunde haben mir vor der Operation Mut gemacht.","en":"My friends encouraged me before the operation."},{"de":"Die Trainerin macht den Kindern immer Mut.","en":"The coach always encourages the children."},{"de":"Mach ihr doch ein bisschen Mut, sie ist so unsicher.","en":"Why don't you encourage her a little, she's so unsure of herself."}],"exPlain":[{"de":"Meine Freunde haben mich vor der Operation ermutigt.","en":"My friends encouraged me before the operation."},{"de":"Die Trainerin ermutigt die Kinder immer.","en":"The coach always encourages the children."}],"vAlt":["zusprechen"]},
 {"np":"seine Stimme","verb":"abgeben","plain":"wählen","en":"to cast one's vote; to vote","lv":"B1","vdecoys":["aufgeben","ausgeben","einreichen"],"pdecoys":["entscheiden","aussortieren","ernennen"],"note":"Trennbares Verb (gibt … ab). Bei einer Wahl oder Abstimmung. Alltagssprachlich auch: wählen gehen.","ex":[{"de":"Bei der Wahl haben nur sechzig Prozent der Bürger ihre Stimme abgegeben.","en":"Only sixty percent of citizens cast their vote in the election."},{"de":"Ab achtzehn Jahren darf man seine Stimme abgeben.","en":"From the age of eighteen you may cast your vote."},{"de":"Du kannst deine Stimme auch per Brief abgeben.","en":"You can also cast your vote by post."}],"exPlain":[{"de":"Ab achtzehn Jahren darf man wählen.","en":"From the age of eighteen you may vote."},{"de":"Du kannst auch per Brief wählen.","en":"You can also vote by post."}]},
 {"np":"Ruhe","verb":"bewahren","plain":"ruhig bleiben","en":"to keep calm","lv":"B1","vdecoys":["stellen","tragen","tun"],"pdecoys":["sich beruhigen","schweigen","stillstehen"],"vAlt":["behalten"],"note":"Meist als Aufforderung: Bewahren Sie Ruhe! Auch die Ruhe bewahren/behalten. Nicht: sich beruhigen (= sich wieder beruhigen, nachdem man aufgeregt war).","ex":[{"de":"Bei einem Unfall ist es wichtig, Ruhe zu bewahren.","en":"In an accident it's important to keep calm."},{"de":"Bewahren Sie bitte Ruhe, es ist alles unter Kontrolle.","en":"Please stay calm, everything is under control."},{"de":"Trotz des Lärms bewahrte sie die Ruhe.","en":"In spite of the noise she kept calm."}],"exPlain":[{"de":"Bei einem Unfall ist es wichtig, ruhig zu bleiben.","en":"In an accident it's important to stay calm."},{"de":"Bleiben Sie bitte ruhig, es ist alles unter Kontrolle.","en":"Please stay calm, everything is under control."}]},
 {"np":"Wert","verb":"legen","plain":"wichtig finden","en":"to attach importance to; to consider important","lv":"B1","vdecoys":["setzen","stellen","tragen"],"pdecoys":["mögen","bezahlen","kosten"],"note":"Mit auf + Akk.: Wert auf etwas legen, oft mit großen/viel Wert. Das Subjekt hält etwas für wichtig: Ich lege Wert auf Pünktlichkeit ≈ Ich finde Pünktlichkeit wichtig.","ex":[{"de":"Ich lege großen Wert auf frische Zutaten.","en":"I attach great importance to fresh ingredients."},{"de":"Meine Eltern legen viel Wert darauf, dass wir pünktlich sind.","en":"My parents attach great importance to us being on time."},{"de":"Bei Möbeln hat sie immer Wert auf gutes Design gelegt.","en":"With furniture she has always cared about good design."}],"exPlain":[{"de":"Frische Zutaten finde ich sehr wichtig.","en":"I think fresh ingredients are very important."},{"de":"Meine Eltern finden es wichtig, dass wir pünktlich sind.","en":"My parents think it's important that we are on time."}]},
 {"np":"der Meinung","verb":"sein","plain":"meinen","en":"to be of the opinion; to think","lv":"B1","vdecoys":["haben","liegen","stehen"],"pdecoys":["wissen","bezweifeln","fragen"],"pAlt":["finden"],"note":"Fester Genitiv: der Meinung sein, dass … Verwandt: anderer/gleicher Meinung sein. Etwas gehobener als Ich meine/finde.","ex":[{"de":"Ich bin der Meinung, dass wir mehr für die Umwelt tun müssen.","en":"I'm of the opinion that we have to do more for the environment."},{"de":"Die meisten Nachbarn sind der Meinung, dass die Straße zu laut ist.","en":"Most neighbours think the street is too noisy."},{"de":"Wir waren alle der Meinung, dass der Film zu lang war.","en":"We all thought the film was too long."}],"exPlain":[{"de":"Ich meine, dass wir mehr für die Umwelt tun müssen.","en":"I think we have to do more for the environment."},{"de":"Die meisten Nachbarn meinen, dass die Straße zu laut ist.","en":"Most neighbours think the street is too noisy."}]},
 {"np":"eine Rolle","verb":"spielen","plain":"wichtig sein","en":"to play a role; to matter","lv":"B1","vdecoys":["führen","halten","setzen"],"pdecoys":["stören","fehlen","gewinnen"],"note":"Meist mit Adjektiv: eine große/wichtige Rolle spielen (eine kleine Rolle spielen = wenig wichtig sein). Verneint: Das spielt keine Rolle = Das ist egal. Plain: wichtig/von Bedeutung sein.","ex":[{"de":"Beim Kochen spielt frisches Gemüse eine große Rolle.","en":"Fresh vegetables play a major part in cooking."},{"de":"Das Wetter spielte für uns keine Rolle.","en":"The weather didn't matter to us."},{"de":"Welche Rolle spielt die Familie für dich?","en":"What role does family play for you?"}],"exPlain":[{"de":"Beim Kochen ist frisches Gemüse sehr wichtig.","en":"Fresh vegetables are very important in cooking."},{"de":"Wie wichtig ist die Familie für dich?","en":"How important is family to you?"}]},
 {"np":"Ahnung","verb":"haben","plain":"sich auskennen","en":"to know about something; to be knowledgeable","lv":"B1","vdecoys":["wissen","kennen","tun"],"pdecoys":["sich interessieren","erkennen","lernen"],"note":"Meist Ahnung von + Dat. haben, oft verneint (keine Ahnung). Umgangssprachlich. Achtung: Keine Ahnung! allein bedeutet auch nur Ich weiß es nicht.","ex":[{"de":"Ich habe keine Ahnung von Autos.","en":"I know nothing about cars."},{"de":"Mein Bruder hat von Computern wirklich Ahnung.","en":"My brother really knows his computers."},{"de":"Hast du Ahnung von Gartenarbeit?","en":"Do you know anything about gardening?"}],"exPlain":[{"de":"Ich kenne mich mit Autos nicht aus.","en":"I don't know anything about cars."},{"de":"Mein Bruder kennt sich mit Computern wirklich gut aus.","en":"My brother really knows his way around computers."}]},
 {"np":"eine Erkältung","verb":"bekommen","plain":"sich erkälten","en":"to catch a cold","lv":"B1","vdecoys":["machen","nehmen","tragen"],"pdecoys":["sich erholen","sich verletzen","sich verbrennen"],"vAlt":["kriegen"],"note":"Plain ist reflexiv: sich erkälten (Perfekt: Ich habe mich erkältet). Auch: sich eine Erkältung holen/zuziehen. Zustand: eine Erkältung haben.","ex":[{"de":"Im Winter bekomme ich fast jedes Jahr eine Erkältung.","en":"In winter I catch a cold almost every year."},{"de":"Ohne Mütze hat sie bei dem kalten Wind schnell eine Erkältung bekommen.","en":"Without a hat she quickly caught a cold in the cold wind."},{"de":"Wenn ihr so dünn angezogen rausgeht, bekommt ihr eine Erkältung.","en":"If you go out dressed so lightly, you'll catch a cold."}],"exPlain":[{"de":"Im Winter erkälte ich mich fast jedes Jahr.","en":"In winter I catch a cold almost every year."},{"de":"Wenn ihr so dünn angezogen rausgeht, erkältet ihr euch.","en":"If you go out dressed so lightly, you'll catch a cold."}]},
 {"np":"zur Welt","verb":"kommen","plain":"geboren werden","en":"to be born","lv":"B1","vdecoys":["gehen","fallen","treten"],"pdecoys":["wachsen","gebären","aufwachsen"],"note":"Passivische Bedeutung: Ein Kind kommt zur Welt = wird geboren. Nicht verwechseln mit zur Welt bringen (= ein Kind gebären).","ex":[{"de":"Unser Sohn kam in der Nacht zur Welt.","en":"Our son was born during the night."},{"de":"Ihre Tochter kam drei Wochen zu früh zur Welt.","en":"Her daughter was born three weeks early."},{"de":"Als ich zur Welt kam, schneite es seit Tagen.","en":"When I was born it had been snowing for days."}],"exPlain":[{"de":"Unser Sohn wurde in der Nacht geboren.","en":"Our son was born during the night."},{"de":"Ihre Tochter wurde drei Wochen zu früh geboren.","en":"Her daughter was born three weeks early."}]},
 {"np":"Mitglied","verb":"werden","plain":"beitreten","en":"to become a member; to join","lv":"B1","vdecoys":["machen","nehmen","gehen"],"pdecoys":["angehören","verlassen","gründen"],"note":"Plain steht mit Dativ: Ich trete dem Verein bei. Mitglied sein (Zustand) entspricht angehören (auch mit Dativ).","ex":[{"de":"Ich möchte Mitglied in einem Chor werden.","en":"I'd like to join a choir."},{"de":"Wir sind vor zwei Jahren Mitglied im Tennisclub geworden.","en":"We joined the tennis club two years ago."},{"de":"Wer Mitglied wird, bekommt das Jahresheft kostenlos.","en":"Anyone who becomes a member gets the annual magazine free."}],"exPlain":[{"de":"Ich möchte einem Chor beitreten.","en":"I'd like to join a choir."},{"de":"Wir sind vor zwei Jahren dem Tennisclub beigetreten.","en":"We joined the tennis club two years ago."}]},
 {"np":"Beifall","verb":"klatschen","plain":"applaudieren","en":"to applaud","lv":"B2","vdecoys":["machen","schlagen","heben"],"pdecoys":["singen","tanzen","pfeifen"],"vAlt":["spenden"],"note":"Mit Dativ der Person: dem Sänger Beifall klatschen = dem Sänger applaudieren. Beifall klatschen ist alltäglicher als das gehobene Beifall spenden.","ex":[{"de":"Nach dem Konzert klatschte das Publikum minutenlang Beifall.","en":"After the concert the audience applauded for minutes."},{"de":"Die Zuschauer klatschten der Sängerin begeistert Beifall.","en":"The spectators applauded the singer enthusiastically."},{"de":"Alle klatschten Beifall, als der Sieger auf die Bühne kam.","en":"Everyone applauded when the winner came onto the stage."}],"exPlain":[{"de":"Nach dem Konzert applaudierte das Publikum minutenlang.","en":"After the concert the audience applauded for minutes."},{"de":"Die Zuschauer applaudierten der Sängerin begeistert.","en":"The spectators applauded the singer enthusiastically."}]},
 {"np":"Talent","verb":"haben","plain":"begabt sein","en":"to be talented","lv":"B1","vdecoys":["machen","tun","führen"],"pdecoys":["lernen","üben","gewinnen"],"note":"Meist Talent für/zu etwas haben. Plain: begabt sein für etwas.","ex":[{"de":"Sie hat großes Talent für Sprachen.","en":"She has a great talent for languages."},{"de":"Meine Tochter hat Talent zum Zeichnen.","en":"My daughter has a talent for drawing."},{"de":"Er hatte schon als Kind Talent für Musik.","en":"Even as a child he had a talent for music."}],"exPlain":[{"de":"Sie ist sehr begabt für Sprachen.","en":"She is very gifted at languages."},{"de":"Meine Tochter ist fürs Zeichnen begabt.","en":"My daughter is gifted at drawing."}]},
 {"np":"eine Strafe","verb":"bekommen","plain":"bestraft werden","en":"to be punished; to get a penalty","lv":"B1","vdecoys":["machen","nehmen","stellen"],"pdecoys":["verurteilen","beschuldigen","verbieten"],"vAlt":["erhalten"],"note":"Passivische Bedeutung: Wer eine Strafe bekommt, wird bestraft. Auch: für etwas eine Strafe bekommen.","ex":[{"de":"Wer hier falsch parkt, bekommt eine Strafe.","en":"Anyone who parks wrongly here gets a fine."},{"de":"Der Fahrer bekam eine hohe Strafe, weil er viel zu schnell gefahren war.","en":"The driver got a heavy penalty because he had been driving far too fast."},{"de":"Die Kinder haben für den Streich keine Strafe bekommen.","en":"The children didn't get any punishment for the prank."}],"exPlain":[{"de":"Wer hier falsch parkt, wird bestraft.","en":"Anyone who parks wrongly here is punished."},{"de":"Der Fahrer wurde hart bestraft, weil er viel zu schnell gefahren war.","en":"The driver was punished severely because he had been driving far too fast."}]},
 {"np":"in Behandlung","verb":"sein","plain":"behandelt werden","en":"to be under treatment","lv":"B1","vdecoys":["liegen","fallen","hängen"],"pdecoys":["heilen","untersuchen","pflegen"],"note":"Meist bei einem Arzt/einer Ärztin in Behandlung sein. Passivische Bedeutung: Man wird behandelt (nicht: man behandelt selbst).","ex":[{"de":"Mein Vater ist seit Monaten wegen seines Rückens in Behandlung.","en":"My father has been under treatment for his back for months."},{"de":"Sie war lange bei einer Psychologin in Behandlung.","en":"She was in treatment with a psychologist for a long time."},{"de":"Bist du wegen der Allergie bei einem Arzt in Behandlung?","en":"Are you seeing a doctor for the allergy?"}],"exPlain":[{"de":"Mein Vater wird seit Monaten wegen seines Rückens behandelt.","en":"My father has been treated for his back for months."},{"de":"Sie wurde lange von einer Psychologin behandelt.","en":"She was treated by a psychologist for a long time."}]},
 {"np":"eine Lösung","verb":"finden","plain":"lösen","en":"to find a solution; to solve","lv":"B1","vdecoys":["stellen","legen","tragen"],"pdecoys":["entscheiden","erklären","vermeiden"],"note":"Valenz: eine Lösung für + Akk. finden = etwas (Akk.) lösen. Nicht ganz gleich: finden betont das Ergebnis der Suche.","ex":[{"de":"Wir müssen schnell eine Lösung für das Parkplatzproblem finden.","en":"We have to find a solution to the parking problem quickly."},{"de":"Gemeinsam haben sie endlich eine Lösung gefunden.","en":"Together they finally found a solution."},{"de":"Hast du eine Lösung für das Rätsel gefunden?","en":"Have you found the solution to the riddle?"}],"exPlain":[{"de":"Wir müssen das Parkplatzproblem schnell lösen.","en":"We have to solve the parking problem quickly."},{"de":"Gemeinsam haben sie das Problem endlich gelöst.","en":"Together they finally solved the problem."}]},
 {"np":"die Absicht","verb":"haben","plain":"vorhaben","en":"to intend; to plan to","lv":"B1","vdecoys":["machen","geben","stellen"],"pdecoys":["vergessen","verlangen","versprechen"],"pAlt":["beabsichtigen"],"note":"Meist die Absicht haben, … zu + Infinitiv; oft verneint. Etwas formeller als vorhaben. Plain ist trennbar: Ich habe vor, … zu …","ex":[{"de":"Ich habe nicht die Absicht, die Stadt zu verlassen.","en":"I have no intention of leaving the city."},{"de":"Hast du die Absicht, im Sommer umzuziehen?","en":"Do you intend to move in the summer?"},{"de":"Sie hatte nie die Absicht, jemanden zu verletzen.","en":"She never intended to hurt anyone."}],"exPlain":[{"de":"Ich habe nicht vor, die Stadt zu verlassen.","en":"I don't plan to leave the city."},{"de":"Hast du vor, im Sommer umzuziehen?","en":"Do you plan to move in the summer?"}]},
 {"np":"den Abwasch","verb":"machen","plain":"abwaschen","en":"to do the dishes","lv":"B1","vdecoys":["nehmen","führen","halten"],"pdecoys":["putzen","kochen","trocknen"],"pAlt":["spülen","abspülen"],"note":"Alltagssprachlich. Plain ist trennbar (wäscht … ab). In manchen Regionen sagt man spülen.","ex":[{"de":"Wer macht heute Abend den Abwasch?","en":"Who's doing the dishes tonight?"},{"de":"Nach dem Essen haben wir zusammen den Abwasch gemacht.","en":"After the meal we did the dishes together."},{"de":"Ich mache lieber den Abwasch, als zu kochen.","en":"I'd rather do the dishes than cook."}],"exPlain":[{"de":"Wer wäscht heute Abend ab?","en":"Who's washing up tonight?"},{"de":"Nach dem Essen haben wir zusammen abgewaschen.","en":"After the meal we washed up together."}]},
 {"np":"auf den Weg","verb":"machen","plain":"aufbrechen","en":"to set off","lv":"B2","vdecoys":["nehmen","tun","haben"],"pdecoys":["ankommen","zurückkehren","sich verirren"],"pAlt":["losgehen"],"note":"Reflexiv: sich auf den Weg machen. Plain ist trennbar: Wir brechen auf; Perfekt mit sein: Wir sind aufgebrochen.","ex":[{"de":"Wir müssen uns früh auf den Weg machen, sonst kommen wir in den Stau.","en":"We have to set off early, otherwise we'll get stuck in traffic."},{"de":"Er machte sich bei Sonnenaufgang auf den Weg zum Gipfel.","en":"He set off for the summit at sunrise."},{"de":"Die Gruppe hat sich gegen acht Uhr auf den Weg gemacht.","en":"The group set off at around eight o'clock."}],"exPlain":[{"de":"Wir müssen früh aufbrechen, sonst kommen wir in den Stau.","en":"We have to set off early, otherwise we'll get stuck in traffic."},{"de":"Er brach bei Sonnenaufgang zum Gipfel auf.","en":"He set off for the summit at sunrise."}],"vAlt":["begeben"]},
 {"np":"die Geduld","verb":"verlieren","plain":"ungeduldig werden","en":"to lose patience","lv":"B1","vdecoys":["versäumen","verlegen","vergessen"],"pdecoys":["warten","sich beruhigen","zögern"],"note":"Gegenteil: Geduld haben. Der Zustand danach: ungeduldig sein.","ex":[{"de":"Nach zwei Stunden im Stau verlor er die Geduld.","en":"After two hours in the traffic jam he lost his patience."},{"de":"Verlier bitte nicht die Geduld, wir sind gleich da.","en":"Please don't lose patience, we'll be there soon."},{"de":"Die Kinder haben bei der langen Fahrt schnell die Geduld verloren.","en":"The children quickly lost patience on the long journey."}],"exPlain":[{"de":"Nach zwei Stunden im Stau wurde er ungeduldig.","en":"After two hours in the traffic jam he became impatient."},{"de":"Werde bitte nicht ungeduldig, wir sind gleich da.","en":"Please don't get impatient, we'll be there soon."}]},
 {"np":"den Anfang","verb":"machen","plain":"anfangen","en":"to make a start; to begin","lv":"B1","vdecoys":["geben","stellen","führen"],"pdecoys":["beenden","vorbereiten","fortfahren"],"pAlt":["beginnen"],"note":"Meist Wer macht den Anfang? Auch: mit etwas den Anfang machen = mit etwas beginnen. Plain ist trennbar: fängt an.","ex":[{"de":"Wer möchte heute den Anfang machen?","en":"Who would like to make a start today?"},{"de":"Die Jüngsten machten den Anfang und sangen ein Lied.","en":"The youngest ones started off and sang a song."},{"de":"Ich mache den Anfang, danach seid ihr dran.","en":"I'll start, then it's your turn."}],"exPlain":[{"de":"Wer möchte heute anfangen?","en":"Who would like to start today?"},{"de":"Die Jüngsten fingen an und sangen ein Lied.","en":"The youngest ones started and sang a song."}]},
 {"np":"eine Entdeckung","verb":"machen","plain":"entdecken","en":"to make a discovery; to discover","lv":"B1","vdecoys":["tun","finden","stellen"],"pdecoys":["erfinden","suchen","verstecken"],"note":"Plain braucht ein Objekt (Akk.): etwas Neues entdecken. Die Wendung betont oft das Überraschende.","ex":[{"de":"Beim Aufräumen habe ich eine tolle Entdeckung gemacht: Ich fand mein altes Tagebuch.","en":"While tidying up I made a great discovery: I found my old diary."},{"de":"Die Forscher machten im Wald eine überraschende Entdeckung.","en":"The researchers made a surprising discovery in the forest."},{"de":"Machst du im Urlaub gern neue Entdeckungen?","en":"Do you like making new discoveries on holiday?"}],"exPlain":[{"de":"Beim Aufräumen habe ich mein altes Tagebuch entdeckt.","en":"While tidying up I discovered my old diary."},{"de":"Die Forscher entdeckten im Wald eine seltene Pflanze.","en":"The researchers discovered a rare plant in the forest."}]},
 {"np":"einen Tipp","verb":"geben","plain":"empfehlen","en":"to give a tip; to recommend","lv":"B1","vdecoys":["legen","stellen","nehmen"],"pdecoys":["warnen","befehlen","bestellen"],"note":"Dativ der Person: jemandem einen Tipp geben. Plain: jemandem etwas empfehlen (Dativ + Akkusativ). Nicht mit einen Rat geben (= raten) gleichsetzen.","ex":[{"de":"Kannst du mir einen Tipp für ein gutes Restaurant geben?","en":"Can you give me a tip for a good restaurant?"},{"de":"Sie hat mir einen guten Tipp für die Reise nach Wien gegeben.","en":"She gave me a good tip for the trip to Vienna."},{"de":"Ich gebe dir einen Tipp: Buch die Karten rechtzeitig.","en":"I'll give you a tip: book the tickets in good time."}],"exPlain":[{"de":"Kannst du mir ein gutes Restaurant empfehlen?","en":"Can you recommend a good restaurant to me?"},{"de":"Sie empfahl mir ein kleines Hotel in Wien.","en":"She recommended a small hotel in Vienna to me."}]},
 {"np":"Gas","verb":"geben","plain":"beschleunigen","en":"to accelerate; to step on the gas","lv":"B2","vdecoys":["legen","tragen","setzen"],"pdecoys":["bremsen","anhalten","wenden"],"note":"Wörtlich beim Autofahren, übertragen auch: sich beeilen. Gegenteil: bremsen/vom Gas gehen. Umgangssprachlich: Vollgas geben.","ex":[{"de":"An der Ampel gab er sofort Gas.","en":"He stepped on the gas straight away at the traffic light."},{"de":"Wenn du jetzt Gas gibst, schaffen wir den Zug noch.","en":"If you step on it now, we'll still make the train."},{"de":"Auf der leeren Landstraße gab sie ordentlich Gas.","en":"On the empty country road she really put her foot down."}],"exPlain":[{"de":"An der Ampel beschleunigte er sofort.","en":"He accelerated straight away at the traffic light."},{"de":"Wenn du jetzt beschleunigst, schaffen wir den Zug noch.","en":"If you speed up now, we'll still make the train."}]},
 {"np":"Lob","verb":"bekommen","plain":"gelobt werden","en":"to be praised; to receive praise","lv":"B1","vdecoys":["machen","nehmen","tun"],"pdecoys":["kritisieren","bestrafen","tadeln"],"vAlt":["erhalten","ernten"],"note":"Passivische Bedeutung: Wer Lob bekommt, wird gelobt. Auch: für etwas Lob bekommen/ernten.","ex":[{"de":"Für ihren Kuchen hat sie viel Lob bekommen.","en":"She received a lot of praise for her cake."},{"de":"Die Kinder bekamen vom Trainer ein großes Lob.","en":"The children received great praise from the coach."},{"de":"Ich habe selten so viel Lob bekommen wie nach dem Fest.","en":"I've rarely received as much praise as after the party."}],"exPlain":[{"de":"Für ihren Kuchen wurde sie sehr gelobt.","en":"She was praised a lot for her cake."},{"de":"Die Kinder wurden vom Trainer sehr gelobt.","en":"The children were praised a lot by the coach."}]},
 {"np":"im Gedächtnis","verb":"behalten","plain":"sich merken","en":"to remember; to keep in mind","lv":"B1","vdecoys":["stellen","setzen","legen"],"pdecoys":["vergessen","sich erinnern","lernen"],"note":"Auch: im Kopf behalten. Plain ist reflexiv mit Dativ: sich (Dat.) etwas merken. Nicht: sich erinnern (= sich an Vergangenes zurückerinnern).","ex":[{"de":"Diese Telefonnummer solltest du im Gedächtnis behalten.","en":"You should keep this phone number in mind."},{"de":"Sie hat die Namen aller Gäste im Gedächtnis behalten.","en":"She remembered the names of all the guests."},{"de":"Ich konnte die Reihenfolge der Schritte nicht im Gedächtnis behalten.","en":"I couldn't keep the order of the steps in my head."}],"exPlain":[{"de":"Diese Telefonnummer solltest du dir merken.","en":"You should remember this phone number."},{"de":"Sie hat sich die Namen aller Gäste gemerkt.","en":"She remembered the names of all the guests."}],"vAlt":["bewahren","haben"]},
 {"np":"jemandem Angst","verb":"machen","plain":"ängstigen","en":"to frighten someone; to scare someone","lv":"B2","vdecoys":["geben","tun","stellen"],"pdecoys":["trösten","warnen","verbieten"],"vAlt":["einjagen","bereiten"],"note":"Die Person steht im Dativ: Das macht mir Angst = Das ängstigt mich (Akk.). Im Alltag ist Angst machen viel üblicher; ängstigen klingt gehobener. Jemandem Angst einjagen ist stärker.","ex":[{"de":"Die Dunkelheit macht dem Kind Angst.","en":"The dark frightens the child."},{"de":"Mach deinem kleinen Bruder doch keine Angst!","en":"Don't scare your little brother!"},{"de":"Der Lärm des Gewitters machte den Hunden große Angst.","en":"The noise of the thunderstorm terrified the dogs."}],"exPlain":[{"de":"Die Dunkelheit ängstigt das Kind.","en":"The dark frightens the child."},{"de":"Das laute Gewitter ängstigte die Hunde sehr.","en":"The loud thunderstorm frightened the dogs a lot."}]},
 {"np":"einen Schreck","verb":"bekommen","plain":"erschrecken","en":"to get a fright; to be startled","lv":"B1","vdecoys":["machen","nehmen","tun"],"pdecoys":["aufwachen","stolpern","sich verlaufen"],"vAlt":["kriegen"],"note":"Plain ist intransitiv und stark: erschrecken (er erschrickt, erschrak, ist erschrocken). Nicht verwechseln mit jemandem einen Schreck einjagen / jemanden erschrecken (transitiv, schwach).","ex":[{"de":"Ich habe einen Schreck bekommen, als plötzlich die Tür zuschlug.","en":"I got a fright when the door suddenly slammed."},{"de":"Als der Hund bellte, bekam das Kind einen großen Schreck.","en":"When the dog barked, the child got a big fright."},{"de":"Du bekommst bestimmt einen Schreck, wenn du die Rechnung siehst.","en":"You'll surely get a shock when you see the bill."}],"exPlain":[{"de":"Ich bin erschrocken, als plötzlich die Tür zuschlug.","en":"I was startled when the door suddenly slammed."},{"de":"Als der Hund bellte, erschrak das Kind.","en":"When the dog barked, the child was startled."}]},
 {"np":"eine Einladung","verb":"bekommen","plain":"eingeladen werden","en":"to receive an invitation; to be invited","lv":"B1","vdecoys":["machen","nehmen","tragen"],"pdecoys":["einladen","annehmen","absagen"],"vAlt":["erhalten"],"note":"Passivische Bedeutung: Wer eine Einladung bekommt, wird eingeladen. Der Einladende dagegen schickt oder spricht eine Einladung aus.","ex":[{"de":"Zur Hochzeit meiner Cousine habe ich eine Einladung bekommen.","en":"I got an invitation to my cousin's wedding."},{"de":"Wir haben eine Einladung zum Grillen bekommen.","en":"We got an invitation to a barbecue."},{"de":"Hast du auch eine Einladung bekommen?","en":"Did you get an invitation too?"}],"exPlain":[{"de":"Ich wurde zur Hochzeit meiner Cousine eingeladen.","en":"I was invited to my cousin's wedding."},{"de":"Wir wurden zum Grillen eingeladen.","en":"We were invited to a barbecue."}]},
 {"np":"einen Verband","verb":"anlegen","plain":"verbinden","en":"to apply a bandage; to bandage (a wound)","lv":"B1","vdecoys":["aufsetzen","einsetzen","aufstellen"],"pdecoys":["heilen","untersuchen","impfen"],"note":"Trennbar (legt … an). Plain: eine Wunde / jemandem die Wunde verbinden (verbinden hat auch andere Bedeutungen, z. B. zwei Dinge verbinden).","ex":[{"de":"Die Ärztin legte dem Verletzten einen Verband an.","en":"The doctor put a bandage on the injured man."},{"de":"Kannst du mir bitte einen Verband anlegen?","en":"Can you put a bandage on for me, please?"},{"de":"Der Arzt hat ihr am Knie einen Verband angelegt.","en":"The doctor put a bandage on her knee."}],"exPlain":[{"de":"Die Ärztin verband die Wunde des Verletzten.","en":"The doctor bandaged the injured man's wound."},{"de":"Der Arzt hat ihr das Knie verbunden.","en":"The doctor bandaged her knee."}]},
 {"np":"einen Scherz","verb":"machen","plain":"scherzen","en":"to make a joke; to joke","lv":"B1","vdecoys":["tun","halten","führen"],"pdecoys":["lügen","streiten","lästern"],"note":"Auch: Scherze machen, einen Spaß machen. Mach keine Scherze! = Das kann nicht dein Ernst sein! Scherzen klingt etwas gehobener.","ex":[{"de":"Er hat beim Essen einen Scherz gemacht, und alle haben gelacht.","en":"He made a joke during dinner and everyone laughed."},{"de":"Ich wollte doch nur einen Scherz machen!","en":"I only wanted to make a joke!"},{"de":"Mach keine Scherze, das glaubst du doch selbst nicht!","en":"You must be joking, you don't even believe that yourself!"}],"exPlain":[{"de":"Er hat beim Essen gescherzt, und alle haben gelacht.","en":"He joked during dinner and everyone laughed."},{"de":"Ich wollte doch nur scherzen!","en":"I only wanted to joke!"}]},
 {"np":"Blut","verb":"verlieren","plain":"bluten","en":"to lose blood; to bleed","lv":"B1","vdecoys":["sparen","verbrauchen","verlegen"],"pdecoys":["heilen","verbinden","spenden"],"note":"Meist viel/wenig Blut verlieren. Plain: stark/leicht bluten. Nicht verwechseln mit Blut spenden.","ex":[{"de":"Der Radfahrer verlor nach dem Sturz viel Blut.","en":"The cyclist lost a lot of blood after the fall."},{"de":"Wer viel Blut verliert, braucht schnell Hilfe.","en":"Anyone who loses a lot of blood needs help quickly."},{"de":"Sie hat beim Unfall zum Glück nur wenig Blut verloren.","en":"Luckily she lost only little blood in the accident."}],"exPlain":[{"de":"Der Radfahrer blutete nach dem Sturz stark.","en":"The cyclist bled heavily after the fall."},{"de":"Wer stark blutet, braucht schnell Hilfe.","en":"Anyone who is bleeding heavily needs help quickly."}]},
 {"np":"Erinnerung","verb":"haben","plain":"sich erinnern","en":"to remember; to have a memory of","lv":"B1","vdecoys":["machen","geben","nehmen"],"pdecoys":["vergessen","sich entschuldigen","erkennen"],"note":"Erinnerung an + Akk. haben = sich an etwas (Akk.) erinnern. Meist verneint oder mit Adjektiv (keine/gute Erinnerung). Plain ist reflexiv.","ex":[{"de":"Ich habe keine Erinnerung an den Unfall.","en":"I have no memory of the accident."},{"de":"Hast du noch eine Erinnerung an dein erstes Fahrrad?","en":"Do you still have a memory of your first bike?"},{"de":"Sie hatte keine Erinnerung mehr daran, wie sie nach Hause gekommen war.","en":"She no longer remembered how she had got home."}],"exPlain":[{"de":"Ich erinnere mich nicht an den Unfall.","en":"I don't remember the accident."},{"de":"Erinnerst du dich noch an dein erstes Fahrrad?","en":"Do you still remember your first bike?"}]},
 {"np":"eine Fahrkarte","verb":"lösen","plain":"kaufen","en":"to buy a ticket","lv":"B1","vdecoys":["machen","legen","setzen"],"pdecoys":["entwerten","verlieren","kontrollieren"],"note":"Etwas formeller als kaufen; üblich bei Fahrkarten und Eintrittskarten. Nicht: eine Fahrkarte machen.","ex":[{"de":"Du musst vor der Fahrt noch eine Fahrkarte lösen.","en":"You still have to buy a ticket before the journey."},{"de":"Am Automaten habe ich eine Fahrkarte für zwei Zonen gelöst.","en":"At the machine I bought a ticket for two zones."},{"de":"Wo kann man hier eine Fahrkarte lösen?","en":"Where can you buy a ticket here?"}],"exPlain":[{"de":"Du musst vor der Fahrt noch eine Fahrkarte kaufen.","en":"You still have to buy a ticket before the journey."},{"de":"Am Automaten habe ich eine Fahrkarte für zwei Zonen gekauft.","en":"At the machine I bought a ticket for two zones."}]},
 {"np":"Beschwerde","verb":"einlegen","plain":"sich beschweren","en":"to lodge a complaint","lv":"B2","vdecoys":["stellen","geben","machen"],"pdecoys":["sich bedanken","sich entschuldigen","sich bewerben"],"vAlt":["erheben"],"note":"Formal/official register; usually a written complaint to an authority or company: bei der Behörde Beschwerde einlegen, gegen etwas Beschwerde einlegen. The plain verb is reflexive: sich über etwas bei jemandem beschweren.","ex":[{"de":"Die Mieter legten beim Vermieter Beschwerde über den Lärm ein.","en":"The tenants lodged a complaint with the landlord about the noise."},{"de":"Wenn Sie mit dem Beschluss des Gerichts nicht einverstanden sind, können Sie dagegen Beschwerde einlegen.","en":"If you do not agree with the court's order, you can lodge a complaint (appeal) against it."},{"de":"Der Kunde hat bei der Aufsichtsbehörde Beschwerde eingelegt.","en":"The customer lodged a complaint with the supervisory authority."}],"exPlain":[{"de":"Die Mieter beschwerten sich beim Vermieter über den Lärm.","en":"The tenants complained to the landlord about the noise."}]},
 {"np":"Widerspruch","verb":"einlegen","plain":"widersprechen","en":"to lodge an objection (against a decision)","lv":"C1","vdecoys":["stellen","geben","machen"],"pdecoys":["zustimmen","bestätigen","genehmigen"],"vAlt":["erheben"],"note":"Administrative law: gegen einen Bescheid Widerspruch einlegen (usually in writing and within a deadline). The plain verb widersprechen takes the dative (einem Bescheid widersprechen). Against tax assessments the technical term is Einspruch (einlegen), not Widerspruch.","ex":[{"de":"Gegen den Ablehnungsbescheid der Behörde hat die Firma fristgerecht Widerspruch eingelegt.","en":"The company filed an objection to the authority's rejection notice within the deadline."},{"de":"Sie können innerhalb eines Monats Widerspruch einlegen.","en":"You can lodge an objection within one month."},{"de":"Die Anwohner legten gegen die Baugenehmigung Widerspruch ein.","en":"The residents objected to the building permit."}],"exPlain":[{"de":"Die Firma hat dem Ablehnungsbescheid der Behörde fristgerecht widersprochen.","en":"The company objected to the authority's rejection notice within the deadline."}]},
 {"np":"Berufung","verb":"einlegen","plain":"anfechten","en":"to appeal (against a court judgment)","lv":"C1","vdecoys":["stellen","geben","machen"],"pdecoys":["verurteilen","freisprechen","begnadigen"],"note":"Legal language. Berufung einlegen gegen ein Urteil; the plain verb anfechten takes a direct object (ein Urteil anfechten) and is broader (it also covers other appeals and legal challenges). Related: in Berufung gehen. Berufung is an appeal on facts and law; Revision (points of law only) is a separate remedy.","ex":[{"de":"Der Verurteilte legte gegen das Urteil Berufung ein.","en":"The convicted man appealed against the judgment."},{"de":"Die Verteidigung kündigte an, noch in dieser Woche Berufung einzulegen.","en":"The defence announced that it would lodge an appeal this week."},{"de":"Wegen der hohen Strafe hat die Angeklagte Berufung eingelegt.","en":"Because of the severe sentence, the defendant has lodged an appeal."}],"exPlain":[{"de":"Der Verurteilte focht das Urteil an.","en":"The convicted man appealed against the judgment."}]},
 {"np":"Verwahrung","verb":"einlegen","plain":"protestieren","en":"to lodge a formal protest","lv":"C1","vdecoys":["stellen","geben","machen"],"pdecoys":["befürworten","bedauern","bewahren"],"pAlt":["sich verwahren"],"note":"Very formal, mostly diplomatic or legal language: gegen etwas Verwahrung einlegen. Not used for everyday protest.","ex":[{"de":"Die Regierung legte gegen die Äußerungen des Botschafters Verwahrung ein.","en":"The government lodged a formal protest against the ambassador's remarks."},{"de":"Der Verband hat gegen die geplante Gesetzesänderung entschieden Verwahrung eingelegt.","en":"The association lodged a firm protest against the planned change in the law."},{"de":"Er legte Verwahrung dagegen ein, dass seine Worte verfälscht wiedergegeben wurden.","en":"He formally protested against his words being misrepresented."}],"exPlain":[{"de":"Die Regierung protestierte gegen die Äußerungen des Botschafters.","en":"The government protested against the ambassador's remarks."}]},
 {"np":"Zustimmung","verb":"erteilen","plain":"zustimmen","en":"to give one's consent","lv":"C1","vdecoys":["machen","stellen","legen"],"pdecoys":["ablehnen","bedenken","verbieten"],"vAlt":["geben"],"note":"Formal; the subject is often an authority or body: seine Zustimmung erteilen. zustimmen takes the dative (dem Vorschlag zustimmen). Compare Genehmigung erteilen (= genehmigen).","ex":[{"de":"Der Aufsichtsrat erteilte der Fusion seine Zustimmung.","en":"The supervisory board gave its consent to the merger."},{"de":"Die Eltern müssen schriftlich ihre Zustimmung erteilen.","en":"The parents must give their consent in writing."},{"de":"Der Bundesrat hat dem Gesetz gestern seine Zustimmung erteilt.","en":"The Bundesrat gave its consent to the law yesterday."}],"exPlain":[{"de":"Der Aufsichtsrat stimmte der Fusion zu.","en":"The supervisory board agreed to the merger."}]},
 {"np":"Vollmacht","verb":"erteilen","plain":"bevollmächtigen","en":"to grant power of attorney / authority","lv":"C1","vdecoys":["machen","stellen","setzen"],"pdecoys":["entlassen","ernennen","entmündigen"],"vAlt":["geben"],"pAlt":["ermächtigen"],"note":"Legal/formal. jemandem Vollmacht erteilen = jemanden (zu etwas) bevollmächtigen. In the plain form the person is the accusative object.","ex":[{"de":"Der Geschäftsführer erteilte seiner Assistentin Vollmacht für alle Bankgeschäfte.","en":"The managing director granted his assistant authority for all banking transactions."},{"de":"Für den Fall einer schweren Krankheit sollte man rechtzeitig einer Vertrauensperson Vollmacht erteilen.","en":"In case of serious illness, one should grant power of attorney to a trusted person in good time."},{"de":"Die Erbin hatte dem Anwalt Vollmacht erteilt, den Verkauf abzuwickeln.","en":"The heiress had authorised the lawyer to handle the sale."}],"exPlain":[{"de":"Der Geschäftsführer bevollmächtigte seine Assistentin für alle Bankgeschäfte.","en":"The managing director authorised his assistant for all banking transactions."}]},
 {"np":"eine Rüge","verb":"erteilen","plain":"rügen","en":"to reprimand formally","lv":"C1","vdecoys":["machen","stellen","tun"],"pdecoys":["loben","belehren","bestrafen"],"vAlt":["aussprechen"],"note":"Official/formal: a reprimand by a superior or a body (Aufsichtsbehörde, Gericht, Vorstand). jemandem eine Rüge erteilen = jemanden rügen.","ex":[{"de":"Der Vorstand erteilte dem Abteilungsleiter wegen der Verspätung eine Rüge.","en":"The board formally reprimanded the head of department for the delay."},{"de":"Die Aufsichtsbehörde hat dem Unternehmen eine Rüge erteilt.","en":"The regulatory authority has issued a reprimand to the company."},{"de":"Für sein Verhalten im Gerichtssaal wurde ihm eine Rüge erteilt.","en":"He was reprimanded for his behaviour in the courtroom."}],"exPlain":[{"de":"Der Vorstand rügte den Abteilungsleiter wegen der Verspätung.","en":"The board reprimanded the head of department for the delay."}]},
 {"np":"zur Last","verb":"legen","plain":"vorwerfen","en":"to charge someone with; to blame someone for","lv":"C1","vdecoys":["stellen","setzen","bringen"],"pdecoys":["beschenken","verzeihen","entlasten"],"pAlt":["beschuldigen"],"note":"Legal/formal. jemandem etwas zur Last legen = jemandem etwas vorwerfen (dative of person + accusative of the offence). beschuldigen works differently: jemanden einer Tat beschuldigen (genitive). Often passive: Was wird ihm zur Last gelegt?","ex":[{"de":"Die Staatsanwaltschaft legt dem Mann Betrug in mehreren Fällen zur Last.","en":"The public prosecutor charges the man with fraud in several cases."},{"de":"Man kann ihr diesen Fehler nicht zur Last legen.","en":"One cannot blame her for this mistake."},{"de":"Was wird dem Angeklagten konkret zur Last gelegt?","en":"What exactly is the defendant accused of?"}],"exPlain":[{"de":"Die Staatsanwaltschaft wirft dem Mann Betrug in mehreren Fällen vor.","en":"The public prosecutor accuses the man of fraud in several cases."}]},
 {"np":"in Abrede","verb":"stellen","plain":"bestreiten","en":"to deny; to dispute","lv":"C1","vdecoys":["setzen","bringen","nehmen"],"pdecoys":["bestätigen","bezeugen","gestehen"],"pAlt":["leugnen"],"note":"Formal/legal, usually about facts, accusations or claims: eine Tat in Abrede stellen. Not used for denying a person.","ex":[{"de":"Der Geschäftsführer stellte jede Mitschuld an dem Unglück in Abrede.","en":"The managing director denied any share of the blame for the accident."},{"de":"Niemand stellt in Abrede, dass die Lage ernst ist.","en":"Nobody denies that the situation is serious."},{"de":"Die Beschuldigte hat den Vorwurf in Abrede gestellt.","en":"The accused has denied the allegation."}],"exPlain":[{"de":"Der Geschäftsführer bestritt jede Mitschuld an dem Unglück.","en":"The managing director denied any share of the blame for the accident."}]},
 {"np":"in Haft","verb":"nehmen","plain":"verhaften","en":"to take into custody; to arrest","lv":"C1","vdecoys":["stellen","legen","tun"],"pdecoys":["entlassen","verurteilen","verhören"],"pAlt":["festnehmen"],"note":"Police/legal register, mostly in the passive: wurde in Haft genommen. A person is taken into custody (also pre-trial detention).","ex":[{"de":"Die Behörden nahmen den mutmaßlichen Täter noch am selben Tag in Haft.","en":"The authorities took the suspected offender into custody the same day."},{"de":"Er wurde unmittelbar nach der Landung in Haft genommen.","en":"He was taken into custody immediately after landing."},{"de":"Der Richter ordnete an, die Verdächtigen in Haft zu nehmen.","en":"The judge ordered the suspects to be taken into custody."}],"exPlain":[{"de":"Die Behörden verhafteten den mutmaßlichen Täter noch am selben Tag.","en":"The authorities arrested the suspected offender the same day."}]},
 {"np":"in Gewahrsam","verb":"nehmen","plain":"festnehmen","en":"to take into (police) custody","lv":"C1","vdecoys":["legen","stellen","tun"],"pdecoys":["freilassen","verurteilen","befragen"],"vAlt":["bringen"],"note":"Police language; Gewahrsam is short-term, usually preventive police custody (e.g. to stop disturbances or for a person's own protection), not an arrest on suspicion of a crime. Often passive.","ex":[{"de":"Nach den Ausschreitungen nahmen die Beamten mehrere Demonstranten in Gewahrsam.","en":"After the riots the officers took several demonstrators into custody."},{"de":"Der betrunkene Randalierer wurde über Nacht in Gewahrsam genommen.","en":"The drunken rioter was taken into custody for the night."},{"de":"Die Polizei hat den aggressiven Fan vorläufig in Gewahrsam genommen.","en":"The police have provisionally taken the aggressive fan into custody."}],"exPlain":[{"de":"Nach den Ausschreitungen nahmen die Beamten mehrere Demonstranten fest.","en":"After the riots the officers detained several demonstrators."}]},
 {"np":"unter Vertrag","verb":"nehmen","plain":"engagieren","en":"to sign (a player, artist or employee)","lv":"C1","vdecoys":["setzen","stellen","legen"],"pdecoys":["kündigen","entlassen","versetzen"],"pAlt":["verpflichten"],"note":"Journalistic/business register, esp. sport and culture: einen Spieler unter Vertrag nehmen. The state afterwards is unter Vertrag stehen. engagieren is the closest plain verb (hire, esp. artists); verpflichten is the usual sports term.","ex":[{"de":"Der Verein hat den jungen Stürmer für vier Jahre unter Vertrag genommen.","en":"The club has signed the young striker for four years."},{"de":"Das Label nahm die Sängerin unmittelbar nach dem Konzert unter Vertrag.","en":"The label signed the singer straight after the concert."},{"de":"Der Konzern will mehrere Spezialisten unter Vertrag nehmen.","en":"The group wants to sign up several specialists."}],"exPlain":[{"de":"Der Verein hat den jungen Stürmer für vier Jahre engagiert.","en":"The club has signed the young striker for four years."}]},
 {"np":"in die Pflicht","verb":"nehmen","plain":"verpflichten","en":"to hold someone accountable; to call on someone to do their duty","lv":"C1","vdecoys":["setzen","legen","führen"],"pdecoys":["entlasten","entbinden","entschuldigen"],"pAlt":["in die Verantwortung nehmen"],"note":"Common in politics and journalism: jemanden (für etwas) in die Pflicht nehmen = demand that someone fulfils a responsibility. verpflichten is only a rough match (it usually needs zu etwas and can also mean \"to sign\" a player). Not the same as in Anspruch nehmen.","ex":[{"de":"Die Regierung will die großen Energiekonzerne stärker in die Pflicht nehmen.","en":"The government wants to hold the large energy groups more accountable."},{"de":"Der Trainer nahm die erfahrenen Spieler in die Pflicht.","en":"The coach called on the experienced players to take responsibility."},{"de":"Eltern müssen in die Pflicht genommen werden, wenn ihre Kinder die Schule schwänzen.","en":"Parents must be held to their duty when their children skip school."}],"exPlain":[{"de":"Die Regierung will die großen Energiekonzerne stärker verpflichten.","en":"The government wants to put the large energy groups under a stronger obligation."}]},
 {"np":"Abstand","verb":"nehmen","plain":"absehen","en":"to refrain from; to desist from","lv":"C1","vdecoys":["stellen","machen","geben"],"pdecoys":["abwarten","abraten","abbestellen"],"pAlt":["verzichten"],"note":"Formal. Abstand nehmen von etwas (+ Dat.) = von etwas absehen (+ Dat.) or auf etwas verzichten (+ Akk.). Not to be confused with Abstand halten (to keep one's distance).","ex":[{"de":"Die Stadt nahm von dem geplanten Neubau Abstand.","en":"The city refrained from the planned new building."},{"de":"Wir haben davon Abstand genommen, die Preise zu erhöhen.","en":"We have refrained from raising the prices."},{"de":"Der Geschädigte will von einer Anzeige Abstand nehmen, wenn sich der Gegner entschuldigt.","en":"The injured party is willing to refrain from filing a complaint with the police if the opponent apologises."}],"exPlain":[{"de":"Die Stadt sah von dem geplanten Neubau ab.","en":"The city refrained from the planned new building."}]},
 {"np":"Anklage","verb":"erheben","plain":"anklagen","en":"to bring charges; to indict","lv":"C1","vdecoys":["stellen","setzen","machen"],"pdecoys":["verteidigen","freisprechen","vernehmen"],"note":"Legal language; the public prosecutor is the subject. gegen jemanden Anklage erheben (wegen etwas). The plain verb takes an accusative object: jemanden wegen etwas anklagen.","ex":[{"de":"Die Staatsanwaltschaft erhob gegen den Unternehmer Anklage wegen Steuerhinterziehung.","en":"The public prosecutor brought charges against the businessman for tax evasion."},{"de":"Wegen Bestechlichkeit wird gegen mehrere Beamte Anklage erhoben.","en":"Charges are being brought against several officials for taking bribes."},{"de":"Es wurde keine Anklage erhoben, weil die Beweise nicht ausreichten.","en":"No charges were brought because the evidence was insufficient."}],"exPlain":[{"de":"Die Staatsanwaltschaft klagte den Unternehmer wegen Steuerhinterziehung an.","en":"The public prosecutor charged the businessman with tax evasion."}]},
 {"np":"unter Verdacht","verb":"stehen","plain":"verdächtig sein","en":"to be under suspicion","lv":"C1","vdecoys":["liegen","sitzen","hängen"],"pdecoys":["unschuldig sein","verdächtigen","ermitteln"],"note":"State, not event: unter Verdacht stehen (= be suspected). The Aktionsart with geraten marks the beginning (unter Verdacht geraten = become a suspect). Also possible: im Verdacht stehen, etwas getan zu haben.","ex":[{"de":"Der Bürgermeister steht unter Verdacht; er soll Gelder veruntreut haben.","en":"The mayor is under suspicion; he is said to have embezzled funds."},{"de":"Mehrere Mitarbeiter standen lange unter Verdacht.","en":"Several employees were under suspicion for a long time."},{"de":"Wer unter Verdacht steht, hat das Recht zu schweigen.","en":"Anyone who is under suspicion has the right to remain silent."}],"exPlain":[{"de":"Der Bürgermeister ist der Veruntreuung verdächtig.","en":"The mayor is suspected of embezzlement."}]},
 {"np":"unter Anklage","verb":"stehen","plain":"angeklagt sein","en":"to stand accused; to be under indictment","lv":"C1","vdecoys":["liegen","sitzen","hängen"],"pdecoys":["verurteilt sein","freigesprochen sein","verhaftet sein"],"note":"Legal/journalistic. State: unter Anklage stehen. Causative counterpart: jemanden unter Anklage stellen (to indict someone).","ex":[{"de":"Der frühere Minister steht wegen Bestechlichkeit unter Anklage.","en":"The former minister stands accused of taking bribes."},{"de":"Die beiden Männer standen monatelang unter Anklage, bevor sie freigesprochen wurden.","en":"The two men stood accused for months before they were acquitted."},{"de":"Wegen Untreue steht sie nun unter Anklage.","en":"She now stands accused of breach of trust."}],"exPlain":[{"de":"Der frühere Minister ist wegen Bestechlichkeit angeklagt.","en":"The former minister is accused of taking bribes."}]},
 {"np":"ein Urteil","verb":"fällen","plain":"urteilen","en":"to pass judgment; to deliver a verdict","lv":"C1","vdecoys":["geben","machen","stellen"],"pdecoys":["verurteilen","vollstrecken","anklagen"],"vAlt":["sprechen"],"note":"Legal language, but also figurative (ein hartes Urteil über jemanden fällen). Plain urteilen: über etwas urteilen / in einem Verfahren urteilen. Not identical with verurteilen (= to convict).","ex":[{"de":"Das Gericht fällte nach drei Verhandlungstagen sein Urteil.","en":"After three days of hearings the court passed its judgment."},{"de":"Es ist zu früh, ein endgültiges Urteil über die Reform zu fällen.","en":"It is too early to pass a final judgment on the reform."},{"de":"Die Richterin hat ein mildes Urteil gefällt.","en":"The judge handed down a lenient verdict."}],"exPlain":[{"de":"Das Gericht urteilte nach drei Verhandlungstagen.","en":"After three days of hearings the court gave its verdict."}]},
 {"np":"eine Verfügung","verb":"treffen","plain":"verfügen","en":"to order; to decree (officially)","lv":"C1","vdecoys":["machen","geben","stellen"],"pdecoys":["beantragen","bestätigen","aufheben"],"vAlt":["erlassen"],"note":"Legal/administrative sense only: eine Verfügung treffen = verfügen (to order, to determine by decree or will). Do not confuse with verfügen über (= to have at one's disposal).","ex":[{"de":"In ihrem Testament traf die Verstorbene eine Verfügung zugunsten der Kinder.","en":"In her will the deceased made a provision in favour of the children."},{"de":"Die Behörde hat eine vorläufige Verfügung getroffen.","en":"The authority has issued a provisional order."}],"exPlain":[{"de":"In ihrem Testament verfügte die Verstorbene zugunsten der Kinder.","en":"In her will the deceased made provisions in favour of the children."}]},
 {"np":"eine Regelung","verb":"treffen","plain":"regeln","en":"to make an arrangement; to settle by regulation","lv":"C1","vdecoys":["legen","geben","stellen"],"pdecoys":["verwalten","ablehnen","kontrollieren"],"vAlt":["finden"],"note":"Formal/administrative. Both parties or an authority fix how something is to be handled: eine Regelung für etwas treffen.","ex":[{"de":"Die Gemeinde traf eine neue Regelung für das Parken in der Innenstadt.","en":"The municipality made a new regulation for parking in the city centre."},{"de":"Wir sollten rechtzeitig eine Regelung für die Vertretung im Sommer treffen.","en":"We should make an arrangement for cover over the summer in good time."},{"de":"Zwischen den Vertragsparteien wurde eine klare Regelung getroffen.","en":"A clear arrangement was made between the contracting parties."}],"exPlain":[{"de":"Die Gemeinde regelte das Parken in der Innenstadt neu.","en":"The municipality reorganised the parking arrangements in the city centre."}]},
 {"np":"Feststellungen","verb":"treffen","plain":"feststellen","en":"to make findings; to establish","lv":"C1","vdecoys":["geben","stellen","bringen"],"pdecoys":["behaupten","verhindern","übersehen"],"vAlt":["machen"],"note":"Formal/official, typically in reports and audits (plural). Plain feststellen is separable: Wir stellen fest, dass … Note: machen is also acceptable in the less formal Feststellungen machen.","ex":[{"de":"Die Prüfer trafen bei der Kontrolle mehrere Feststellungen zu Mängeln in der Buchführung.","en":"During the inspection the auditors made several findings on shortcomings in the bookkeeping."},{"de":"Der Bericht trifft keine Feststellungen zur Schuldfrage.","en":"The report makes no findings regarding the question of guilt."},{"de":"Dazu konnten bisher keine abschließenden Feststellungen getroffen werden.","en":"No conclusive findings have been made on this so far."}],"exPlain":[{"de":"Die Prüfer stellten bei der Kontrolle mehrere Mängel in der Buchführung fest.","en":"During the inspection the auditors found several shortcomings in the bookkeeping."}]},
 {"np":"Anordnungen","verb":"treffen","plain":"anordnen","en":"to give orders; to issue directives","lv":"C1","vdecoys":["machen","setzen","stellen"],"pdecoys":["befolgen","ausführen","bitten"],"vAlt":["erteilen"],"note":"Official register, usually plural: die nötigen Anordnungen treffen. anordnen takes a direct object (eine Maßnahme anordnen) or a dass-clause.","ex":[{"de":"Die Einsatzleitung traf sofort die notwendigen Anordnungen zur Evakuierung.","en":"The command centre immediately issued the necessary orders for the evacuation."},{"de":"Der Arzt muss in Notfällen selbstständig Anordnungen treffen können.","en":"In emergencies the doctor must be able to give orders independently."},{"de":"Die Behörde hat entsprechende Anordnungen getroffen.","en":"The authority has issued the corresponding directives."}],"exPlain":[{"de":"Die Einsatzleitung ordnete sofort die Evakuierung an.","en":"The command centre immediately ordered the evacuation."}]},
 {"np":"Vorsorge","verb":"treffen","plain":"vorsorgen","en":"to make provisions; to take precautions","lv":"C1","vdecoys":["machen","halten","geben"],"pdecoys":["versorgen","entsorgen","besorgen"],"vAlt":["tragen"],"note":"Formal. Vorsorge treffen für/gegen etwas. The same plain verb also fits Vorkehrungen treffen. Be careful with the look-alikes versorgen/entsorgen/besorgen.","ex":[{"de":"Die Stadt trifft Vorsorge gegen künftige Hochwasser.","en":"The city is taking precautions against future floods."},{"de":"Wer rechtzeitig Vorsorge für das Alter trifft, lebt später sorgenfreier.","en":"Those who make provisions for old age in good time live more worry-free later."},{"de":"Die Versicherung hatte für einen solchen Fall keine Vorsorge getroffen.","en":"The insurer had made no provision for such a case."}],"exPlain":[{"de":"Die Stadt sorgt gegen künftige Hochwasser vor.","en":"The city is taking precautions against future floods."}]},
 {"np":"Einwände","verb":"erheben","plain":"einwenden","en":"to raise objections","lv":"C1","vdecoys":["stellen","geben","treffen"],"pdecoys":["zustimmen","bestätigen","einladen"],"vAlt":["vorbringen"],"note":"Formal. Einwände gegen etwas erheben. The plain verb einwenden is separable and often takes a dass-clause or etwas: Ich habe nichts dagegen einzuwenden.","ex":[{"de":"Mehrere Abgeordnete erhoben Einwände gegen den Gesetzentwurf.","en":"Several members of parliament raised objections to the bill."},{"de":"Die Gutachter haben gegen die Methode schwerwiegende Einwände erhoben.","en":"The experts raised serious objections to the method."},{"de":"Wenn niemand Einwände erhebt, gilt das Protokoll als genehmigt.","en":"If nobody raises any objections, the minutes are considered approved."}],"exPlain":[{"de":"Mehrere Abgeordnete hatten gegen den Gesetzentwurf etwas einzuwenden.","en":"Several members of parliament had objections to the bill."}]},
 {"np":"Gültigkeit","verb":"besitzen","plain":"gelten","en":"to be valid; to remain in force","lv":"C1","vdecoys":["tragen","halten","bringen"],"pdecoys":["ablaufen","verfallen","stimmen"],"vAlt":["haben"],"note":"Formal. Gültigkeit besitzen (or haben) describes a state of validity of a ticket, contract or law. Beginning of validity: Gültigkeit erlangen.","ex":[{"de":"Der Vertrag besitzt auch nach der Änderung weiterhin Gültigkeit.","en":"The contract remains valid even after the amendment."},{"de":"Die Fahrkarte besitzt nur am Tag der Ausstellung Gültigkeit.","en":"The ticket is valid only on the day of issue."},{"de":"Diese Regel besitzt für alle Mitgliedstaaten Gültigkeit.","en":"This rule is valid for all member states."}],"exPlain":[{"de":"Der Vertrag gilt auch nach der Änderung weiter.","en":"The contract remains in force even after the amendment."}]},
 {"np":"Kenntnis","verb":"erlangen","plain":"erfahren","en":"to learn of; to become aware of","lv":"C1","vdecoys":["machen","halten","setzen"],"pdecoys":["wissen","kennen","verstehen"],"vAlt":["erhalten"],"note":"Formal/administrative; note the inchoative sense (the start of knowing): von etwas Kenntnis erlangen. Compare: Kenntnis haben von = wissen; zur Kenntnis nehmen = notice, acknowledge.","ex":[{"de":"Die Firma erlangte erst durch einen anonymen Hinweis Kenntnis von dem Datenleck.","en":"The company learned of the data breach only through an anonymous tip."},{"de":"Von dem Vorfall hatte er erst Tage später Kenntnis erlangt.","en":"He had learned of the incident only days later."},{"de":"Sobald wir davon Kenntnis erlangen, informieren wir Sie.","en":"As soon as we learn of it, we will inform you."}],"exPlain":[{"de":"Die Firma erfuhr erst durch einen anonymen Hinweis von dem Datenleck.","en":"The company learned of the data breach only through an anonymous tip."}]},
 {"np":"eine Verpflichtung","verb":"eingehen","plain":"sich verpflichten","en":"to enter into an obligation; to commit oneself","lv":"C1","vdecoys":["machen","treffen","nehmen"],"pdecoys":["sich weigern","sich entschuldigen","sich bemühen"],"vAlt":["übernehmen"],"note":"Formal/legal. eine Verpflichtung eingehen = a binding commitment is made, usually by contract or declaration. The plain verb is reflexive: sich zu etwas verpflichten.","ex":[{"de":"Mit der Unterschrift ging der Käufer eine langfristige finanzielle Verpflichtung ein.","en":"With his signature the buyer entered into a long-term financial obligation."},{"de":"Die Staaten sind keine bindende Verpflichtung zum Klimaschutz eingegangen.","en":"The states did not enter into a binding obligation on climate protection."},{"de":"Bevor wir eine Verpflichtung eingehen, prüfen wir alle Konditionen.","en":"Before we commit ourselves, we check all the terms."}],"exPlain":[{"de":"Mit der Unterschrift verpflichtete sich der Käufer zu langfristigen Zahlungen.","en":"With his signature the buyer committed himself to long-term payments."}]},
 {"np":"Bürgschaft","verb":"leisten","plain":"bürgen","en":"to stand surety; to give a guarantee","lv":"C1","vdecoys":["machen","tragen","halten"],"pdecoys":["verleihen","borgen","pfänden"],"vAlt":["übernehmen","stellen"],"note":"Legal/financial. für jemanden Bürgschaft leisten = für jemanden bürgen (to be liable for another person's debt). bürgen is intransitive and takes für.","ex":[{"de":"Der Vater leistete für den Kredit seines Sohnes Bürgschaft.","en":"The father stood surety for his son's loan."},{"de":"Die Bank verlangte, dass ein Dritter Bürgschaft leistet.","en":"The bank demanded that a third party stand surety."},{"de":"Für die Mietschulden hat niemand Bürgschaft geleistet.","en":"Nobody stood surety for the rent arrears."}],"exPlain":[{"de":"Der Vater bürgte für den Kredit seines Sohnes.","en":"The father stood surety for his son's loan."}]},
 {"np":"Beistand","verb":"leisten","plain":"beistehen","en":"to give support; to assist (in need)","lv":"C1","vdecoys":["machen","halten","bringen"],"pdecoys":["widersprechen","ausnutzen","überlassen"],"vAlt":["gewähren"],"note":"Formal/elevated: jemandem Beistand leisten (in distress, before a court or in an emergency). beistehen is separable and takes the dative.","ex":[{"de":"Der Anwalt leistete seinem Mandanten während der Vernehmung Beistand.","en":"The lawyer assisted his client during the interrogation."},{"de":"Die Nachbarn leisteten der Familie nach dem Brand tatkräftig Beistand.","en":"After the fire the neighbours actively gave the family support."},{"de":"Im Ernstfall sind die Bündnispartner verpflichtet, einander Beistand zu leisten.","en":"In an emergency the allies are obliged to assist one another."}],"exPlain":[{"de":"Der Anwalt stand seinem Mandanten während der Vernehmung bei.","en":"The lawyer stood by his client during the interrogation."}]},
 {"np":"Vorschub","verb":"leisten","plain":"begünstigen","en":"to encourage; to abet (something undesirable)","lv":"C1","vdecoys":["machen","geben","bringen"],"pdecoys":["verhindern","vorschieben","bremsen"],"pAlt":["fördern"],"note":"Formal; almost always with something negative as object: der Korruption Vorschub leisten. The noun phrase is fixed; the dative object is the thing that is encouraged. begünstigen takes an accusative object.","ex":[{"de":"Mangelnde Kontrollen leisten der Korruption Vorschub.","en":"Insufficient controls encourage corruption."},{"de":"Mit seiner Nachlässigkeit hat er dem Betrug Vorschub geleistet.","en":"With his negligence he aided the fraud."},{"de":"Solche Gerüchte leisten der Fremdenfeindlichkeit Vorschub.","en":"Such rumours encourage xenophobia."}],"exPlain":[{"de":"Mangelnde Kontrollen begünstigen die Korruption.","en":"Insufficient controls favour corruption."}]},
 {"np":"Genüge","verb":"tun","plain":"erfüllen","en":"to satisfy; to meet (a requirement)","lv":"C1","vdecoys":["machen","geben","bringen"],"pdecoys":["verlangen","versäumen","verweigern"],"pAlt":["genügen"],"note":"Formal, somewhat elevated: einer Pflicht/Forderung Genüge tun (dative). The plain verb erfüllen takes an accusative object (eine Pflicht erfüllen); genügen also takes the dative (einer Forderung genügen).","ex":[{"de":"Der Bauherr tat allen Auflagen der Behörde Genüge.","en":"The developer satisfied all of the authority's conditions."},{"de":"Mit diesem Nachweis wird den gesetzlichen Anforderungen Genüge getan.","en":"With this proof the legal requirements are met."},{"de":"Um der Form Genüge zu tun, unterschrieb er das Protokoll.","en":"To satisfy the formalities he signed the minutes."}],"exPlain":[{"de":"Der Bauherr erfüllte alle Auflagen der Behörde.","en":"The developer fulfilled all the authority's conditions."}],"vAlt":["leisten"]},
 {"np":"den Vorsitz","verb":"führen","plain":"leiten","en":"to chair; to preside","lv":"C1","vdecoys":["setzen","tragen","machen"],"pdecoys":["protokollieren","vertreten","beraten"],"vAlt":["haben"],"pAlt":["vorsitzen"],"note":"Formal. den Vorsitz führen (in/bei etwas). leiten takes an accusative object (die Sitzung leiten); vorsitzen is separable and takes the dative (der Sitzung vorsitzen).","ex":[{"de":"Die Staatssekretärin führte den Vorsitz im Prüfungsausschuss.","en":"The state secretary chaired the examination board."},{"de":"Wer führt bei der heutigen Sitzung den Vorsitz?","en":"Who is chairing today's meeting?"},{"de":"Den Vorsitz im Verband hatte er mehr als zwanzig Jahre lang geführt.","en":"He had chaired the association for more than twenty years."}],"exPlain":[{"de":"Die Staatssekretärin leitete den Prüfungsausschuss.","en":"The state secretary headed the examination board."}]},
 {"np":"zur Wahl","verb":"stellen","plain":"kandidieren","en":"to stand for election","lv":"C1","vdecoys":["setzen","legen","bringen"],"pdecoys":["wählen","abstimmen","entscheiden"],"note":"Reflexive: sich zur Wahl stellen (not to be confused with zur Wahl stehen = to be on offer / be a candidate). kandidieren is intransitive, often with für or als.","ex":[{"de":"Die Amtsinhaberin stellt sich im Herbst erneut zur Wahl.","en":"The incumbent is standing for election again in the autumn."},{"de":"Er hat sich nie für den Vorstand zur Wahl gestellt.","en":"He never stood for election to the board."},{"de":"Wer sich zur Wahl stellen möchte, muss bis Ende Mai nominiert werden.","en":"Anyone who wants to stand for election must be nominated by the end of May."}],"exPlain":[{"de":"Die Amtsinhaberin kandidiert im Herbst erneut.","en":"The incumbent is standing again in the autumn."}]},
 {"np":"Respekt","verb":"zollen","plain":"respektieren","en":"to pay respect to; to acknowledge with respect","lv":"C1","vdecoys":["machen","halten","setzen"],"pdecoys":["verachten","fürchten","verspotten"],"vAlt":["erweisen"],"pAlt":["achten","würdigen"],"note":"Elevated/formal; zollen is used mainly with abstract nouns of appreciation (Respekt, Anerkennung, Dank, Beifall, Tribut). jemandem Respekt zollen (dative) vs. jemanden respektieren (accusative).","ex":[{"de":"Alle Kollegen zollten der Leistung der Pflegekräfte großen Respekt.","en":"All colleagues paid great respect to the nurses' achievement."},{"de":"Für seinen Mut zollte ihm selbst der politische Gegner Respekt.","en":"Even his political opponent paid him respect for his courage."},{"de":"Man muss dem Mannschaftskapitän, der trotz Verletzung weiterspielte, Respekt zollen.","en":"One has to pay respect to the team captain, who played on despite his injury."}],"exPlain":[{"de":"Alle Kollegen respektierten die Leistung der Pflegekräfte sehr.","en":"All colleagues greatly respected the nurses' achievement."}]},
 {"np":"ein Gelübde","verb":"ablegen","plain":"geloben","en":"to take a vow","lv":"C1","vdecoys":["setzen","stellen","treffen"],"pdecoys":["bereuen","brechen","verkünden"],"note":"Elevated/religious or ceremonial: ein Gelübde ablegen (e.g. of monks and nuns). geloben is formal and also takes a dass-clause or zu + Infinitiv.","ex":[{"de":"Mit zwanzig legte sie das Gelübde der Armut und des Gehorsams ab.","en":"At twenty she took the vow of poverty and obedience."},{"de":"Die Mönche legen bei der Aufnahme in den Orden ein Gelübde ab.","en":"The monks take a vow on being admitted to the order."},{"de":"Er hatte feierlich ein Gelübde abgelegt, nie wieder um Geld zu spielen.","en":"He had solemnly taken a vow never to gamble again."}],"exPlain":[{"de":"Mit zwanzig gelobte sie Armut und Gehorsam.","en":"At twenty she vowed poverty and obedience."}],"vAlt":["tun"]},
 {"np":"ins Leben","verb":"rufen","plain":"gründen","en":"to found; to set up","lv":"C1","vdecoys":["setzen","bringen","stellen"],"pdecoys":["beleben","auflösen","verwalten"],"pAlt":["initiieren"],"note":"Used for organisations, initiatives, associations, prizes and events. Passive is common: wurde ins Leben gerufen.","ex":[{"de":"Die Bürger riefen eine Initiative gegen den Fluglärm ins Leben.","en":"The citizens set up an initiative against aircraft noise."},{"de":"Der Preis wurde vor dreißig Jahren ins Leben gerufen.","en":"The prize was established thirty years ago."},{"de":"Sie hat ein Netzwerk für junge Gründerinnen ins Leben gerufen.","en":"She has founded a network for young female entrepreneurs."}],"exPlain":[{"de":"Die Bürger gründeten eine Initiative gegen den Fluglärm.","en":"The citizens founded an initiative against aircraft noise."}]},
 {"np":"zur Aufführung","verb":"bringen","plain":"aufführen","en":"to perform; to stage","lv":"C1","vdecoys":["stellen","setzen","nehmen"],"pdecoys":["absagen","proben","besuchen"],"note":"Cultural/formal. Passive counterpart without agent: zur Aufführung kommen/gelangen (= aufgeführt werden).","ex":[{"de":"Das Staatstheater bringt im Herbst ein neues Stück zur Aufführung.","en":"The state theatre will perform a new play in the autumn."},{"de":"Die Oper wurde 1912 erstmals zur Aufführung gebracht.","en":"The opera was first performed in 1912."},{"de":"Der Chor will Bachs Johannespassion zur Aufführung bringen.","en":"The choir wants to perform Bach's St John Passion."}],"exPlain":[{"de":"Das Staatstheater führt im Herbst ein neues Stück auf.","en":"The state theatre will perform a new play in the autumn."}]},
 {"np":"zur Ausführung","verb":"bringen","plain":"ausführen","en":"to carry out; to execute (a plan)","lv":"C1","vdecoys":["setzen","stellen","nehmen"],"pdecoys":["planen","entwerfen","verwerfen"],"pAlt":["durchführen"],"note":"Formal, somewhat dated/administrative: einen Plan, einen Entwurf zur Ausführung bringen. Passive counterpart: zur Ausführung kommen/gelangen.","ex":[{"de":"Der Architekt brachte den Entwurf in zwei Jahren zur Ausführung.","en":"The architect carried out the design within two years."},{"de":"Das Bauvorhaben soll im nächsten Frühjahr zur Ausführung gebracht werden.","en":"The construction project is to be carried out next spring."},{"de":"Er konnte seine Pläne nie zur Ausführung bringen.","en":"He was never able to carry out his plans."}],"exPlain":[{"de":"Der Architekt führte den Entwurf innerhalb von zwei Jahren aus.","en":"The architect carried out the design within two years."}]},
 {"np":"in Erwägung","verb":"ziehen","plain":"erwägen","en":"to consider; to contemplate","lv":"C1","vdecoys":["nehmen","setzen","stellen"],"pdecoys":["erwidern","erwerben","erwähnen"],"pAlt":["in Betracht ziehen"],"note":"Formal; often with zu + Infinitiv or a noun: etwas in Erwägung ziehen. Beware of the look-alikes erwidern/erwerben/erwähnen.","ex":[{"de":"Die Firma zieht eine Verlegung des Standorts in Erwägung.","en":"The company is considering relocating its site."},{"de":"Wir hatten zunächst auch eine Klage in Erwägung gezogen.","en":"At first we had also considered legal action."},{"de":"Sie zog in Erwägung, ihre Stelle zu kündigen.","en":"She considered quitting her job."}],"exPlain":[{"de":"Die Firma erwägt eine Verlegung des Standorts.","en":"The company is considering relocating its site."}]},
 {"np":"in Rechnung","verb":"ziehen","plain":"berücksichtigen","en":"to take into account; to factor in","lv":"C1","vdecoys":["nehmen","legen","halten"],"pdecoys":["abrechnen","verrechnen","ausrechnen"],"pAlt":["einkalkulieren"],"note":"Do not confuse with in Rechnung stellen (= to bill): in Rechnung ziehen means to take something into account, to reckon with it.","ex":[{"de":"Bei der Planung muss man auch die Preissteigerung in Rechnung ziehen.","en":"When planning, one must also take the rise in prices into account."},{"de":"Das Gericht zog das Alter des Angeklagten in Rechnung.","en":"The court took the defendant's age into account."},{"de":"Diese Möglichkeit hatte niemand in Rechnung gezogen.","en":"Nobody had taken this possibility into account."}],"exPlain":[{"de":"Bei der Planung muss man auch die Preissteigerung berücksichtigen.","en":"When planning, one must also take the rise in prices into account."}]},
 {"np":"zur Auszahlung","verb":"gelangen","plain":"ausgezahlt werden","en":"to be paid out","lv":"C1","vdecoys":["gehen","treten","fallen"],"pdecoys":["eingezahlt werden","angespart werden","gesperrt werden"],"vAlt":["kommen"],"note":"Administrative/financial passive-like meaning (no agent): zur Auszahlung gelangen = ausgezahlt werden. With bringen the agent appears: den Betrag zur Auszahlung bringen.","ex":[{"de":"Die Prämie gelangt Ende des Monats zur Auszahlung.","en":"The bonus will be paid out at the end of the month."},{"de":"Die Entschädigung gelangte erst nach Jahren zur Auszahlung.","en":"The compensation was paid out only after years."},{"de":"Das Wohngeld soll künftig schneller zur Auszahlung gelangen.","en":"Housing benefit is to be paid out more quickly in future."}],"exPlain":[{"de":"Die Prämie wird Ende des Monats ausgezahlt.","en":"The bonus will be paid out at the end of the month."}]},
 {"np":"Absatz","verb":"finden","plain":"sich verkaufen","en":"to sell; to find a market","lv":"C1","vdecoys":["treffen","nehmen","ziehen"],"pdecoys":["sich einkaufen","sich bewerben","sich ausbreiten"],"note":"Business language, goods as subject: Die Ware findet Absatz (often: reißenden Absatz finden = to sell like hot cakes). Absatz here means sales, not 'paragraph' or 'heel'.","ex":[{"de":"Die neuen Elektroautos finden in Europa regen Absatz.","en":"The new electric cars are selling briskly in Europe."},{"de":"Das Produkt fand keinen Absatz und wurde vom Markt genommen.","en":"The product found no market and was withdrawn."},{"de":"Handgemachte Seife findet auf dem Weihnachtsmarkt reißenden Absatz.","en":"Handmade soap sells like hot cakes at the Christmas market."}],"exPlain":[{"de":"Die neuen Elektroautos verkaufen sich in Europa gut.","en":"The new electric cars sell well in Europe."}]},
 {"np":"Schaden","verb":"nehmen","plain":"leiden","en":"to be damaged; to suffer harm","lv":"C1","vdecoys":["geben","setzen","treffen"],"pdecoys":["schaden","zerstören","reparieren"],"note":"Intransitive meaning: the subject is the thing or person that is harmed (der Ruf, die Gesundheit). Often with an or bei: an seiner Gesundheit Schaden nehmen, bei einem Unfall Schaden nehmen. Not 'to cause damage' (= Schaden anrichten).","ex":[{"de":"Sein Ruf als Arzt hat durch den Skandal erheblich Schaden genommen.","en":"His reputation as a doctor has been seriously damaged by the scandal."},{"de":"Das Gemälde nahm durch die Feuchtigkeit Schaden.","en":"The painting was damaged by the damp."},{"de":"Die Demokratie nimmt Schaden, wenn Fakten nichts mehr zählen.","en":"Democracy suffers when facts no longer matter."}],"exPlain":[{"de":"Sein Ruf als Arzt hat durch den Skandal erheblich gelitten.","en":"His reputation as a doctor has suffered considerably from the scandal."}]},
 {"np":"in Mitleidenschaft","verb":"ziehen","plain":"beeinträchtigen","en":"to affect adversely; to damage indirectly","lv":"C1","vdecoys":["nehmen","setzen","stellen"],"pdecoys":["bemitleiden","verschonen","verbessern"],"pAlt":["schädigen"],"note":"Mostly passive: in Mitleidenschaft gezogen werden = to suffer as a side effect. Not related to pity (Mitleid).","ex":[{"de":"Der Streik zog den gesamten Güterverkehr in Mitleidenschaft.","en":"The strike adversely affected all freight traffic."},{"de":"Durch das Hochwasser wurde die Fassade stark in Mitleidenschaft gezogen.","en":"The façade was badly damaged by the flood."},{"de":"Der Skandal hat auch die Familie des Politikers in Mitleidenschaft gezogen.","en":"The scandal has also affected the politician's family."}],"exPlain":[{"de":"Der Streik beeinträchtigte den gesamten Güterverkehr.","en":"The strike affected all freight traffic."}]},
 {"np":"zur Last","verb":"fallen","plain":"belasten","en":"to be a burden to","lv":"C1","vdecoys":["treten","kommen","stehen"],"pdecoys":["entlasten","helfen","gehorchen"],"note":"Dative person: jemandem zur Last fallen; plain belasten takes an accusative: jemanden belasten. Do not mix with jemandem etwas zur Last legen (= to charge someone with something).","ex":[{"de":"Er wollte seinen Kindern im Alter nicht zur Last fallen.","en":"He did not want to be a burden to his children in old age."},{"de":"Ich möchte Ihnen nicht länger zur Last fallen.","en":"I do not want to be a burden to you any longer."},{"de":"Sie fiel der Gemeinde jahrelang zur Last.","en":"For years she was a burden on the community."}],"exPlain":[{"de":"Er wollte seine Kinder im Alter nicht belasten.","en":"He did not want to burden his children in old age."}]},
 {"np":"in Verruf","verb":"bringen","plain":"diskreditieren","en":"to bring into disrepute","lv":"C1","vdecoys":["setzen","stellen","ziehen"],"pdecoys":["rühmen","verbreiten","empfehlen"],"note":"Formal/journalistic. The intransitive counterpart is in Verruf geraten/kommen (to fall into disrepute). diskreditieren is a high-register verb; schädigen would need den Ruf as object.","ex":[{"de":"Die Affäre brachte die ganze Branche in Verruf.","en":"The affair brought the entire industry into disrepute."},{"de":"Mit solchen Methoden wird der seriöse Journalismus in Verruf gebracht.","en":"With such methods serious journalism is brought into disrepute."},{"de":"Er hat seinen Arbeitgeber durch sein Verhalten in Verruf gebracht.","en":"He has brought his employer into disrepute through his behaviour."}],"exPlain":[{"de":"Die Affäre diskreditierte die ganze Branche.","en":"The affair discredited the entire industry."}]},
 {"np":"ins Stocken","verb":"geraten","plain":"stocken","en":"to come to a standstill; to stall","lv":"C1","vdecoys":["fallen","gehen","treten"],"pdecoys":["scheitern","stolpern","stornieren"],"vAlt":["kommen"],"note":"Aktionsart: geraten marks the transition into the state (Verhandlungen geraten ins Stocken). Plain stocken is intransitive and not the same as 'stoppen'.","ex":[{"de":"Die Verhandlungen gerieten wegen eines Streits um die Finanzierung ins Stocken.","en":"The negotiations stalled because of a dispute over financing."},{"de":"Der Verkehr ist wegen des Unfalls auf der Autobahn ins Stocken geraten.","en":"Traffic on the motorway slowed to a crawl because of the accident."},{"de":"Als sie die Frage hörte, geriet sie kurz ins Stocken.","en":"When she heard the question she faltered for a moment."}],"exPlain":[{"de":"Die Verhandlungen stockten wegen eines Streits um die Finanzierung.","en":"The negotiations stalled because of a dispute over financing."}]},
 {"np":"in Vergessenheit","verb":"geraten","plain":"vergessen werden","en":"to fall into oblivion","lv":"C1","vdecoys":["laufen","treten","stehen"],"pdecoys":["erinnert werden","gelobt werden","gezeigt werden"],"note":"Aktionsart: geraten = transition. The causative form is in Vergessenheit bringen (rare). Often used for traditions, people, events.","ex":[{"de":"Viele alte Handwerksberufe geraten allmählich in Vergessenheit.","en":"Many old crafts are gradually falling into oblivion."},{"de":"Der Dichter war nach seinem Tod rasch in Vergessenheit geraten.","en":"After his death the poet quickly fell into oblivion."},{"de":"Wir dürfen nicht zulassen, dass diese Verbrechen in Vergessenheit geraten.","en":"We must not allow these crimes to be forgotten."}],"exPlain":[{"de":"Viele alte Handwerksberufe werden allmählich vergessen.","en":"Many old crafts are gradually being forgotten."}]},
 {"np":"zum Erliegen","verb":"bringen","plain":"lahmlegen","en":"to bring to a standstill; to paralyse","lv":"C1","vdecoys":["setzen","stellen","nehmen"],"pdecoys":["beschleunigen","umleiten","beruhigen"],"note":"Journalistic/formal. Intransitive counterpart: zum Erliegen kommen (= to come to a halt). Typical objects: Verkehr, Produktion, Handel.","ex":[{"de":"Der Schneesturm brachte den gesamten Flugverkehr zum Erliegen.","en":"The snowstorm brought all air traffic to a standstill."},{"de":"Ein Cyberangriff hatte die Verwaltung der Stadt zum Erliegen gebracht.","en":"A cyberattack had paralysed the city's administration."},{"de":"Die Proteste drohen, den Hafen zum Erliegen zu bringen.","en":"The protests threaten to bring the port to a standstill."}],"exPlain":[{"de":"Der Schneesturm legte den gesamten Flugverkehr lahm.","en":"The snowstorm paralysed all air traffic."}]},
 {"np":"zum Durchbruch","verb":"kommen","plain":"sich durchsetzen","en":"to make a breakthrough; to prevail","lv":"C1","vdecoys":["gehen","fallen","stehen"],"pdecoys":["durchschauen","durchfallen","durchhalten"],"vAlt":["gelangen"],"note":"Subject is an idea, technology or movement. Compare jemandem/einer Sache zum Durchbruch verhelfen (transitive, dative).","ex":[{"de":"Erst nach vielen Jahren kam die Erfindung zum Durchbruch.","en":"Only after many years did the invention make its breakthrough."},{"de":"Die neue Technologie ist im Alltag endlich zum Durchbruch gekommen.","en":"The new technology has finally made its breakthrough in everyday life."},{"de":"Die Idee der Gleichberechtigung kam nur langsam zum Durchbruch.","en":"The idea of equal rights prevailed only slowly."}],"exPlain":[{"de":"Erst nach vielen Jahren setzte sich die Erfindung durch.","en":"Only after many years did the invention catch on."}]},
 {"np":"zur Geltung","verb":"bringen","plain":"hervorheben","en":"to show off to advantage; to bring out","lv":"C1","vdecoys":["setzen","stellen","nehmen"],"pdecoys":["verbergen","übertönen","verdecken"],"pAlt":["betonen"],"note":"Aesthetic/formal: the object appears at its best. Intransitive: zur Geltung kommen (= to be shown to advantage). Plain hervorheben takes an accusative object.","ex":[{"de":"Die Beleuchtung bringt die Farben der Gemälde besonders gut zur Geltung.","en":"The lighting shows the colours of the paintings off especially well."},{"de":"Der Architekt wollte den Altbau durch den Anbau zur Geltung bringen.","en":"The architect wanted to bring out the old building through the extension."},{"de":"Mit der richtigen Kleidung bringt man seine Vorzüge zur Geltung.","en":"With the right clothes one shows one's strengths to advantage."}],"exPlain":[{"de":"Die Beleuchtung hebt die Farben der Gemälde besonders hervor.","en":"The lighting particularly emphasises the colours of the paintings."}]},
 {"np":"zur Vollendung","verb":"bringen","plain":"vollenden","en":"to bring to perfection; to complete","lv":"C1","vdecoys":["setzen","stellen","nehmen"],"pdecoys":["beginnen","unterbrechen","abbrechen"],"note":"Elevated/literary register: ein Werk zur Vollendung bringen. Intransitive: zur Vollendung gelangen/kommen.","ex":[{"de":"Der Komponist konnte das Werk nicht mehr zur Vollendung bringen.","en":"The composer was no longer able to complete the work."},{"de":"Mit diesem Gemälde brachte der Maler seinen Stil zur Vollendung.","en":"With this painting the artist brought his style to perfection."},{"de":"Die Handwerker brachten den Dom nach hundert Jahren zur Vollendung.","en":"After a hundred years the craftsmen brought the cathedral to completion."}],"exPlain":[{"de":"Der Komponist konnte das Werk nicht mehr vollenden.","en":"The composer was no longer able to complete the work."}]},
 {"np":"in Augenschein","verb":"nehmen","plain":"besichtigen","en":"to inspect; to examine closely","lv":"C1","vdecoys":["setzen","stellen","bringen"],"pdecoys":["übersehen","fotografieren","verdecken"],"pAlt":["begutachten"],"note":"Formal; often official or professional inspection: einen Schaden, ein Grundstück, einen Gegenstand in Augenschein nehmen.","ex":[{"de":"Der Gutachter nahm den Schaden am Dach in Augenschein.","en":"The surveyor inspected the damage to the roof."},{"de":"Die Kommission will das Gelände vor der Entscheidung in Augenschein nehmen.","en":"The commission wants to inspect the site before making a decision."},{"de":"Wir haben die Wohnung gestern gründlich in Augenschein genommen.","en":"We inspected the flat thoroughly yesterday."}],"exPlain":[{"de":"Der Gutachter besichtigte den Schaden am Dach.","en":"The surveyor inspected the damage to the roof."}]},
 {"np":"ins Auge","verb":"fassen","plain":"planen","en":"to envisage; to have in view","lv":"C1","vdecoys":["nehmen","setzen","ziehen"],"pdecoys":["verwerfen","vergessen","ablehnen"],"pAlt":["vorhaben","anstreben"],"note":"Formal/journalistic; the object is a plan, a date, an option: einen Termin ins Auge fassen. Not to be confused with ins Auge sehen (e.g. dem Tod ins Auge sehen).","ex":[{"de":"Die Stadt fasst einen Neubau der Brücke ins Auge.","en":"The city is envisaging a new bridge."},{"de":"Wir hatten den Mai für die Eröffnung ins Auge gefasst.","en":"We had pencilled in May for the opening."},{"de":"Für die Reform wird das Jahr 2028 ins Auge gefasst.","en":"The year 2028 is envisaged for the reform."}],"exPlain":[{"de":"Die Stadt plant einen Neubau der Brücke.","en":"The city is planning a new bridge."}]},
 {"np":"Eingang","verb":"finden","plain":"aufgenommen werden","en":"to be included; to find its way in","lv":"C1","vdecoys":["treffen","machen","geben"],"pdecoys":["ausgeschlossen werden","eingeladen werden","vergessen werden"],"note":"Passive meaning; the subject is an idea, term or formulation. Typical frame: in etwas Eingang finden (+ Akk.) = in etwas aufgenommen werden.","ex":[{"de":"Diese Ideen fanden Eingang in das Grundgesetz.","en":"These ideas found their way into the Basic Law."},{"de":"Die Formulierung hat auch Eingang in den Koalitionsvertrag gefunden.","en":"The wording has also found its way into the coalition agreement."},{"de":"Neue Wörter finden regelmäßig Eingang in den Duden.","en":"New words regularly make it into the Duden."}],"exPlain":[{"de":"Diese Ideen wurden in das Grundgesetz aufgenommen.","en":"These ideas were included in the Basic Law."}]},
 {"np":"Niederschlag","verb":"finden","plain":"sich niederschlagen","en":"to be reflected; to find expression","lv":"C1","vdecoys":["machen","treffen","nehmen"],"pdecoys":["verschwinden","ausbleiben","verjähren"],"note":"Formal; typically in etwas (seinen) Niederschlag finden = sich in etwas niederschlagen (to be reflected in). The plain verb is reflexive.","ex":[{"de":"Die Preissteigerungen fanden ihren Niederschlag in höheren Mieten.","en":"The price increases were reflected in higher rents."},{"de":"Seine Erfahrungen im Krieg fanden Niederschlag in seinem späteren Werk.","en":"His experiences of war found expression in his later work."},{"de":"Diese Entwicklung hat in der Statistik kaum Niederschlag gefunden.","en":"This development has hardly been reflected in the statistics."}],"exPlain":[{"de":"Die Preissteigerungen schlugen sich in höheren Mieten nieder.","en":"The price increases were reflected in higher rents."}]},
 {"np":"Erwähnung","verb":"finden","plain":"erwähnt werden","en":"to be mentioned","lv":"C1","vdecoys":["haben","treffen","nehmen"],"pdecoys":["verschwiegen werden","übersetzt werden","erinnert werden"],"note":"Passive meaning; formal. Compare Beachtung finden (= beachtet werden). The agent version is erwähnen (or Erwähnung tun, rare).","ex":[{"de":"Der Verein fand in dem Bericht keine Erwähnung.","en":"The club was not mentioned in the report."},{"de":"Seine Verdienste finden in der Chronik der Stadt ausführlich Erwähnung.","en":"His achievements are mentioned at length in the city's chronicle."},{"de":"Das Thema findet in den Lehrplänen kaum Erwähnung.","en":"The topic is hardly mentioned in the curricula."}],"exPlain":[{"de":"Der Verein wurde in dem Bericht nicht erwähnt.","en":"The club was not mentioned in the report."}]},
 {"np":"Untersuchungen","verb":"anstellen","plain":"untersuchen","en":"to carry out investigations","lv":"C1","vdecoys":["geben","treffen","halten"],"pdecoys":["anstellen","bestellen","auswerten"],"vAlt":["durchführen","vornehmen"],"note":"Scholarly/official; anstellen is separable (stellt … an). Beware: the plain verb anstellen alone means 'to employ' or 'to switch on'; here it only appears in the combination. untersuchen takes a direct object.","ex":[{"de":"Die Forscher stellten umfangreiche Untersuchungen zur Wirkung des Medikaments an.","en":"The researchers carried out extensive investigations into the effect of the drug."},{"de":"Zur Klärung des Unfalls wurden gründliche Untersuchungen angestellt.","en":"Thorough investigations were carried out to clarify the accident."},{"de":"Wir haben vergleichende Untersuchungen angestellt, um die Ursache zu finden.","en":"We carried out comparative investigations in order to find the cause."}],"exPlain":[{"de":"Die Forscher untersuchten ausführlich die Wirkung des Medikaments.","en":"The researchers investigated the effect of the drug in detail."}]},
 {"np":"Nachforschungen","verb":"anstellen","plain":"nachforschen","en":"to make enquiries; to investigate","lv":"C1","vdecoys":["treffen","halten","geben"],"pdecoys":["nachlassen","nachgeben","nachahmen"],"vAlt":["betreiben"],"pAlt":["recherchieren"],"note":"Formal; plural. Nachforschungen über/nach etwas anstellen. nachforschen is separable and takes the dative (dem Verbleib nachforschen) or nach + Dat.","ex":[{"de":"Die Polizei stellte Nachforschungen über den Verbleib des Gemäldes an.","en":"The police made enquiries about the whereabouts of the painting."},{"de":"Er hat jahrelang Nachforschungen über seine Herkunft angestellt.","en":"For years he researched his origins."},{"de":"Wenn Sie Nachforschungen anstellen, finden Sie die Akte vielleicht im Stadtarchiv.","en":"If you make enquiries, you may find the file in the city archive."}],"exPlain":[{"de":"Die Polizei forschte dem Verbleib des Gemäldes nach.","en":"The police made enquiries about the whereabouts of the painting."}]},
 {"np":"Überlegungen","verb":"anstellen","plain":"überlegen","en":"to ponder; to reflect","lv":"C1","vdecoys":["treffen","halten","geben"],"pdecoys":["entscheiden","vermuten","vergleichen"],"pAlt":["nachdenken"],"note":"Formal/written register, plural: Überlegungen zu etwas anstellen. Often with nouns like theoretische, grundsätzliche, strategische Überlegungen.","ex":[{"de":"Die Geschäftsleitung stellt Überlegungen zur künftigen Strategie an.","en":"The management is reflecting on the future strategy."},{"de":"Vor der Entscheidung wurden eingehende Überlegungen angestellt.","en":"Detailed deliberations were carried out before the decision."},{"de":"Der Aufsatz stellt grundsätzliche Überlegungen zur Rolle der Medien an.","en":"The essay offers fundamental reflections on the role of the media."}],"exPlain":[{"de":"Die Geschäftsleitung überlegt, wie die künftige Strategie aussehen soll.","en":"The management is thinking about what the future strategy should look like."}]},
 {"np":"eine These","verb":"aufstellen","plain":"postulieren","en":"to put forward a thesis","lv":"C1","vdecoys":["machen","treffen","geben"],"pdecoys":["widerlegen","bestätigen","verifizieren"],"pAlt":["behaupten"],"note":"Academic register. eine These aufstellen = to formulate and present a thesis (not necessarily proven). postulieren is a high-register verb (accusative object or dass-clause) that presents something as a given assumption, so it is only a rough match.","ex":[{"de":"Der Soziologe stellte die These auf, dass Medien das Vertrauen in Institutionen schwächen.","en":"The sociologist put forward the thesis that the media weaken trust in institutions."},{"de":"Im ersten Kapitel stellt die Autorin mehrere Thesen auf.","en":"In the first chapter the author puts forward several theses."},{"de":"Diese These wurde bereits in den Sechzigerjahren aufgestellt.","en":"This thesis was already put forward in the sixties."}],"exPlain":[{"de":"Der Soziologe postulierte, dass Medien das Vertrauen in Institutionen schwächen.","en":"The sociologist postulated that the media weaken trust in institutions."}]},
 {"np":"einen Zusammenhang","verb":"herstellen","plain":"verknüpfen","en":"to establish a connection","lv":"C1","vdecoys":["machen","legen","stellen"],"pdecoys":["trennen","vermeiden","bestreiten"],"pAlt":["verbinden"],"note":"Scholarly/journalistic; herstellen is separable. einen Zusammenhang zwischen A und B herstellen. verknüpfen: A mit B verknüpfen.","ex":[{"de":"Die Studie stellt einen Zusammenhang zwischen Schlafmangel und Übergewicht her.","en":"The study establishes a connection between lack of sleep and obesity."},{"de":"Es ist schwierig, zwischen den beiden Ereignissen einen Zusammenhang herzustellen.","en":"It is difficult to establish a connection between the two events."},{"de":"Die Ermittler haben einen Zusammenhang mit früheren Vorfällen hergestellt.","en":"The investigators have drawn a connection to earlier incidents."}],"exPlain":[{"de":"Die Studie verknüpft Schlafmangel mit Übergewicht.","en":"The study links lack of sleep with obesity."}]},
 {"np":"den Anstoß","verb":"geben","plain":"anregen","en":"to give the impetus for; to trigger","lv":"C1","vdecoys":["stellen","treffen","legen"],"pdecoys":["verhindern","abraten","befehlen"],"pAlt":["initiieren"],"note":"Do not confuse with Anstoß nehmen (= to take offence). den Anstoß zu/für etwas geben: the object is the process that gets started.","ex":[{"de":"Ein Zeitungsartikel gab den Anstoß zu einer breiten öffentlichen Debatte.","en":"A newspaper article gave the impetus for a broad public debate."},{"de":"Die Studie hat den Anstoß für die Reform gegeben.","en":"The study provided the impetus for the reform."},{"de":"Mit ihrem Vortrag gab sie den Anstoß zur Gründung des Vereins.","en":"With her lecture she provided the impetus for founding the association."}],"exPlain":[{"de":"Ein Zeitungsartikel regte eine breite öffentliche Debatte an.","en":"A newspaper article stimulated a broad public debate."}]},
 {"np":"Linderung","verb":"verschaffen","plain":"lindern","en":"to bring relief","lv":"C1","vdecoys":["machen","tun","treffen"],"pdecoys":["verschlimmern","verhindern","verordnen"],"vAlt":["bringen"],"note":"Medical/formal. jemandem Linderung verschaffen (dative of person); lindern takes the complaint as accusative object (Schmerzen lindern).","ex":[{"de":"Die Salbe verschaffte ihm spürbare Linderung.","en":"The ointment gave him noticeable relief."},{"de":"Das Medikament verschafft den Patienten Linderung ihrer Schmerzen.","en":"The drug relieves the patients' pain."},{"de":"Eine Massage kann bei Rückenbeschwerden Linderung verschaffen.","en":"A massage can bring relief for back problems."}],"exPlain":[{"de":"Die Salbe linderte seine Beschwerden spürbar.","en":"The ointment noticeably eased his complaints."}]},
 {"np":"unter Schutz","verb":"stellen","plain":"schützen","en":"to place under (legal) protection","lv":"C1","vdecoys":["setzen","legen","ziehen"],"pdecoys":["abholzen","bebauen","verkaufen"],"note":"Legal/administrative sense: an authority declares a building, species or area protected. Common: unter Denkmalschutz/Naturschutz stellen. Often passive.","ex":[{"de":"Das Moor wurde 1990 unter Schutz gestellt.","en":"The moor was placed under protection in 1990."},{"de":"Die Behörde will das alte Bahnhofsgebäude unter Schutz stellen.","en":"The authority wants to place the old station building under protection."},{"de":"Mehrere seltene Arten wurden unter Schutz gestellt, um sie vor dem Aussterben zu bewahren.","en":"Several rare species were placed under protection to save them from extinction."}],"exPlain":[{"de":"Das Moor wurde 1990 offiziell geschützt.","en":"The moor was officially protected in 1990."}]},
 {"np":"eine E-Mail","verb":"schicken","plain":"mailen","en":"to send an email","lv":"A2","vdecoys":["stellen","geben","nehmen"],"pdecoys":["telefonieren","chatten","lesen"],"vAlt":["senden","schreiben"],"pAlt":["schreiben"],"note":"Mailen ist im Alltag ganz normal. Es steht mit Dativ und Akkusativ: Ich maile dir die Adresse.","ex":[{"de":"Ich schicke dir morgen eine E-Mail mit dem Plan.","en":"I'll send you an email with the plan tomorrow."},{"de":"Hast du Frau Weber schon eine E-Mail geschickt?","en":"Have you already sent Ms Weber an email?"},{"de":"Der Lehrer schickt uns jede Woche eine E-Mail mit den Hausaufgaben.","en":"The teacher sends us an email with the homework every week."}],"exPlain":[{"de":"Ich maile dir morgen den Plan.","en":"I'll email you the plan tomorrow."},{"de":"Der Lehrer mailt uns jede Woche die Hausaufgaben.","en":"The teacher emails us the homework every week."}]},
 {"np":"ein Video","verb":"machen","plain":"filmen","en":"to make a video, to film","lv":"A2","vdecoys":["geben","tun","nehmen"],"pdecoys":["fotografieren","zeichnen","zeigen"],"vAlt":["drehen","aufnehmen"],"note":"Ein Video von etwas machen = etwas filmen (das Objekt steht dann direkt beim Verb): Ich mache ein Video vom Konzert = Ich filme das Konzert.","ex":[{"de":"Wir machen ein Video von der Geburtstagsfeier.","en":"We are making a video of the birthday party."},{"de":"Sie hat im Urlaub ein kurzes Video gemacht.","en":"She made a short video on holiday."},{"de":"Machst du bitte ein Video von uns?","en":"Could you take a video of us, please?"}],"exPlain":[{"de":"Wir filmen die Geburtstagsfeier.","en":"We are filming the birthday party."},{"de":"Filmst du uns bitte?","en":"Could you film us, please?"}]},
 {"np":"Besuch","verb":"bekommen","plain":"besucht werden","en":"to have visitors, to get a visit","lv":"A2","vdecoys":["geben","nehmen","stellen"],"pdecoys":["eingeladen werden","angerufen werden","abgeholt werden"],"vAlt":["haben","kriegen"],"note":"Die einfache Form ist Passiv: Ich bekomme Besuch von Anna = Anna besucht mich = Ich werde von Anna besucht. Nicht verwechseln: zu Besuch kommen (das sagt der Gast: Ich komme zu Besuch).","ex":[{"de":"Am Wochenende bekomme ich Besuch von meiner Schwester.","en":"This weekend my sister is coming to visit me."},{"de":"Wir haben gestern überraschend Besuch bekommen.","en":"We had a surprise visitor yesterday."},{"de":"Bekommst du heute Abend Besuch?","en":"Are you having visitors this evening?"}],"exPlain":[{"de":"Am Wochenende werde ich von meiner Schwester besucht.","en":"This weekend I will be visited by my sister."},{"de":"Gestern wurden wir überraschend besucht.","en":"We were visited by surprise yesterday."}]},
 {"np":"eine Erklärung","verb":"geben","plain":"erklären","en":"to give an explanation, to explain","lv":"A2","vdecoys":["tun","stellen","nehmen"],"pdecoys":["erzählen","beschreiben","zeigen"],"note":"Jemandem eine Erklärung für etwas geben = jemandem etwas erklären. Nicht verwechseln: eine Erklärung abgeben = eine offizielle Aussage machen.","ex":[{"de":"Der Lehrer gibt uns eine einfache Erklärung.","en":"The teacher gives us a simple explanation."},{"de":"Kannst du mir bitte eine Erklärung dafür geben?","en":"Can you please give me an explanation for that?"},{"de":"Er hat keine Erklärung für seinen Fehler gegeben.","en":"He did not give an explanation for his mistake."}],"exPlain":[{"de":"Der Lehrer erklärt uns die Regel einfach.","en":"The teacher explains the rule to us simply."},{"de":"Kannst du mir das bitte erklären?","en":"Can you please explain that to me?"}]}
];
